insert into public.livros (id, titulo, autor, genero, idioma, resumo, nivel_dificuldade, tags) values
  ('b4b9fa04-a1e3-5966-80ec-7af0449044fc', 'Pride and Prejudice', 'Jane Austen', 'Romance', 'en', 'Elizabeth Bennet, a segunda de cinco irmãs, vive numa família que precisa casar as filhas bem. Quando o rico Bingley aluga a mansão vizinha, ele se encanta por Jane, e o amigo orgulhoso, Darcy, se interessa por Elizabeth. Ela forma uma opinião ruim dele, apoiada nas histórias de Wickham, e só descobre os erros do próprio julgamento depois de recusar um pedido de casamento.', 'Avançado', array['clássico', 'romance', 'inglaterra', 'século xix', 'sociedade']),
  ('fd1051e4-dae9-55fb-9d87-af88ec9b585b', 'Sense and Sensibility', 'Jane Austen', 'Romance', 'en', 'Com a morte do pai, as irmãs Elinor e Marianne Dashwood perdem a casa e vão morar num chalé no campo com a mãe. Elinor é contida e racional; Marianne, apaixonada, se entrega ao charmoso Willoughby. Enquanto uma esconde a dor por Edward Ferrars e a outra sofre abertamente, o romance compara duas formas de enfrentar o amor.', 'Avançado', array['clássico', 'romance', 'irmãs', 'inglaterra', 'século xix']),
  ('4aa98c4e-1377-5d41-87af-b85636eef93a', 'Emma', 'Jane Austen', 'Romance', 'en', 'Emma Woodhouse, jovem rica e confiante, se acha uma excelente casamenteira e se mete na vida amorosa dos conhecidos. Seus planos dão errado de forma cômica e a obrigam a olhar para os próprios sentimentos. Um retrato divertido de vaidade e amadurecimento.', 'Avançado', array['clássico', 'romance', 'comédia de costumes', 'casamenteira', 'inglaterra']),
  ('4a2b4aba-3d97-54fc-af55-84998fb884ae', 'Persuasion', 'Jane Austen', 'Romance', 'en', 'Aos vinte e sete anos, Anne Elliot ainda pensa em Frederick Wentworth, com quem rompeu o noivado oito anos antes por conselho de uma madrinha. Ele volta rico e respeitado como capitão da marinha, e os dois passam a se encontrar em Lyme e em Bath. Entre cortesia e silêncio, o livro mostra se existe uma segunda chance quando os dois já mudaram.', 'Avançado', array['clássico', 'romance', 'segunda chance', 'inglaterra', 'século xix']),
  ('9cba2098-f74b-57c4-b201-7e84ba8b519e', 'Northanger Abbey', 'Jane Austen', 'Romance', 'en', 'Catherine Morland, de dezessete anos, vive devorando romances góticos e vai a Bath, onde conhece Henry Tilney e as irmãs Thorpe. Convidada para a abadia de Northanger, ela imagina segredos horríveis e crimes escondidos nos corredores. Ao ver que a realidade é bem menos sombria, aprende a separar a ficção da vida, com humor e sem perder o encanto.', 'Avançado', array['clássico', 'sátira', 'romance gótico', 'juventude', 'inglaterra']),
  ('8d9fcf19-12cb-5dc0-a6c0-d0ddbaf2aa5f', 'Mansfield Park', 'Jane Austen', 'Romance', 'en', 'Fanny Price, uma menina pobre, é criada na casa de parentes ricos e vive sempre à sombra deles. Com o tempo, sua firmeza de caráter contrasta com o comportamento leviano das pessoas ao redor. Uma história sobre integridade, dependência e lealdade.', 'Avançado', array['clássico', 'romance', 'família', 'moralidade', 'inglaterra']),
  ('8f8b85c2-8a0a-5762-89a2-6ba2ec74029c', 'Jane Eyre', 'Charlotte Brontë', 'Ficção Clássica', 'en', 'Órfã e maltratada na infância, Jane Eyre se torna governanta na mansão de Thornfield e se aproxima do enigmático Rochester. Um segredo guardado na casa ameaça a felicidade dos dois. A narrativa defende a dignidade e a independência de uma mulher em uma sociedade rígida.', 'Avançado', array['clássico', 'romance gótico', 'órfã', 'independência', 'inglaterra']),
  ('32116ac1-1c66-504c-b9eb-5bb3638c5275', 'Wuthering Heights', 'Emily Brontë', 'Ficção Clássica', 'en', 'Nos campos de Yorkshire, o órfão Heathcliff é criado na casa dos Earnshaw e se apaixona por Catherine, que acaba se casando com o rico Edgar Linton. Ferido, ele some e volta anos depois rico, decidido a se vingar das duas famílias. A história é contada pela criada Nelly Dean a um inquilino curioso, o senhor Lockwood.', 'Avançado', array['clássico', 'romance gótico', 'paixão', 'vingança', 'charneca']),
  ('5178b14d-f24e-53d5-a413-4ecdf505b9f7', 'The Tenant of Wildfell Hall', 'Anne Brontë', 'Ficção Clássica', 'en', 'Uma misteriosa viúva chega com o filho a uma mansão isolada e desperta a curiosidade dos vizinhos. Aos poucos, seu passado e o casamento que deixou para trás vêm à tona. O romance trata de abuso, coragem e da busca por liberdade.', 'Avançado', array['clássico', 'drama', 'casamento', 'independência', 'século xix']),
  ('cad7d448-241f-5106-bb50-daf2f9273fb4', 'Great Expectations', 'Charles Dickens', 'Ficção Clássica', 'en', 'O órfão Pip recebe uma fortuna de um benfeitor misterioso e se muda para Londres para se tornar um cavalheiro. Com o dinheiro vêm a vaidade, a vergonha de suas origens e verdades dolorosas sobre quem o ajudou. É uma história de amadurecimento sobre ambição e gratidão.', 'Avançado', array['clássico', 'dickens', 'formação', 'londres', 'classes sociais']),
  ('5941d0c5-454b-582b-92dd-bab5b6f4c9fe', 'Oliver Twist', 'Charles Dickens', 'Ficção Clássica', 'en', 'Oliver nasce em um asilo para pobres e foge para Londres, onde cai nas mãos de um grupo de batedores de carteira. Entre crueldade e gestos inesperados de bondade, ele tenta encontrar um lugar no mundo. Uma crítica contundente à miséria da Inglaterra vitoriana.', 'Avançado', array['clássico', 'dickens', 'órfão', 'pobreza', 'londres']),
  ('99fd7f3b-058e-53bf-ae15-685c540d5cc7', 'A Tale of Two Cities', 'Charles Dickens', 'Ficção Clássica', 'en', 'Entre Londres e Paris, vidas de várias pessoas se cruzam nos anos que antecedem e acompanham a Revolução Francesa. O advogado Sydney Carton, desiludido, acaba diante de uma escolha que muda tudo. O livro fala de injustiça, violência e redenção.', 'Avançado', array['clássico', 'dickens', 'revolução francesa', 'sacrifício', 'londres']),
  ('6fa01548-ae23-51ae-84c2-c7cdf2dc8a43', 'David Copperfield', 'Charles Dickens', 'Ficção Clássica', 'en', 'David narra a própria vida, da infância difícil à maturidade como escritor, passando por perdas, amizades e erros. Pelo caminho ele conhece figuras inesquecíveis, boas e más. É um dos romances mais pessoais e queridos de Dickens.', 'Avançado', array['clássico', 'dickens', 'formação', 'infância', 'autobiografia']),
  ('96eee825-32b7-5bc7-8a61-d6ee69bdd913', 'Bleak House', 'Charles Dickens', 'Ficção Clássica', 'en', 'Um processo judicial interminável arruína famílias e liga destinos aparentemente sem relação. A jovem Esther Summerson divide a narração com um narrador onisciente e descobre segredos sobre sua origem. O livro ataca a lentidão e a indiferença do sistema legal.', 'Avançado', array['clássico', 'dickens', 'justiça', 'mistério', 'londres']),
  ('180dcef3-09a5-5a11-bf57-42c6f8bf71aa', 'Hard Times', 'Charles Dickens', 'Ficção Clássica', 'en', 'Em Coketown, cidade industrial cinzenta, o professor Thomas Gradgrind educa os filhos e os alunos só com fatos e números, sem espaço para imaginação. Sua filha Louisa casa sem amor com o banqueiro Bounderby, e o filho Tom se mete em dívidas. Ao lado, o operário honesto Stephen Blackpool paga o preço de uma sociedade que trata pessoas como máquinas.', 'Avançado', array['clássico', 'dickens', 'industrialização', 'educação', 'crítica social']),
  ('4ae7fd1b-ebd8-50d8-849d-de39d2b3b881', 'A Christmas Carol', 'Charles Dickens', 'Ficção Clássica', 'en', 'Ebenezer Scrooge, um velho avarento, odeia o Natal e trata mal o empregado Bob Cratchit. Na véspera, o fantasma do ex-sócio Marley o avisa de que três espíritos virão: o do Natal Passado, o do Presente e o do Futuro. Depois de ver sua própria vida e a morte do pequeno Tiny Tim, Scrooge acorda decidido a mudar.', 'Intermediário', array['clássico', 'dickens', 'natal', 'fantasmas', 'redenção']),
  ('d675e6f4-f63d-5257-836d-5a34ad1bbb9e', 'Middlemarch', 'George Eliot', 'Ficção Clássica', 'en', 'Numa cidade do interior, Dorothea Brooke sonha em fazer algo grandioso e casa com um erudito que a decepciona. Ao redor dela, outras histórias de ambição, dinheiro e amor se entrelaçam. Considerado um dos grandes romances em inglês pela profundidade com que retrata as pessoas.', 'Avançado', array['clássico', 'sociedade', 'casamento', 'ideais', 'interior inglês']),
  ('1f4fa974-bdce-5f3d-a73d-900ea8247aff', 'Silas Marner', 'George Eliot', 'Ficção Clássica', 'en', 'O tecelão Silas vive isolado depois de ser injustamente acusado e passa a se apegar apenas ao ouro que junta. Quando seu dinheiro é roubado, uma criança aparece em sua casa e muda sua vida. Uma fábula sobre solidão, afeto e pertencimento.', 'Avançado', array['clássico', 'solidão', 'comunidade', 'adoção', 'século xix']),
  ('c102ef4d-38c4-5fc8-b274-e4da7f603d39', 'Vanity Fair', 'William Makepeace Thackeray', 'Ficção Clássica', 'en', 'A esperta e pobre Becky Sharp luta para subir na escala social, em contraste com sua amiga doce e protegida Amelia. A história se passa durante as guerras napoleônicas e debocha da vaidade da alta sociedade. Uma sátira longa e mordaz sobre dinheiro e aparências.', 'Avançado', array['clássico', 'sátira', 'sociedade', 'ambição', 'napoleão']),
  ('27a594c9-0ba0-5b47-afc9-2b88b23aee90', 'Tess of the d''Urbervilles', 'Thomas Hardy', 'Ficção Clássica', 'en', 'Tess, jovem de família humilde, é empurrada a procurar parentes ricos e tem a vida marcada por um grave episódio. A sociedade a julga com dureza enquanto o destino parece conspirar contra ela. Uma tragédia sobre injustiça e moral hipócrita.', 'Avançado', array['clássico', 'tragédia', 'destino', 'sociedade', 'campo']),
  ('500a1dcd-2420-54bb-a6ad-8f829c92ec45', 'Far from the Madding Crowd', 'Thomas Hardy', 'Ficção Clássica', 'en', 'A independente Bathsheba Everdene herda uma fazenda e atrai três pretendentes muito diferentes. Suas escolhas precipitadas trazem consequências sérias para todos. Um romance rural sobre orgulho, paixão e lealdade.', 'Avançado', array['clássico', 'romance', 'campo', 'independência', 'inglaterra']),
  ('7473f742-d96e-5989-8c62-56e71cc51813', 'Jude the Obscure', 'Thomas Hardy', 'Ficção Clássica', 'en', 'Jude, um jovem pedreiro, sonha em estudar na universidade, mas sua origem humilde fecha as portas. Seu relacionamento com a prima Sue tropeça nas convenções da época. É um romance sombrio e polêmico sobre ambição e preconceito.', 'Avançado', array['clássico', 'tragédia', 'educação', 'classes sociais', 'casamento']),
  ('23ba3531-301b-57f4-98c2-57c8fb2b1b03', 'The Mayor of Casterbridge', 'Thomas Hardy', 'Ficção Clássica', 'en', 'Numa feira rural, o lavrador Michael Henchard, bêbado, vende a esposa Susan e a filha pequena por cinco guinéus. Dezoito anos depois, é o prefeito respeitado de Casterbridge, mas Susan reaparece e o segredo volta à tona. Com o orgulho, o temperamento e a rivalidade com o jovem escocês Donald Farfrae, Henchard destrói a própria vida.', 'Avançado', array['clássico', 'tragédia', 'passado', 'orgulho', 'inglaterra']),
  ('16c377ca-d0ce-5ab7-9730-bb7fc01787ed', 'The Adventures of Tom Sawyer', 'Mark Twain', 'Aventura', 'en', 'Em St Petersburg, uma cidade às margens do Mississippi, Tom Sawyer foge da escola, engana os amigos para caiarem a cerca da tia Polly e se apaixona por Becky Thatcher. À noite, no cemitério, ele e Huck Finn veem um assassinato cometido pelo Injun Joe. O medo de contar a verdade os leva a uma caverna, onde Tom e Becky se perdem.', 'Intermediário', array['clássico', 'infância', 'aventura', 'mississippi', 'humor']),
  ('24f5fa94-3b21-55f1-ab0c-279cb7573832', 'Adventures of Huckleberry Finn', 'Mark Twain', 'Ficção Clássica', 'en', 'Huck foge de casa e desce o rio Mississippi numa balsa ao lado de Jim, um homem escravizado em fuga. Pelo caminho, o garoto questiona o que aprendeu sobre certo e errado. Um clássico americano, escrito com dialetos regionais, sobre liberdade e consciência.', 'Avançado', array['clássico', 'mississippi', 'amizade', 'racismo', 'aventura']),
  ('cd7bb947-1534-5b22-aadf-32bbf9f34ccc', 'The Prince and the Pauper', 'Mark Twain', 'Aventura', 'en', 'Na Londres de 1547, o príncipe Edward e o menino pobre Tom Canty, que são idênticos, trocam de roupa por brincadeira. Tom é levado ao palácio e todos acham que ele é o príncipe; Edward, expulso, passa pelas ruas e conhece a miséria. Com a ajuda do cavaleiro Miles Hendon, Edward luta para voltar antes da coroação.', 'Intermediário', array['clássico', 'identidade', 'inglaterra', 'tudor', 'aventura']),
  ('942f9ee7-5c6f-5a60-9b32-e1065483d79e', 'A Connecticut Yankee in King Arthur''s Court', 'Mark Twain', 'Ficção Clássica', 'en', 'Hank Morgan, mecânico de uma fábrica de Connecticut, leva uma pancada na cabeça e acorda no ano 528, na corte do rei Arthur. Usa o que sabe de ciência, como a previsão de um eclipse, para virar o homem mais poderoso do reino, o Chefe. Tenta trazer telégrafo, escolas e fábricas, mas a Igreja e os cavaleiros resistem, e o final é de guerra.', 'Avançado', array['clássico', 'viagem no tempo', 'sátira', 'rei arthur', 'humor']),
  ('b0de4863-d9d8-5ee7-9753-0c1694d6eeca', 'The Scarlet Letter', 'Nathaniel Hawthorne', 'Ficção Clássica', 'en', 'Na Boston puritana do século XVII, Hester Prynne tem uma filha, Pearl, fora do casamento e é obrigada a usar no peito a letra A, de adúltera. Ela se recusa a revelar quem é o pai. Enquanto isso o pastor Arthur Dimmesdale esconde o segredo e adoece de culpa, e o marido de Hester, agora com outro nome, procura vingança.', 'Avançado', array['clássico', 'puritanos', 'culpa', 'sociedade', 'século xvii']),
  ('7e15e70a-20a4-5779-a671-02112d7b240f', 'Moby-Dick', 'Herman Melville', 'Aventura', 'en', 'O marinheiro Ishmael embarca no baleeiro Pequod, comandado pelo capitão Ahab, que vive para caçar a baleia branca que o mutilou. A viagem vira obsessão e se mistura a longas reflexões sobre o mar e a natureza. Uma obra monumental, de linguagem exigente.', 'Avançado', array['clássico', 'mar', 'obsessão', 'baleia', 'aventura']),
  ('f1b5392d-f7dd-544a-ae37-c765b6fbee00', 'Bartleby, the Scrivener', 'Herman Melville', 'Contos', 'en', 'Um copista de um escritório em Nova York começa a responder a todo pedido com a frase "eu preferiria não fazer". A recusa calma desestabiliza o patrão e o ambiente de trabalho. Um conto enigmático sobre alienação e obediência.', 'Avançado', array['clássico', 'novela', 'trabalho', 'recusa', 'nova york']),
  ('e52fcdb4-6d72-5534-b5f9-d3beb9940cee', 'The Picture of Dorian Gray', 'Oscar Wilde', 'Ficção Clássica', 'en', 'O pintor Basil Hallward faz o retrato do belo Dorian Gray, e Lord Henry Wotton o convence de que a juventude é tudo o que importa. Dorian deseja que o quadro envelheça no lugar dele, e o desejo se realiza. Enquanto leva uma vida cada vez mais cruel, o rosto de Dorian continua intacto e a pintura guarda o preço de cada ato.', 'Avançado', array['clássico', 'vaidade', 'juventude', 'gótico', 'londres']),
  ('e88b18ca-c47f-58a7-b481-67a60f57223d', 'Treasure Island', 'Robert Louis Stevenson', 'Aventura', 'en', 'Jim Hawkins, filho de uma estalajadeira, encontra um mapa do tesouro entre as coisas de um velho pirata morto. Ele embarca no navio Hispaniola com o fidalgo Trelawney, o doutor Livesey e o cozinheiro de uma perna só, Long John Silver, que esconde planos de motim. Na ilha, o grupo disputa o tesouro com piratas e com Ben Gunn, abandonado há anos.', 'Intermediário', array['clássico', 'piratas', 'tesouro', 'aventura', 'juventude']),
  ('2db59aae-8af8-5bc2-9dab-8e5924ea7207', 'Strange Case of Dr Jekyll and Mr Hyde', 'Robert Louis Stevenson', 'Ficção Clássica', 'en', 'Um advogado investiga a estranha ligação entre o respeitado doutor Jekyll e o violento Hyde. A verdade sobre os dois revela os perigos de tentar separar o bem e o mal dentro de uma pessoa. Uma novela curta e sombria.', 'Intermediário', array['clássico', 'duplo', 'ciência', 'gótico', 'londres']),
  ('e0d24b09-f264-541f-98f2-ab045be06c23', 'Kidnapped', 'Robert Louis Stevenson', 'Aventura', 'en', 'Em 1751, o órfão David Balfour, de dezessete anos, vai ao encontro do tio Ebenezer, que o engana e o vende a um navio rumo à América. Depois de um naufrágio, David encontra o jacobita Alan Breck Stewart, e os dois fogem pelas montanhas da Escócia, perseguidos pelos soldados ingleses. A amizade entre eles, tão diferentes, dá força à aventura.', 'Intermediário', array['clássico', 'escócia', 'aventura', 'amizade', 'século xviii']),
  ('4e4c108f-fc63-51d1-a9e5-7062559e85b0', 'Dracula', 'Bram Stoker', 'Terror', 'en', 'Um jovem advogado visita um castelo na Transilvânia e descobre que o anfitrião, o conde Drácula, é um vampiro prestes a chegar à Inglaterra. Contada por cartas e diários, a história acompanha o grupo que tenta detê-lo. O romance que fixou o vampiro na imaginação popular.', 'Avançado', array['clássico', 'vampiro', 'gótico', 'cartas', 'transilvânia']),
  ('17806d25-8ea6-5712-b0f5-24591f11eb17', 'Frankenstein', 'Mary Shelley', 'Ficção Clássica', 'en', 'O estudante Victor Frankenstein monta uma criatura com partes de corpos e a faz viver, mas foge horrorizado e a abandona. Rejeitada por todos, a criatura aprende a falar lendo livros, procura o criador e pede uma companheira. Quando Victor se recusa, ela se vinga dele, e a história, contada nas cartas de um capitão no Ártico, termina em perseguição.', 'Avançado', array['clássico', 'ficção científica', 'criação', 'gótico', 'responsabilidade']),
  ('b5e9ef71-ecbb-5918-a967-89d50f2a608d', 'The Time Machine', 'H. G. Wells', 'Ficção Científica', 'en', 'Um inventor, chamado só de Viajante do Tempo, mostra aos amigos uma máquina e parte para o ano 802.701. Lá encontra os Eloi, gente frágil e despreocupada, e descobre que sob a terra vivem os Morlocks, que os caçam. Depois de perder a máquina e fazer amizade com a jovem Weena, ele ainda avança para um futuro em que a Terra está morrendo.', 'Intermediário', array['clássico', 'viagem no tempo', 'futuro', 'sociedade', 'novela']),
  ('432cf9da-8d3b-510b-95dd-b42f9b8f49c8', 'The War of the Worlds', 'H. G. Wells', 'Ficção Científica', 'en', 'Cilindros vindos de Marte caem na região de Surrey, e deles saem máquinas de três pernas que disparam um raio de calor e soltam fumaça negra. O narrador, sem nome, foge com a esposa e depois sozinho enquanto Londres entra em pânico. Ninguém consegue deter os invasores, até que algo muito pequeno faz o trabalho.', 'Intermediário', array['clássico', 'invasão', 'marcianos', 'inglaterra', 'apocalipse']),
  ('fb3f74a4-9e27-583f-bb0a-4b72fa745ce9', 'The Invisible Man', 'H. G. Wells', 'Ficção Científica', 'en', 'Em pleno inverno, um desconhecido todo enfaixado chega à vila de Iping e se tranca numa pousada. Ele é Griffin, um cientista que descobriu como ficar invisível e não sabe voltar atrás. Sem dinheiro, perseguido e cada vez mais violento, procura abrigo com o antigo colega doutor Kemp, que precisa decidir o que fazer.', 'Intermediário', array['clássico', 'ciência', 'invisibilidade', 'suspense', 'novela']),
  ('112aa3e8-d110-59c7-9746-60ec125e0885', 'The Island of Doctor Moreau', 'H. G. Wells', 'Ficção Científica', 'en', 'Edward Prendick sobrevive a um naufrágio e é levado a uma ilha onde o doutor Moreau e o assistente Montgomery fazem experimentos. As criaturas que andam por lá são animais transformados à força em quase humanos, obrigados a seguir uma Lei. Quando a cirurgia perde o controle, a ilha vira um lugar de medo para Prendick.', 'Intermediário', array['clássico', 'experimentos', 'ética', 'ilha', 'terror']),
  ('1ff37340-ef72-53dd-8552-e48f46ee46de', 'Heart of Darkness', 'Joseph Conrad', 'Ficção Clássica', 'en', 'Numa noite no Tâmisa, o marinheiro Marlow conta aos companheiros do barco como subiu o rio Congo a serviço de uma empresa de marfim. O objetivo era encontrar Kurtz, um agente que virou lenda e que ninguém vê há meses. A viagem pela selva mostra a crueldade da colonização e o que acontece com o homem quando longe de qualquer lei.', 'Avançado', array['clássico', 'colonialismo', 'novela', 'viagem', 'áfrica']),
  ('d74af92b-e90c-59a2-af83-c988fcc0bc67', 'Lord Jim', 'Joseph Conrad', 'Ficção Clássica', 'en', 'Jim, um jovem marinheiro, comete um ato de covardia e passa a vida tentando recuperar a honra. Marlow narra sua trajetória e tenta entender o que acontece com a consciência de um homem. Um romance sobre culpa e redenção.', 'Avançado', array['clássico', 'honra', 'culpa', 'mar', 'redenção']),
  ('5fbb7ece-5e9d-5814-b527-f9dfdd2010ac', 'The Hound of the Baskervilles', 'Arthur Conan Doyle', 'Mistério e Suspense', 'en', 'Sir Charles Baskerville aparece morto nos pântanos de Devonshire, e diz a lenda que um cão gigante e sobrenatural persegue a família. Holmes envia Watson para proteger o herdeiro, Sir Henry, na mansão isolada, enquanto investiga por conta própria. Entre a névoa, o lamaçal de Grimpen e vizinhos de aparência suspeita, o perigo cresce a cada noite.', 'Intermediário', array['clássico', 'sherlock holmes', 'mistério', 'detetive', 'inglaterra']),
  ('50f7d8cf-8c16-5360-8442-406e8d005217', 'A Study in Scarlet', 'Arthur Conan Doyle', 'Mistério e Suspense', 'en', 'O doutor Watson volta ferido do Afeganistão e divide um apartamento na Baker Street com um sujeito estranho, Sherlock Holmes. Quando um homem aparece morto numa casa vazia de Londres, com a palavra RACHE escrita na parede, Holmes mostra seu método de dedução pela primeira vez. A segunda metade do livro viaja ao deserto de Utah para explicar o motivo do crime.', 'Intermediário', array['clássico', 'sherlock holmes', 'detetive', 'londres', 'primeiro caso']),
  ('4de81066-55fa-58c6-8f2a-e94169d64fe3', 'The Adventures of Sherlock Holmes', 'Arthur Conan Doyle', 'Mistério e Suspense', 'en', 'Doze contos narrados por Watson mostram Holmes em casos bem diferentes: o rei da Boêmia e a astuta Irene Adler, a Liga dos Cabeças-Vermelhas, a banda malhada que mata dentro de um quarto trancado. Cada história é curta, tem um enigma e uma solução que parece óbvia só depois que Holmes explica.', 'Intermediário', array['clássico', 'sherlock holmes', 'contos', 'detetive', 'dedução']),
  ('fbef09e7-db10-5417-af10-e2be75c0f9aa', 'The Jungle Book', 'Rudyard Kipling', 'Aventura', 'en', 'Mogli, um menino criado por lobos na selva indiana, aprende a Lei da Selva com o urso Balu e a pantera Bagheera. O tigre Shere Khan quer matá-lo, e Mogli precisa decidir entre os animais e o povo da aldeia. Os contos incluem também Rikki-Tikki-Tavi, a mangusto que defende uma casa de cobras.', 'Intermediário', array['clássico', 'selva', 'animais', 'mogli', 'contos']),
  ('8cfb080f-e206-5045-b25c-45b9e53cc9e6', 'Kim', 'Rudyard Kipling', 'Aventura', 'en', 'Kim, órfão de um soldado irlandês, vive nas ruas de Lahore, na Índia britânica, e vira discípulo de um velho lama tibetano que procura um rio sagrado. No caminho, é recrutado como espião pelo Grande Jogo, a disputa secreta entre a Inglaterra e a Rússia. O livro é uma aventura pela estrada, cheia de cores, línguas e religiões da Índia.', 'Avançado', array['clássico', 'índia', 'espionagem', 'aventura', 'formação']),
  ('682a1f6e-b2f8-5791-a90d-1e9e167c3e12', 'Robinson Crusoe', 'Daniel Defoe', 'Aventura', 'en', 'Depois de um naufrágio, Robinson Crusoe vive por décadas em uma ilha deserta, aprendendo a plantar, construir e sobreviver. Mais tarde, conhece Sexta-Feira e a solidão ganha novo sentido. Um dos primeiros romances em inglês e referência em histórias de sobrevivência.', 'Avançado', array['clássico', 'náufrago', 'sobrevivência', 'ilha', 'aventura']),
  ('8e9f0d66-c932-5bbb-b6f0-425e94f9f0d5', 'Gulliver''s Travels', 'Jonathan Swift', 'Aventura', 'en', 'Lemuel Gulliver, médico de navio, faz quatro viagens que dão errado: à ilha de Lilliput, onde os habitantes têm quinze centímetros; a Brobdingnag, terra de gigantes; à ilha voadora de Laputa; e ao país dos Houyhnhnms, cavalos que falam e governam. Cada lugar serve de espelho para criticar a política, a ciência e os costumes da Inglaterra de Swift.', 'Avançado', array['clássico', 'sátira', 'viagens', 'fantasia', 'século xviii']),
  ('41a431d0-14f7-5681-926c-d6b70fc652e5', '1984', 'George Orwell', 'Ficção Científica', 'en', 'Winston Smith vive sob o regime do Grande Irmão, onde o Partido controla os fatos, a linguagem e até o pensamento. Ele começa um diário e um romance proibido, tentando preservar a própria verdade. Um alerta duradouro sobre vigilância e manipulação da realidade.', 'Intermediário', array['distopia', 'vigilância', 'totalitarismo', 'clássico', 'política']),
  ('af401986-a712-5ffe-8134-55a1e5c59adb', 'Animal Farm', 'George Orwell', 'Ficção Clássica', 'en', 'Os animais de uma fazenda expulsam o dono humano e prometem criar uma sociedade igualitária. Aos poucos, os porcos assumem o controle e as regras vão sendo reescritas a seu favor. Uma fábula curta e ácida sobre poder e corrupção dos ideais.', 'Intermediário', array['sátira', 'política', 'fábula', 'revolução', 'clássico']),
  ('fd4d9bd9-f6f5-5a6a-bf13-f102cebab9ef', 'Brave New World', 'Aldous Huxley', 'Ficção Científica', 'en', 'Num futuro em que as pessoas são projetadas em laboratório e mantidas satisfeitas por prazer e drogas, a estabilidade vale mais do que a liberdade. Bernard Marx e o "selvagem" John começam a questionar esse mundo perfeito. Uma distopia sobre conforto, consumo e perda de individualidade.', 'Avançado', array['distopia', 'tecnologia', 'sociedade', 'clássico', 'controle']),
  ('1b09704e-15a7-5a85-8b87-8855b8777afb', 'The Great Gatsby', 'F. Scott Fitzgerald', 'Ficção Clássica', 'en', 'No verão de 1922, Nick Carraway se muda para Long Island e vira vizinho do misterioso Jay Gatsby, que dá festas enormes todo fim de semana. Aos poucos Nick descobre que tudo aquilo serve para reencontrar Daisy, prima dele, hoje casada com o rico Tom Buchanan. O sonho de recuperar o passado termina em tragédia.', 'Intermediário', array['sonho americano', 'anos 1920', 'riqueza', 'amor', 'clássico']),
  ('8bef5ab3-c680-5cb5-b1ca-3a79e3afb072', 'The Old Man and the Sea', 'Ernest Hemingway', 'Ficção Clássica', 'en', 'Santiago, um velho pescador cubano, passa 84 dias sem pegar nada e se aventura mar adentro. Ele fisga um marlim gigantesco e enfrenta uma luta longa e solitária. Uma novela de linguagem simples sobre dignidade e perseverança.', 'Intermediário', array['pescaria', 'perseverança', 'mar', 'novela', 'clássico']),
  ('1f7e0086-fbda-5673-9764-6d97130fadaf', 'A Farewell to Arms', 'Ernest Hemingway', 'Ficção Clássica', 'en', 'Frederic Henry, motorista de ambulância americano na Itália durante a Primeira Guerra, se apaixona pela enfermeira Catherine Barkley. O romance acompanha o amor do casal em meio à violência e ao desencanto com a guerra. Um relato sóbrio e trágico.', 'Intermediário', array['guerra', 'amor', 'primeira guerra', 'itália', 'clássico']),
  ('9ed39db9-233f-595b-adb5-cb384c5747c3', 'The Sun Also Rises', 'Ernest Hemingway', 'Ficção Clássica', 'en', 'Um grupo de expatriados vai de Paris a Pamplona para assistir às touradas, marcado por desilusão após a guerra. Jake Barnes e Brett Ashley vivem um amor impossível entre bebida e tédio. O livro é símbolo da "geração perdida".', 'Intermediário', array['geração perdida', 'paris', 'espanha', 'touradas', 'pós-guerra']),
  ('a4c71ef7-e3b7-5b17-b9de-889a4505bae2', 'For Whom the Bell Tolls', 'Ernest Hemingway', 'Ficção Clássica', 'en', 'Robert Jordan, um americano especialista em explosivos, une-se a guerrilheiros na Guerra Civil Espanhola com a missão de destruir uma ponte. Em poucos dias, ele vive amor, dúvida e a consciência da morte. Um romance sobre lealdade e sacrifício.', 'Intermediário', array['guerra civil espanhola', 'missão', 'amor', 'coragem', 'clássico']),
  ('14972063-c546-56a8-9ead-761306bd9fa1', 'Of Mice and Men', 'John Steinbeck', 'Ficção Clássica', 'en', 'George e Lennie, trabalhadores rurais itinerantes na Califórnia, sonham em ter um pedaço de terra. A força descomunal e a inocência de Lennie ameaçam esse plano. Uma novela curta e comovente sobre amizade e esperança.', 'Intermediário', array['amizade', 'sonho americano', 'depressão', 'novela', 'clássico']),
  ('880dae31-d604-54bd-b50b-d1d051f346b6', 'The Grapes of Wrath', 'John Steinbeck', 'Ficção Clássica', 'en', 'A família Joad perde a terra em Oklahoma e parte para a Califórnia em busca de trabalho durante a Grande Depressão. A viagem expõe a exploração e a solidariedade entre os pobres. Um retrato duro e humano da crise dos anos 1930.', 'Avançado', array['grande depressão', 'migração', 'família', 'justiça social', 'clássico']),
  ('146eabff-8cae-5f43-8735-f1fca2fcf71d', 'East of Eden', 'John Steinbeck', 'Ficção Clássica', 'en', 'Duas famílias, os Trask e os Hamilton, constroem a vida no vale de Salinas, na Califórnia. A rivalidade entre irmãos ecoa a história de Caim e Abel, enquanto os personagens lidam com livre-arbítrio e culpa. Uma saga ampla sobre escolha moral.', 'Avançado', array['família', 'bem e mal', 'califórnia', 'irmãos', 'clássico']),
  ('12718b68-2d41-5a39-933c-6606de22e52b', 'Cannery Row', 'John Steinbeck', 'Ficção Clássica', 'en', 'Em Monterey, um grupo de moradores pobres de uma rua de fábricas de conserva tenta organizar uma festa para o querido Doc. Os planos dão errado de formas engraçadas e tocantes. Um retrato caloroso de gente simples.', 'Intermediário', array['comunidade', 'humor', 'califórnia', 'amizade', 'novela']),
  ('eb705727-46da-5312-9366-749826c55fc7', 'The Pearl', 'John Steinbeck', 'Ficção Clássica', 'en', 'Kino, um pescador de pérolas pobre, encontra uma pérola enorme e sonha com uma vida melhor para a família. A descoberta atrai cobiça e violência. Uma parábola curta, em linguagem direta, sobre ganância e esperança.', 'Iniciante', array['parábola', 'ganância', 'pobreza', 'novela', 'méxico']),
  ('5a5493bc-3599-5b17-8781-29a524f2e976', 'To Kill a Mockingbird', 'Harper Lee', 'Ficção Clássica', 'en', 'Na pequena cidade de Maycomb, a menina Scout vê o pai, o advogado Atticus Finch, defender um homem negro injustamente acusado. A história mostra o preconceito e a coragem de agir com decência. Um clássico sobre justiça e empatia visto pelos olhos de uma criança.', 'Intermediário', array['racismo', 'justiça', 'infância', 'alabama', 'clássico']),
  ('58ed62bd-30c8-57b4-8f79-bfed7e731c24', 'The Catcher in the Rye', 'J. D. Salinger', 'Ficção Clássica', 'en', 'Expulso do colégio, o adolescente Holden Caulfield vaga por Nova York durante alguns dias, entre solidão e revolta. A narrativa em primeira pessoa expõe seu desconforto com a hipocrisia dos adultos. Um retrato marcante da adolescência.', 'Intermediário', array['adolescência', 'alienação', 'nova york', 'juventude', 'clássico']),
  ('ace71f0d-59c9-5269-9b7e-18baee8068d2', 'Lord of the Flies', 'William Golding', 'Ficção Clássica', 'en', 'Um grupo de meninos ingleses fica preso numa ilha deserta e tenta se organizar sem adultos. Aos poucos, regras e razão dão lugar ao medo e à violência. Uma alegoria sombria sobre a fragilidade da civilização.', 'Intermediário', array['sobrevivência', 'ilha', 'civilização', 'crianças', 'alegoria']),
  ('03e417cb-cceb-5182-a25d-2e5d6dd51f11', 'Fahrenheit 451', 'Ray Bradbury', 'Ficção Científica', 'en', 'Num futuro em que os livros são proibidos, Guy Montag é um bombeiro cuja função é queimá-los. Um encontro inesperado o leva a questionar a sociedade que o cerca. Uma distopia sobre censura, entretenimento vazio e valor da leitura.', 'Intermediário', array['distopia', 'livros', 'censura', 'futuro', 'clássico']),
  ('87a48fd3-af75-5a05-a527-14aa7750e64c', 'The Martian Chronicles', 'Ray Bradbury', 'Ficção Científica', 'en', 'Uma série de histórias interligadas narra a chegada dos humanos a Marte e o efeito disso sobre os marcianos e sobre os próprios colonizadores. O tom alterna poesia, nostalgia e crítica. Um clássico melancólico da ficção científica.', 'Intermediário', array['marte', 'colonização', 'contos', 'solidão', 'clássico']),
  ('88724426-4493-5879-9971-f4f54ca41431', 'Slaughterhouse-Five', 'Kurt Vonnegut', 'Ficção Científica', 'en', 'Billy Pilgrim sobrevive ao bombardeio de Dresden na Segunda Guerra e passa a "saltar" por momentos de sua vida fora de ordem. Entre humor negro e extraterrestres, o livro tenta dar sentido ao horror. Um romance antiguerra singular.', 'Intermediário', array['guerra', 'viagem no tempo', 'sátira', 'dresden', 'absurdo']),
  ('a8f20fcf-0e98-5b4f-b60a-a2ae300a2c99', 'Cat''s Cradle', 'Kurt Vonnegut', 'Ficção Científica', 'en', 'Um escritor investiga a família do inventor da bomba atômica e acaba numa ilha caribenha onde surge uma religião inventada. A história passa por uma substância capaz de congelar o planeta. Uma sátira sobre ciência, fé e responsabilidade.', 'Intermediário', array['sátira', 'ciência', 'religião', 'fim do mundo', 'humor negro']),
  ('5230c403-8ec3-5f30-9afd-a0845aff4dfc', 'On the Road', 'Jack Kerouac', 'Ficção Clássica', 'en', 'Sal Paradise cruza os Estados Unidos com o carismático Dean Moriarty, atrás de aventura, música e sentido. A prosa rápida e livre virou símbolo da geração beat. Um retrato de inquietação e busca por liberdade.', 'Intermediário', array['beat', 'viagem', 'liberdade', 'estados unidos', 'juventude']),
  ('7e862e1c-3728-5096-b525-2be529e73567', 'In Cold Blood', 'Truman Capote', 'Mistério e Suspense', 'en', 'O livro reconstrói o assassinato de uma família no Kansas, em 1959, e a captura dos autores. Capote usa técnicas de romance para contar fatos reais. Um marco do chamado romance de não ficção.', 'Avançado', array['crime real', 'assassinato', 'kansas', 'jornalismo', 'não ficção']),
  ('fb21f651-67f2-590b-b179-a8b62cb3b7cb', 'Breakfast at Tiffany''s', 'Truman Capote', 'Ficção Clássica', 'en', 'Um escritor relembra Holly Golightly, sua vizinha encantadora e imprevisível, que vive de festas e de companhias ricas em Nova York. Por trás do charme, ela guarda inseguranças e uma vontade de liberdade. Uma novela curta e elegante.', 'Intermediário', array['nova york', 'novela', 'independência', 'anos 1940', 'identidade']),
  ('154f83d6-4ac3-5ec3-bf23-646b643a65d5', 'Go Tell It on the Mountain', 'James Baldwin', 'Ficção Clássica', 'en', 'Em Harlem, o adolescente John Grimes enfrenta a religiosidade rígida da família e os segredos do passado deles. A narrativa explora fé, culpa e identidade. Um romance de estreia profundo e poético.', 'Avançado', array['fé', 'família', 'harlem', 'racismo', 'formação']),
  ('813f27f4-4ed8-5335-9a04-c740a966dc67', 'Giovanni''s Room', 'James Baldwin', 'Ficção Clássica', 'en', 'David, um americano em Paris, se envolve com Giovanni e luta contra o medo de assumir quem é. O romance trata de desejo, vergonha e autoengano. Uma obra delicada e dolorosa sobre identidade.', 'Avançado', array['paris', 'identidade', 'desejo', 'sociedade', 'amor']),
  ('96ce0ffb-27fa-5e4e-b9a8-462c418e899d', 'Beloved', 'Toni Morrison', 'Ficção Clássica', 'en', 'Sethe, que foi escravizada, vive em Ohio assombrada pelo passado e pela presença de uma criança misteriosa. O romance enfrenta a memória e o custo da liberdade. Uma obra poderosa e dolorosa da literatura americana.', 'Avançado', array['escravidão', 'memória', 'trauma', 'mãe', 'pós-guerra civil']),
  ('bcaa5f40-3b30-5db1-a76d-6af1ee448fdb', 'The Bluest Eye', 'Toni Morrison', 'Ficção Clássica', 'en', 'Pecola, menina negra nos Estados Unidos dos anos 1940, deseja ter olhos azuis acreditando que isso a tornaria amada. A história mostra o peso do padrão de beleza imposto pela sociedade. Um romance duro e sensível.', 'Avançado', array['racismo', 'beleza', 'infância', 'ohio', 'identidade']),
  ('c998d277-980c-51bd-be25-5ee2f4ff2c80', 'Invisible Man', 'Ralph Ellison', 'Ficção Clássica', 'en', 'Um narrador sem nome, jovem negro, vai do Sul a Nova York e descobre que as pessoas só enxergam o que querem nele. A jornada passa por instituições, ideologias e desilusões. Um dos grandes romances sobre identidade e racismo nos Estados Unidos.', 'Avançado', array['racismo', 'identidade', 'nova york', 'sociedade', 'clássico']),
  ('588c9208-8ac8-5d3a-8ac5-cb8c237980e3', 'Native Son', 'Richard Wright', 'Ficção Clássica', 'en', 'Bigger Thomas, jovem negro e pobre em Chicago, comete um erro que o lança em uma espiral de medo e violência. O romance mostra como o racismo e a pobreza moldam suas escolhas. Uma obra forte e direta sobre injustiça social.', 'Intermediário', array['racismo', 'chicago', 'crime', 'sociedade', 'clássico']),
  ('3a0bfde9-56f3-5f84-9911-10ce349593d2', 'The Color Purple', 'Alice Walker', 'Ficção Clássica', 'en', 'Celie, mulher negra do sul dos Estados Unidos, conta em cartas a violência que sofre e sua lenta redescoberta de si. A amizade com Shug Avery lhe abre caminhos de afeto e coragem. Um romance sobre resiliência e dignidade.', 'Intermediário', array['cartas', 'racismo', 'mulheres', 'amizade', 'sul dos eua']),
  ('0db4a9b9-3369-5904-8ff8-d634372bf286', 'Their Eyes Were Watching God', 'Zora Neale Hurston', 'Ficção Clássica', 'en', 'Janie Crawford conta como buscou amor e voz própria ao longo de três casamentos na Flórida. A linguagem mistura narração poética e dialeto falado. Um clássico sobre autonomia feminina e identidade negra.', 'Avançado', array['amor', 'independência', 'flórida', 'mulheres', 'dialeto']),
  ('0a7acbfa-ac6f-54ea-a3fe-94a0d74fd222', 'Mrs Dalloway', 'Virginia Woolf', 'Ficção Clássica', 'en', 'Num único dia em Londres, Clarissa Dalloway prepara uma festa enquanto lembra do passado. Em paralelo, o veterano de guerra Septimus sofre com os traumas do conflito. Um romance moderno sobre memória, tempo e vida interior.', 'Avançado', array['londres', 'modernismo', 'fluxo de consciência', 'tempo', 'sociedade']),
  ('2a417d3a-f5f9-5f73-b8cb-503e2c54ff9a', 'To the Lighthouse', 'Virginia Woolf', 'Ficção Clássica', 'en', 'Numa casa de veraneio escocesa, a família Ramsay planeja um passeio ao farol que acaba adiado. Os anos passam, a guerra chega e as pessoas mudam. Um romance sobre o tempo, a perda e a percepção.', 'Avançado', array['modernismo', 'família', 'tempo', 'memória', 'fluxo de consciência']),
  ('a2eeeed0-0fb6-5c90-b38f-7a48a2e13a79', 'Orlando', 'Virginia Woolf', 'Ficção Clássica', 'en', 'Orlando atravessa séculos de história inglesa sem envelhecer muito e, em certo ponto, passa a viver como mulher. A obra brinca com biografia, gênero e literatura. Uma fantasia irreverente e inventiva.', 'Avançado', array['fantasia', 'gênero', 'biografia', 'séculos', 'humor']),
  ('d2479f60-7c70-52ec-8178-9e65a096259c', 'Ulysses', 'James Joyce', 'Ficção Clássica', 'en', 'Em um único dia de 1904 em Dublin, o publicitário Leopold Bloom e o jovem Stephen Dedalus percorrem a cidade em paralelo à Odisseia de Homero. O romance experimenta estilos e vozes a cada capítulo. Uma obra desafiadora e central do modernismo.', 'Avançado', array['modernismo', 'dublin', 'um dia', 'experimental', 'odisseia']),
  ('51611bf8-c736-5f0e-b63e-6b5509c71d5e', 'Dubliners', 'James Joyce', 'Contos', 'en', 'Quinze contos retratam a vida comum em Dublin, da infância à velhice. Cada história revela frustração, hábito e raros momentos de lucidez. Uma coletânea precisa e melancólica.', 'Avançado', array['dublin', 'irlanda', 'cotidiano', 'contos', 'modernismo']),
  ('aab5ce15-3c46-5da1-96ce-61fc150ceedd', 'A Portrait of the Artist as a Young Man', 'James Joyce', 'Ficção Clássica', 'en', 'Stephen Dedalus cresce na Irlanda, entre família, religião e vocação artística, até decidir partir. A linguagem acompanha seu amadurecimento. Um romance de formação sobre liberdade e criação.', 'Avançado', array['formação', 'irlanda', 'religião', 'arte', 'modernismo']),
  ('7fda0fc9-6659-5fb9-999a-9dbab460f803', 'Sons and Lovers', 'D. H. Lawrence', 'Ficção Clássica', 'en', 'Paul Morel cresce numa família de mineradores na Inglaterra, preso à forte ligação com a mãe. Seus relacionamentos amorosos esbarram nesse laço. Um romance de formação intenso e semiautobiográfico.', 'Avançado', array['família', 'classe operária', 'amor', 'inglaterra', 'formação']),
  ('64fd3dd3-a421-5fe7-9e27-9c860f939b7d', 'Lady Chatterley''s Lover', 'D. H. Lawrence', 'Ficção Clássica', 'en', 'Constance Chatterley, casada com um aristocrata paralisado, se aproxima do guarda de caça da propriedade. O romance une desejo, classe social e crítica à frieza da vida industrial. Foi censurado por anos pela abordagem franca da sexualidade.', 'Avançado', array['desejo', 'classe social', 'polêmico', 'inglaterra', 'casamento']),
  ('66c27f92-1e6b-5222-8d89-03f349f096bf', 'A Passage to India', 'E. M. Forster', 'Ficção Clássica', 'en', 'Na Índia britânica, uma visita às cavernas de Marabar termina em uma acusação grave contra o médico indiano Aziz. O episódio expõe o abismo entre colonizadores e colonizados. Um romance sobre amizade, preconceito e mal-entendidos culturais.', 'Avançado', array['colonialismo', 'índia', 'amizade', 'justiça', 'império britânico']),
  ('a280b968-39ae-510b-9c12-325a5d3f617e', 'Howards End', 'E. M. Forster', 'Ficção Clássica', 'en', 'As irmãs Schlegel, intelectuais e idealistas, se cruzam com os ricos Wilcox e com o pobre Leonard Bast. A disputa em torno de uma casa de campo reflete tensões entre classes. Um romance sobre conexão humana e herança.', 'Avançado', array['classes sociais', 'família', 'casa', 'inglaterra', 'edwardiano']),
  ('596a8e89-ecb3-5c50-8982-408e8ec0b394', 'A Room with a View', 'E. M. Forster', 'Romance', 'en', 'Lucy Honeychurch conhece pessoas inesperadas na Itália e começa a questionar as convenções que a guiam. Ao voltar à Inglaterra, precisa escolher entre o conforto e a paixão. Um romance leve e irônico sobre liberdade de escolha.', 'Intermediário', array['itália', 'romance', 'sociedade', 'juventude', 'edwardiano']),
  ('26617f90-47ae-5de4-b13c-2cdb8c40f15b', 'Brideshead Revisited', 'Evelyn Waugh', 'Ficção Clássica', 'en', 'Charles Ryder relembra sua amizade com Sebastian Flyte e a convivência com a família Marchmain na mansão de Brideshead. Entre privilégio, fé e perdas, o passado se transforma em memória. Um romance melancólico sobre nostalgia e catolicismo.', 'Avançado', array['nostalgia', 'aristocracia', 'religião', 'amizade', 'inglaterra']),
  ('a82fbbe3-7a9d-5ba3-81c7-89f8fe30f4a5', 'Rebecca', 'Daphne du Maurier', 'Mistério e Suspense', 'en', 'Uma jovem sem nome se casa com o rico Maxim de Winter e vai morar em Manderley, onde a memória de sua primeira esposa, Rebecca, ainda domina tudo. Aos poucos, segredos vêm à tona. Um suspense gótico sobre ciúme e insegurança.', 'Intermediário', array['gótico', 'suspense', 'mansão', 'casamento', 'mistério']),
  ('24b9982e-efeb-5471-a086-9c936f25ce5f', 'Lolita', 'Vladimir Nabokov', 'Ficção Clássica', 'en', 'O narrador, Humbert Humbert, tenta justificar sua obsessão por uma menina, e a linguagem sedutora que usa esconde um abuso. O livro expõe a manipulação por trás do discurso do narrador. Um romance polêmico e de rara sofisticação verbal.', 'Avançado', array['polêmico', 'narrador não confiável', 'literatura', 'eua', 'moral']),
  ('41d8e870-2439-518d-bd6d-b7ff99dd15d3', 'The Bell Jar', 'Sylvia Plath', 'Ficção Clássica', 'en', 'Esther Greenwood, jovem promissora, passa um verão em Nova York e começa a afundar em uma depressão profunda. O romance acompanha sua perda de sentido e sua busca por recuperação. Um retrato franco da saúde mental.', 'Intermediário', array['depressão', 'juventude', 'mulheres', 'anos 1950', 'autobiográfico']),
  ('7773acad-11fe-5b41-b767-924d00f2e2d4', 'One Flew Over the Cuckoo''s Nest', 'Ken Kesey', 'Ficção Clássica', 'en', 'Randle McMurphy chega a uma ala psiquiátrica e desafia o controle rígido da enfermeira Ratched. A história é narrada pelo silencioso Chefe Bromden. Um romance sobre liberdade e autoridade.', 'Intermediário', array['hospital psiquiátrico', 'rebeldia', 'poder', 'liberdade', 'clássico']),
  ('bb67a468-dbc9-553e-8487-a7b81371e4ee', 'Catch-22', 'Joseph Heller', 'Ficção Clássica', 'en', 'O capitão Yossarian, bombardeiro na Segunda Guerra, tenta escapar das missões, mas as regras do exército o prendem num paradoxo. Entre humor e horror, o livro satiriza a burocracia da guerra. Um clássico do absurdo.', 'Avançado', array['guerra', 'sátira', 'absurdo', 'burocracia', 'humor negro']),
  ('5496f63d-0227-5282-8539-8b2ddd6db301', 'The Sound and the Fury', 'William Faulkner', 'Ficção Clássica', 'en', 'A decadência da família Compson, no Mississippi, é contada por quatro pontos de vista diferentes. A estrutura fragmentada exige atenção do leitor. Uma obra-prima difícil e influente do modernismo.', 'Avançado', array['sul dos eua', 'família', 'decadência', 'experimental', 'modernismo']),
  ('badfefee-a326-56e7-9b4d-b3655ec8ff44', 'As I Lay Dying', 'William Faulkner', 'Ficção Clássica', 'en', 'A família Bundren atravessa o Mississippi para enterrar a mãe, Addie, na cidade onde ela pediu para ser sepultada. A viagem é narrada por quinze vozes diferentes. Uma história de dor, orgulho e absurdo.', 'Avançado', array['sul dos eua', 'família', 'morte', 'vozes', 'modernismo']),
  ('7b6cfc3b-fc47-5a80-9fee-686c9f2a5da4', 'Alice''s Adventures in Wonderland', 'Lewis Carroll', 'Fantasia', 'en', 'Numa tarde quente, Alice segue um coelho branco de colete até uma toca e cai num mundo onde tudo muda de tamanho e de regra. Ela encontra o Gato de Cheshire, o Chapeleiro Maluco num chá sem fim e a Rainha de Copas, que manda cortar cabeças por qualquer coisa. O livro brinca com a lógica, a linguagem e o jeito dos sonhos.', 'Intermediário', array['clássico', 'fantasia', 'nonsense', 'infantil', 'coelho branco'])
insert into public.livros (id, titulo, autor, genero, idioma, resumo, nivel_dificuldade, tags) values
  ('19d8ef05-d878-5112-9771-d57256652724', 'Through the Looking-Glass', 'Lewis Carroll', 'Fantasia', 'en', 'Alice atravessa o espelho da sala e chega a um mundo organizado como um tabuleiro de xadrez, onde tudo é ao contrário. Ela encontra a Rainha Vermelha, os gêmeos Tweedledum e Tweedledee, o Humpty Dumpty e o poema do Jabberwocky. Seu objetivo é chegar ao último quadrado para virar rainha.', 'Intermediário', array['clássico', 'fantasia', 'xadrez', 'espelho', 'nonsense']),
  ('856bab55-3a37-55f8-a16a-7b6e8367255f', 'The Wonderful Wizard of Oz', 'L. Frank Baum', 'Fantasia', 'en', 'Um ciclone leva a casa de Dorothy, do Kansas, até a terra de Oz. Para voltar, ela segue a estrada de tijolos amarelos até a Cidade das Esmeraldas, onde mora o Mágico, e no caminho faz amizade com o Espantalho, o Homem de Lata e o Leão Covarde, cada um em busca de algo. No livro, os sapatos mágicos são de prata, não vermelhos como no filme.', 'Intermediário', array['clássico', 'fantasia', 'aventura', 'amizade', 'oz']),
  ('c8beade6-ff16-5d5a-95f0-ee5b1b788159', 'Peter Pan', 'J. M. Barrie', 'Fantasia', 'en', 'Wendy e os irmãos voam com Peter Pan até a Terra do Nunca, onde crianças não crescem. Lá enfrentam o Capitão Gancho e fazem amizade com Sininho. Uma história sobre infância e a dor de crescer.', 'Intermediário', array['clássico', 'fantasia', 'infância', 'aventura', 'terra do nunca']),
  ('540bd37f-fb2b-53ba-869f-c114c098d20c', 'The Secret Garden', 'Frances Hodgson Burnett', 'Infantil', 'en', 'Mary Lennox, uma menina mimada, perde os pais na Índia e vai morar numa mansão enorme em Yorkshire com um tio distante. Ali ela ouve choros à noite, descobre um jardim trancado há dez anos e ganha a ajuda do menino Dickon. Cuidar do jardim muda Mary e também o primo doente, Colin, escondido num quarto da casa.', 'Intermediário', array['clássico', 'jardim', 'amizade', 'cura', 'inglaterra']),
  ('486a3c7e-6f0c-5124-bb8f-dfa5b6f089ec', 'A Little Princess', 'Frances Hodgson Burnett', 'Infantil', 'en', 'Sara Crewe, filha de um pai rico, estuda num internato de Londres e é tratada como princesa pela diretora, a senhorita Minchin. Quando o pai morre e a fortuna desaparece, Sara é mandada para um sótão e vira criada da escola. Ela se agarra à imaginação e à amizade da copeira Becky, até que o vizinho do lado muda o seu destino.', 'Intermediário', array['clássico', 'imaginação', 'internato', 'bondade', 'londres']),
  ('ea5e1c42-723d-578e-bb27-d1210155f307', 'Little Women', 'Louisa May Alcott', 'Ficção Clássica', 'en', 'Meg, Jo, Beth e Amy March crescem juntas na Nova Inglaterra durante a Guerra Civil americana. Cada uma persegue sonhos e enfrenta perdas à sua maneira. Um retrato afetuoso de família e amadurecimento.', 'Intermediário', array['clássico', 'irmãs', 'família', 'juventude', 'estados unidos']),
  ('3216d8c2-9903-514e-8c4b-dad9d196cafc', 'Anne of Green Gables', 'L. M. Montgomery', 'Juvenil', 'en', 'Os irmãos Marilla e Matthew Cuthbert pedem um menino para ajudar na fazenda, mas por engano chega Anne Shirley, uma órfã de onze anos, ruiva e muito falante. Ela transforma a vida em Avonlea, na Ilha do Príncipe Eduardo, com a imaginação, a amizade com Diana e a rivalidade com Gilbert Blythe. A história acompanha seu crescimento até a idade adulta.', 'Intermediário', array['clássico', 'órfã', 'imaginação', 'família', 'canadá']),
  ('a6a3854e-6978-5d7e-af02-37cbaf8a1e80', 'Black Beauty', 'Anna Sewell', 'Infantil', 'en', 'Black Beauty, um cavalo de pelagem negra, conta a própria vida: dos prados da infância na Inglaterra a donos gentis, a donos cruéis e aos anos puxando carros de aluguel em Londres. Pelo caminho encontra a égua Ginger e o pônei Merrylegs, e vê o que o cansaço e os maus-tratos fazem com os animais. O livro foi escrito para pedir bondade com os cavalos.', 'Intermediário', array['clássico', 'cavalos', 'animais', 'bondade', 'inglaterra']),
  ('21bd1db0-285d-5df7-932e-13e9b7f7cff2', 'The Wind in the Willows', 'Kenneth Grahame', 'Infantil', 'en', 'A Toupeira, cansada da faxina de primavera, sai de casa e conhece o Rato d''Água na beira do rio. Os dois fazem amizade com o sábio Texugo e o Sapo, rico e doido por carros, que acaba preso por roubá-los. Quando o Sapo foge, os amigos tentam retomar o castelo dele, tomado pelos furões e doninhas da Floresta Selvagem.', 'Intermediário', array['clássico', 'animais', 'amizade', 'rio', 'aventura']),
  ('94589c1c-f161-5520-87c2-bf3696f1a01c', 'Winnie-the-Pooh', 'A. A. Milne', 'Infantil', 'en', 'Os brinquedos de Christopher Robin, como o ursinho Pooh, o Leitão e o Bisonho, vivem pequenas aventuras na Floresta dos Cem Acres. As histórias são curtas, doces e cheias de humor ingênuo. Um clássico sobre amizade e simplicidade.', 'Iniciante', array['clássico', 'ursinho', 'amizade', 'infantil', 'floresta']),
  ('6944fa9c-fd07-501c-b6a7-f952a97985de', 'The House at Pooh Corner', 'A. A. Milne', 'Infantil', 'en', 'Pooh e seus amigos ganham a companhia do saltitante Tigrão e continuam suas aventuras na floresta. No fim, Christopher Robin precisa seguir em frente e crescer. Uma continuação doce e levemente melancólica.', 'Iniciante', array['clássico', 'ursinho', 'amizade', 'infantil', 'despedida']),
  ('f20f160d-a5b0-54fa-bafb-8a0253cc2a3e', 'The Tale of Peter Rabbit', 'Beatrix Potter', 'Infantil', 'en', 'O coelhinho Peter ignora o conselho da mãe e entra no jardim do senhor McGregor para comer legumes. Ele quase é pego e volta para casa cansado e assustado. Um conto curto e ilustrado sobre desobediência e susto.', 'Iniciante', array['clássico', 'coelho', 'travessura', 'infantil', 'jardim']),
  ('6182f61f-6fe0-509f-8046-7f184cf93ae0', 'The Lion, the Witch and the Wardrobe', 'C. S. Lewis', 'Fantasia', 'en', 'Quatro irmãos entram em Nárnia por um guarda-roupa e encontram um reino congelado pela Feiticeira Branca. Com a ajuda do leão Aslan, eles enfrentam a bruxa e descobrem seu papel. O primeiro livro das Crônicas de Nárnia.', 'Intermediário', array['clássico', 'fantasia', 'nárnia', 'irmãos', 'aventura']),
  ('035b5c5c-22ec-5bce-8788-099e4115b16e', 'Prince Caspian', 'C. S. Lewis', 'Fantasia', 'en', 'Os irmãos Pevensie voltam a Nárnia e encontram um reino mudado, onde o jovem príncipe Caspian luta para recuperar o trono. Eles ajudam a despertar o espírito antigo da terra. Uma aventura sobre fé e coragem.', 'Intermediário', array['clássico', 'fantasia', 'nárnia', 'aventura', 'coragem']),
  ('bf32394b-598b-5fa4-8298-880937aa1d4a', 'The Voyage of the Dawn Treader', 'C. S. Lewis', 'Fantasia', 'en', 'Edmund, Lucy e o primo Eustace embarcam com o rei Caspian numa viagem marítima até os confins do mundo. Cada ilha traz um desafio, e Eustace passa por uma transformação inesperada. Uma aventura de descobertas.', 'Intermediário', array['clássico', 'fantasia', 'nárnia', 'viagem', 'mar']),
  ('3a03e822-d203-53e5-9a3c-98497d719240', 'The Hobbit', 'J. R. R. Tolkien', 'Fantasia', 'en', 'O pacato Bilbo Bolseiro é convidado pelo mago Gandalf e por treze anões a recuperar um tesouro guardado pelo dragão Smaug. Na viagem, ele descobre coragem e um anel misterioso. A aventura que antecede O Senhor dos Anéis.', 'Intermediário', array['clássico', 'fantasia', 'dragão', 'aventura', 'terra média']),
  ('d0787e73-5596-5c06-aba7-645c525d5abd', 'Charlie and the Chocolate Factory', 'Roald Dahl', 'Infantil', 'en', 'O pobre Charlie Bucket ganha um bilhete dourado e visita a misteriosa fábrica de chocolate de Willy Wonka. Os outros ganhadores, mimados e gananciosos, enfrentam consequências divertidas. Uma fábula bem-humorada sobre bondade e ganância.', 'Intermediário', array['dahl', 'humor', 'chocolate', 'fábrica', 'crianças']),
  ('edec0269-8394-5358-adf6-93b94e7e8864', 'Matilda', 'Roald Dahl', 'Infantil', 'en', 'Matilda é uma menina genial, ignorada pelos pais e adoradora de livros. Na escola, ela enfrenta a diretora cruel, Trunchbull, e descobre poderes inesperados. Uma história sobre inteligência, justiça e amor pela leitura.', 'Intermediário', array['dahl', 'humor', 'inteligência', 'escola', 'livros']),
  ('6c9de171-b780-5c01-9188-2ef71b7a576e', 'James and the Giant Peach', 'Roald Dahl', 'Infantil', 'en', 'Depois de fugir das tias cruéis, James entra num pêssego gigante e viaja com insetos falantes. A aventura leva o grupo através do oceano até Nova York. Uma fantasia divertida e cheia de rimas.', 'Intermediário', array['dahl', 'humor', 'aventura', 'insetos', 'fantasia']),
  ('ef86041a-df34-5187-97d7-0355a02085e5', 'The BFG', 'Roald Dahl', 'Infantil', 'en', 'A órfã Sophie é levada por um gigante gentil que coleta e distribui sonhos, mas os outros gigantes devoram crianças. Os dois bolam um plano para detê-los. Uma aventura cheia de palavras inventadas.', 'Intermediário', array['dahl', 'gigante', 'fantasia', 'humor', 'amizade']),
  ('7efae1ce-9038-5edf-bf97-4b7206c42b2f', 'The Witches', 'Roald Dahl', 'Infantil', 'en', 'Um menino e sua avó descobrem que as bruxas existem e odeiam crianças. Quando uma reunião delas é descoberta, os dois tentam impedir o plano macabro. Um livro sombrio, engraçado e cheio de suspense.', 'Intermediário', array['dahl', 'bruxas', 'humor', 'aventura', 'sombrio']),
  ('01a66ae7-7a91-56fb-bc8e-22a02fd66b03', 'Fantastic Mr Fox', 'Roald Dahl', 'Infantil', 'en', 'Uma raposa esperta rouba de três fazendeiros malvados, que passam a caçar a família dela. Para sobreviver, os animais cavam túneis e bolam um grande plano. Uma história curta sobre esperteza e cooperação.', 'Iniciante', array['dahl', 'raposa', 'humor', 'esperteza', 'animais']),
  ('a70a917b-53fc-5b10-9534-b84d12626a6f', 'The Twits', 'Roald Dahl', 'Infantil', 'en', 'O casal Twit é nojento e cruel, e os dois vivem passando truques sujos um no outro. Os animais que eles maltratam decidem se vingar. Um livro curto, engraçado e exagerado.', 'Iniciante', array['dahl', 'humor', 'travessuras', 'vingança', 'animais']),
  ('346a9977-4918-59a1-b68a-0571311488e9', 'George''s Marvellous Medicine', 'Roald Dahl', 'Infantil', 'en', 'Cansado da avó rabugenta, George mistura todo tipo de produto doméstico numa poção para consertá-la. O resultado é bem diferente do esperado. Uma história curta, cheia de humor e exagero.', 'Iniciante', array['dahl', 'humor', 'poção', 'avó', 'travessura']),
  ('0e6d413f-ff12-5d16-bd71-caa2c8840d4a', 'Danny, the Champion of the World', 'Roald Dahl', 'Infantil', 'en', 'Danny vive com o pai, mecânico, num trailer, e descobre que ele tem um segredo ligado a faisões. Juntos, planejam uma ousada travessura contra um vizinho rico e arrogante. Uma história sobre amor entre pai e filho.', 'Intermediário', array['dahl', 'pai e filho', 'aventura', 'campo', 'humor']),
  ('80504b2e-e80b-588f-8af3-e9343afb616f', 'Charlotte''s Web', 'E. B. White', 'Infantil', 'en', 'O porquinho Wilbur é salvo do abate pela amiga Charlotte, uma aranha que tece palavras na teia. Ao longo das estações, a amizade das duas enfrenta o tempo e a perda. Um clássico delicado sobre lealdade e despedida.', 'Intermediário', array['clássico', 'amizade', 'animais', 'fazenda', 'infância']),
  ('9fe97ec7-f9be-5139-b707-88e2cf054688', 'Stuart Little', 'E. B. White', 'Infantil', 'en', 'Stuart, um menino do tamanho de um rato, nasce numa família humana de Nova York e vive aventuras pela cidade. Corajoso e curioso, ele sai em busca de uma amiga. Uma história leve e inventiva.', 'Intermediário', array['clássico', 'aventura', 'humor', 'nova york', 'família']),
  ('2d01cb67-29b7-5dfd-8d6e-979de4d0238c', 'The Trumpet of the Swan', 'E. B. White', 'Infantil', 'en', 'Louis, um cisne que nasce sem voz, aprende a tocar trompete para se comunicar e conquistar a amada. Para ajudar o pai, ele enfrenta o mundo humano. Uma história de superação e música.', 'Intermediário', array['clássico', 'cisne', 'música', 'superação', 'natureza']),
  ('35db896e-bb97-5085-90e2-1e36b1abff09', 'The Cat in the Hat', 'Dr. Seuss', 'Infantil', 'en', 'Num dia chuvoso, dois irmãos recebem a visita de um gato travesso de chapéu listrado que transforma a casa numa bagunça. A mãe vai chegar e é preciso arrumar tudo. Um clássico das primeiras leituras, cheio de rimas.', 'Iniciante', array['seuss', 'rimas', 'humor', 'leitor iniciante', 'gato']),
  ('665dc2f0-d09d-525b-9368-e502bcce9a3d', 'Green Eggs and Ham', 'Dr. Seuss', 'Infantil', 'en', 'Sam-I-Am tenta convencer um personagem ranzinza a provar ovos verdes e presunto, em qualquer lugar e de qualquer jeito. A repetição divertida leva a um final inesperado. Um livro de vocabulário curto e muita insistência.', 'Iniciante', array['seuss', 'rimas', 'humor', 'leitor iniciante', 'insistência']),
  ('11c7eedf-c040-572a-b129-453bcbe05a1d', 'How the Grinch Stole Christmas!', 'Dr. Seuss', 'Infantil', 'en', 'O Grinch, que vive no alto de uma montanha, odeia o Natal e decide roubá-lo dos moradores de Whoville. Eles, porém, celebram mesmo sem os presentes. Uma história curta e rimada sobre o verdadeiro sentido da data.', 'Iniciante', array['seuss', 'natal', 'rimas', 'generosidade', 'humor']),
  ('bd286ba1-7194-5041-8b5c-44d2ba2e4a81', 'Oh, the Places You''ll Go!', 'Dr. Seuss', 'Infantil', 'en', 'Em versos rimados, o livro acompanha alguém que parte rumo ao futuro, entre subidas, quedas e momentos de dúvida. A mensagem é seguir em frente com coragem e otimismo. Um clássico motivacional de presente.', 'Iniciante', array['seuss', 'rimas', 'motivação', 'vida', 'formatura']),
  ('75343d77-a9d1-58ed-87d7-6589fc533895', 'Horton Hears a Who!', 'Dr. Seuss', 'Infantil', 'en', 'O elefante Horton ouve vozes vindas de um grão de poeira e decide proteger os pequenos habitantes, apesar da zombaria dos outros animais. A lição é que uma pessoa é uma pessoa, não importa o tamanho. Uma história rimada sobre empatia.', 'Iniciante', array['seuss', 'rimas', 'empatia', 'elefante', 'igualdade']),
  ('bd24c0d4-74fa-5caf-a53c-e82d4fa1d9a7', 'The Lorax', 'Dr. Seuss', 'Infantil', 'en', 'O Once-ler corta as árvores Truffula para fabricar produtos, apesar dos avisos do Lorax, que fala em nome da natureza. Quando as árvores acabam, resta um alerta. Uma fábula rimada sobre meio ambiente e consumo.', 'Iniciante', array['seuss', 'meio ambiente', 'rimas', 'natureza', 'responsabilidade']),
  ('110133a3-5f8c-5f4b-a80b-5029567db833', 'Where the Wild Things Are', 'Maurice Sendak', 'Infantil', 'en', 'Max, mandado para a cama sem jantar depois de uma travessura, navega até uma ilha de criaturas selvagens e é coroado rei. Ao final, ele sente saudade de casa. Um livro ilustrado sobre raiva, imaginação e afeto.', 'Iniciante', array['livro ilustrado', 'imaginação', 'infância', 'emoções', 'clássico']),
  ('ebf48287-3df6-51a0-bdc4-b13f7c5c72b5', 'The Giving Tree', 'Shel Silverstein', 'Infantil', 'en', 'Uma árvore dá tudo o que tem a um menino que, ao crescer, volta sempre pedindo mais. O livro, com texto simples e traço minimalista, convida a pensar sobre amor e doação. Um clássico que divide opiniões e emociona.', 'Iniciante', array['fábula', 'generosidade', 'amizade', 'árvore', 'clássico']),
  ('1ae8b78d-0498-54b8-8e4e-98f5317c9693', 'Where the Sidewalk Ends', 'Shel Silverstein', 'Poesia', 'en', 'Um livro de poemas curtos e ilustrações engraçadas, que falam de criaturas absurdas, travessuras e emoções. A linguagem simples e o humor nonsense agradam crianças e adultos. Uma ótima porta de entrada para a poesia.', 'Iniciante', array['poesia', 'humor', 'infantil', 'ilustrado', 'rimas']),
  ('86e594b4-e431-5dc4-b245-f70bf5832095', 'The Very Hungry Caterpillar', 'Eric Carle', 'Infantil', 'en', 'Uma lagarta faminta come uma quantidade crescente de alimentos ao longo da semana e depois se transforma em borboleta. O livro ensina dias da semana e números de forma divertida. Excelente para vocabulário básico em inglês.', 'Iniciante', array['livro ilustrado', 'lagarta', 'números', 'dias da semana', 'infantil']),
  ('7c7bb064-1a28-5c47-be22-0b80c71700c6', 'Goodnight Moon', 'Margaret Wise Brown', 'Infantil', 'en', 'Um coelhinho dá boa-noite a cada objeto do seu quarto antes de dormir. O ritmo calmo e as rimas formam um ritual de sono. Um clássico para ler em voz alta.', 'Iniciante', array['livro ilustrado', 'hora de dormir', 'rimas', 'infantil', 'clássico']),
  ('9cda4492-f3a6-5e88-9269-f8ac5bbfe1ca', 'The Velveteen Rabbit', 'Margery Williams', 'Infantil', 'en', 'Um coelho de pelúcia deseja se tornar real e aprende que isso só acontece por meio do amor de uma criança. A história fala de afeto, perda e transformação. Uma fábula terna sobre o que nos torna reais.', 'Iniciante', array['clássico', 'amor', 'brinquedos', 'infância', 'fábula']),
  ('d6915e58-06b7-5900-9fc3-0b0c45101b58', 'The Polar Express', 'Chris Van Allsburg', 'Infantil', 'en', 'Na véspera de Natal, um menino embarca num trem misterioso rumo ao Polo Norte. Lá, ele recebe um presente especial que só quem acredita pode ouvir. Um livro ilustrado sobre magia e confiança.', 'Iniciante', array['natal', 'livro ilustrado', 'fantasia', 'fé', 'infância']),
  ('c01e148b-f5e3-5461-9cf8-96ebaaa6b765', 'Holes', 'Louis Sachar', 'Juvenil', 'en', 'Stanley Yelnats é enviado a um acampamento no deserto onde meninos cavam buracos todos os dias. Aos poucos, ele descobre um segredo ligado à sua família e ao passado do lugar. Uma aventura inteligente sobre amizade e justiça.', 'Intermediário', array['mistério', 'acampamento', 'amizade', 'destino', 'aventura']),
  ('9d2e4ebe-d242-5082-ab40-6a24977101b6', 'The Giver', 'Lois Lowry', 'Ficção Científica', 'en', 'Jonas vive numa comunidade aparentemente perfeita, sem dor nem escolhas. Quando é designado para receber as memórias do passado, ele descobre o que foi sacrificado. Uma distopia juvenil sobre liberdade e emoção.', 'Intermediário', array['distopia', 'memória', 'juvenil', 'sociedade', 'liberdade']),
  ('93bb73f8-f6c6-565e-900a-573fe7485cc5', 'Number the Stars', 'Lois Lowry', 'Juvenil', 'en', 'Na Dinamarca ocupada pelos nazistas, a menina Annemarie ajuda a amiga judia Ellen a escapar. A história mostra o risco e a coragem de pessoas comuns. Um romance histórico sensível para jovens leitores.', 'Intermediário', array['segunda guerra', 'dinamarca', 'coragem', 'amizade', 'história']),
  ('6fafc6c2-0d9e-5fb0-ae4a-d3998089a1be', 'Bridge to Terabithia', 'Katherine Paterson', 'Juvenil', 'en', 'Jess e Leslie criam um reino imaginário na floresta e fortalecem sua amizade. Um acontecimento trágico muda tudo e obriga Jess a lidar com a dor. Uma história comovente sobre amizade e luto.', 'Intermediário', array['amizade', 'imaginação', 'perda', 'infância', 'escola']),
  ('21780c61-09eb-5753-bcdb-60626aa23b53', 'A Wrinkle in Time', 'Madeleine L''Engle', 'Ficção Científica', 'en', 'Meg Murry, o irmão Charles Wallace e o amigo Calvin viajam pelo universo para resgatar o pai, cientista desaparecido. Eles enfrentam uma força sombria que ameaça o mundo. Uma aventura de ficção científica sobre amor e coragem.', 'Intermediário', array['ficção científica', 'juvenil', 'família', 'viagem', 'coragem']),
  ('06c7103b-6926-5dc2-8389-486a1c337a6e', 'Island of the Blue Dolphins', 'Scott O''Dell', 'Juvenil', 'en', 'Karana, uma menina indígena, fica sozinha numa ilha da Califórnia e aprende a sobreviver por anos. A história é inspirada em fatos reais. Um livro sobre coragem, solidão e convivência com a natureza.', 'Intermediário', array['sobrevivência', 'ilha', 'coragem', 'baseado em fatos', 'juvenil']),
  ('09f4f36f-a7a9-550a-bfb5-0a029159b93e', 'Hatchet', 'Gary Paulsen', 'Juvenil', 'en', 'Depois de um acidente de avião, o adolescente Brian Robeson sobrevive sozinho na mata canadense com apenas um machadinho. Ele aprende a caçar, fazer fogo e enfrentar o medo. Uma aventura direta e envolvente de sobrevivência.', 'Iniciante', array['sobrevivência', 'natureza', 'aventura', 'juvenil', 'superação']),
  ('805ba77d-7ef2-59ef-842a-e3b129e33725', 'Diary of a Wimpy Kid', 'Jeff Kinney', 'Humor', 'en', 'Greg Heffley registra em um diário ilustrado seu primeiro ano numa escola de ensino fundamental II, repleto de gafes e planos para ser popular. O formato mistura texto curto e desenhos. Uma leitura leve e engraçada para iniciantes.', 'Iniciante', array['humor', 'escola', 'diário', 'quadrinhos', 'juvenil']),
  ('ff2623c7-8ce2-5aec-bfd8-6d0dd95fb6a7', 'Harry Potter and the Philosopher''s Stone', 'J. K. Rowling', 'Fantasia', 'en', 'Harry, um menino órfão criado pelos tios, descobre aos onze anos que é bruxo e vai estudar em Hogwarts. Lá ele faz amigos, descobre seu passado e se envolve num mistério em torno de uma pedra poderosa. O livro que iniciou a série mais famosa da fantasia moderna.', 'Intermediário', array['harry potter', 'magia', 'hogwarts', 'amizade', 'juvenil']),
  ('52f4cf4a-e563-5160-88e6-a4535cfe09c5', 'Harry Potter and the Chamber of Secrets', 'J. K. Rowling', 'Fantasia', 'en', 'No segundo ano em Hogwarts, ataques misteriosos paralisam alunos e uma antiga lenda sobre uma câmara secreta volta à tona. Harry e os amigos investigam, enquanto ele tenta entender por que só ele ouve uma voz estranha. Um mistério sombrio e cheio de descobertas.', 'Intermediário', array['harry potter', 'magia', 'hogwarts', 'mistério', 'juvenil']),
  ('d87d23f2-bb55-5690-a3ab-8e8591484a7c', 'Harry Potter and the Prisoner of Azkaban', 'J. K. Rowling', 'Fantasia', 'en', 'Sirius Black escapa da prisão de Azkaban e todos acreditam que ele quer atacar Harry. Enquanto os guardas da prisão cercam Hogwarts, Harry descobre verdades sobre a história de seus pais. Um livro mais maduro, cheio de reviravoltas.', 'Intermediário', array['harry potter', 'magia', 'hogwarts', 'passado', 'juvenil']),
  ('4cdb66a4-9381-5644-9d30-761b8c751af7', 'Harry Potter and the Goblet of Fire', 'J. K. Rowling', 'Fantasia', 'en', 'Hogwarts recebe o Torneio Tribruxo, e Harry é escolhido de forma misteriosa como um quarto competidor. Ele enfrenta provas perigosas enquanto uma ameaça maior se aproxima. Um marco na série, em que o tom fica mais sombrio.', 'Intermediário', array['harry potter', 'magia', 'torneio', 'hogwarts', 'juvenil']),
  ('e1de2d58-1435-50f4-acb9-8fd90e33eba4', 'Harry Potter and the Order of the Phoenix', 'J. K. Rowling', 'Fantasia', 'en', 'O Ministério da Magia nega o retorno do perigo, e a rígida professora Umbridge assume o controle de Hogwarts. Harry e os colegas formam um grupo secreto para aprender a se defender. Uma história sobre rebeldia, amizade e responsabilidade.', 'Intermediário', array['harry potter', 'magia', 'resistência', 'hogwarts', 'juvenil']),
  ('34f8054c-6b97-58f7-82c4-f0b8452e387d', 'Harry Potter and the Half-Blood Prince', 'J. K. Rowling', 'Fantasia', 'en', 'Dumbledore leva Harry a explorar memórias do passado para entender como derrotar o inimigo. Ao mesmo tempo, Harry encontra um velho livro de poções com anotações misteriosas e desconfia de um colega. Um capítulo de revelações e despedidas.', 'Intermediário', array['harry potter', 'magia', 'memórias', 'hogwarts', 'juvenil']),
  ('4406f6a5-e820-5258-80e5-39a59ce7f0d6', 'Harry Potter and the Deathly Hallows', 'J. K. Rowling', 'Fantasia', 'en', 'Harry, Rony e Hermione deixam a escola para procurar objetos que mantêm o inimigo poderoso. Perseguidos e sem apoio, eles precisam confiar uns nos outros. O desfecho épico da série.', 'Intermediário', array['harry potter', 'magia', 'final', 'amizade', 'juvenil']),
  ('0dc723ab-42e7-5c17-8b30-d40ceecbed4d', 'The Hunger Games', 'Suzanne Collins', 'Ficção Científica', 'en', 'Em Panem, jovens de cada distrito são sorteados para lutar até a morte num espetáculo televisionado. Katniss Everdeen se oferece no lugar da irmã e luta pela vida diante das câmeras. Uma distopia sobre poder, mídia e sacrifício.', 'Intermediário', array['distopia', 'sobrevivência', 'juvenil', 'rebelião', 'jogos']),
  ('ba049cbc-d74f-5fe7-85de-08058e44cd25', 'Catching Fire', 'Suzanne Collins', 'Ficção Científica', 'en', 'Depois de vencer os Jogos, Katniss descobre que seu gesto de desafio inspirou revoltas nos distritos. O governo reage com um novo torneio que reúne antigos vencedores. Um segundo volume mais tenso e político.', 'Intermediário', array['distopia', 'rebelião', 'juvenil', 'jogos', 'sobrevivência']),
  ('624a067a-53c3-54c5-8e9f-779d21330afa', 'Mockingjay', 'Suzanne Collins', 'Ficção Científica', 'en', 'Katniss se torna o símbolo da rebelião contra a Capital e se vê no centro de uma guerra. O livro mostra o custo da violência e o uso da propaganda. O desfecho sombrio da trilogia.', 'Intermediário', array['distopia', 'guerra', 'rebelião', 'juvenil', 'trauma']),
  ('7a47321f-bc3c-5a7e-ae65-b6ce0a36023e', 'Percy Jackson and the Lightning Thief', 'Rick Riordan', 'Fantasia', 'en', 'Percy Jackson, de doze anos, descobre que é filho de um deus grego e é acusado de roubar o raio de Zeus. Ele parte numa jornada pelos Estados Unidos para provar sua inocência. Uma aventura leve e engraçada que mistura mitologia e vida moderna.', 'Intermediário', array['mitologia grega', 'aventura', 'juvenil', 'humor', 'deuses']),
  ('d8ce747c-26bc-53b0-ae0e-fcb63e8c66ee', 'Percy Jackson and the Sea of Monsters', 'Rick Riordan', 'Fantasia', 'en', 'Percy, Annabeth e o ciclope Tyson partem para o Mar dos Monstros em busca do Velocino de Ouro para salvar o acampamento dos semideuses. A jornada traz perigos e novas alianças. Uma sequência cheia de humor e ação.', 'Intermediário', array['mitologia grega', 'aventura', 'juvenil', 'humor', 'monstros']),
  ('652142f2-cc7b-5620-a0dc-47a47c8b048d', 'Divergent', 'Veronica Roth', 'Ficção Científica', 'en', 'Numa Chicago futura dividida em facções, Beatrice descobre que não se encaixa em nenhuma e esconde essa condição perigosa. Ela escolhe uma facção e passa por testes duros. Uma distopia sobre identidade e coragem.', 'Intermediário', array['distopia', 'juvenil', 'facções', 'identidade', 'ação']),
  ('fa4be59c-22f4-5e17-b173-014bb4afc9b5', 'Insurgent', 'Veronica Roth', 'Ficção Científica', 'en', 'Depois de um ataque devastador, Tris e Quatro se veem no meio de um conflito entre facções. Ela lida com culpa e precisa decidir em quem confiar. Um segundo volume de ação e dilemas morais.', 'Intermediário', array['distopia', 'juvenil', 'facções', 'guerra', 'identidade']),
  ('eb1dbb22-0b7b-57c1-8782-129f6345ac27', 'The Maze Runner', 'James Dashner', 'Ficção Científica', 'en', 'Thomas acorda numa clareira cercada por um labirinto, sem lembrar de nada além do próprio nome. Os meninos que vivem ali tentam descobrir uma saída enquanto o labirinto muda a cada noite. Uma história de mistério e sobrevivência.', 'Intermediário', array['distopia', 'labirinto', 'juvenil', 'mistério', 'sobrevivência']),
  ('8c245aef-8dab-5fb6-af6c-44403600dda4', 'Twilight', 'Stephenie Meyer', 'Romance', 'en', 'Bella Swan se muda para a pequena Forks e se aproxima do enigmático Edward Cullen, que guarda um segredo perigoso. O amor dos dois desafia regras e coloca todos em risco. Um romance sobrenatural que marcou uma geração.', 'Intermediário', array['vampiros', 'romance', 'juvenil', 'fantasia', 'amor']),
  ('f569ef88-9fb5-5e1f-948f-bfab242a6638', 'New Moon', 'Stephenie Meyer', 'Romance', 'en', 'Quando Edward deixa Bella, ela mergulha na tristeza e se aproxima do amigo Jacob. A amizade traz conforto, mas esconde segredos. O segundo livro da saga explora perda e novas lealdades.', 'Intermediário', array['vampiros', 'romance', 'juvenil', 'perda', 'fantasia']),
  ('46d1ec66-d33e-5236-90cc-5380773e877c', 'Eclipse', 'Stephenie Meyer', 'Romance', 'en', 'Uma ameaça cresce em Seattle enquanto Bella precisa decidir entre Edward e Jacob. Antigos rivais precisam se unir diante de um inimigo comum. O terceiro volume equilibra romance e ação.', 'Intermediário', array['vampiros', 'romance', 'juvenil', 'triângulo amoroso', 'fantasia']),
  ('b6e15527-5870-5dc5-9bff-1696930f3868', 'Breaking Dawn', 'Stephenie Meyer', 'Romance', 'en', 'Bella e Edward se casam, e as consequências da união mudam a vida de todos de forma inesperada. O livro encerra a saga com decisões difíceis e conflitos que envolvem outras criaturas. Um desfecho cheio de reviravoltas.', 'Intermediário', array['vampiros', 'romance', 'juvenil', 'casamento', 'fantasia']),
  ('22b28667-0ace-5219-899b-605bc32f977d', 'Eragon', 'Christopher Paolini', 'Fantasia', 'en', 'Eragon, um jovem fazendeiro, encontra uma pedra azul que se revela um ovo de dragão. Treinado por um velho contador de histórias, ele precisa enfrentar o rei tirano que domina o reino. Uma fantasia clássica de dragões e destino.', 'Intermediário', array['dragões', 'aventura', 'juvenil', 'magia', 'jornada']),
  ('14a28cc8-ef66-5f70-8e9b-de694e187dce', 'Artemis Fowl', 'Eoin Colfer', 'Fantasia', 'en', 'Artemis Fowl, um menino gênio e criminoso, sequestra uma fada para exigir resgate em ouro. Ele não esperava a reação do mundo subterrâneo e de sua polícia tecnológica. Uma fantasia ágil, cheia de gadgets e ironia.', 'Intermediário', array['gênio', 'fadas', 'humor', 'aventura', 'juvenil']),
  ('e858d3e4-7ca8-5502-b1cb-a6ec83962527', 'Northern Lights', 'Philip Pullman', 'Fantasia', 'en', 'Lyra Belacqua vive num mundo paralelo em que cada pessoa tem um daemon, um animal que é parte de sua alma. Quando crianças começam a desaparecer, ela parte numa jornada rumo ao Norte. Primeiro livro da trilogia Fronteiras do Universo.', 'Intermediário', array['mundos paralelos', 'aventura', 'juvenil', 'daemons', 'mistério']),
  ('84cd91d2-7473-5efb-8a86-afdffe3f1087', 'The Subtle Knife', 'Philip Pullman', 'Fantasia', 'en', 'Lyra encontra Will, um menino de outro mundo, e os dois descobrem uma faca capaz de abrir passagens entre universos. Cada um busca respostas sobre o pai e sobre uma ameaça maior. Um segundo volume mais amplo e sombrio.', 'Intermediário', array['mundos paralelos', 'aventura', 'juvenil', 'ciência', 'fantasia']),
  ('fc816177-fbc6-5f7c-baf3-1aab06d68f35', 'The Amber Spyglass', 'Philip Pullman', 'Fantasia', 'en', 'Lyra e Will viajam entre mundos enquanto um conflito de proporções gigantescas envolve todos os universos. A história toca em temas como liberdade, fé e crescimento. O desfecho da trilogia, mais filosófico.', 'Intermediário', array['mundos paralelos', 'aventura', 'juvenil', 'fé', 'final']),
  ('e1f56137-11b0-5505-a85a-b54bede06ba6', 'A Game of Thrones', 'George R. R. Martin', 'Fantasia', 'en', 'Em Westeros, casas nobres disputam o Trono de Ferro, e a família Stark se vê no centro de intrigas mortais. Enquanto isso, uma ameaça antiga desperta no Norte. O primeiro livro de As Crônicas de Gelo e Fogo.', 'Avançado', array['política', 'reinos', 'guerra', 'fantasia épica', 'intrigas']),
  ('eaeecca4-95aa-5abd-8611-2d132db3cf09', 'A Clash of Kings', 'George R. R. Martin', 'Fantasia', 'en', 'Com o reino fragmentado, vários pretendentes reivindicam o trono e a guerra se espalha por Westeros. Personagens espalhados pelo mundo enfrentam perdas e escolhas difíceis. O segundo volume amplia o conflito e os dilemas.', 'Avançado', array['política', 'guerra', 'reinos', 'fantasia épica', 'intrigas']),
  ('b0fbf112-8243-5e45-9efe-0feb6cf0f329', 'The Name of the Wind', 'Patrick Rothfuss', 'Fantasia', 'en', 'Num albergue, Kvothe, um homem comum que esconde uma lenda, conta sua própria vida a um cronista. Ele fala de uma infância com trupe de atores, da tragédia que o marcou e dos anos numa escola de magia. Uma fantasia poética e muito detalhada.', 'Avançado', array['magia', 'música', 'narrativa', 'universidade', 'fantasia épica']),
  ('d8623100-1a30-5eee-8f95-93f3bb4be064', 'Mistborn: The Final Empire', 'Brandon Sanderson', 'Fantasia', 'en', 'Num mundo coberto de cinzas e dominado por um imperador imortal, a jovem ladra Vin se une a uma equipe que planeja derrubá-lo. Ela descobre que tem poderes ligados ao consumo de metais. Uma fantasia com sistema de magia engenhoso.', 'Intermediário', array['magia', 'rebelião', 'assalto', 'fantasia épica', 'sistema de magia']),
  ('b21b6268-3f91-55cb-93bd-1dd464b95438', 'The Way of Kings', 'Brandon Sanderson', 'Fantasia', 'en', 'Num mundo castigado por tempestades, um soldado escravizado, um príncipe guerreiro e uma jovem erudita enfrentam os custos da guerra e da honra. Os destinos deles se cruzam em torno de segredos ancestrais. O início da série O Arquivo das Tempestades.', 'Intermediário', array['fantasia épica', 'guerra', 'honra', 'magia', 'mundo novo']),
  ('761bd54c-ab77-5a9a-a76c-a579e7d38e03', 'The Fellowship of the Ring', 'J. R. R. Tolkien', 'Fantasia', 'en', 'Frodo herda um anel perigoso e parte numa missão para destruí-lo, acompanhado por amigos e aliados. A Sociedade do Anel enfrenta tentações e perigos pelo caminho. O primeiro volume da obra-prima de Tolkien.', 'Avançado', array['clássico', 'fantasia épica', 'anel', 'jornada', 'terra média']),
  ('5462790b-c28e-5a43-812b-a807d0b0ae02', 'The Two Towers', 'J. R. R. Tolkien', 'Fantasia', 'en', 'A Sociedade se separa, e Frodo e Sam seguem rumo a Mordor com a ajuda de Gollum. Enquanto isso, Aragorn e os companheiros lutam para proteger Rohan. Um volume dividido entre duas linhas narrativas.', 'Avançado', array['clássico', 'fantasia épica', 'guerra', 'jornada', 'terra média']),
  ('eeb1a2b4-c769-5765-9b55-0e6896cae8c5', 'The Return of the King', 'J. R. R. Tolkien', 'Fantasia', 'en', 'A guerra pelo destino da Terra-média chega ao auge enquanto Frodo e Sam enfrentam as últimas etapas de sua jornada. Gondor se prepara para uma batalha decisiva. O desfecho emocionante da trilogia.', 'Avançado', array['clássico', 'fantasia épica', 'batalha', 'final', 'terra média']),
  ('2167a4eb-7241-58df-91ae-b3d9ff4101c8', 'The Silmarillion', 'J. R. R. Tolkien', 'Fantasia', 'en', 'Reúne os mitos e lendas das Eras antigas da Terra-média, da criação do mundo às guerras dos elfos pelas joias chamadas Silmarils. O texto tem tom de crônica e linguagem solene. Um livro para quem quer conhecer a mitologia por trás de O Senhor dos Anéis.', 'Avançado', array['mitologia', 'clássico', 'elfos', 'criação', 'terra média']),
  ('0d02b92d-1b44-536e-a526-8882343a8022', 'A Wizard of Earthsea', 'Ursula K. Le Guin', 'Fantasia', 'en', 'Ged, um jovem de talento para a magia, quebra uma regra por orgulho e libera uma sombra que passa a persegui-lo. Para recuperar o equilíbrio, ele precisa enfrentar a si mesmo. Um clássico de formação que discute poder e responsabilidade.', 'Intermediário', array['magia', 'formação', 'clássico', 'equilíbrio', 'fantasia']),
  ('c03d657d-a386-5001-bbdf-db29c641243d', 'American Gods', 'Neil Gaiman', 'Fantasia', 'en', 'Shadow, recém-saído da prisão, vira acompanhante do enigmático Mr Wednesday e descobre uma guerra entre deuses antigos e novos nos Estados Unidos. A viagem de carro revela o lado mágico do país. Um romance sobre fé, imigração e identidade.', 'Intermediário', array['mitologia', 'estrada', 'deuses', 'américa', 'fantasia urbana']),
  ('65f86874-7c29-5379-a530-0aeece30d7dc', 'Coraline', 'Neil Gaiman', 'Fantasia', 'en', 'Coraline descobre uma porta que leva a uma casa parecida com a sua, mas com uma "outra mãe" de botões no lugar dos olhos. Ela percebe o perigo escondido por trás do mundo perfeito. Uma novela arrepiante e curta, ótima para leitores jovens.', 'Iniciante', array['terror suave', 'aventura', 'infantil', 'portas', 'mistério']),
  ('87542134-f946-5a1b-9470-22eaa2f6814c', 'Neverwhere', 'Neil Gaiman', 'Fantasia', 'en', 'Richard Mayhew ajuda uma moça ferida e descobre a Londres de Baixo, um mundo oculto sob a cidade que ele conhece. Para voltar à vida normal, precisa enfrentar perigos estranhos. Uma fantasia urbana engenhosa e cheia de humor.', 'Intermediário', array['londres', 'fantasia urbana', 'aventura', 'submundo', 'mistério']),
  ('7ba480d7-30a8-559a-9e9a-4518688e10e1', 'Good Omens', 'Terry Pratchett and Neil Gaiman', 'Fantasia', 'en', 'O anjo Aziraphale e o demônio Crowley, acomodados à vida na Terra, tentam impedir o fim do mundo depois de um erro na troca do filho do Anticristo. Entre profecias e confusões, o apocalipse se atrapalha. Uma comédia inglesa afiada sobre o bem e o mal.', 'Avançado', array['humor', 'apocalipse', 'anjos', 'demônios', 'comédia']),
  ('d3925165-d8b1-56e1-8eb6-b501158fbd82', 'The Colour of Magic', 'Terry Pratchett', 'Fantasia', 'en', 'O mago fracassado Rincewind é contratado como guia do ingênuo turista Duasflores no Discworld, um mundo plano sobre tartaruga gigante. O que deveria ser um passeio vira uma sequência de confusões. O primeiro livro da série de humor fantástico.', 'Avançado', array['humor', 'discworld', 'magia', 'sátira', 'aventura']),
  ('5912b82e-d02d-55b7-a1c0-0f96eb0a89bb', 'Mort', 'Terry Pratchett', 'Fantasia', 'en', 'A Morte, personagem do Discworld, contrata o desajeitado Mort como aprendiz. Ele acaba interferindo no destino de uma princesa e bagunçando a ordem das coisas. Uma comédia fantástica sobre responsabilidade e vida.', 'Avançado', array['humor', 'discworld', 'morte', 'fantasia', 'sátira']),
  ('df33079c-31ab-5272-a07a-4b9c85d885d4', 'The Lies of Locke Lamora', 'Scott Lynch', 'Fantasia', 'en', 'Locke Lamora lidera os Gentlemen Bastards, um bando de ladrões trapaceiros na cidade de Camorr. Os planos dão certo até que um rival poderoso ameaça o grupo. Uma fantasia de golpes e traições com tom irreverente.', 'Avançado', array['assalto', 'fantasia', 'crime', 'cidade', 'humor negro']),
  ('1b71f6af-f291-5fb3-ac23-89c49edf2b60', 'The Eye of the World', 'Robert Jordan', 'Fantasia', 'en', 'Um grupo de jovens de uma vila rural é arrancado de casa quando uma misteriosa mulher revela que um deles pode ter um destino enorme. Perseguidos por criaturas sombrias, eles fogem pelo mundo. O início da longa série A Roda do Tempo.', 'Intermediário', array['fantasia épica', 'jornada', 'destino', 'magia', 'roda do tempo']),
  ('02331af9-3a1f-5c26-a4a5-39bccefef9b5', 'Wonder', 'R. J. Palacio', 'Juvenil', 'en', 'Auggie Pullman, um garoto que nasceu com uma diferença facial, começa a frequentar a escola pela primeira vez, aos dez anos. A história é contada por vários narradores e mostra gentileza e preconceito. Uma leitura emocionante e acessível.', 'Iniciante', array['empatia', 'escola', 'superação', 'família', 'bullying']),
  ('6d118392-0468-5195-bb12-f4f4a0031cbb', 'The Princess Bride', 'William Goldman', 'Fantasia', 'en', 'Westley e Buttercup se amam, mas o destino os separa em meio a piratas, gigantes, duelos e vingança. O narrador interrompe a história com comentários divertidos. Uma mistura de aventura, romance e paródia.', 'Intermediário', array['humor', 'aventura', 'romance', 'piratas', 'clássico']),
  ('ac89dee5-225c-561d-8536-3e6c4a797497', 'Stardust', 'Neil Gaiman', 'Fantasia', 'en', 'Para conquistar a moça que ama, Tristran atravessa um muro e entra no reino das fadas em busca de uma estrela caída. Lá descobre que a estrela é algo bem diferente do que imaginava. Um conto de fadas para adultos, leve e inventivo.', 'Intermediário', array['fantasia', 'conto de fadas', 'aventura', 'romance', 'magia']),
  ('5fde0ad1-92ba-571e-9fc8-e07a159948bd', 'The Graveyard Book', 'Neil Gaiman', 'Juvenil', 'en', 'Depois que a família é assassinada, um bebê foge para um cemitério e é criado por fantasmas, que o chamam de Bod. Crescendo entre os mortos, ele precisa enfrentar o perigo que ainda o procura. Uma história sobre família e amadurecimento.', 'Intermediário', array['fantasmas', 'cemitério', 'formação', 'aventura', 'juvenil']),
  ('3d8dcc1d-8529-559b-9759-32c1bffe16ff', 'Throne of Glass', 'Sarah J. Maas', 'Fantasia', 'en', 'Celaena Sardothien, uma assassina condenada a trabalhos forçados, ganha a chance de lutar como campeã do rei e conquistar a liberdade. A competição esconde mistérios sombrios. O início de uma série de fantasia e intrigas.', 'Intermediário', array['assassina', 'competição', 'fantasia', 'juvenil', 'magia']),
  ('0c39b0fd-44c9-5c2f-907b-233482495276', 'A Court of Thorns and Roses', 'Sarah J. Maas', 'Fantasia', 'en', 'Feyre, uma caçadora humana, é levada para o mundo das fadas depois de matar um lobo e vive numa corte encantada e perigosa. Aos poucos, ela se envolve com seu captor e descobre uma ameaça maior. Uma releitura de A Bela e a Fera.', 'Intermediário', array['fadas', 'romance', 'fantasia', 'reinterpretação', 'juvenil']),
  ('3aa13095-f68a-540e-8972-554bf205ad1a', 'Six of Crows', 'Leigh Bardugo', 'Fantasia', 'en', 'Kaz Brekker reúne uma equipe de marginais talentosos para um assalto quase impossível numa cidade cheia de perigos. Cada um carrega um passado e segredos próprios. Uma fantasia de golpe e reviravoltas.', 'Intermediário', array['assalto', 'fantasia', 'grupo', 'juvenil', 'crime']),
  ('d4016839-36c7-5d8f-84e2-5f31911dbaa6', 'Shadow and Bone', 'Leigh Bardugo', 'Fantasia', 'en', 'Alina Starkov, uma jovem soldado, descobre um poder raro capaz de enfrentar a Dobra da Sombra, uma faixa de escuridão que corta o reino. Levada à corte, ela precisa aprender a controlá-lo. O primeiro livro da trilogia Sombra e Ossos.', 'Intermediário', array['fantasia', 'magia', 'juvenil', 'romance', 'reino']),
  ('121070a6-14fc-5503-a80e-2ac34e6240f4', 'Dune', 'Frank Herbert', 'Ficção Científica', 'en', 'A família Atreides assume o controle do planeta desértico Arrakis, única fonte da valiosa especiaria que move o império. Traição, religião e a chegada do jovem Paul a um povo do deserto mudam o destino de todos. Um dos grandes épicos da ficção científica.', 'Avançado', array['clássico', 'deserto', 'política', 'ecologia', 'épico'])
insert into public.livros (id, titulo, autor, genero, idioma, resumo, nivel_dificuldade, tags) values
  ('db9e2a17-c497-5bd7-bbb9-275336f5cd56', 'Dune Messiah', 'Frank Herbert', 'Ficção Científica', 'en', 'Anos depois da vitória, Paul governa o império, mas conspirações ameaçam seu poder. Ele enfrenta o custo de ser visto como messias e de ter previsto o futuro. Uma continuação mais sombria e reflexiva.', 'Avançado', array['clássico', 'política', 'profecia', 'império', 'épico']),
  ('5a7a0a3c-9586-5a6a-bc74-1001f54928fc', 'Foundation', 'Isaac Asimov', 'Ficção Científica', 'en', 'O matemático Hari Seldon prevê a queda do Império Galáctico e cria uma fundação para encurtar a era de trevas que virá. A história acompanha crises ao longo de séculos, resolvidas mais por inteligência do que por força. Um clássico de ideias.', 'Intermediário', array['clássico', 'império galáctico', 'futuro', 'ciência', 'política']),
  ('5ef4bf4f-192c-545b-94b3-fe31c84d9c61', 'Foundation and Empire', 'Isaac Asimov', 'Ficção Científica', 'en', 'A Fundação enfrenta primeiro os restos do Império e depois uma ameaça imprevista, o misterioso Mulo. O plano de Seldon parece então ruir. Um segundo volume cheio de reviravoltas.', 'Intermediário', array['clássico', 'império galáctico', 'futuro', 'ciência', 'estratégia']),
  ('75ba0d4b-9d09-59f6-a8a1-e257bb2606a1', 'I, Robot', 'Isaac Asimov', 'Ficção Científica', 'en', 'Reúne contos sobre robôs regidos pelas três leis da robótica, contados a partir das lembranças da psicóloga Susan Calvin. Cada história mostra como essas regras simples produzem dilemas inesperados. Um clássico sobre inteligência artificial e ética.', 'Intermediário', array['robôs', 'clássico', 'ética', 'contos', 'tecnologia']),
  ('ed4d20af-c160-5929-963f-aa7371ef7d94', 'The Caves of Steel', 'Isaac Asimov', 'Ficção Científica', 'en', 'Numa Nova York futura e superlotada, o detetive Elijah Baley investiga um assassinato com a ajuda do robô Daneel Olivaw. A parceria desafia preconceitos contra robôs. Um romance policial de ficção científica.', 'Intermediário', array['robôs', 'mistério', 'detetive', 'futuro', 'clássico']),
  ('a2663bae-f411-51b5-867e-2b65768c9fe3', '2001: A Space Odyssey', 'Arthur C. Clarke', 'Ficção Científica', 'en', 'Um misterioso monólito influencia a humanidade ao longo de sua evolução e, no futuro, guia uma nave rumo a Saturno. Durante a viagem, o computador HAL passa a agir de modo preocupante. Uma obra clássica sobre evolução e inteligência.', 'Intermediário', array['clássico', 'espaço', 'inteligência artificial', 'evolução', 'monólito']),
  ('227b3d97-551e-51f3-b1e4-83fbeed20680', 'Childhood''s End', 'Arthur C. Clarke', 'Ficção Científica', 'en', 'Alienígenas chegam à Terra e trazem paz e prosperidade, mas mantêm seus verdadeiros planos em segredo. A humanidade descobre o preço desse novo mundo. Um clássico melancólico sobre destino e progresso.', 'Intermediário', array['clássico', 'alienígenas', 'utopia', 'futuro', 'evolução']),
  ('0af71d67-49a2-5fc9-b1d3-9b93a61111ec', 'Rendezvous with Rama', 'Arthur C. Clarke', 'Ficção Científica', 'en', 'Uma enorme nave cilíndrica de origem desconhecida entra no sistema solar, e uma equipe humana é enviada a explorá-la. O interior revela paisagens e mistérios que desafiam a compreensão. Uma aventura de descoberta e maravilhamento.', 'Intermediário', array['exploração', 'espaço', 'mistério', 'alienígenas', 'clássico']),
  ('cf4df65e-82c7-5732-b2d7-d7ae46b4cb56', 'Ender''s Game', 'Orson Scott Card', 'Ficção Científica', 'en', 'Ender Wiggin, um menino genial, é treinado desde cedo numa escola militar espacial para enfrentar uma ameaça alienígena. Os jogos de guerra e o isolamento o pressionam ao limite. Um romance sobre liderança, violência e empatia.', 'Intermediário', array['guerra', 'estratégia', 'crianças', 'alienígenas', 'dilemas morais']),
  ('548d07c5-f4c8-5ee6-a62d-b82a90465c73', 'Speaker for the Dead', 'Orson Scott Card', 'Ficção Científica', 'en', 'Séculos depois dos eventos anteriores, Ender se tornou um "Falador pelos Mortos" e é chamado a um planeta habitado por uma espécie estranha. Lá ele investiga uma morte e enfrenta o passado. Uma continuação mais filosófica e comovente.', 'Avançado', array['alienígenas', 'culpa', 'empatia', 'futuro', 'filosofia']),
  ('b00d9e38-6f03-5375-b3d1-b1de63535829', 'Stranger in a Strange Land', 'Robert A. Heinlein', 'Ficção Científica', 'en', 'Valentine Michael Smith, um humano criado por marcianos, chega à Terra e estranha os costumes sociais. Suas ideias abalam a religião, a política e a sexualidade. Um clássico polêmico sobre cultura e liberdade.', 'Avançado', array['clássico', 'sociedade', 'religião', 'marte', 'liberdade']),
  ('db6ec50d-e242-5f13-b690-23e2f620a6ed', 'Starship Troopers', 'Robert A. Heinlein', 'Ficção Científica', 'en', 'Johnny Rico se alista na infantaria móvel e enfrenta uma guerra contra insetos alienígenas. O livro discute dever, cidadania e o papel dos militares. Uma obra influente e controversa.', 'Intermediário', array['guerra', 'militarismo', 'cidadania', 'alienígenas', 'clássico']),
  ('68372f68-7bf0-5147-bbcd-78d1465452e6', 'The Moon Is a Harsh Mistress', 'Robert A. Heinlein', 'Ficção Científica', 'en', 'Os colonos da Lua, explorados pela Terra, planejam uma revolução ajudados por um computador que desenvolveu consciência. A luta pela independência traz dilemas políticos. Uma aventura sobre liberdade e estratégia.', 'Avançado', array['revolução', 'computador', 'lua', 'política', 'clássico']),
  ('d0cd04fd-5858-5e0c-bdc1-318aadd61b8d', 'The Left Hand of Darkness', 'Ursula K. Le Guin', 'Ficção Científica', 'en', 'O enviado Genly Ai chega ao planeta gelado Gethen, onde as pessoas não têm sexo fixo, para convencer os povos a se unirem a uma aliança. A amizade com um político local o obriga a rever seus preconceitos. Um clássico sobre cultura, gênero e confiança.', 'Avançado', array['gênero', 'cultura', 'clássico', 'planeta gelado', 'diplomacia']),
  ('fadf3639-1dc0-5eb3-917d-adb2c0e15a91', 'The Dispossessed', 'Ursula K. Le Guin', 'Ficção Científica', 'en', 'O físico Shevek vive numa lua anarquista e viaja ao mundo capitalista vizinho para compartilhar suas ideias. O contraste entre os dois sistemas é uma lição de política e utopia. Um romance sofisticado sobre liberdade e propriedade.', 'Avançado', array['utopia', 'política', 'anarquismo', 'clássico', 'sociedade']),
  ('a4c4ec25-d558-571a-904d-04dc92549d09', 'Do Androids Dream of Electric Sheep?', 'Philip K. Dick', 'Ficção Científica', 'en', 'Num futuro devastado, Rick Deckard caça androides fugitivos quase idênticos a humanos. Quanto mais ele os persegue, mais questiona o que torna alguém humano. O livro inspirou Blade Runner.', 'Intermediário', array['androides', 'distopia', 'identidade', 'clássico', 'futuro']),
  ('a55d4841-8947-5160-8ba5-666858a8dc13', 'The Man in the High Castle', 'Philip K. Dick', 'Ficção Científica', 'en', 'Num mundo em que as potências do Eixo venceram a Segunda Guerra, os Estados Unidos estão divididos e ocupados. Vários personagens vivem sob o regime e discutem um livro que imagina outro desfecho. Um romance sobre realidade e resistência.', 'Intermediário', array['história alternativa', 'segunda guerra', 'totalitarismo', 'clássico', 'realidade']),
  ('1dfa04b0-3771-52e3-a45d-d95115b6f087', 'Ubik', 'Philip K. Dick', 'Ficção Científica', 'en', 'Depois de um atentado, os funcionários de uma empresa que combate poderes psíquicos percebem que a realidade ao redor se desfaz. Eles buscam um misterioso produto chamado Ubik. Um romance inquietante sobre o que é real.', 'Avançado', array['realidade', 'paranoia', 'clássico', 'telepatia', 'futuro']),
  ('3645818d-8eaf-5ace-991a-d837cde3c305', 'A Scanner Darkly', 'Philip K. Dick', 'Ficção Científica', 'en', 'Um agente policial infiltrado entre usuários de drogas se vicia numa substância e perde o controle da própria identidade. A vigilância o obriga a vigiar a si mesmo. Um romance sombrio sobre vício e identidade.', 'Intermediário', array['drogas', 'identidade', 'vigilância', 'distopia', 'clássico']),
  ('b9335b32-bd8c-5546-94ec-9b2b8f3fc470', 'Neuromancer', 'William Gibson', 'Ficção Científica', 'en', 'Case, um hacker que perdeu a capacidade de entrar no ciberespaço, é recrutado para uma missão arriscada. A trama envolve inteligências artificiais e grandes corporações. O livro que definiu o gênero cyberpunk.', 'Avançado', array['cyberpunk', 'hackers', 'inteligência artificial', 'futuro', 'clássico']),
  ('dd1c9b43-f773-5ef4-a91c-95aaace8b1f4', 'Snow Crash', 'Neal Stephenson', 'Ficção Científica', 'en', 'Hiro Protagonist, hacker e entregador de pizza, investiga uma droga digital que afeta o mundo virtual e o real. A história imagina um Metaverso e uma sociedade fragmentada por empresas. Uma sátira ágil e cheia de ideias.', 'Avançado', array['cyberpunk', 'metaverso', 'sátira', 'hackers', 'tecnologia']),
  ('63b45ba2-f705-5504-91a0-fd9cfa137d26', 'The Handmaid''s Tale', 'Margaret Atwood', 'Ficção Científica', 'en', 'Offred vive em Gilead, uma ditadura religiosa em que mulheres férteis são forçadas a servir como "aias". Ela narra seu cotidiano e as memórias de uma vida anterior. Uma distopia sobre poder, corpo e resistência.', 'Intermediário', array['distopia', 'feminismo', 'religião', 'controle', 'opressão']),
  ('f366db6b-1f49-52a7-b500-3ea62cfe25d9', 'Oryx and Crake', 'Margaret Atwood', 'Ficção Científica', 'en', 'Snowman, aparentemente o último humano, relembra como a ciência sem limites levou o mundo ao colapso. Ao lado dele, estranhas criaturas criadas em laboratório. Um romance inquietante sobre ganância e biotecnologia.', 'Avançado', array['distopia', 'engenharia genética', 'pós-apocalipse', 'sociedade', 'futuro']),
  ('b45cf030-8407-563c-9157-855c572b1b1a', 'The Hitchhiker''s Guide to the Galaxy', 'Douglas Adams', 'Ficção Científica', 'en', 'Arthur Dent escapa da destruição da Terra com seu amigo Ford Prefect, que na verdade é um alienígena. Pelo universo, eles passam por situações absurdas guiados por um livro de viagens. Uma comédia espacial muito inglesa.', 'Intermediário', array['humor', 'espaço', 'comédia', 'absurdo', 'clássico']),
  ('17ec6222-3843-52d1-9e84-2444739f2826', 'The Restaurant at the End of the Universe', 'Douglas Adams', 'Ficção Científica', 'en', 'Arthur, Ford e seus companheiros continuam as aventuras pela galáxia, passando por situações improváveis, entre elas um restaurante que serve jantar durante o fim do universo. O humor absurdo segue em alta. Uma continuação divertida.', 'Intermediário', array['humor', 'espaço', 'comédia', 'absurdo', 'clássico']),
  ('411d12ff-d4ff-57dd-9081-03182b1c186a', 'Dirk Gently''s Holistic Detective Agency', 'Douglas Adams', 'Ficção Científica', 'en', 'O detetive holístico Dirk Gently acredita que tudo está conectado e resolve casos aparentemente impossíveis. Um assassinato misterioso envolve fantasmas, máquinas do tempo e acasos. Uma comédia policial inglesa e maluca.', 'Intermediário', array['humor', 'detetive', 'absurdo', 'comédia', 'mistério']),
  ('b197577c-579c-57f8-a18e-2eb0097a6451', 'The Martian', 'Andy Weir', 'Ficção Científica', 'en', 'O astronauta Mark Watney é deixado para trás em Marte depois de um acidente e usa ciência e engenhosidade para sobreviver. A história alterna diário bem-humorado e esforços de resgate na Terra. Uma aventura de superação e solução de problemas.', 'Intermediário', array['sobrevivência', 'marte', 'ciência', 'humor', 'espaço']),
  ('4949e855-64c3-530f-a56e-0d23aea06db4', 'Project Hail Mary', 'Andy Weir', 'Ficção Científica', 'en', 'Um homem acorda numa nave, sem memória, e aos poucos descobre que sua missão é salvar a Terra. Ele encontra um aliado inesperado, de outra espécie. Uma aventura científica sobre cooperação.', 'Intermediário', array['espaço', 'ciência', 'amizade', 'alienígenas', 'sobrevivência']),
  ('d73c878c-f046-5ec2-b729-769623e1ab5c', 'Artemis', 'Andy Weir', 'Ficção Científica', 'en', 'Jazz Bashara, contrabandista da cidade lunar de Artemis, aceita uma proposta arriscada que a envolve numa conspiração. Ela usa seu conhecimento da cidade e da ciência para sobreviver. Um suspense de ficção científica ambientado na Lua.', 'Intermediário', array['lua', 'crime', 'ciência', 'aventura', 'futuro']),
  ('ca244348-94ed-5dab-85ce-e2868790d80b', 'Jurassic Park', 'Michael Crichton', 'Ficção Científica', 'en', 'Numa ilha, um milionário cria um parque de diversões com dinossauros clonados. Quando o sistema de segurança falha, um grupo de visitantes precisa fugir dos predadores. Um suspense científico sobre os riscos de brincar com a natureza.', 'Intermediário', array['dinossauros', 'ciência', 'suspense', 'genética', 'aventura']),
  ('0de5ce3d-7307-5069-9c15-de2d6cae5277', 'The Andromeda Strain', 'Michael Crichton', 'Ficção Científica', 'en', 'Depois que um satélite cai numa cidadezinha dos Estados Unidos, os moradores morrem de forma misteriosa. Um grupo de cientistas corre contra o tempo para entender e conter um micro-organismo desconhecido. Um thriller científico em ritmo de relatório.', 'Intermediário', array['ciência', 'suspense', 'micróbio', 'laboratório', 'tecnologia']),
  ('21bcf2bb-491d-5b71-9cdb-8b2082f4a7b7', 'Sphere', 'Michael Crichton', 'Ficção Científica', 'en', 'Uma equipe de especialistas é levada ao fundo do oceano para investigar uma enorme nave encontrada ali. Dentro dela, há um objeto misterioso que afeta a mente de quem se aproxima. Um suspense claustrofóbico.', 'Intermediário', array['oceano', 'mistério', 'suspense', 'psicologia', 'nave']),
  ('a9c0fb9f-5ddd-50c8-bd10-4bf137516657', 'Contact', 'Carl Sagan', 'Ficção Científica', 'en', 'A radioastrônoma Ellie Arroway capta um sinal vindo de outra civilização, o que abala governos, religiões e a ciência. Quando surge um projeto para responder ao sinal, ela é peça central. Um romance sobre ciência, fé e encontro com o desconhecido.', 'Intermediário', array['alienígenas', 'ciência', 'fé', 'sinal', 'espaço']),
  ('367236dd-5464-5caf-ba6f-496de6602506', 'Hyperion', 'Dan Simmons', 'Ficção Científica', 'en', 'Sete peregrinos viajam ao planeta Hyperion para encontrar uma criatura misteriosa e, no caminho, contam suas histórias. Cada relato revela um estilo e um segredo. Um romance em camadas, inspirado em Os Contos de Canterbury.', 'Avançado', array['peregrinação', 'histórias', 'futuro', 'mistério', 'épico']),
  ('fff83af5-3f1a-5177-85f0-7d3607479b06', 'Ringworld', 'Larry Niven', 'Ficção Científica', 'en', 'Um grupo diverso parte para explorar o Mundo-Anel, uma estrutura artificial gigantesca em volta de uma estrela. A nave sofre problemas, e eles precisam sobreviver num ambiente imenso e desconhecido. Uma aventura de ideias grandiosas.', 'Intermediário', array['exploração', 'espaço', 'megaestrutura', 'aventura', 'clássico']),
  ('0c768893-9db3-5284-b4e0-0d585958f6cc', 'The Forever War', 'Joe Haldeman', 'Ficção Científica', 'en', 'O soldado William Mandella luta numa guerra interestelar em que cada viagem faz o tempo na Terra passar mais depressa. Ao voltar, ele não reconhece mais o mundo. Uma reflexão sobre guerra e alienação.', 'Intermediário', array['guerra', 'viagem no tempo', 'solidão', 'clássico', 'futuro']),
  ('ffc192d4-2516-56f9-9994-8c8cd78cdb41', 'Old Man''s War', 'John Scalzi', 'Ficção Científica', 'en', 'Aos 75 anos, John Perry entra para as Forças de Defesa Coloniais e ganha um novo corpo para lutar numa guerra espacial. Ele se adapta ao treino e à violência com humor. Uma ficção militar leve e ágil.', 'Intermediário', array['guerra', 'envelhecimento', 'humor', 'espaço', 'aventura']),
  ('57e8ef52-17a3-50a9-8612-a9964d2a266e', 'Ready Player One', 'Ernest Cline', 'Ficção Científica', 'en', 'Num futuro sombrio, o jovem Wade Watts passa a vida no mundo virtual OASIS e entra numa caçada pelo tesouro deixado pelo criador. A busca envolve referências dos anos 1980. Uma aventura nostálgica sobre jogos.', 'Intermediário', array['realidade virtual', 'cultura pop', 'aventura', 'jogos', 'futuro']),
  ('7221ae51-d830-56b7-b3e6-9f7a5a3f4f87', 'Station Eleven', 'Emily St. John Mandel', 'Ficção Científica', 'en', 'Depois de uma pandemia devastadora, uma trupe de atores e músicos viaja pelas cidades vazias apresentando peças de Shakespeare. A história alterna passado e presente e liga personagens inesperados. Um romance sobre arte e memória.', 'Intermediário', array['pós-apocalipse', 'arte', 'sobrevivência', 'pandemia', 'memória']),
  ('0c38c066-32cd-5218-8827-38cb5e48ca6e', 'The Road', 'Cormac McCarthy', 'Ficção Científica', 'en', 'Um pai e seu filho caminham por uma América destruída, carregando pouco mais que o desejo de chegar ao litoral. A jornada é marcada por fome, medo e encontros perigosos. Um romance sóbrio e comovente sobre amor e sobrevivência.', 'Intermediário', array['pós-apocalipse', 'pai e filho', 'sobrevivência', 'sombrio', 'esperança']),
  ('3d7d9812-3048-5e11-8499-6b3d09960080', 'Flowers for Algernon', 'Daniel Keyes', 'Ficção Científica', 'en', 'Charlie Gordon, um homem com deficiência intelectual, passa por um experimento que aumenta sua inteligência. Os relatórios que escreve mostram as mudanças e o custo humano disso. Um clássico comovente sobre ciência e afeto.', 'Intermediário', array['inteligência', 'ética', 'diário', 'ciência', 'emoção']),
  ('0b840145-4b33-51c2-a89e-d56635205bd7', 'The Time Traveler''s Wife', 'Audrey Niffenegger', 'Romance', 'en', 'Henry tem uma condição genética que o faz viajar no tempo sem controle, e Clare o conhece desde a infância. O casal enfrenta ausências e reencontros inesperados. Um romance sobre amor e tempo.', 'Intermediário', array['viagem no tempo', 'romance', 'amor', 'destino', 'drama']),
  ('f0b103b7-e1e2-5b57-9527-da82636cddf7', 'Kindred', 'Octavia E. Butler', 'Ficção Científica', 'en', 'Dana, uma mulher negra da Califórnia dos anos 1970, é arrancada de casa e levada várias vezes a uma plantação escravista do século XIX. Ali ela precisa sobreviver e proteger seus antepassados. Um romance intenso sobre memória e racismo.', 'Intermediário', array['escravidão', 'viagem no tempo', 'história', 'racismo', 'sobrevivência']),
  ('5bca0343-8c97-56ae-ae11-a924e605f673', 'Parable of the Sower', 'Octavia E. Butler', 'Ficção Científica', 'en', 'Lauren Olamina vive numa Califórnia futura em colapso e tem uma condição que a faz sentir a dor dos outros. Enquanto tenta sobreviver, ela cria uma nova crença chamada Semente da Terra. Uma distopia sobre esperança e mudança.', 'Intermediário', array['distopia', 'religião', 'sobrevivência', 'futuro', 'comunidade']),
  ('c5794bbd-9d63-5279-af31-a59e01a2f7e3', 'A Canticle for Leibowitz', 'Walter M. Miller Jr.', 'Ficção Científica', 'en', 'Depois de uma guerra nuclear, monges de um mosteiro preservam fragmentos de conhecimento ao longo de séculos. A história mostra como a humanidade repete erros. Um clássico filosófico sobre fé e ciência.', 'Avançado', array['pós-apocalipse', 'religião', 'conhecimento', 'clássico', 'história']),
  ('c95f2920-5030-5fcd-9eab-c82b0864b92e', 'The Day of the Triffids', 'John Wyndham', 'Ficção Científica', 'en', 'Uma chuva de meteoros deixa quase toda a humanidade cega, enquanto plantas carnívoras andam livres e atacam. Um sobrevivente tenta se orientar nesse mundo em ruínas. Um clássico britânico do apocalipse.', 'Intermediário', array['apocalipse', 'plantas', 'sobrevivência', 'clássico', 'inglaterra']),
  ('35036304-01cd-5be8-98de-71b135a47296', 'The Midwich Cuckoos', 'John Wyndham', 'Ficção Científica', 'en', 'Depois de um dia em que todos desmaiam, as mulheres de uma vila inglesa descobrem que estão grávidas. As crianças nascidas têm características estranhas e poderes inquietantes. Um suspense britânico sobre o medo do desconhecido.', 'Intermediário', array['alienígenas', 'mistério', 'vila', 'clássico', 'inglaterra']),
  ('57c69767-e905-5043-9325-24f973628ce7', 'Annihilation', 'Jeff VanderMeer', 'Ficção Científica', 'en', 'Uma expedição de quatro mulheres entra na Área X, uma região isolada onde as leis naturais parecem diferentes. A bióloga narra o que encontram e como a região a transforma. Um romance estranho e hipnótico.', 'Avançado', array['mistério', 'natureza', 'exploração', 'estranho', 'suspense']),
  ('ad67f3ac-385c-5b63-a54d-d74c26eb53a4', 'Wool', 'Hugh Howey', 'Ficção Científica', 'en', 'Numa comunidade que vive num silo subterrâneo, sair é proibido, e a pena para a curiosidade é a expulsão. Juliette, uma engenheira, começa a desconfiar da versão oficial. Uma distopia de mistério e resistência.', 'Intermediário', array['distopia', 'silo', 'mistério', 'sobrevivência', 'segredos']),
  ('971d7558-bb8c-533a-9044-ae0e3ac2e80e', 'Murder on the Orient Express', 'Agatha Christie', 'Mistério e Suspense', 'en', 'Um trem de luxo fica preso na neve, e um passageiro rico é encontrado morto em sua cabine. O detetive Hercule Poirot interroga os viajantes, todos com algo a esconder. Um dos mistérios mais famosos da literatura policial.', 'Intermediário', array['agatha christie', 'poirot', 'trem', 'detetive', 'clássico']),
  ('de607524-c078-52d3-b1f0-c16ef4ec1a2d', 'And Then There Were None', 'Agatha Christie', 'Mistério e Suspense', 'en', 'Dez desconhecidos são convidados para uma ilha isolada e acusados de crimes do passado. Um a um, eles começam a morrer seguindo uma antiga cantiga infantil. O romance policial mais vendido de Christie.', 'Intermediário', array['agatha christie', 'ilha', 'assassinato', 'suspense', 'clássico']),
  ('4ba4993f-494e-5d32-81a2-3aefdaa03b38', 'The Murder of Roger Ackroyd', 'Agatha Christie', 'Mistério e Suspense', 'en', 'Num vilarejo inglês, o rico Roger Ackroyd é encontrado morto, e Poirot, aposentado, é chamado a investigar. O caso é narrado por um médico local, e a solução surpreendeu os leitores da época. Um clássico pela ousadia da estrutura.', 'Intermediário', array['agatha christie', 'poirot', 'vilarejo', 'reviravolta', 'clássico']),
  ('a4b3009c-4b52-5349-b1b1-2fd49edb916d', 'Death on the Nile', 'Agatha Christie', 'Mistério e Suspense', 'en', 'Durante um cruzeiro pelo Nilo, uma jovem herdeira recém-casada é assassinada, e várias pessoas a bordo tinham motivos. Poirot investiga entre ciúmes, dinheiro e rancores. Um mistério elegante e exótico.', 'Intermediário', array['agatha christie', 'poirot', 'egito', 'cruzeiro', 'ciúme']),
  ('b813efff-b7ef-5ff3-b65c-47b11e1beacf', 'The ABC Murders', 'Agatha Christie', 'Mistério e Suspense', 'en', 'Um assassino manda cartas a Poirot anunciando crimes em cidades cujos nomes seguem a ordem do alfabeto. O detetive precisa descobrir o padrão antes do próximo ataque. Um jogo de gato e rato cheio de suspense.', 'Intermediário', array['agatha christie', 'poirot', 'serial killer', 'cartas', 'enigma']),
  ('fb5ec9c2-5f7a-54d0-b965-596be31bec24', 'The Murder at the Vicarage', 'Agatha Christie', 'Mistério e Suspense', 'en', 'Um homem desagradável é encontrado morto na casa paroquial do pacato vilarejo de St Mary Mead. A observadora Miss Marple junta pistas que a polícia deixa passar. A estreia da famosa detetive amadora.', 'Intermediário', array['agatha christie', 'miss marple', 'vilarejo', 'mistério', 'clássico']),
  ('ce4f7cf1-377e-51d8-9df7-00dc5db38e38', 'The Mysterious Affair at Styles', 'Agatha Christie', 'Mistério e Suspense', 'en', 'Uma rica senhora é envenenada em sua mansão no campo, e o refugiado belga Hercule Poirot é chamado a investigar. Ele conta com a ajuda do capitão Hastings. O primeiro romance de Agatha Christie e a estreia de Poirot.', 'Intermediário', array['agatha christie', 'poirot', 'envenenamento', 'primeiro livro', 'mansão']),
  ('965070b3-110b-5486-8c6b-7d45c74c2bf7', 'Evil Under the Sun', 'Agatha Christie', 'Mistério e Suspense', 'en', 'Num hotel à beira-mar, uma atriz glamourosa é encontrada estrangulada, e todos os hóspedes parecem ter álibis. Poirot, em férias, investiga os segredos de cada um. Um mistério ensolarado e cheio de pistas falsas.', 'Intermediário', array['agatha christie', 'poirot', 'hotel', 'praia', 'férias']),
  ('440371c9-8f09-50b2-8b47-89c906272cdd', 'Five Little Pigs', 'Agatha Christie', 'Mistério e Suspense', 'en', 'Anos depois de uma condenação, uma jovem pede a Poirot que prove a inocência da mãe, acusada de matar o pai. Ele ouve cinco testemunhas e compara versões do mesmo dia. Um enigma sobre memória e verdade.', 'Intermediário', array['agatha christie', 'poirot', 'passado', 'memória', 'testemunhas']),
  ('596cf039-30f3-5333-b02f-a11cc9599006', 'A Murder Is Announced', 'Agatha Christie', 'Mistério e Suspense', 'en', 'Um anúncio no jornal informa que haverá um assassinato numa casa do vilarejo, e os vizinhos aparecem por curiosidade. Quando um tiro é disparado, Miss Marple descobre que o crime era real. Um dos casos mais engenhosos da série.', 'Intermediário', array['agatha christie', 'miss marple', 'vilarejo', 'anúncio', 'mistério']),
  ('2274db35-e646-5ce4-957d-728c97991bd2', 'The Body in the Library', 'Agatha Christie', 'Mistério e Suspense', 'en', 'Uma jovem desconhecida é encontrada morta na biblioteca de uma casa de campo. Miss Marple descobre ligações entre moradores e visitantes. Um mistério clássico de "casa de campo".', 'Intermediário', array['agatha christie', 'miss marple', 'mistério', 'clássico', 'vilarejo']),
  ('aec56944-5444-5325-a65a-ea125ade4018', '4.50 from Paddington', 'Agatha Christie', 'Mistério e Suspense', 'en', 'Uma mulher vê, pela janela de um trem, um homem estrangular outra mulher no vagão ao lado, mas ninguém acredita nela. Miss Marple decide investigar o caso. Um suspense que começa numa viagem de trem.', 'Intermediário', array['agatha christie', 'miss marple', 'trem', 'testemunha', 'mistério']),
  ('b504634e-d22b-547b-9dfd-9d2eeea53795', 'The Big Sleep', 'Raymond Chandler', 'Mistério e Suspense', 'en', 'O detetive Philip Marlowe é contratado por um general rico para lidar com um caso de chantagem envolvendo suas filhas. A investigação o leva a uma rede de segredos e crimes em Los Angeles. Um marco do romance policial noir.', 'Avançado', array['noir', 'detetive', 'los angeles', 'philip marlowe', 'clássico']),
  ('ef12d802-4304-5ee7-bf4c-0133d40f748b', 'Farewell, My Lovely', 'Raymond Chandler', 'Mistério e Suspense', 'en', 'Marlowe é arrastado para a busca de um ex-presidiário por uma antiga namorada, e o caso se complica com assassinatos e golpes. O texto é cheio de metáforas e diálogos afiados. Um clássico do noir americano.', 'Avançado', array['noir', 'detetive', 'los angeles', 'philip marlowe', 'clássico']),
  ('76b3c5f8-5e58-57f7-83d7-5732d715ee13', 'The Long Goodbye', 'Raymond Chandler', 'Mistério e Suspense', 'en', 'Marlowe se torna amigo de um homem bêbado e fica ao lado dele quando é acusado de matar a esposa. A investigação mostra quanto a lealdade custa. Um romance noir mais melancólico e pessoal.', 'Avançado', array['noir', 'detetive', 'amizade', 'philip marlowe', 'clássico']),
  ('1cd5c2b7-5307-5d7c-8c8d-e2bdc172cc8e', 'The Maltese Falcon', 'Dashiell Hammett', 'Mistério e Suspense', 'en', 'Depois da morte de seu sócio, o detetive Sam Spade se vê envolvido com uma mulher misteriosa e uma estatueta valiosíssima. Todos os personagens mentem e disputam o objeto. Um clássico da literatura policial americana.', 'Avançado', array['noir', 'detetive', 'são francisco', 'estátua', 'clássico']),
  ('6ce1b6ed-a800-5db7-8ac8-3899b9e70927', 'The Thin Man', 'Dashiell Hammett', 'Mistério e Suspense', 'en', 'O ex-detetive Nick Charles e a esposa Nora, ambos bem-humorados e apaixonados por drinques, são arrastados para um caso de assassinato em Nova York. Entre diálogos rápidos, a solução vai aparecendo. Um policial leve e espirituoso.', 'Intermediário', array['detetive', 'humor', 'casal', 'nova york', 'clássico']),
  ('195a483a-7f3e-580c-9b78-059fb9b4e261', 'The Talented Mr. Ripley', 'Patricia Highsmith', 'Mistério e Suspense', 'en', 'Tom Ripley é enviado à Itália para convencer um jovem rico a voltar para casa, mas se encanta com a vida dele. A admiração vira obsessão e engano. Um suspense psicológico sobre identidade e inveja.', 'Intermediário', array['psicológico', 'itália', 'identidade', 'crime', 'suspense']),
  ('4c3f0866-8de8-51f1-afb1-f65d8cc5c0fc', 'Strangers on a Train', 'Patricia Highsmith', 'Mistério e Suspense', 'en', 'Dois desconhecidos conversam num trem, e um deles sugere uma troca de assassinatos para que ninguém desconfie. O outro ignora a ideia, mas o primeiro decide agir. Um suspense psicológico sobre culpa e manipulação.', 'Intermediário', array['psicológico', 'crime', 'troca', 'trem', 'suspense']),
  ('48cd82d3-6824-5aef-b43e-0a31612fee7e', 'Gone Girl', 'Gillian Flynn', 'Mistério e Suspense', 'en', 'No quinto aniversário de casamento, Amy desaparece, e o marido, Nick, se torna o principal suspeito. A narrativa alterna as versões dos dois e esconde segredos. Um thriller sobre casamento, aparências e manipulação.', 'Intermediário', array['thriller psicológico', 'casamento', 'desaparecimento', 'reviravolta', 'mídia']),
  ('e62852f6-ea4b-5b69-a84b-963bc9a8c673', 'Sharp Objects', 'Gillian Flynn', 'Mistério e Suspense', 'en', 'A repórter Camille Preaker volta à cidade natal para cobrir o assassinato de meninas e é obrigada a encarar a família que deixou para trás. Enquanto investiga, traumas antigos reaparecem. Um thriller sombrio e psicológico.', 'Intermediário', array['thriller psicológico', 'família', 'cidade pequena', 'jornalismo', 'trauma']),
  ('0f85996f-7d0d-52f9-889c-ed0bf146b6b6', 'The Da Vinci Code', 'Dan Brown', 'Mistério e Suspense', 'en', 'Um curador é assassinado no Louvre e deixa mensagens cifradas. O professor Robert Langdon se une a uma criptógrafa para decifrar pistas escondidas em obras de Leonardo da Vinci. Um thriller de ritmo acelerado, cheio de enigmas e teorias.', 'Intermediário', array['thriller', 'códigos', 'arte', 'religião', 'paris']),
  ('f6cdda23-aa99-56c5-afd7-248e30f4fcfa', 'Angels & Demons', 'Dan Brown', 'Mistério e Suspense', 'en', 'Robert Langdon é chamado para ajudar a evitar um atentado que envolve uma antiga sociedade secreta e uma substância perigosa, em plena eleição papal. Ele corre por Roma seguindo pistas de arte e história. Um thriller de ação e símbolos.', 'Intermediário', array['thriller', 'vaticano', 'enigmas', 'ciência e religião', 'roma']),
  ('cfe10d50-b3f6-5c5a-a44e-3d8761702269', 'Inferno', 'Dan Brown', 'Mistério e Suspense', 'en', 'Robert Langdon acorda num hospital em Florença sem memória e logo percebe que é perseguido. Pistas ligadas à Divina Comédia de Dante levam a uma ameaça global. Um thriller de fuga e decifração.', 'Intermediário', array['thriller', 'dante', 'florença', 'ciência', 'enigmas']),
  ('3c76e654-5995-5552-bcc9-f0b632a46e0f', 'The Girl on the Train', 'Paula Hawkins', 'Mistério e Suspense', 'en', 'Rachel observa todos os dias, do trem, um casal que ela imagina perfeito, até que a mulher desaparece. Com lapsos de memória por causa da bebida, ela se envolve no caso. Um suspense psicológico de narradoras instáveis.', 'Intermediário', array['thriller psicológico', 'memória', 'narradora pouco confiável', 'subúrbio', 'trem']),
  ('0a4b553a-5e47-513b-ba24-266afec67cf1', 'The Silent Patient', 'Alex Michaelides', 'Mistério e Suspense', 'en', 'Alicia Berenson é acusada de matar o marido e, desde então, não diz uma palavra. O psicoterapeuta Theo Faber decide descobrir por que ela se calou. Um thriller psicológico com final surpreendente.', 'Intermediário', array['thriller psicológico', 'terapia', 'mistério', 'reviravolta', 'silêncio']),
  ('1f97c792-55ac-55ea-aa3d-62e199d83b9e', 'The Woman in the Window', 'A. J. Finn', 'Mistério e Suspense', 'en', 'Anna Fox, psicóloga que não sai de casa, passa os dias espiando os vizinhos pela janela. Um dia, ela acredita ter visto um crime, mas ninguém acredita nela. Um suspense inspirado nos filmes de Hitchcock.', 'Intermediário', array['thriller psicológico', 'agorafobia', 'vizinhos', 'suspense', 'reviravolta']),
  ('a4a3e850-19a0-540f-ae91-b1534afc2a17', 'In the Woods', 'Tana French', 'Mistério e Suspense', 'en', 'O detetive Rob Ryan, da divisão de homicídios de Dublin, investiga o assassinato de uma menina em uma cidade onde, na infância, dois amigos dele desapareceram. O passado e o presente se misturam. Um policial psicológico de atmosfera densa.', 'Avançado', array['policial', 'irlanda', 'trauma', 'investigação', 'psicológico']),
  ('4fdc8b07-4b64-5fb3-91cb-ade03bcced22', 'The Silence of the Lambs', 'Thomas Harris', 'Mistério e Suspense', 'en', 'A estagiária do FBI Clarice Starling procura a ajuda do brilhante e perigoso Hannibal Lecter para pegar um assassino em série. As conversas entre os dois viram um duelo de inteligência. Um thriller que marcou o gênero.', 'Intermediário', array['thriller', 'serial killer', 'fbi', 'psicológico', 'clássico']),
  ('704c277b-5054-5158-8e3d-1ab2287785c3', 'Red Dragon', 'Thomas Harris', 'Mistério e Suspense', 'en', 'O ex-agente do FBI Will Graham é chamado de volta para capturar um assassino que ataca famílias durante a lua cheia. Para entender a mente do criminoso, ele consulta o psiquiatra Hannibal Lecter. Um thriller de tensão crescente.', 'Intermediário', array['thriller', 'serial killer', 'fbi', 'psicológico', 'hannibal lecter']),
  ('02ac82ac-ceb9-5610-98b8-1084ce2fa662', 'The Firm', 'John Grisham', 'Mistério e Suspense', 'en', 'O jovem advogado Mitch McDeere aceita uma proposta irrecusável de uma firma em Memphis e descobre que ela esconde segredos perigosos. Pressionado pelo FBI e pela própria empresa, ele precisa agir. Um thriller jurídico de ritmo rápido.', 'Intermediário', array['thriller jurídico', 'advocacia', 'conspiração', 'memphis', 'suspense']),
  ('bad11be6-5ab7-5885-a9bd-177fc9c5f07e', 'A Time to Kill', 'John Grisham', 'Mistério e Suspense', 'en', 'No Mississippi, um pai negro mata os homens que agrediram sua filha, e o advogado Jake Brigance assume a defesa. O julgamento expõe preconceito e conflito moral na cidade. Um drama jurídico intenso.', 'Intermediário', array['thriller jurídico', 'racismo', 'julgamento', 'sul dos eua', 'justiça']),
  ('73af5624-ad52-5e5f-88aa-0635102cf256', 'The Pelican Brief', 'John Grisham', 'Mistério e Suspense', 'en', 'Depois do assassinato de dois juízes da Suprema Corte, a estudante de direito Darby Shaw escreve uma teoria sobre quem pode estar por trás. O texto cai nas mãos erradas, e ela vira alvo. Um thriller de conspiração e fuga.', 'Intermediário', array['thriller jurídico', 'conspiração', 'política', 'washington', 'suspense']),
  ('25b43082-810e-5aab-ba25-bbbfc8fc2a8c', 'The Client', 'John Grisham', 'Mistério e Suspense', 'en', 'Mark Sway, de onze anos, presencia o suicídio de um advogado ligado à máfia e fica sabendo de um segredo perigoso. A advogada Reggie Love o ajuda a enfrentar a polícia e os criminosos. Um thriller com protagonista infantil.', 'Intermediário', array['thriller jurídico', 'criança', 'máfia', 'advogada', 'suspense']),
  ('4f8e0c2d-31b5-5069-b29f-3b0328872cb2', 'Killing Floor', 'Lee Child', 'Mistério e Suspense', 'en', 'Jack Reacher, ex-policial militar errante, chega a uma cidade pequena da Geórgia e é preso por um assassinato. Para provar a inocência, ele investiga uma conspiração local. A estreia do herói de ação Jack Reacher.', 'Intermediário', array['thriller', 'ação', 'jack reacher', 'cidade pequena', 'investigação']),
  ('d6cf478c-7c79-5b5c-b551-c9b13fe91443', 'The Bourne Identity', 'Robert Ludlum', 'Mistério e Suspense', 'en', 'Um homem é resgatado do mar com ferimentos e sem memória, mas descobre que tem habilidades surpreendentes e que muita gente quer vê-lo morto. Ele tenta descobrir quem é, fugindo por vários países. Um thriller de espionagem de ritmo intenso.', 'Intermediário', array['espionagem', 'amnésia', 'ação', 'thriller', 'identidade']),
  ('3f44f343-8177-58d9-b5fc-75400e80db3e', 'The Day of the Jackal', 'Frederick Forsyth', 'Mistério e Suspense', 'en', 'Um assassino profissional é contratado para matar o presidente francês Charles de Gaulle, e a polícia corre contra o tempo. O livro acompanha o planejamento e a investigação com detalhes quase documentais. Um clássico do thriller político.', 'Avançado', array['thriller', 'atentado', 'frança', 'clássico', 'perseguição']),
  ('fa549049-10c4-5301-a765-efa196a24dc9', 'The Spy Who Came in from the Cold', 'John le Carré', 'Mistério e Suspense', 'en', 'Alec Leamas, agente britânico cansado, aceita uma última missão na Alemanha durante a Guerra Fria. A operação envolve enganos dentro de enganos. Um romance de espionagem sombrio e realista.', 'Avançado', array['espionagem', 'guerra fria', 'berlim', 'clássico', 'traição']),
  ('6381c5f5-82ae-5be2-a15b-12ec7b295c65', 'Tinker Tailor Soldier Spy', 'John le Carré', 'Mistério e Suspense', 'en', 'O veterano George Smiley é chamado de volta para descobrir um agente soviético infiltrado no alto escalão da inteligência britânica. A investigação exige paciência e cautela. Um dos grandes romances de espionagem.', 'Avançado', array['espionagem', 'guerra fria', 'traição', 'george smiley', 'clássico']),
  ('626e9276-a5f5-5149-969c-7df3f0d5e13a', 'Casino Royale', 'Ian Fleming', 'Mistério e Suspense', 'en', 'O agente James Bond recebe a missão de arruinar um agente inimigo numa mesa de jogo, em um cassino francês. Ao lado dele está a agente Vesper Lynd, e nem tudo é o que parece. O primeiro romance de James Bond.', 'Intermediário', array['espionagem', 'james bond', 'cassino', 'ação', 'clássico']),
  ('4c6eac78-f7fe-51a5-8c2f-7f3bc9985dea', 'The Hunt for Red October', 'Tom Clancy', 'Mistério e Suspense', 'en', 'Um capitão soviético conduz seu submarino nuclear pelo Atlântico, e americanos e soviéticos tentam entender suas intenções. O analista Jack Ryan percebe uma possibilidade ousada. Um thriller militar técnico e tenso.', 'Avançado', array['thriller', 'submarino', 'guerra fria', 'militar', 'espionagem']),
  ('8f0b0caf-ba6c-5fec-91fa-59f29717d0d8', 'Shutter Island', 'Dennis Lehane', 'Mistério e Suspense', 'en', 'Em 1954, o agente Teddy Daniels vai a uma ilha com um hospital psiquiátrico para investigar o desaparecimento de uma paciente. Quanto mais ele procura, mais estranho tudo fica. Um thriller psicológico cheio de reviravoltas.', 'Intermediário', array['thriller psicológico', 'ilha', 'hospital psiquiátrico', 'mistério', 'reviravolta']),
  ('62212eda-9eed-58b7-947e-5f3fb42e3c62', 'Mystic River', 'Dennis Lehane', 'Mistério e Suspense', 'en', 'Três amigos de infância, marcados por um trauma, se reencontram anos depois, quando a filha de um deles é assassinada. A investigação reabre feridas antigas. Um policial denso e emocional.', 'Intermediário', array['policial', 'amizade', 'bairro', 'drama', 'crime']),
  ('9747c4b4-7b9d-5a4c-a546-db84f3289a0e', 'The Woman in White', 'Wilkie Collins', 'Mistério e Suspense', 'en', 'O professor de desenho Walter Hartright encontra uma mulher vestida de branco numa estrada escura e logo percebe que ela está ligada a um mistério em torno de uma jovem herdeira. O romance é narrado por vários depoimentos. Um clássico do suspense vitoriano.', 'Avançado', array['clássico', 'mistério', 'século xix', 'suspense', 'sensation novel']),
  ('e130aac2-4829-5741-8b2e-b5788ec049c7', 'The Moonstone', 'Wilkie Collins', 'Mistério e Suspense', 'en', 'Um diamante precioso desaparece de uma casa de campo na noite da festa de aniversário de uma jovem. Vários narradores e um detetive tentam descobrir o culpado. Frequentemente considerado o primeiro romance policial em inglês.', 'Avançado', array['clássico', 'detetive', 'diamante', 'século xix', 'mistério']),
  ('7ac32cf9-3ba2-59cf-9c4f-5709d111b613', 'The Cuckoo''s Calling', 'Robert Galbraith', 'Mistério e Suspense', 'en', 'O detetive particular Cormoran Strike, em dificuldades financeiras, é contratado para investigar a morte de uma famosa modelo, dada como suicídio. Com a ajuda da assistente Robin, ele reconstitui os últimos dias dela. Um policial clássico com toque moderno.', 'Intermediário', array['detetive', 'londres', 'cormoran strike', 'mistério', 'policial']),
  ('8be07c1e-a3d7-55c5-a142-6e63efbcc5ae', 'Presumed Innocent', 'Scott Turow', 'Mistério e Suspense', 'en', 'O promotor Rusty Sabich é encarregado de investigar a morte de uma colega e, aos poucos, torna-se o principal acusado. O julgamento exige que ele confronte seu passado. Um thriller jurídico denso e complexo.', 'Avançado', array['thriller jurídico', 'julgamento', 'corrupção', 'investigação', 'suspense']),
  ('6a613791-bdc9-5808-8124-a616fcdb3b53', 'The Bone Collector', 'Jeffery Deaver', 'Mistério e Suspense', 'en', 'O ex-chefe da perícia Lincoln Rhyme, paralisado em uma cama, comanda a caça a um assassino em Nova York usando como olhos a jovem policial Amelia Donaghy. As pistas deixadas pelo criminoso formam um jogo mortal. Um thriller forense envolvente.', 'Intermediário', array['thriller', 'serial killer', 'forense', 'nova york', 'investigação']),
  ('5bf5ebc6-88f8-5861-ac0e-0f1291223f4b', 'Along Came a Spider', 'James Patterson', 'Mistério e Suspense', 'en', 'O psicólogo e detetive Alex Cross investiga o sequestro de duas crianças em uma escola de elite em Washington. Um criminoso engenhoso provoca a polícia a cada passo. Um thriller de capítulos curtos e ritmo rápido.', 'Iniciante', array['thriller', 'sequestro', 'detetive', 'washington', 'ritmo rápido']),
  ('9a183186-76f8-5e1f-af6c-8d17826a1f39', 'The Lincoln Lawyer', 'Michael Connelly', 'Mistério e Suspense', 'en', 'Mickey Haller, advogado de defesa que trabalha dentro de um carro, aceita o caso de um rico acusado de agressão. Aos poucos, percebe que foi manipulado. Um thriller jurídico de Los Angeles cheio de reviravoltas.', 'Intermediário', array['thriller jurídico', 'advogado', 'los angeles', 'defesa', 'suspense']),
  ('594863d4-7a61-5b6d-9ddc-fa58df6c9feb', 'The Fault in Our Stars', 'John Green', 'Juvenil', 'en', 'Hazel Grace, adolescente com câncer, conhece Augustus Waters num grupo de apoio e os dois se apaixonam. Juntos, viajam a Amsterdã em busca de respostas de um escritor favorito. Uma história comovente e bem-humorada sobre amor e finitude.', 'Intermediário', array['romance', 'adolescência', 'doença', 'amor', 'juvenil'])
insert into public.livros (id, titulo, autor, genero, idioma, resumo, nivel_dificuldade, tags) values
  ('5e14ae0a-1a9f-52a1-94e4-b1e304620418', 'Looking for Alaska', 'John Green', 'Juvenil', 'en', 'Miles, um garoto tímido, vai para um internato no Alabama e conhece a imprevisível Alaska Young. A amizade e as travessuras do grupo são marcadas por um acontecimento que muda tudo. Um romance de formação sobre luto e culpa.', 'Intermediário', array['adolescência', 'internato', 'amizade', 'perda', 'juvenil']),
  ('6781f2b7-5211-5e6b-8b7f-ea6c7949d779', 'Paper Towns', 'John Green', 'Juvenil', 'en', 'Quentin passa uma noite de aventuras com a vizinha Margo, que depois desaparece deixando pistas. Ele e os amigos tentam decifrá-las numa viagem. Uma história sobre idealização e conhecer de verdade as pessoas.', 'Intermediário', array['mistério', 'adolescência', 'amizade', 'estrada', 'juvenil']),
  ('b3c4f607-e96c-5b4e-a3fe-1573d64d6edb', 'An Abundance of Katherines', 'John Green', 'Juvenil', 'en', 'Colin, um ex-menino-prodígio que já foi deixado por dezenove garotas chamadas Katherine, sai numa viagem de carro com um amigo. Ele tenta criar uma fórmula matemática para prever relacionamentos. Uma comédia romântica com muitas notas de rodapé.', 'Intermediário', array['humor', 'adolescência', 'matemática', 'estrada', 'juvenil']),
  ('1ef87c9f-b61c-5534-9743-526e642a074f', 'Turtles All the Way Down', 'John Green', 'Juvenil', 'en', 'Aza, uma adolescente que luta contra pensamentos obsessivos, investiga com a melhor amiga o sumiço de um bilionário. A história mostra como é viver com ansiedade e como isso afeta as relações. Um romance sensível sobre saúde mental.', 'Intermediário', array['saúde mental', 'adolescência', 'mistério', 'amizade', 'juvenil']),
  ('ee29ee46-cb26-5677-907d-452857b74310', 'Eleanor & Park', 'Rainbow Rowell', 'Juvenil', 'en', 'Em 1986, Eleanor e Park, dois adolescentes deslocados, começam a conversar no ônibus escolar e a dividir quadrinhos e música. Aos poucos, o afeto cresce apesar dos problemas de cada um. Um romance doce e realista sobre primeiro amor.', 'Intermediário', array['romance', 'adolescência', 'anos 1980', 'música', 'juvenil']),
  ('6c4ed4c5-1b4a-5295-98bc-f8bd1e97aaf4', 'Fangirl', 'Rainbow Rowell', 'Juvenil', 'en', 'Cath, fã apaixonada de uma saga de fantasia, entra na faculdade e tem dificuldade para se adaptar longe da irmã gêmea. Ela escreve fanfics e aos poucos abre espaço para novas amizades. Uma história sobre crescer sem abandonar o que se ama.', 'Intermediário', array['faculdade', 'escrita', 'família', 'amor', 'juvenil']),
  ('65ab6393-1d8a-501d-80e3-2f257863a8e7', 'Attachments', 'Rainbow Rowell', 'Romance', 'en', 'Em 1999, Lincoln trabalha numa redação monitorando e-mails dos funcionários e acaba se encantando por duas colegas que conversam sobre a vida pessoal. Ele se apaixona sem conhecer ninguém pessoalmente. Uma comédia romântica leve e simpática.', 'Intermediário', array['comédia romântica', 'anos 1990', 'trabalho', 'e-mails', 'amor']),
  ('b8f210bb-ae65-570c-bc41-7265a8fa95cd', 'The Notebook', 'Nicholas Sparks', 'Romance', 'en', 'Noah e Allie se apaixonam num verão na Carolina do Norte, mas diferenças sociais os separam. Anos depois, um idoso lê a história a uma mulher com problemas de memória. Um romance sentimental sobre amor duradouro.', 'Iniciante', array['romance', 'amor', 'década de 1940', 'carolina do norte', 'memória']),
  ('29553bd1-442a-5906-abf5-8c5f0456bad5', 'A Walk to Remember', 'Nicholas Sparks', 'Romance', 'en', 'Landon, um adolescente popular, é obrigado a participar de uma peça escolar e se aproxima de Jamie, a filha do pastor, discreta e firme. A convivência muda os dois. Um romance juvenil sobre amor e transformação.', 'Iniciante', array['romance', 'adolescência', 'fé', 'amor', 'carolina do norte']),
  ('2c340c2d-c8e8-5a8d-a2cc-d149ca4bb5c9', 'Dear John', 'Nicholas Sparks', 'Romance', 'en', 'John, um soldado americano, conhece Savannah durante uma licença e eles se apaixonam. Quando ele precisa voltar ao serviço, mantêm o romance por cartas. Um romance sobre distância e escolhas difíceis.', 'Iniciante', array['romance', 'cartas', 'soldado', 'amor', 'distância']),
  ('7b6add23-254b-5e8a-83a1-ed65572f39a6', 'Message in a Bottle', 'Nicholas Sparks', 'Romance', 'en', 'Theresa encontra na praia uma carta de amor dentro de uma garrafa e decide descobrir quem a escreveu. Ela conhece Garrett, viúvo ainda preso ao passado. Um romance sobre perda e recomeço.', 'Iniciante', array['romance', 'carta', 'amor', 'luto', 'carolina do norte']),
  ('e6c796c6-1306-542d-81ce-7e142efe82e7', 'The Last Song', 'Nicholas Sparks', 'Romance', 'en', 'Ronnie, adolescente rebelde, é obrigada a passar o verão com o pai pianista numa cidade litorânea. Aos poucos, ela se reaproxima dele e vive o primeiro amor. Uma história sobre perdão e laços de família.', 'Iniciante', array['romance', 'família', 'música', 'adolescência', 'litoral']),
  ('2e922d81-e5f3-530e-a27a-eb8c512fabac', 'Me Before You', 'Jojo Moyes', 'Romance', 'en', 'Louisa Clark, que perdeu o emprego, passa a cuidar de Will Traynor, um homem que ficou paraplégico depois de um acidente. A convivência muda a vida dos dois e levanta dilemas difíceis. Um romance emocionante sobre amor, dignidade e autonomia.', 'Intermediário', array['romance', 'amor', 'deficiência', 'escolhas', 'drama']),
  ('db24c920-525f-5dc3-adca-1dd0d30f117a', 'After You', 'Jojo Moyes', 'Romance', 'en', 'Louisa tenta reconstruir a vida mais de um ano depois de um grande luto e é surpreendida por um acontecimento inesperado. Ela precisa decidir como seguir adiante. Uma continuação sobre perda e novos começos.', 'Intermediário', array['romance', 'luto', 'recomeço', 'drama', 'amor']),
  ('26c5c1f2-1c8a-568e-9aa1-b7af168eb179', 'The Giver of Stars', 'Jojo Moyes', 'Ficção Clássica', 'en', 'Em 1937, mulheres do Kentucky formam uma biblioteca itinerante e entregam livros a cavalo em comunidades isoladas. A coragem e a amizade delas enfrentam preconceito e perigo. Um romance histórico sobre o poder da leitura.', 'Intermediário', array['biblioteca', 'mulheres', 'década de 1930', 'kentucky', 'amizade']),
  ('b6aa0d22-14fb-52da-a570-2bfc71681ada', 'It Ends with Us', 'Colleen Hoover', 'Romance', 'en', 'Lily Bloom se apaixona pelo cirurgião Ryle, mas o relacionamento se mostra mais difícil do que ela esperava, e um antigo amor reaparece. A história aborda de forma direta temas como violência doméstica e coragem de recomeçar. Um romance emotivo e muito popular.', 'Iniciante', array['romance', 'relacionamento', 'violência doméstica', 'escolhas', 'contemporâneo']),
  ('1909107f-7c3a-5ca2-83fe-7f5647922f34', 'Verity', 'Colleen Hoover', 'Mistério e Suspense', 'en', 'A escritora Lowen é contratada para terminar a série de uma autora famosa, impedida de escrever, e encontra um manuscrito que parece uma autobiografia sombria. Enquanto lê, ela se aproxima do marido da autora. Um thriller psicológico de ritmo rápido.', 'Iniciante', array['thriller psicológico', 'suspense', 'escritora', 'segredos', 'romance']),
  ('5eb32a1f-5e39-565b-a887-b084180df754', 'Ugly Love', 'Colleen Hoover', 'Romance', 'en', 'Tate e Miles começam um acordo sem compromisso, mas as regras ficam cada vez mais difíceis de seguir. A narrativa alterna presente e passado para explicar por que ele evita o amor. Um romance intenso sobre feridas e confiança.', 'Iniciante', array['romance', 'relacionamento', 'passado', 'contemporâneo', 'drama']),
  ('db57e952-334d-5055-8472-a0b84d32f1a5', 'Where the Crawdads Sing', 'Delia Owens', 'Drama', 'en', 'Kya, a "garota do pântano", cresce praticamente sozinha nos pântanos da Carolina do Norte. Quando um jovem da cidade aparece morto, ela se torna a principal suspeita. Um romance de natureza, solidão e mistério.', 'Intermediário', array['natureza', 'solidão', 'mistério', 'carolina do norte', 'romance']),
  ('90d5c574-bd25-580c-8c01-1a00f1f961e6', 'Normal People', 'Sally Rooney', 'Romance', 'en', 'Connell e Marianne se conhecem no colégio, na Irlanda, e mantêm uma relação intensa que se repete ao longo dos anos. Eles se separam e se reencontram, enquanto mudam e lidam com classe e autoestima. Um romance contemporâneo sobre intimidade.', 'Intermediário', array['romance', 'irlanda', 'juventude', 'classe social', 'relacionamentos']),
  ('80e4a1c7-13c0-56d0-b62f-7e142313f09c', 'Conversations with Friends', 'Sally Rooney', 'Romance', 'en', 'Frances, estudante e poeta em Dublin, e a amiga Bobbi se aproximam de um casal mais velho. Ela inicia um romance com o marido e lida com questões de lealdade e identidade. Um retrato afiado das relações modernas.', 'Intermediário', array['romance', 'dublin', 'amizade', 'juventude', 'relacionamentos']),
  ('d73b1542-126a-558b-ab6c-b02b0cb63fdb', 'Beach Read', 'Emily Henry', 'Romance', 'en', 'January, autora de romances, e Gus, escritor de livros sérios, são vizinhos e rivais e resolvem trocar de gênero durante o verão. A competição vira aproximação, e os dois falam sobre luto e inspiração. Uma comédia romântica sobre escrever e recomeçar.', 'Intermediário', array['comédia romântica', 'escritores', 'verão', 'amor', 'contemporâneo']),
  ('d97be25c-b571-533d-bd32-aa1fec4c158c', 'People We Meet on Vacation', 'Emily Henry', 'Romance', 'en', 'Poppy e Alex são melhores amigos e viajam juntos todo verão, até que uma briga os afasta. Ela propõe uma última viagem para tentar consertar tudo. Um romance sobre amizade, viagens e sentimentos nunca ditos.', 'Intermediário', array['comédia romântica', 'amizade', 'viagens', 'amor', 'contemporâneo']),
  ('d80374a8-deb1-59b2-a21f-c45fb5c442a6', 'The Seven Husbands of Evelyn Hugo', 'Taylor Jenkins Reid', 'Romance', 'en', 'A lendária atriz Evelyn Hugo escolhe uma jovem jornalista desconhecida para contar sua história de glamour e sete casamentos. Aos poucos, a verdade por trás de cada um vem à tona. Um romance sobre fama, amor e escolhas.', 'Intermediário', array['romance', 'hollywood', 'segredos', 'fama', 'drama']),
  ('95615b2b-c7c6-5fce-8a8f-e1c9e9a09d77', 'Daisy Jones & The Six', 'Taylor Jenkins Reid', 'Ficção Clássica', 'en', 'Contado em forma de entrevistas, o livro narra a ascensão e a queda de uma banda de rock dos anos 1970 e sua cantora. As versões dos membros se contradizem. Uma história sobre fama, criação e conflito.', 'Intermediário', array['música', 'anos 1970', 'rock', 'entrevistas', 'drama']),
  ('3582d969-800f-59e3-9718-e43fedf28011', 'Malibu Rising', 'Taylor Jenkins Reid', 'Drama', 'en', 'Em 1983, os irmãos Riva organizam sua grande festa anual em Malibu, enquanto segredos de família e tensões chegam ao limite. A história alterna passado e noite da festa. Um romance sobre família e lealdade.', 'Intermediário', array['família', 'anos 1980', 'festa', 'malibu', 'drama']),
  ('be9425c0-aeb0-556f-9779-1dcb58aae9cc', 'Big Little Lies', 'Liane Moriarty', 'Mistério e Suspense', 'en', 'Em uma cidade litorânea da Austrália, três mães da mesma escola se envolvem em conflitos que culminam num incidente numa noite de gala. A narrativa mostra o que cada uma esconde por trás da aparência perfeita. Um suspense doméstico com humor ácido.', 'Intermediário', array['suspense', 'mães', 'subúrbio', 'segredos', 'drama']),
  ('7916cc48-8d21-54a8-a377-69f82f4b8777', 'The Husband''s Secret', 'Liane Moriarty', 'Mistério e Suspense', 'en', 'Cecilia encontra em casa uma carta do marido para ser aberta só depois da morte dele. O que lê muda sua vida e a de outras pessoas. Um romance sobre verdade, culpa e consequências.', 'Intermediário', array['suspense', 'família', 'segredos', 'culpa', 'drama']),
  ('ac0f0f3b-24d8-526b-b939-0b7d21b2c77a', 'The Kite Runner', 'Khaled Hosseini', 'Drama', 'en', 'Em Cabul, os meninos Amir e Hassan crescem como melhores amigos, até que uma traição de Amir os separa. Décadas depois, ele tenta se redimir. Um romance comovente sobre culpa, perdão e amizade.', 'Intermediário', array['afeganistão', 'amizade', 'culpa', 'redenção', 'drama']),
  ('bb56d16b-c506-52bd-aaae-433b92b12de8', 'A Thousand Splendid Suns', 'Khaled Hosseini', 'Drama', 'en', 'Mariam e Laila, de gerações diferentes, têm suas vidas ligadas pelo casamento com o mesmo homem no Afeganistão em guerra. A convivência as aproxima e as obriga a resistir. Um romance sobre amizade e sobrevivência.', 'Intermediário', array['afeganistão', 'mulheres', 'guerra', 'amizade', 'drama']),
  ('d307b925-d3d3-58e5-9b29-9497840ccd16', 'And the Mountains Echoed', 'Khaled Hosseini', 'Drama', 'en', 'Em 1952, a vida de dois irmãos afegãos muda para sempre quando são separados. A narrativa salta no tempo e entre personagens ligados por essa decisão. Um romance sobre laços, sacrifício e memória.', 'Intermediário', array['afeganistão', 'família', 'separação', 'histórias', 'drama']),
  ('460880f8-adac-564a-a1b2-c975ae0c090d', 'The Nightingale', 'Kristin Hannah', 'Drama', 'en', 'Duas irmãs francesas, Vianne e Isabelle, enfrentam a ocupação nazista de maneiras diferentes: uma tenta proteger a família, a outra se junta à resistência. A guerra testa os laços e a coragem delas. Um romance histórico de coragem e sacrifício.', 'Intermediário', array['segunda guerra', 'frança', 'irmãs', 'resistência', 'história']),
  ('266e5b9d-1cb4-5c65-a566-d6d40bf213b7', 'The Great Alone', 'Kristin Hannah', 'Drama', 'en', 'Em 1974, uma família se muda para o Alasca em busca de recomeço, mas o isolamento e os traumas do pai tornam a vida difícil. A filha adolescente, Leni, narra o que vê. Um romance sobre natureza e família.', 'Intermediário', array['alasca', 'família', 'sobrevivência', 'década de 1970', 'drama']),
  ('d0c03274-5717-5120-a95e-0eb075f5e52b', 'The Book Thief', 'Markus Zusak', 'Drama', 'en', 'Narrada pela própria Morte, a história acompanha Liesel, uma menina que rouba livros na Alemanha nazista e encontra neles refúgio. Ela ajuda a esconder um judeu no porão da família adotiva. Um romance comovente sobre palavras e humanidade.', 'Avançado', array['segunda guerra', 'alemanha', 'livros', 'narrador morte', 'história']),
  ('caacc755-4100-5684-bd46-fd0a61543162', 'All the Light We Cannot See', 'Anthony Doerr', 'Drama', 'en', 'Marie-Laure, uma menina cega que vive em Paris, e Werner, um garoto alemão talentoso com rádios, têm vidas que se cruzam durante a Segunda Guerra. A história alterna os dois ao longo dos anos de conflito. Um romance poético sobre guerra e conexão.', 'Avançado', array['segunda guerra', 'frança', 'alemanha', 'rádio', 'história']),
  ('1da9e292-cf57-5e62-afe7-42c40a590918', 'The Help', 'Kathryn Stockett', 'Drama', 'en', 'Em Jackson, nos anos 1960, a jovem Skeeter convence empregadas negras a contar suas experiências em casas de famílias brancas. O projeto é perigoso e muda a vida de todas. Um romance sobre racismo, coragem e voz.', 'Intermediário', array['racismo', 'anos 1960', 'mississippi', 'amizade', 'sociedade']),
  ('527389ff-50ae-5a62-aa94-6137d7483413', 'The Secret Life of Bees', 'Sue Monk Kidd', 'Drama', 'en', 'Em 1964, Lily foge com sua ama, Rosaleen, e chega à casa de três irmãs apicultoras na Carolina do Sul. Ali encontra acolhimento e descobre verdades sobre a mãe. Um romance de formação sobre pertencimento.', 'Intermediário', array['racismo', 'anos 1960', 'família', 'mel', 'formação']),
  ('74c8ecc0-4c4b-5428-b81a-31b5952e0fbe', 'Eat, Pray, Love', 'Elizabeth Gilbert', 'Biografia e Memórias', 'en', 'Depois de um divórcio doloroso, a autora passa um ano na Itália, na Índia e na Indonésia em busca de prazer, espiritualidade e equilíbrio. O relato mistura humor e reflexão. Uma das memórias de viagem mais lidas.', 'Intermediário', array['memórias', 'viagem', 'autoconhecimento', 'espiritualidade', 'mulheres']),
  ('8e7802da-0b0c-592a-a833-0f42b9b119ca', 'Bridget Jones''s Diary', 'Helen Fielding', 'Romance', 'en', 'Bridget, uma londrina de trinta e poucos anos, registra em um diário suas tentativas de emagrecer, parar de fumar e encontrar o amor. Ela se divide entre o chefe encantador e o reservado Mark Darcy. Uma comédia romântica inspirada em Orgulho e Preconceito.', 'Intermediário', array['comédia romântica', 'londres', 'diário', 'humor', 'anos 1990']),
  ('c080ce3e-f7c6-50c0-9946-85ac0950e00f', 'Outlander', 'Diana Gabaldon', 'Romance', 'en', 'A enfermeira Claire Randall toca uma pedra antiga e vai parar na Escócia de 1743, onde se envolve com o guerreiro Jamie Fraser. Presa entre dois tempos, precisa escolher onde pertence. Um romance histórico longo e envolvente.', 'Avançado', array['romance histórico', 'viagem no tempo', 'escócia', 'aventura', 'fantasia']),
  ('d5d221cc-885b-57b2-8d31-650df5b5b9c2', 'The Hating Game', 'Sally Thorne', 'Romance', 'en', 'Lucy e Joshua dividem uma sala de trabalho e uma rivalidade constante, até que uma disputa por promoção muda o clima. A implicância mútua esconde algo mais. Uma comédia romântica ágil sobre inimigos que se apaixonam.', 'Intermediário', array['comédia romântica', 'trabalho', 'rivalidade', 'humor', 'contemporâneo']),
  ('9b855b52-f3ba-57c2-9d94-a4f61dcf8f9c', 'The Love Hypothesis', 'Ali Hazelwood', 'Romance', 'en', 'Olive, doutoranda, finge namorar um professor famoso por ser difícil para convencer a amiga de que superou um término. O combinado vai ficando complicado. Uma comédia romântica ambientada na vida acadêmica.', 'Intermediário', array['comédia romântica', 'ciência', 'universidade', 'namoro de fachada', 'contemporâneo']),
  ('2a24eb4a-f149-5cec-b54a-3e5e5e4ee039', 'Red, White & Royal Blue', 'Casey McQuiston', 'Romance', 'en', 'Alex, filho da presidente dos Estados Unidos, e o príncipe Henry são rivais públicos e precisam fingir amizade para evitar um escândalo. Aos poucos, o relacionamento se transforma. Uma comédia romântica leve e cheia de humor.', 'Intermediário', array['comédia romântica', 'política', 'realeza', 'amor', 'contemporâneo']),
  ('6617b754-f579-5a86-8e15-ec1f40501fae', 'The Rosie Project', 'Graeme Simsion', 'Romance', 'en', 'Don, um professor de genética metódico, cria um questionário para encontrar a esposa ideal e conhece Rosie, que não se encaixa em nenhum critério. A convivência o desafia a mudar. Uma comédia romântica sobre neurodiversidade e amor.', 'Intermediário', array['comédia romântica', 'ciência', 'humor', 'amor', 'austrália']),
  ('2b474724-5986-5315-a8ac-b72883839fcc', 'One Day', 'David Nicholls', 'Romance', 'en', 'Emma e Dexter passam a noite da formatura juntos e a história acompanha como estão no mesmo dia do ano durante vinte anos. Entre amizade e desencontros, a relação deles muda com a vida. Um romance sobre tempo, escolhas e amor.', 'Intermediário', array['romance', 'amizade', 'tempo', 'drama', 'anos 1980']),
  ('d46a7f57-7360-531b-80d7-07400ec8579b', 'The Guernsey Literary and Potato Peel Pie Society', 'Mary Ann Shaffer and Annie Barrows', 'Ficção Clássica', 'en', 'Em 1946, a escritora Juliet troca cartas com moradores da ilha de Guernsey e descobre como um clube de leitura os ajudou durante a ocupação alemã. Ela viaja para conhecê-los. Um romance epistolar caloroso sobre livros e comunidade.', 'Intermediário', array['cartas', 'pós-guerra', 'ilha', 'livros', 'comunidade']),
  ('1c339300-6700-534e-bb76-9cdd3b8dbe38', 'The Midnight Library', 'Matt Haig', 'Ficção Científica', 'en', 'Nora, infeliz e cheia de arrependimentos, chega a uma biblioteca em que cada livro é uma vida que poderia ter vivido. Ela testa várias possibilidades em busca da melhor. Uma fábula sobre escolhas e esperança.', 'Intermediário', array['vida', 'escolhas', 'arrependimento', 'fantasia', 'esperança']),
  ('3fd854d1-165e-59e5-985b-ec3da2801314', 'Little Fires Everywhere', 'Celeste Ng', 'Drama', 'en', 'Em Shaker Heights, a família Richardson aluga uma casa a Mia e sua filha Pearl, e as vidas das duas famílias se entrelaçam. Um caso de adoção divide a cidade e traz segredos à tona. Um romance sobre maternidade e privilégio.', 'Intermediário', array['família', 'subúrbio', 'segredos', 'maternidade', 'drama']),
  ('6a9bc283-098e-5bde-a5e3-b4465e197923', 'Where''d You Go, Bernadette', 'Maria Semple', 'Humor', 'en', 'Bee, uma adolescente, tenta descobrir o paradeiro da mãe, Bernadette, arquiteta excêntrica que desapareceu. A história é contada por e-mails, bilhetes e documentos. Uma comédia sobre família e criatividade.', 'Intermediário', array['humor', 'família', 'mistério', 'seattle', 'sátira']),
  ('7686e807-e98f-5491-b1a3-d46f04b8220b', 'The Remains of the Day', 'Kazuo Ishiguro', 'Drama', 'en', 'Em 1956, o mordomo Stevens faz uma viagem pelo interior da Inglaterra e relembra os anos de serviço na mansão de Darlington Hall. Entre lembranças, ele revela dedicação cega, sentimentos reprimidos e escolhas que nunca questionou. Um romance delicado sobre dever e oportunidades perdidas.', 'Avançado', array['mordomo', 'memória', 'inglaterra', 'dever', 'arrependimento']),
  ('003d9dbc-9158-5b5b-bc41-7580ee5341c9', 'Never Let Me Go', 'Kazuo Ishiguro', 'Ficção Científica', 'en', 'Kathy recorda a infância no internato de Hailsham e a amizade com Ruth e Tommy. Aos poucos, percebemos o destino reservado aos alunos. Um romance suave e perturbador sobre amor, memória e o valor de uma vida.', 'Intermediário', array['distopia', 'amizade', 'memória', 'ética', 'internato']),
  ('aeff87b6-0c07-5ff8-a6d4-fdb2a1cc9a94', 'Klara and the Sun', 'Kazuo Ishiguro', 'Ficção Científica', 'en', 'Klara, uma "amiga artificial" movida a energia solar, observa o mundo da vitrine de uma loja até ser escolhida por uma adolescente doente. Ela tenta cuidar da menina com devoção. Uma história sobre amor, fé e o que significa ser humano.', 'Intermediário', array['inteligência artificial', 'amizade', 'solidão', 'futuro', 'humanidade']),
  ('e0d29838-6683-511d-bd5e-1bc590ee804f', 'Atonement', 'Ian McEwan', 'Drama', 'en', 'Em 1935, a menina Briony Tallis acusa injustamente o namorado da irmã de um crime, e essa mentira muda a vida de todos. A história avança até a Segunda Guerra e a velhice da narradora. Um romance sobre culpa, perdão e o poder da ficção.', 'Avançado', array['culpa', 'guerra', 'inglaterra', 'imaginação', 'redenção']),
  ('e48879b7-f686-58da-b15a-b24ec2923c6f', 'Enduring Love', 'Ian McEwan', 'Drama', 'en', 'Depois de um acidente de balão, Joe Rose é seguido por um desconhecido que se convence de que os dois têm um vínculo especial. A perseguição abala a relação com a namorada. Um romance psicológico sobre obsessão e racionalidade.', 'Intermediário', array['obsessão', 'psicológico', 'acidente', 'amor', 'suspense']),
  ('38add66a-2b9f-5545-bf72-fe2dad0b8e57', 'On Chesil Beach', 'Ian McEwan', 'Drama', 'en', 'Em 1962, um jovem casal passa a noite de núpcias num hotel à beira-mar, tenso e inseguro. Pequenos mal-entendidos mudam o futuro dos dois. Uma novela curta sobre expectativas, silêncio e a dificuldade de falar de intimidade.', 'Intermediário', array['casamento', 'anos 1960', 'silêncio', 'novela', 'inglaterra']),
  ('c3b2317e-dca8-58a0-b170-d77ef10e603b', 'Amsterdam', 'Ian McEwan', 'Drama', 'en', 'Depois do funeral de uma ex-amante em comum, dois velhos amigos, um compositor e um jornalista, fazem um pacto sombrio. As decisões profissionais de cada um provocam consequências sérias. Uma sátira ácida sobre ambição e ética.', 'Intermediário', array['amizade', 'moral', 'ambição', 'novela', 'inglaterra']),
  ('fc4d03d6-8dd8-5c6a-9827-f96aae31c8d2', 'The Blind Assassin', 'Margaret Atwood', 'Drama', 'en', 'Iris Chase, já idosa, relembra a vida e a morte misteriosa da irmã Laura. A narrativa se divide entre memórias, notícias de jornal e um livro de ficção científica. Um romance em camadas sobre segredos de família.', 'Avançado', array['família', 'segredos', 'história', 'romance dentro de romance', 'canadá']),
  ('c9f25f7d-fe9a-57d2-9a32-66162c220c97', 'Alias Grace', 'Margaret Atwood', 'Drama', 'en', 'Em 1843, Grace Marks é condenada por assassinato no Canadá e cumpre pena, mas ninguém sabe ao certo se é culpada. Um psiquiatra tenta descobrir a verdade por meio de suas lembranças. Um romance histórico baseado num caso real.', 'Avançado', array['baseado em fatos', 'século xix', 'crime', 'memória', 'canadá']),
  ('c308a0aa-1048-5ec6-96b1-1460b847f852', 'The Testaments', 'Margaret Atwood', 'Ficção Científica', 'en', 'Quinze anos depois de O Conto da Aia, três mulheres com vidas muito diferentes contam o que viram do regime de Gilead. As histórias se cruzam e levam a um plano arriscado. Uma continuação sobre poder, segredos e resistência.', 'Intermediário', array['distopia', 'gilead', 'feminismo', 'resistência', 'continuação']),
  ('b06f41e2-d660-5ac5-a5a7-c5a3495cec21', 'The Secret History', 'Donna Tartt', 'Drama', 'en', 'Richard entra numa pequena faculdade de Vermont e passa a integrar um grupo fechado de estudantes de grego antigo. Um crime cometido por eles muda o rumo do grupo. Um romance sobre obsessão, culpa e fascínio pela beleza.', 'Avançado', array['faculdade', 'grupo de amigos', 'crime', 'clássicos', 'suspense']),
  ('7478548f-13f4-55b0-a73d-85e4758ea18c', 'The Goldfinch', 'Donna Tartt', 'Drama', 'en', 'Theo Decker sobrevive a um atentado num museu e leva consigo um pequeno quadro famoso. O objeto o acompanha por anos de perdas, amizades e riscos. Um romance extenso sobre luto, arte e destino.', 'Avançado', array['arte', 'luto', 'juventude', 'crime', 'nova york']),
  ('6885f9b4-7fd0-5dee-81b5-a4e71506df80', 'White Teeth', 'Zadie Smith', 'Drama', 'en', 'Em Londres, a amizade entre Archie, um inglês, e Samad, um bengalês, atravessa décadas e envolve as famílias dos dois. O livro mistura humor, religião e identidade. Um retrato animado da sociedade multicultural britânica.', 'Avançado', array['londres', 'imigração', 'humor', 'famílias', 'identidade']),
  ('e7efdf19-b9f3-5402-bc60-5b6e038896ca', 'On Beauty', 'Zadie Smith', 'Drama', 'en', 'As famílias de dois professores rivais, numa cidade universitária americana, se cruzam por causa de casamentos, traições e diferenças de ideias. O romance é inspirado em Howards End, de Forster. Uma comédia de costumes sobre arte, raça e valores.', 'Avançado', array['família', 'universidade', 'racismo', 'arte', 'boston']),
  ('13b1f516-6bcb-56e3-985c-62bb63439b5c', 'The Namesake', 'Jhumpa Lahiri', 'Drama', 'en', 'Gogol Ganguli, filho de imigrantes bengaleses nos Estados Unidos, se incomoda com o nome incomum que recebeu do pai. Ao crescer, ele busca seu lugar entre duas culturas. Um romance delicado sobre identidade e pertencimento.', 'Intermediário', array['imigração', 'identidade', 'família', 'índia', 'estados unidos']),
  ('091b2239-e30f-55f1-a67d-35c70de4f3a1', 'Interpreter of Maladies', 'Jhumpa Lahiri', 'Contos', 'en', 'Nove contos acompanham indianos e imigrantes em situações de afastamento, desencontros e pequenas descobertas. A escrita é simples e muito precisa. Uma coletânea premiada sobre vínculos e distância.', 'Intermediário', array['índia', 'imigração', 'contos', 'relacionamentos', 'premiado']),
  ('df1a4a05-d30d-5844-9904-dcf6d5e0779b', 'Americanah', 'Chimamanda Ngozi Adichie', 'Drama', 'en', 'Ifemelu e Obinze se apaixonam na Nigéria, mas a vida os leva a caminhos diferentes: ela emigra para os Estados Unidos. Anos depois, ambos reavaliam o que deixaram. Um romance sobre raça, imigração e amor.', 'Intermediário', array['nigéria', 'imigração', 'raça', 'amor', 'identidade']),
  ('0fdf8c79-d266-5063-abd8-9c9a4b61b39d', 'Half of a Yellow Sun', 'Chimamanda Ngozi Adichie', 'Drama', 'en', 'Durante a guerra de Biafra, na Nigéria dos anos 1960, três pessoas, uma professora, um criado e um escritor inglês, têm suas vidas transformadas. Amores e lealdades são postos à prova. Um romance histórico sobre guerra e família.', 'Intermediário', array['nigéria', 'guerra', 'biafra', 'história', 'amor']),
  ('4cd88409-8103-5dda-af81-453cab085492', 'Purple Hibiscus', 'Chimamanda Ngozi Adichie', 'Drama', 'en', 'Kambili, de quinze anos, vive sob o rigor de um pai religioso e violento numa casa nigeriana. Uma temporada na casa de uma tia lhe mostra outro jeito de viver. Um romance de formação sobre fé, liberdade e silêncio.', 'Intermediário', array['nigéria', 'família', 'religião', 'adolescência', 'liberdade']),
  ('dc768107-26c2-5faf-9d31-716bc820c825', 'The Underground Railroad', 'Colson Whitehead', 'Ficção Clássica', 'en', 'Cora, uma jovem escravizada na Geórgia, foge por uma ferrovia subterrânea de verdade, que a leva a estados diferentes, cada um com um tipo de horror e de esperança. Um caçador de escravos a persegue. Um romance histórico de forte imaginação.', 'Intermediário', array['escravidão', 'fuga', 'história', 'ficção histórica', 'estados unidos']),
  ('d90460fc-cb49-563c-bb1f-6ad12410f757', 'The Nickel Boys', 'Colson Whitehead', 'Drama', 'en', 'Elwood, um garoto negro estudioso, é enviado por engano a um reformatório violento na Flórida dos anos 1960. Lá ele faz amizade e tenta manter a esperança. Um romance duro, baseado em fatos, sobre injustiça e resistência.', 'Intermediário', array['racismo', 'reformatório', 'anos 1960', 'amizade', 'história']),
  ('9b61d160-3239-5120-8262-98b591302d99', 'Wolf Hall', 'Hilary Mantel', 'Ficção Clássica', 'en', 'Thomas Cromwell, filho de um ferreiro, sobe na corte de Henrique VIII durante a crise do casamento do rei. A narrativa em presente acompanha seus planos e sua inteligência política. Um romance histórico premiado, com linguagem rica.', 'Avançado', array['história', 'henrique viii', 'inglaterra', 'poder', 'romance histórico']),
  ('dd24ced8-7881-5a1f-967b-d3f06fff43ff', 'Bring Up the Bodies', 'Hilary Mantel', 'Ficção Clássica', 'en', 'Cromwell se vê diante da missão de ajudar o rei a se livrar de Ana Bolena. A corte se enche de rivalidades e armadilhas. Uma continuação intensa, centrada em política e sobrevivência.', 'Avançado', array['história', 'henrique viii', 'inglaterra', 'poder', 'romance histórico']),
  ('b994bfc9-6d4e-5a89-ac71-bd0f85c5efe2', 'Life of Pi', 'Yann Martel', 'Aventura', 'en', 'Depois de um naufrágio, o jovem Pi Patel fica à deriva num bote salva-vidas com um tigre-de-bengala. Para sobreviver, ele precisa dividir o espaço com o animal durante meses. Uma aventura sobre fé, imaginação e narrativa.', 'Intermediário', array['sobrevivência', 'mar', 'fé', 'tigre', 'aventura']),
  ('709417e2-9465-5870-9df3-afb5b49cc2ee', 'No Country for Old Men', 'Cormac McCarthy', 'Mistério e Suspense', 'en', 'Um homem encontra dinheiro de uma negociação de drogas fracassada e é perseguido por um assassino implacável. O velho xerife tenta entender a violência crescente. Um thriller seco sobre destino e moral.', 'Avançado', array['crime', 'fronteira', 'texas', 'violência', 'perseguição']),
  ('7203c2f1-0973-5af7-996c-bbcbbc249dbd', 'Blood Meridian', 'Cormac McCarthy', 'Ficção Clássica', 'en', 'Na década de 1850, um garoto se junta a um bando que caça escalpos na fronteira entre os Estados Unidos e o México. A prosa poética contrasta com a brutalidade das cenas. Um faroeste sombrio e exigente.', 'Avançado', array['faroeste', 'violência', 'século xix', 'estilo', 'clássico moderno']),
  ('044ccb59-5ce4-5960-b720-37da0cd34ce7', 'The Corrections', 'Jonathan Franzen', 'Drama', 'en', 'Os pais idosos Alfred e Enid, do Meio-Oeste americano, tentam reunir os três filhos adultos, cada um com problemas próprios. A doença de Alfred avança e a família se vê diante de conflitos antigos. Um retrato satírico e comovente da família americana.', 'Avançado', array['família', 'estados unidos', 'sátira', 'saúde', 'sociedade']),
  ('d0b6dc9a-5abe-549d-ae30-ca6545acf70f', 'Freedom', 'Jonathan Franzen', 'Drama', 'en', 'Patty e Walter Berglund parecem o casal perfeito de um bairro liberal de Minnesota, até que escolhas pessoais e políticas os desfazem. O romance acompanha o casal ao longo de décadas. Um retrato de relações, ambição e liberdade nos Estados Unidos.', 'Avançado', array['família', 'casamento', 'política', 'sociedade', 'estados unidos']),
  ('209646c3-ea85-5038-ab97-159a62f94442', 'A Visit from the Goon Squad', 'Jennifer Egan', 'Ficção Clássica', 'en', 'Capítulos conectados acompanham pessoas ligadas ao mundo da música em épocas e lugares diferentes. Cada um tem um estilo próprio e mostra como o tempo muda as pessoas. Um romance fragmentado e premiado sobre tempo e perda.', 'Avançado', array['música', 'tempo', 'contos interligados', 'experimental', 'premiado']),
  ('6accbf29-2ead-5856-a75f-1c33a059c97a', 'The Brief Wondrous Life of Oscar Wao', 'Junot Díaz', 'Drama', 'en', 'Oscar, um jovem dominicano-americano obcecado por ficção científica, sonha em encontrar o amor. A história dele se mistura à de sua família e a uma suposta maldição ligada à ditadura de Trujillo. Um romance vibrante, cheio de gírias e referências nerds.', 'Avançado', array['imigração', 'república dominicana', 'maldição', 'família', 'humor']),
  ('ed12cc0c-b8a7-5b2c-8d51-ebbe2bd6b0ed', 'Gilead', 'Marilynne Robinson', 'Drama', 'en', 'Em 1956, o velho pastor John Ames escreve uma longa carta ao filho pequeno, contando a vida, as dúvidas e a história da família. A narrativa é calma, reflexiva e cheia de gratidão. Um romance premiado sobre fé e herança.', 'Avançado', array['fé', 'família', 'pai e filho', 'espiritualidade', 'interior americano']),
  ('44a6445b-255f-50b2-88db-7aa342a636a4', 'Lincoln in the Bardo', 'George Saunders', 'Ficção Clássica', 'en', 'Em 1862, o presidente Lincoln chora a morte do filho Willie num cemitério onde vozes de fantasmas comentam tudo. O livro mistura citações históricas e falas dos mortos. Um romance inventivo sobre luto e aceitação.', 'Avançado', array['fantasmas', 'luto', 'história', 'experimental', 'cemitério']),
  ('070e0311-950c-5f35-aea6-20b8d7c93fb3', 'A Little Life', 'Hanya Yanagihara', 'Drama', 'en', 'Quatro amigos se mudam para Nova York e constroem carreiras e vidas ao longo de décadas. A narrativa se concentra em Jude, que carrega um passado de abuso e dor. Um romance longo e intenso sobre amizade e trauma.', 'Avançado', array['amizade', 'trauma', 'nova york', 'drama', 'sofrimento']),
  ('0e27dcd2-dafd-5071-95f8-2710ad127de4', 'The Poisonwood Bible', 'Barbara Kingsolver', 'Drama', 'en', 'Em 1959, um pastor americano leva a esposa e as quatro filhas para o Congo Belga, ignorando os avisos sobre a região. A história é contada por elas, em vozes diferentes. Um romance sobre fé, arrogância e colonialismo.', 'Intermediário', array['congo', 'missionários', 'família', 'colonialismo', 'história']),
  ('110661cf-bf13-5997-bf8f-97b34700b7ac', 'Demon Copperhead', 'Barbara Kingsolver', 'Drama', 'en', 'Demon nasce numa família pobre dos Apalaches e luta para sobreviver entre o sistema de assistência, o futebol e a crise dos opioides. O romance reconta David Copperfield em um cenário atual. Uma história de resiliência contada com humor e dor.', 'Intermediário', array['infância', 'pobreza', 'apalaches', 'vício', 'formação']),
  ('182c71c7-4e2e-5566-a554-bc961febc7ce', 'Middlesex', 'Jeffrey Eugenides', 'Drama', 'en', 'Cal, que nasceu com uma condição intersexo, conta a história da família grega desde a fuga de Esmirna até Detroit. A herança genética e as escolhas dos antepassados explicam sua vida. Um romance épico sobre identidade e origem.', 'Avançado', array['identidade', 'família', 'imigração', 'gênero', 'história']),
  ('bf2b4059-20ae-53a0-85e0-23b81ceabe1c', 'The Virgin Suicides', 'Jeffrey Eugenides', 'Drama', 'en', 'Os meninos de um bairro americano tentam entender, décadas depois, a história das cinco irmãs Lisbon que viviam sob regras muito rígidas. A narrativa coletiva mistura memória e fascínio. Um romance melancólico sobre adolescência.', 'Intermediário', array['adolescência', 'mistério', 'subúrbio', 'anos 1970', 'memória']),
  ('27055bc3-9b6a-57f5-b9d4-25010ad64489', 'Cloud Atlas', 'David Mitchell', 'Ficção Científica', 'en', 'Seis histórias em épocas e gêneros diferentes se conectam por vestígios que passam de uma para outra. Cada uma muda de estilo, do diário de viagem ao futuro distante. Um romance ambicioso sobre poder, liberdade e repetição.', 'Avançado', array['histórias interligadas', 'tempo', 'experimental', 'distopia', 'aventura']),
  ('eca4dc65-8b18-5203-9ba1-010063e61406', 'The God of Small Things', 'Arundhati Roy', 'Drama', 'en', 'Na Índia, os gêmeos Rahel e Estha, muito ligados, vivem um acontecimento que muda a família em 1969. Mais de vinte anos depois, eles se reencontram. Um romance poético sobre castas, amor proibido e perda da infância.', 'Avançado', array['índia', 'família', 'castas', 'infância', 'tragédia']),
  ('d8288ae7-56d6-5ef2-a42d-074f4b893b2f', 'Midnight''s Children', 'Salman Rushdie', 'Ficção Clássica', 'en', 'Saleem Sinai nasce à meia-noite da independência da Índia, em 1947, e tem poderes ligados a outros nascidos à mesma hora. A vida dele se mistura com a história do país. Um romance de realismo mágico, cheio de humor e imaginação.', 'Avançado', array['índia', 'história', 'realismo mágico', 'independência', 'identidade']),
  ('3021c3d8-d185-5d94-a0d2-ca3a19cde822', 'Disgrace', 'J. M. Coetzee', 'Drama', 'en', 'David Lurie, professor universitário em Cidade do Cabo, perde o cargo depois de um escândalo e se refugia na fazenda da filha. Lá, um ataque violento transforma a relação dos dois. Um romance duro sobre culpa e a África do Sul pós-apartheid.', 'Avançado', array['áfrica do sul', 'moral', 'pós-apartheid', 'família', 'premiado']),
  ('aeddf09e-c0f1-5cfc-a001-8a092155e36d', 'Waiting for the Barbarians', 'J. M. Coetzee', 'Drama', 'en', 'Um magistrado de uma cidade de fronteira vê o poder do Império se voltar contra pessoas inocentes e passa a questionar o próprio papel. A história acontece num tempo e lugar indefinidos. Uma alegoria sobre poder e consciência.', 'Avançado', array['império', 'moral', 'poder', 'alegoria', 'fronteira']),
  ('a3d297ca-e4c9-53a9-a0ed-05a01e8ce743', 'The English Patient', 'Michael Ondaatje', 'Drama', 'en', 'No fim da Segunda Guerra, uma enfermeira cuida de um homem gravemente queimado numa villa italiana abandonada. Aos poucos, a história dele e de um antigo amor vem à tona. Um romance poético sobre memória e perda.', 'Avançado', array['segunda guerra', 'itália', 'memória', 'amor', 'poético']),
  ('5cc0c92a-34b0-5f40-992f-9d86bc0eb7ad', 'Oscar and Lucinda', 'Peter Carey', 'Ficção Clássica', 'en', 'Dois jogadores obcecados, um jovem pastor inglês e uma herdeira australiana, se apaixonam e fazem uma aposta para transportar uma igreja de vidro por terra. A história mistura fé, risco e acaso. Um romance premiado de imaginação rica.', 'Avançado', array['século xix', 'fé', 'jogo', 'austrália', 'história']),
  ('c6d2c6c3-c6ab-5225-8668-1ed097eacabe', 'Cold Mountain', 'Charles Frazier', 'Drama', 'en', 'Ferido na Guerra Civil americana, o soldado Inman decide voltar a pé para casa e para a mulher que ama. Enquanto isso, Ada luta para sobreviver na fazenda. Um romance histórico sobre guerra, amor e travessia.', 'Intermediário', array['guerra civil', 'jornada', 'amor', 'estados unidos', 'história']),
  ('d616bd62-d3e8-5601-acb1-1859164fff35', 'Olive Kitteridge', 'Elizabeth Strout', 'Contos', 'en', 'Treze histórias ligadas em torno de Olive, uma professora aposentada de uma cidade do Maine, difícil e profundamente humana. Cada episódio mostra um aspecto de sua vida e de quem a cerca. Um livro premiado sobre solidão e afeto.', 'Intermediário', array['cidade pequena', 'família', 'envelhecimento', 'contos interligados', 'premiado']),
  ('1521803c-d1d3-552e-b067-f92b9b09af0c', 'My Name Is Lucy Barton', 'Elizabeth Strout', 'Drama', 'en', 'Lucy, internada por semanas, recebe a visita inesperada da mãe, com quem tem uma relação difícil. As conversas despertam lembranças da infância pobre. Uma novela curta e contida sobre laços familiares.', 'Intermediário', array['mãe e filha', 'hospital', 'memória', 'novela', 'família']),
  ('2b420329-0964-5482-b2c5-ba63535522f5', 'Everything I Never Told You', 'Celeste Ng', 'Drama', 'en', 'Em 1977, a família Lee, de origem chinesa em Ohio, acorda e descobre que a filha Lydia, a preferida, foi encontrada morta num lago. A investigação revela expectativas e segredos de cada um. Um romance sobre pressão e silêncio.', 'Intermediário', array['família', 'segredos', 'anos 1970', 'identidade', 'mistério']),
  ('ab6866aa-66d9-587f-9bb5-f1ea2969cd08', 'Pachinko', 'Min Jin Lee', 'Drama', 'en', 'Uma família coreana enfrenta quatro gerações no Japão, desde a década de 1910, lidando com preconceito, trabalho e sobrevivência. A trajetória começa com Sunja e atravessa décadas. Um romance de fôlego sobre pertencimento e resistência.', 'Intermediário', array['coreia', 'japão', 'família', 'imigração', 'gerações']),
  ('4da7ab4f-70d7-5f3b-ac97-38f35f67f30e', 'Circe', 'Madeline Miller', 'Fantasia', 'en', 'Filha do deus Hélio, Circe é exilada numa ilha por usar feitiçaria e lá desenvolve seus poderes. Ela cruza com deuses e heróis como Odisseu. Uma releitura mitológica do ponto de vista dela.', 'Intermediário', array['mitologia grega', 'feminismo', 'magia', 'ilha', 'reinterpretação']),
  ('6d2f532c-e351-5765-bd8a-b597ab878d4b', 'How to Win Friends and Influence People', 'Dale Carnegie', 'Desenvolvimento Pessoal', 'en', 'Publicado em 1936, o livro reúne princípios simples para lidar com as pessoas, como mostrar interesse genuíno, lembrar nomes e saber ouvir. Cada capítulo traz exemplos e conselhos práticos. Um clássico sobre comunicação e convivência.', 'Intermediário', array['relacionamentos', 'comunicação', 'clássico', 'influência', 'habilidades sociais'])
insert into public.livros (id, titulo, autor, genero, idioma, resumo, nivel_dificuldade, tags) values
  ('9b683d10-c544-5752-be94-d97fd41b6061', 'How to Stop Worrying and Start Living', 'Dale Carnegie', 'Desenvolvimento Pessoal', 'en', 'Carnegie reúne técnicas práticas para reduzir a preocupação e viver o presente, como separar o que se pode controlar do que não se pode. O livro usa muitos relatos reais. Um guia clássico para lidar com a ansiedade.', 'Intermediário', array['ansiedade', 'preocupação', 'clássico', 'hábitos', 'calma']),
  ('5d75803c-fc6c-5afa-bce2-9a38950884e0', 'The 7 Habits of Highly Effective People', 'Stephen R. Covey', 'Desenvolvimento Pessoal', 'en', 'Covey apresenta sete hábitos, como ser proativo, começar com o fim em mente e priorizar o que é importante. Ele defende que a eficácia nasce do caráter e dos princípios. Um clássico sobre pessoas e organizações.', 'Intermediário', array['hábitos', 'produtividade', 'liderança', 'clássico', 'princípios']),
  ('3904acbf-88db-5eb6-b6d4-c94d26d86a6e', 'Atomic Habits', 'James Clear', 'Desenvolvimento Pessoal', 'en', 'Clear mostra como pequenas mudanças diárias, repetidas, produzem grandes resultados. Ele explica um sistema para criar bons hábitos e abandonar os ruins. Um guia prático, claro e muito popular.', 'Intermediário', array['hábitos', 'mudança', 'pequenos passos', 'identidade', 'produtividade']),
  ('b542dabe-fd93-5311-a614-3cc8f68f5c7f', 'The Power of Habit', 'Charles Duhigg', 'Desenvolvimento Pessoal', 'en', 'Duhigg explica como funcionam os hábitos, do gatilho à recompensa, e como é possível mudá-los. O livro usa casos de pessoas, empresas e organizações. Uma leitura envolvente sobre ciência do comportamento.', 'Intermediário', array['hábitos', 'psicologia', 'comportamento', 'mudança', 'negócios']),
  ('e95ea0f9-41c4-55eb-a71a-90a02ba10838', 'Mindset', 'Carol S. Dweck', 'Psicologia', 'en', 'A psicóloga Carol Dweck diferencia a mentalidade fixa, que vê talento como algo imutável, da mentalidade de crescimento, que valoriza esforço e aprendizado. Ela mostra como isso afeta escola, trabalho e relacionamentos. Uma ideia simples com grande impacto.', 'Intermediário', array['aprendizado', 'motivação', 'crescimento', 'psicologia', 'educação']),
  ('2e290912-0a56-5e5f-83cf-efaf03edacab', 'Grit', 'Angela Duckworth', 'Psicologia', 'en', 'Duckworth defende que o sucesso depende mais de paixão e perseverança do que de talento. Ela apresenta pesquisas e histórias de pessoas que não desistem. Um livro sobre persistência a longo prazo.', 'Intermediário', array['perseverança', 'paixão', 'sucesso', 'psicologia', 'esforço']),
  ('6a4c3741-78f1-54b4-9096-237777c6dbd6', 'The Subtle Art of Not Giving a F*ck', 'Mark Manson', 'Desenvolvimento Pessoal', 'en', 'Manson sugere que a felicidade vem de escolher bem o que importa e aceitar que problemas e sofrimento fazem parte da vida. O tom é direto, irreverente e cheio de palavrões. Uma autoajuda às avessas.', 'Intermediário', array['prioridades', 'humor', 'valores', 'autoajuda', 'realidade']),
  ('98859c89-437f-50f2-bd7a-7f7bddfc717e', 'The Power of Now', 'Eckhart Tolle', 'Espiritualidade', 'en', 'Tolle defende que o sofrimento nasce de viver preso ao passado e ao futuro e propõe observar os pensamentos e voltar ao momento presente. O texto é feito de perguntas e respostas. Um livro sobre atenção plena e paz interior.', 'Intermediário', array['presente', 'mindfulness', 'mente', 'meditação', 'paz']),
  ('f161ca9b-b125-54c9-93f6-a98921bdf213', 'A New Earth', 'Eckhart Tolle', 'Espiritualidade', 'en', 'Tolle analisa como o ego distorce nossas relações e propõe despertar uma nova forma de consciência. O livro mistura reflexão espiritual e exemplos do cotidiano. Uma continuação aprofundada de O Poder do Agora.', 'Intermediário', array['ego', 'consciência', 'espiritualidade', 'presente', 'transformação']),
  ('8dd45fa4-b974-5271-9a96-17977795f04a', 'The Secret', 'Rhonda Byrne', 'Desenvolvimento Pessoal', 'en', 'O livro apresenta a "lei da atração", ideia de que pensamentos positivos atraem resultados positivos. O conceito se popularizou muito, mas é criticado por falta de base científica. Uma leitura simples e motivacional.', 'Iniciante', array['lei da atração', 'pensamento positivo', 'visualização', 'motivação', 'popular']),
  ('aa6b1092-3056-5636-bb9d-bd8681705a2e', 'Think and Grow Rich', 'Napoleon Hill', 'Desenvolvimento Pessoal', 'en', 'Lançado em 1937, o livro reúne princípios que o autor diz ter observado em pessoas bem-sucedidas, como desejo, persistência e planejamento. Seu foco é a mentalidade para alcançar metas. Um clássico do gênero, de linguagem antiga.', 'Intermediário', array['riqueza', 'mentalidade', 'clássico', 'metas', 'sucesso']),
  ('783f81d8-89b4-5b5c-97ee-2188ac68df79', 'Awaken the Giant Within', 'Tony Robbins', 'Desenvolvimento Pessoal', 'en', 'Robbins propõe técnicas para assumir o controle das emoções, dos hábitos e das decisões. Ele trata de metas, dinheiro e relacionamentos de forma motivadora. Um livro de autoajuda cheio de exercícios.', 'Intermediário', array['motivação', 'emoções', 'hábitos', 'metas', 'mudança']),
  ('7ede8d0e-66ef-53b8-b1b4-c43b4a13c0af', 'Daring Greatly', 'Brené Brown', 'Psicologia', 'en', 'Brown mostra que a vulnerabilidade não é fraqueza, mas a base da coragem, da criatividade e dos vínculos. Ela explica como a vergonha nos paralisa e como lidar com ela. Um livro baseado em anos de pesquisa.', 'Intermediário', array['vulnerabilidade', 'coragem', 'vergonha', 'relacionamentos', 'liderança']),
  ('d0010dca-30fa-51f4-9388-69b12f431efc', 'The Gifts of Imperfection', 'Brené Brown', 'Psicologia', 'en', 'Brown apresenta dez "práticas" para viver com autenticidade e abandonar a busca pela perfeição. O foco é cultivar compaixão, descanso e gratidão. Um guia curto e acolhedor.', 'Intermediário', array['autoaceitação', 'vergonha', 'vida plena', 'coragem', 'autoestima']),
  ('2c1c1309-6bc2-50c0-9565-ebbdc97eb1c0', 'Rising Strong', 'Brené Brown', 'Psicologia', 'en', 'Brown explica como nos levantamos depois de quedas e fracassos, passando por reconhecer emoções, questionar as histórias que contamos e agir. O livro mistura pesquisa e relatos pessoais. Um manual sobre resiliência.', 'Intermediário', array['resiliência', 'fracasso', 'coragem', 'emoções', 'recomeço']),
  ('8b465741-a03c-5a7b-baa2-1889d79931d6', 'Braving the Wilderness', 'Brené Brown', 'Psicologia', 'en', 'Brown discute o que significa pertencer de verdade, sem abrir mão de quem somos, num tempo de divisões. Ela sugere práticas para encarar a solidão e manter conexões. Um livro sobre pertencimento e autenticidade.', 'Intermediário', array['pertencimento', 'coragem', 'comunidade', 'autenticidade', 'sociedade']),
  ('087d3733-bded-59f5-89ac-2651a8b8bc98', 'Quiet', 'Susan Cain', 'Psicologia', 'en', 'Cain mostra o valor dos introvertidos numa sociedade que premia quem fala mais alto. Ela reúne pesquisas e histórias sobre trabalho, escola e relações. Um livro que ajuda a entender diferentes temperamentos.', 'Intermediário', array['introversão', 'personalidade', 'trabalho', 'sociedade', 'psicologia']),
  ('b0cde661-46bf-5bb1-8431-c68162463492', 'Deep Work', 'Cal Newport', 'Desenvolvimento Pessoal', 'en', 'Newport defende que a capacidade de se concentrar sem distração é rara e valiosa. Ele propõe rotinas e regras para criar tempo de trabalho profundo. Um guia prático de foco.', 'Intermediário', array['foco', 'produtividade', 'distração', 'trabalho', 'concentração']),
  ('d5f11be7-26db-520e-a5a2-fc9830add74a', 'Digital Minimalism', 'Cal Newport', 'Desenvolvimento Pessoal', 'en', 'Newport propõe usar a tecnologia de forma intencional, mantendo apenas ferramentas que realmente trazem valor. Ele sugere um período de desintoxicação digital e novas atividades. Um livro sobre atenção e vida offline.', 'Intermediário', array['tecnologia', 'foco', 'vida digital', 'atenção', 'hábitos']),
  ('b9c18d76-afe4-55f6-8c8c-5babab78d022', 'So Good They Can''t Ignore You', 'Cal Newport', 'Desenvolvimento Pessoal', 'en', 'Newport argumenta que seguir a paixão é um mau conselho e que o prazer no trabalho vem de desenvolver habilidades raras. Ele apresenta a ideia de "capital de carreira". Um livro sobre construir uma carreira com sentido.', 'Intermediário', array['carreira', 'habilidades', 'paixão', 'trabalho', 'estratégia']),
  ('90fe0bb7-2edf-5e74-917f-26b83dcfa21b', 'Make Your Bed', 'William H. McRaven', 'Desenvolvimento Pessoal', 'en', 'O almirante McRaven, ex-comandante das forças especiais americanas, compartilha dez lições aprendidas no treinamento militar, a começar por arrumar a cama todo dia. Cada lição é curta e direta. Um livro simples e inspirador sobre disciplina.', 'Iniciante', array['disciplina', 'liderança', 'resiliência', 'motivação', 'militar']),
  ('2db34934-5200-519a-be2f-a4ee5f821f58', 'The Miracle Morning', 'Hal Elrod', 'Desenvolvimento Pessoal', 'en', 'Elrod propõe uma rotina matinal de seis práticas, como meditação, leitura e exercício, para transformar o dia. Ele conta como encontrou esse método depois de um acidente. Uma leitura leve e motivadora.', 'Iniciante', array['rotina matinal', 'hábitos', 'motivação', 'produtividade', 'bem-estar']),
  ('6197b096-bc87-57d4-8443-56d1ea118751', 'The 5 Second Rule', 'Mel Robbins', 'Desenvolvimento Pessoal', 'en', 'Mel Robbins propõe contar regressivamente de cinco a um e agir antes que a dúvida paralise. A técnica é apresentada com exemplos pessoais. Um livro rápido e prático sobre vencer a hesitação.', 'Iniciante', array['motivação', 'ação', 'hesitação', 'coragem', 'hábitos']),
  ('a8e374ef-978c-552e-9acc-1716c1c390f8', 'The Four Agreements', 'Don Miguel Ruiz', 'Espiritualidade', 'en', 'Ruiz propõe quatro acordos pessoais: ser impecável com as palavras, não levar nada para o lado pessoal, não fazer suposições e dar sempre o melhor. O livro é curto, de linguagem simples. Uma leitura inspirada na sabedoria tolteca.', 'Iniciante', array['sabedoria tolteca', 'liberdade', 'palavras', 'autoconhecimento', 'paz']),
  ('03d195a9-d082-5447-b9d4-5fd3553f7cd0', 'You Are a Badass', 'Jen Sincero', 'Desenvolvimento Pessoal', 'en', 'Com tom bem-humorado e cheio de palavrões, Jen Sincero propõe mudar crenças limitantes e investir em si mesmo. O livro mistura histórias pessoais e exercícios. Uma autoajuda divertida e direta.', 'Intermediário', array['autoconfiança', 'humor', 'mentalidade', 'sucesso', 'motivação']),
  ('f685940e-c0c5-5cda-b4c8-f92ed816ca1b', 'Feel the Fear and Do It Anyway', 'Susan Jeffers', 'Desenvolvimento Pessoal', 'en', 'Jeffers defende que o medo faz parte da vida e que devemos agir mesmo sentindo-o. Ela apresenta técnicas para ganhar confiança e tomar decisões. Um clássico de autoajuda sobre coragem.', 'Intermediário', array['medo', 'coragem', 'ação', 'confiança', 'clássico']),
  ('e77d128d-1dee-594e-bb83-75e7333b5365', 'Who Moved My Cheese?', 'Spencer Johnson', 'Desenvolvimento Pessoal', 'en', 'Uma fábula sobre quatro personagens num labirinto que enfrentam o desaparecimento do queijo de que dependem. Cada um reage de um jeito à mudança. Um livro curto e simples sobre adaptação.', 'Iniciante', array['mudança', 'fábula', 'carreira', 'adaptação', 'clássico']),
  ('33e286d2-c1fc-5923-9fd7-dbce36b141e0', 'The One Thing', 'Gary Keller', 'Desenvolvimento Pessoal', 'en', 'Keller defende que os melhores resultados vêm de concentrar a atenção em uma única tarefa mais importante de cada vez. Ele propõe perguntar sempre qual é "a coisa" que torna o resto mais fácil. Um guia sobre foco e prioridade.', 'Intermediário', array['foco', 'produtividade', 'prioridades', 'metas', 'trabalho']),
  ('d8eb484e-6ca0-5988-8255-6289162c6772', 'Getting Things Done', 'David Allen', 'Desenvolvimento Pessoal', 'en', 'Allen apresenta um método para tirar tarefas da cabeça e organizá-las em listas confiáveis, reduzindo o estresse. O sistema envolve capturar, esclarecer, organizar, revisar e executar. Um clássico da produtividade.', 'Intermediário', array['produtividade', 'organização', 'tarefas', 'método', 'trabalho']),
  ('c914af0b-8705-5fb8-8081-04ea83ab23b7', 'Essentialism', 'Greg McKeown', 'Desenvolvimento Pessoal', 'en', 'McKeown defende que fazer menos, mas melhor, é um jeito mais sábio de viver e trabalhar. Ele propõe aprender a dizer não ao que não é essencial. Um guia sobre escolhas e prioridades.', 'Intermediário', array['prioridades', 'foco', 'simplicidade', 'decisões', 'menos é mais']),
  ('5898b156-520c-567e-aff8-bb82d4377374', 'Eat That Frog!', 'Brian Tracy', 'Desenvolvimento Pessoal', 'en', 'Tracy sugere começar o dia pela tarefa mais difícil, o "sapo", para vencer a procrastinação. O livro reúne vinte e uma técnicas curtas de gestão do tempo. Uma leitura prática e objetiva.', 'Iniciante', array['produtividade', 'procrastinação', 'tempo', 'tarefas', 'hábitos']),
  ('0253e2ca-07e3-5ff7-a9f9-73972aee63d5', 'The Compound Effect', 'Darren Hardy', 'Desenvolvimento Pessoal', 'en', 'Hardy explica que pequenas escolhas repetidas por muito tempo produzem grandes resultados, para o bem ou para o mal. Ele sugere registrar hábitos e manter a constância. Um livro simples sobre disciplina.', 'Iniciante', array['hábitos', 'disciplina', 'pequenas escolhas', 'sucesso', 'constância']),
  ('f463d3bb-f259-53e9-98fd-ce777f44a393', 'Can''t Hurt Me', 'David Goggins', 'Biografia e Memórias', 'en', 'Goggins conta como superou uma infância difícil e se transformou num atleta de resistência e militar de elite. Ele propõe desafiar os próprios limites. Uma autobiografia crua e motivacional.', 'Intermediário', array['superação', 'disciplina', 'mentalidade', 'memórias', 'resiliência']),
  ('ec734779-70f1-56d7-bb70-bc63f40e886a', 'Big Magic', 'Elizabeth Gilbert', 'Desenvolvimento Pessoal', 'en', 'Gilbert propõe viver de forma criativa, sem deixar o medo e a perfeição bloquearem os projetos. Ela mistura experiências pessoais e conselhos para artistas. Um livro leve e encorajador.', 'Intermediário', array['criatividade', 'medo', 'inspiração', 'escrita', 'vida criativa']),
  ('2e992982-c07d-55f5-aeab-9936a5b0b84c', 'The Artist''s Way', 'Julia Cameron', 'Desenvolvimento Pessoal', 'en', 'Cameron apresenta um programa de doze semanas para destravar a criatividade, com práticas como as "páginas matinais". O livro combina espiritualidade e exercícios. Um guia clássico para criadores.', 'Intermediário', array['criatividade', 'bloqueio', 'escrita', 'arte', 'exercícios']),
  ('8bd27aa0-686d-5d81-801c-140112c66035', 'The Road Less Traveled', 'M. Scott Peck', 'Psicologia', 'en', 'O psiquiatra Peck começa com a frase "a vida é difícil" e defende que crescer exige disciplina, amor e responsabilidade. Ele usa casos de pacientes para ilustrar suas ideias. Um clássico de psicologia popular.', 'Intermediário', array['disciplina', 'amor', 'crescimento espiritual', 'psicologia', 'clássico']),
  ('c3e97915-4291-5ade-bf65-57a52c24927b', 'Emotional Intelligence', 'Daniel Goleman', 'Psicologia', 'en', 'Goleman defende que a capacidade de reconhecer e lidar com emoções pesa tanto quanto o QI para o sucesso e a felicidade. Ele explica como isso se desenvolve na infância e no trabalho. Um livro que popularizou o conceito.', 'Intermediário', array['emoções', 'inteligência emocional', 'relacionamentos', 'psicologia', 'trabalho']),
  ('45cc3c5d-436b-5c0c-a9d7-938fe1d0c31b', 'The Happiness Project', 'Gretchen Rubin', 'Desenvolvimento Pessoal', 'en', 'Gretchen Rubin dedica um ano a testar ideias para ser mais feliz, com metas diferentes para cada mês. Ela conta o que funcionou e o que não funcionou. Um relato leve e prático.', 'Intermediário', array['felicidade', 'hábitos', 'experimento', 'rotina', 'bem-estar']),
  ('ba527f88-1cf9-5484-a33a-747db47df0ae', 'Better Than Before', 'Gretchen Rubin', 'Desenvolvimento Pessoal', 'en', 'Rubin propõe que o melhor método para criar hábitos depende do temperamento de cada pessoa e apresenta quatro tendências. O livro traz estratégias para diferentes perfis. Um guia sobre mudar sem se forçar.', 'Intermediário', array['hábitos', 'personalidade', 'rotina', 'mudança', 'autoconhecimento']),
  ('4ae3c267-8e07-55ba-a2e9-cf25a393e805', 'The Happiness Advantage', 'Shawn Achor', 'Psicologia', 'en', 'Achor defende que a felicidade vem antes do sucesso e melhora o desempenho. Ele apresenta práticas simples, apoiadas em pesquisas de psicologia positiva. Um livro curto sobre mentalidade positiva.', 'Intermediário', array['felicidade', 'psicologia positiva', 'trabalho', 'sucesso', 'mentalidade']),
  ('a84be989-e4c2-5c26-8901-421476f1090c', 'Flow', 'Mihaly Csikszentmihalyi', 'Psicologia', 'en', 'O psicólogo Csikszentmihalyi descreve o "fluxo", estado de total envolvimento numa atividade desafiadora, e o liga à felicidade. Ele explica como criar essas experiências no trabalho e no lazer. Um clássico da psicologia positiva.', 'Avançado', array['fluxo', 'felicidade', 'concentração', 'psicologia', 'experiência ótima']),
  ('444abd74-7146-57a8-99eb-6d85e214bf8d', 'Drive', 'Daniel H. Pink', 'Negócios e Finanças', 'en', 'Pink argumenta que, para tarefas criativas, a motivação vem de autonomia, domínio e propósito, mais do que de recompensas externas. Ele traz estudos e exemplos de empresas. Um livro sobre o que move as pessoas.', 'Intermediário', array['motivação', 'trabalho', 'autonomia', 'propósito', 'liderança']),
  ('5e80c259-5489-5275-96fd-13231ec4b0bd', 'The Gap and the Gain', 'Dan Sullivan and Benjamin Hardy', 'Desenvolvimento Pessoal', 'en', 'Os autores propõem medir o progresso comparando-se com o ponto de partida, e não com um ideal inatingível. Eles chamam isso de pensar no "ganho" em vez da "distância". Um livro curto sobre perspectiva e satisfação.', 'Intermediário', array['mentalidade', 'progresso', 'gratidão', 'metas', 'felicidade']),
  ('788e7a5d-11c9-5ec2-bea5-b9c15df4deae', 'Ego Is the Enemy', 'Ryan Holiday', 'Filosofia', 'en', 'Holiday mostra como o ego atrapalha nas fases de aspiração, sucesso e fracasso, usando exemplos históricos. Ele propõe humildade, trabalho constante e foco. Um livro de inspiração estoica.', 'Intermediário', array['ego', 'estoicismo', 'humildade', 'disciplina', 'sucesso']),
  ('1c8ba51f-04f8-5183-84d5-379bb8904c31', 'The Obstacle Is the Way', 'Ryan Holiday', 'Filosofia', 'en', 'Inspirado no estoicismo, Holiday defende que obstáculos podem se tornar oportunidades, se mudarmos a percepção e a ação. Ele usa exemplos de pessoas famosas. Um guia filosófico e prático.', 'Intermediário', array['estoicismo', 'resiliência', 'obstáculos', 'perseverança', 'filosofia']),
  ('d62ffc21-c8eb-562a-9ebe-51d439a8fda9', 'Stillness Is the Key', 'Ryan Holiday', 'Filosofia', 'en', 'Holiday explora a importância da quietude da mente, do corpo e da alma para decidir melhor e viver bem. Ele recorre a filósofos e a histórias da vida real. Um livro sobre calma num mundo agitado.', 'Intermediário', array['estoicismo', 'calma', 'foco', 'filosofia', 'atenção']),
  ('f5c17174-13eb-5400-a6cd-2b8f929cf5b4', 'The 48 Laws of Power', 'Robert Greene', 'Desenvolvimento Pessoal', 'en', 'Greene reúne 48 "leis" sobre conquistar e manter poder, ilustradas com episódios da história. O livro é polêmico por seu tom pragmático e muitas vezes cínico. Uma leitura influente, mas que pede senso crítico.', 'Avançado', array['poder', 'estratégia', 'história', 'manipulação', 'polêmico']),
  ('2bbd2980-aedb-5347-997f-3edc0d4cad87', 'Mastery', 'Robert Greene', 'Desenvolvimento Pessoal', 'en', 'Greene analisa a trajetória de grandes mestres e propõe um caminho de aprendizado que passa por aprendizado prático, observação e perseverança. Mistura biografias e conselhos. Um livro sobre dominar um ofício.', 'Avançado', array['maestria', 'aprendizado', 'carreira', 'história', 'disciplina']),
  ('806a9b2f-d223-55e4-9f5f-cab709c01100', 'Stumbling on Happiness', 'Daniel Gilbert', 'Psicologia', 'en', 'O psicólogo Daniel Gilbert mostra por que somos tão ruins em prever o que nos fará felizes e como a imaginação nos engana. O livro mistura humor e pesquisas científicas. Uma leitura divertida sobre expectativas e bem-estar.', 'Avançado', array['felicidade', 'psicologia', 'decisões', 'futuro', 'imaginação']),
  ('1836af0d-71e5-5f70-a73b-4923da4f466b', 'The Lean Startup', 'Eric Ries', 'Negócios e Finanças', 'en', 'Ries propõe criar empresas por meio de ciclos curtos de construir, medir e aprender, testando ideias com versões simples do produto. A proposta é reduzir desperdício e errar rápido. Um guia de referência para startups.', 'Intermediário', array['startups', 'inovação', 'empreendedorismo', 'experimentos', 'produto']),
  ('98240201-f765-569a-b8b2-3a3ce03b5f70', 'Zero to One', 'Peter Thiel', 'Negócios e Finanças', 'en', 'Thiel defende que o verdadeiro progresso vem de criar algo novo, e não de copiar o que já existe. Ele discute monopólios, tecnologia e como pensar o futuro de uma empresa. Um livro provocativo para empreendedores.', 'Intermediário', array['startups', 'inovação', 'monopólio', 'futuro', 'empreendedorismo']),
  ('5f80aa0b-1205-54c6-bfd9-bd55ce9ed5aa', 'Good to Great', 'Jim Collins', 'Negócios e Finanças', 'en', 'Collins estuda empresas que deram um salto duradouro de desempenho e identifica o que elas têm em comum, como liderança humilde e disciplina. O livro apresenta conceitos como o do "ouriço". Um clássico de gestão baseado em pesquisa.', 'Intermediário', array['liderança', 'empresas', 'gestão', 'pesquisa', 'estratégia']),
  ('9fb5d8ac-7cc1-5f82-b0f2-24d0b213243f', 'Built to Last', 'Jim Collins and Jerry I. Porras', 'Negócios e Finanças', 'en', 'Os autores comparam empresas visionárias duradouras com concorrentes comuns e extraem princípios sobre valores e cultura. A ideia central é construir uma organização, e não apenas um produto. Um clássico sobre empresas que resistem ao tempo.', 'Intermediário', array['empresas', 'visão', 'cultura', 'liderança', 'gestão']),
  ('1b9fde38-3cf9-5596-809e-b9f2b53803cf', 'The Hard Thing About Hard Things', 'Ben Horowitz', 'Negócios e Finanças', 'en', 'Horowitz conta, de forma franca, as decisões difíceis de dirigir uma empresa em crise, como demitir, vender e manter a equipe motivada. Ele usa episódios da própria carreira. Um livro realista sobre liderança em tempos difíceis.', 'Intermediário', array['liderança', 'startups', 'decisões', 'crises', 'empreendedorismo']),
  ('942ce637-5b7f-58d1-a0cf-a7c1ea0abb27', 'Start with Why', 'Simon Sinek', 'Negócios e Finanças', 'en', 'Sinek propõe que as melhores organizações começam pelo "porquê", seu propósito, e só depois falam do "como" e do "o quê". Ele apresenta o "círculo dourado". Um livro sobre inspirar pessoas por meio de propósito.', 'Intermediário', array['propósito', 'liderança', 'motivação', 'marketing', 'empresas']),
  ('de594406-5f3e-5ab9-a2ca-b19e5fcb6a21', 'Leaders Eat Last', 'Simon Sinek', 'Negócios e Finanças', 'en', 'Sinek defende que bons líderes criam ambientes seguros e cuidam primeiro das pessoas. Ele une exemplos militares e empresariais a explicações biológicas. Um livro sobre confiança e cooperação.', 'Intermediário', array['liderança', 'confiança', 'equipes', 'cultura', 'biologia']),
  ('ed5c7aeb-5f29-54ee-bb7c-02fc6591281d', 'The Infinite Game', 'Simon Sinek', 'Negócios e Finanças', 'en', 'Sinek diferencia jogos finitos, com vencedores definidos, de jogos infinitos, em que o objetivo é continuar jogando. Ele argumenta que líderes devem pensar no longo prazo. Um livro sobre estratégia e propósito.', 'Intermediário', array['liderança', 'estratégia', 'longo prazo', 'propósito', 'empresas']),
  ('c6e37398-fc0b-56fa-a6da-5e01846d16ee', 'The Psychology of Money', 'Morgan Housel', 'Negócios e Finanças', 'en', 'Housel defende que lidar bem com dinheiro depende mais de comportamento do que de conhecimento técnico. Em capítulos curtos, ele conta histórias sobre ganância, medo e paciência. Um livro acessível sobre finanças pessoais.', 'Intermediário', array['dinheiro', 'comportamento', 'investimentos', 'finanças pessoais', 'psicologia']),
  ('523c396d-4cad-5c43-a57f-3283e9ad21d6', 'Rich Dad Poor Dad', 'Robert T. Kiyosaki', 'Negócios e Finanças', 'en', 'Kiyosaki compara a visão de dois "pais" sobre dinheiro, um empregado e outro empresário, para ensinar a diferença entre ativos e passivos. A linguagem é simples e direta. Um best-seller polêmico de educação financeira.', 'Iniciante', array['finanças pessoais', 'investimentos', 'mentalidade', 'educação financeira', 'empreendedorismo']),
  ('8329b4f7-d88c-5eee-afc7-b46755f15b11', 'The Intelligent Investor', 'Benjamin Graham', 'Negócios e Finanças', 'en', 'Publicado em 1949, o livro defende o investimento em valor, a margem de segurança e o controle emocional diante das oscilações do mercado. Graham apresenta a figura de Mr Market, um sócio instável. Um clássico exigente e influente.', 'Avançado', array['investimentos', 'bolsa', 'valor', 'clássico', 'finanças']),
  ('45204265-0df7-5285-adfc-9c903ebcf69b', 'A Random Walk Down Wall Street', 'Burton G. Malkiel', 'Negócios e Finanças', 'en', 'Malkiel argumenta que é muito difícil superar o mercado e defende investimentos diversificados e de baixo custo, como fundos de índice. O livro explica teorias e bolhas históricas. Um guia clássico de investimentos.', 'Intermediário', array['investimentos', 'bolsa', 'fundos de índice', 'mercado', 'finanças']),
  ('fa2f4df4-139e-59d6-9fb4-9f6f8cdb9af1', 'The Millionaire Next Door', 'Thomas J. Stanley and William D. Danko', 'Negócios e Finanças', 'en', 'Com base em pesquisas, os autores mostram que muitos milionários americanos vivem de forma discreta, economizam e investem com disciplina. O livro desmonta a ideia de que riqueza depende de aparência. Um clássico de finanças pessoais.', 'Intermediário', array['riqueza', 'finanças pessoais', 'hábitos', 'economia', 'pesquisa']),
  ('2db17565-7e6d-5e0e-ba26-bf6225a8b9b2', 'The Total Money Makeover', 'Dave Ramsey', 'Negócios e Finanças', 'en', 'Ramsey apresenta um plano em passos para sair das dívidas, formar reserva de emergência e construir patrimônio. Ele defende quitar primeiro as menores dívidas. Um método simples e direto de organização financeira.', 'Iniciante', array['dívidas', 'finanças pessoais', 'orçamento', 'economia', 'hábitos']),
  ('39c02fca-36b7-525c-a58e-2426a3363632', 'I Will Teach You to Be Rich', 'Ramit Sethi', 'Negócios e Finanças', 'en', 'Sethi propõe um programa de seis semanas para organizar contas, investir e automatizar a vida financeira. O tom é direto, com foco no que traz mais resultado. Um guia prático para quem está começando.', 'Intermediário', array['finanças pessoais', 'investimentos', 'automação', 'orçamento', 'hábitos']),
  ('1408ce99-d640-5008-b205-25ed7c72ad96', 'Principles', 'Ray Dalio', 'Negócios e Finanças', 'en', 'Dalio compartilha os princípios que usou para decidir na vida e no trabalho e descreve uma cultura de transparência radical e meritocracia de ideias. O livro tem tom de manual. Uma leitura longa, útil para líderes.', 'Intermediário', array['princípios', 'decisões', 'gestão', 'cultura', 'vida']),
  ('525db0ee-06ec-554e-a5a1-f42d6007f187', 'The 4-Hour Workweek', 'Timothy Ferriss', 'Negócios e Finanças', 'en', 'Ferriss defende que é possível trabalhar menos e viver melhor, com automação, delegação e foco no essencial. O livro propõe criar uma vida de "nova riqueza", feita de tempo e mobilidade. Uma leitura provocativa sobre estilo de vida.', 'Intermediário', array['produtividade', 'estilo de vida', 'automação', 'empreendedorismo', 'liberdade']),
  ('61be760a-b6d7-526f-9936-acd5f295a372', 'Tools of Titans', 'Timothy Ferriss', 'Desenvolvimento Pessoal', 'en', 'Ferriss reúne táticas, rotinas e conselhos de pessoas de alto desempenho entrevistadas em seu podcast. O livro é organizado em saúde, riqueza e sabedoria. Um compêndio para consultar e pegar ideias.', 'Intermediário', array['rotinas', 'entrevistas', 'desempenho', 'hábitos', 'produtividade']),
  ('881f609d-ff27-5fd9-9e70-8902c02643e8', 'The Innovator''s Dilemma', 'Clayton M. Christensen', 'Negócios e Finanças', 'en', 'Christensen explica por que empresas bem geridas podem fracassar ao ignorar tecnologias menores que depois as superam. Ele apresenta o conceito de inovação disruptiva. Um clássico de estratégia empresarial.', 'Avançado', array['inovação', 'tecnologia', 'disrupção', 'empresas', 'estratégia']),
  ('e6b47b69-389f-5286-a366-398d4ea8f0af', 'Crossing the Chasm', 'Geoffrey A. Moore', 'Negócios e Finanças', 'en', 'Moore mostra a dificuldade de levar um produto de tecnologia dos primeiros entusiastas para o mercado de massa e sugere estratégias para atravessar esse "abismo". O foco está em escolher um nicho. Um clássico de marketing de tecnologia.', 'Intermediário', array['marketing', 'tecnologia', 'startups', 'clientes', 'estratégia']),
  ('c4255df8-79dd-599f-b26d-3b3c732b4195', 'The E-Myth Revisited', 'Michael E. Gerber', 'Negócios e Finanças', 'en', 'Gerber explica por que tantas pequenas empresas fracassam e propõe que o dono trabalhe "no negócio" como gestor, e não apenas "dentro" dele como técnico. Ele defende criar processos replicáveis. Um livro para quem quer empreender.', 'Intermediário', array['pequenos negócios', 'empreendedorismo', 'gestão', 'processos', 'sistemas']),
  ('f9b70c2a-9464-5b6f-a280-e26f2e84f84f', 'Purple Cow', 'Seth Godin', 'Negócios e Finanças', 'en', 'Godin defende que, num mundo cheio de opções, só produtos notáveis chamam atenção, como uma vaca roxa no meio de um pasto. Ele sugere pensar em novidade desde a criação do produto. Um livro curto sobre se destacar.', 'Intermediário', array['marketing', 'diferenciação', 'inovação', 'produto', 'empreendedorismo']),
  ('5c6ca5f5-7801-570e-b136-01291f3bbaff', 'This Is Marketing', 'Seth Godin', 'Negócios e Finanças', 'en', 'Godin apresenta o marketing como serviço e empatia e sugere escolher com cuidado quem se deseja atingir, o "menor público viável". O livro valoriza integridade. Um guia reflexivo para quem comunica produtos e ideias.', 'Intermediário', array['marketing', 'público', 'empatia', 'histórias', 'empreendedorismo']),
  ('e9147b51-8599-522f-adfe-731d87396cc2', 'Contagious', 'Jonah Berger', 'Negócios e Finanças', 'en', 'Berger analisa por que algumas ideias, produtos e histórias se espalham e propõe seis fatores, resumidos na sigla STEPPS. Ele usa exemplos de campanhas e conteúdos populares. Um livro sobre boca a boca e influência.', 'Intermediário', array['marketing', 'viralização', 'comportamento', 'comunicação', 'ideias']),
  ('6ae69e93-2fbe-5c9b-9c42-5805d2b68939', 'Made to Stick', 'Chip Heath and Dan Heath', 'Negócios e Finanças', 'en', 'Os irmãos Heath explicam por que certas ideias ficam na memória e outras são esquecidas, e propõem seis princípios: simples, inesperadas, concretas, críveis, emocionais e contadas como histórias. O livro tem muitos exemplos. Um guia para comunicar melhor.', 'Intermediário', array['comunicação', 'ideias', 'memória', 'persuasão', 'narrativa']),
  ('2dea3839-c137-5476-a866-5afce1cc6fad', 'Switch', 'Chip Heath and Dan Heath', 'Negócios e Finanças', 'en', 'Os autores usam a imagem de um condutor, um elefante e um caminho para explicar como promover mudanças, dentro e fora das empresas. A ideia é falar à razão, à emoção e ao ambiente. Um livro prático sobre transformar comportamentos.', 'Intermediário', array['mudança', 'comportamento', 'liderança', 'hábitos', 'organizações']),
  ('834b07bb-fbd9-5207-9c7a-d9121156503e', 'Influence', 'Robert B. Cialdini', 'Psicologia', 'en', 'Cialdini apresenta seis princípios da persuasão, como reciprocidade, prova social e escassez, e mostra como eles guiam decisões. O livro usa experimentos e casos reais. Um clássico sobre como somos influenciados.', 'Intermediário', array['persuasão', 'psicologia', 'comportamento', 'marketing', 'negociação']),
  ('5464d41d-1985-54e8-9f51-3ffe56918dc5', 'Pre-Suasion', 'Robert B. Cialdini', 'Psicologia', 'en', 'Cialdini defende que o que acontece antes da mensagem, como o foco da atenção, pesa muito na resposta de quem a recebe. Ele traz estudos e exemplos de situações cotidianas. Um complemento ao seu clássico sobre persuasão.', 'Intermediário', array['persuasão', 'atenção', 'comunicação', 'psicologia', 'marketing']),
  ('8207f8e3-ae6f-569f-b9e7-e50c81f6ee4f', 'Never Split the Difference', 'Chris Voss', 'Negócios e Finanças', 'en', 'O ex-negociador do FBI Chris Voss apresenta técnicas de negociação baseadas em escuta e empatia, como perguntas abertas e espelhamento. Ele conta casos de sequestro e do dia a dia. Um manual prático e envolvente.', 'Intermediário', array['negociação', 'comunicação', 'empatia', 'fbi', 'persuasão']),
  ('925fccab-d38c-5a1d-83d2-366233b345e5', 'Getting to Yes', 'Roger Fisher and William Ury', 'Negócios e Finanças', 'en', 'Os autores, ligados a Harvard, defendem a "negociação baseada em princípios": separar pessoas dos problemas, focar interesses e buscar opções vantajosas para ambos. Um clássico sobre resolução de conflitos.', 'Intermediário', array['negociação', 'acordos', 'conflito', 'comunicação', 'clássico']),
  ('599db096-3762-56bc-a6a6-8a7236b86e10', 'Crucial Conversations', 'Kerry Patterson, Joseph Grenny, Ron McMillan and Al Switzler', 'Desenvolvimento Pessoal', 'en', 'O livro ensina a conduzir conversas difíceis, em que há muito em jogo e as emoções ficam à flor da pele. Os autores propõem ferramentas para manter o diálogo aberto. Um guia útil para o trabalho e para a vida pessoal.', 'Intermediário', array['comunicação', 'conflito', 'relacionamentos', 'trabalho', 'diálogo']),
  ('5fe8f581-9f47-5f19-ade8-8b43afa0905a', 'The Five Dysfunctions of a Team', 'Patrick Lencioni', 'Negócios e Finanças', 'en', 'Lencioni conta uma fábula sobre uma executiva que assume uma equipe disfuncional e depois explica cinco problemas, da falta de confiança à falta de foco em resultados. A estrutura em história facilita a leitura. Um livro curto sobre trabalho em equipe.', 'Iniciante', array['equipes', 'liderança', 'confiança', 'fábula', 'trabalho em grupo']),
  ('cb19cf02-0d0c-53fa-8a5c-656431abe291', 'Radical Candor', 'Kim Scott', 'Negócios e Finanças', 'en', 'Kim Scott propõe unir o cuidado pessoal com a franqueza direta para dar feedback eficaz. Ela mostra erros comuns de gestores e como evitá-los. Um guia prático para líderes.', 'Intermediário', array['liderança', 'feedback', 'comunicação', 'gestão', 'equipes']),
  ('5d0ff616-855f-553d-80d6-1ad177961036', 'Dare to Lead', 'Brené Brown', 'Negócios e Finanças', 'en', 'Brown aplica suas pesquisas sobre vulnerabilidade e coragem ao ambiente de trabalho. Ela propõe habilidades para liderar com empatia e conversas difíceis. Um livro sobre liderança humana.', 'Intermediário', array['liderança', 'coragem', 'vulnerabilidade', 'equipes', 'cultura']),
  ('0571c557-f541-5c65-9ca8-3bda7bdf3755', 'Outliers', 'Malcolm Gladwell', 'Psicologia', 'en', 'Gladwell investiga por que algumas pessoas alcançam sucesso extraordinário e argumenta que contexto, oportunidades e prática pesam tanto quanto talento. Ele apresenta a famosa ideia das 10 mil horas. Um livro curioso e muito debatido.', 'Intermediário', array['sucesso', 'talento', 'sociedade', 'oportunidade', 'pesquisa']),
  ('4491813b-7e06-5f88-b2d7-a0d154d25607', 'The Tipping Point', 'Malcolm Gladwell', 'Psicologia', 'en', 'Gladwell explica como pequenas mudanças podem desencadear grandes transformações sociais e tendências, como numa epidemia. Ele fala de pessoas-chave e do poder do contexto. Um livro sobre como as ideias se espalham.', 'Intermediário', array['sociedade', 'tendências', 'comportamento', 'epidemias', 'ideias']),
  ('07f3eb55-5fb7-5ca8-9068-4cb48bebe1fa', 'Blink', 'Malcolm Gladwell', 'Psicologia', 'en', 'Gladwell examina o poder e os limites dos julgamentos rápidos, mostrando quando a intuição funciona e quando engana. O livro traz estudos e casos curiosos. Uma leitura sobre decisões instantâneas.', 'Intermediário', array['intuição', 'decisões', 'psicologia', 'primeira impressão', 'pesquisa']),
  ('6be89eca-be84-53ff-bbe7-6158ffc5ad14', 'David and Goliath', 'Malcolm Gladwell', 'Psicologia', 'en', 'Gladwell reinterpreta a história bíblica e mostra que desvantagens e dificuldades podem se transformar em forças. Ele reúne histórias de pessoas e grupos que venceram contra as expectativas. Uma reflexão sobre adversidade.', 'Intermediário', array['desvantagens', 'superação', 'sociedade', 'histórias', 'pesquisa']),
  ('e33df008-bb62-5b6e-9d80-ba72b81f4f96', 'Talking to Strangers', 'Malcolm Gladwell', 'Psicologia', 'en', 'Gladwell discute por que é tão difícil entender pessoas que não conhecemos e como confiança e aparências nos enganam. Ele usa casos reais, de espionagem a julgamentos. Um livro sobre os limites da leitura de pessoas.', 'Intermediário', array['comunicação', 'confiança', 'sociedade', 'mal-entendidos', 'pesquisa']),
  ('00bc5809-44a2-59bf-bead-354969c4e7ea', 'Freakonomics', 'Steven D. Levitt and Stephen J. Dubner', 'Negócios e Finanças', 'en', 'Levitt e Dubner usam ferramentas da economia para investigar questões inusitadas, de trapaça em escolas a nomes de bebês. O foco está em como os incentivos movem as pessoas. Um livro curioso e muito popular.', 'Intermediário', array['economia', 'comportamento', 'incentivos', 'dados', 'curiosidades']),
  ('98fe4751-a4f7-50c2-aac2-f9964b9f5319', 'SuperFreakonomics', 'Steven D. Levitt and Stephen J. Dubner', 'Negócios e Finanças', 'en', 'Os autores voltam a aplicar o olhar econômico a temas surpreendentes, como altruísmo, saúde e soluções para problemas globais. Eles apresentam dados e histórias inesperadas. Uma continuação bem-humorada.', 'Intermediário', array['economia', 'comportamento', 'incentivos', 'dados', 'curiosidades']),
  ('d2b2ba06-8077-5ea8-ad73-85bfe5bdd4d5', 'Nudge', 'Richard H. Thaler and Cass R. Sunstein', 'Negócios e Finanças', 'en', 'Thaler e Sunstein mostram como pequenos estímulos, os "nudges", podem influenciar boas decisões sem restringir a liberdade de escolha. Eles discutem saúde, finanças e políticas públicas. Um livro central da economia comportamental.', 'Intermediário', array['economia comportamental', 'decisões', 'políticas públicas', 'escolhas', 'psicologia']),
  ('6cf05602-9a61-5cfd-a65b-1478028dd0fc', 'Misbehaving', 'Richard H. Thaler', 'Negócios e Finanças', 'en', 'Thaler conta, com humor, como nasceu a economia comportamental ao questionar a ideia de que as pessoas sempre agem de modo racional. Ele relata debates e experimentos. Uma história pessoal da área.', 'Intermediário', array['economia comportamental', 'psicologia', 'memórias', 'humor', 'decisões']),
  ('5e368bd1-c5d0-574b-a092-6941d520bc8d', 'The Black Swan', 'Nassim Nicholas Taleb', 'Negócios e Finanças', 'en', 'Taleb argumenta que eventos raros e imprevisíveis, os "cisnes negros", têm impacto enorme e que nossos modelos os subestimam. O tom é provocador e cheio de digressões. Um livro influente sobre risco e incerteza.', 'Avançado', array['incerteza', 'probabilidade', 'risco', 'filosofia', 'economia']),
  ('bb58db33-c65b-553a-985b-2ad432138aa2', 'Antifragile', 'Nassim Nicholas Taleb', 'Negócios e Finanças', 'en', 'Taleb apresenta o conceito de antifragilidade, a capacidade de melhorar com choques e estresse, e o aplica a negócios, saúde e política. O texto é opinativo e rico em exemplos. Uma continuação das ideias de O Cisne Negro.', 'Avançado', array['incerteza', 'risco', 'resiliência', 'filosofia', 'economia']),
  ('01bcf7b2-b254-5ca0-949b-5bbf2e2a8a93', 'Fooled by Randomness', 'Nassim Nicholas Taleb', 'Negócios e Finanças', 'en', 'Taleb mostra como confundimos sorte com talento e como subestimamos o papel do acaso, sobretudo nos mercados. O livro mistura histórias e reflexão filosófica. Uma crítica ao excesso de confiança.', 'Avançado', array['aleatoriedade', 'probabilidade', 'mercados', 'psicologia', 'filosofia']),
  ('84fb2eb4-1999-50f9-8d40-c79202fcbb2b', 'Shoe Dog', 'Phil Knight', 'Biografia e Memórias', 'en', 'O fundador da Nike conta, de forma pessoal, como transformou uma pequena importadora de tênis numa marca global. Ele relata riscos, dívidas e amizades. Uma memória honesta sobre construir um negócio.', 'Intermediário', array['memórias', 'empreendedorismo', 'nike', 'negócios', 'história']),
  ('80f84a52-fe79-58ad-bc93-42081419d555', 'Elon Musk', 'Ashlee Vance', 'Biografia e Memórias', 'en', 'Vance narra a trajetória do empreendedor Elon Musk, da infância na África do Sul à criação de empresas como SpaceX e Tesla. A biografia baseia-se em entrevistas e acompanha sua ambição e seu estilo exigente. Um retrato da inovação moderna.', 'Intermediário', array['biografia', 'tecnologia', 'empreendedorismo', 'inovação', 'espaço']),
  ('bb7d3f4c-19c4-55d6-a522-2b003ae680a6', 'Bad Blood', 'John Carreyrou', 'Biografia e Memórias', 'en', 'O jornalista Carreyrou conta como a startup Theranos prometeu revolucionar exames de sangue, enganou investidores e foi desmascarada. A narrativa é de reportagem investigativa. Um relato de fraude no Vale do Silício.', 'Intermediário', array['jornalismo', 'fraude', 'tecnologia', 'saúde', 'investigação']),
  ('2819be0b-9633-524e-8897-777e59273d3d', 'The Everything Store', 'Brad Stone', 'Biografia e Memórias', 'en', 'Stone conta a história da Amazon e de seu fundador, Jeff Bezos, da livraria on-line à gigante do comércio e da tecnologia. O livro mostra decisões ousadas e cultura de trabalho intensa. Um retrato de ambição e inovação.', 'Intermediário', array['amazon', 'empreendedorismo', 'biografia', 'tecnologia', 'negócios']),
  ('2723c27d-de29-5486-8545-e0e34e153121', 'Cosmos', 'Carl Sagan', 'Ciência', 'en', 'Sagan conduz o leitor por uma viagem do início do universo à vida na Terra, contando a história da ciência com entusiasmo e poesia. O livro nasceu junto de uma célebre série de televisão. Uma obra clássica de divulgação científica.', 'Intermediário', array['astronomia', 'universo', 'história da ciência', 'divulgação científica', 'clássico'])
insert into public.livros (id, titulo, autor, genero, idioma, resumo, nivel_dificuldade, tags) values
  ('f975b9ed-f884-582e-a207-01783541e2b8', 'Pale Blue Dot', 'Carl Sagan', 'Ciência', 'en', 'Inspirado na foto da Terra como um pequeno ponto azul, tirada pela sonda Voyager, Sagan reflete sobre o lugar da humanidade no cosmos e sobre o futuro da exploração espacial. O texto mistura ciência e humildade. Um livro inspirador e reflexivo.', 'Intermediário', array['astronomia', 'espaço', 'humanidade', 'futuro', 'divulgação científica']),
  ('b298ae41-ec45-5cea-a131-7f0c9767df6f', 'The Demon-Haunted World', 'Carl Sagan', 'Ciência', 'en', 'Sagan defende a ciência como uma "vela no escuro" contra superstições e engodos e explica como pensar com ceticismo. Ele fala de ufos, charlatães e educação científica. Um manual de pensamento crítico.', 'Intermediário', array['pensamento crítico', 'ceticismo', 'pseudociência', 'ciência', 'educação']),
  ('c58b24c8-fe57-52d1-9648-3c8aab1e6b7a', 'A Brief History of Time', 'Stephen Hawking', 'Ciência', 'en', 'Hawking apresenta, sem fórmulas, ideias sobre a origem do universo, o Big Bang, os buracos negros e a natureza do tempo. O livro virou um fenômeno de vendas. Uma porta de entrada para a cosmologia moderna.', 'Intermediário', array['física', 'cosmologia', 'buracos negros', 'tempo', 'divulgação científica']),
  ('25d9f0d9-1afb-5e3d-9b75-c25276b3d692', 'The Universe in a Nutshell', 'Stephen Hawking', 'Ciência', 'en', 'Em formato ilustrado, Hawking atualiza e amplia ideias de sua obra anterior, de teorias das cordas à relatividade. As imagens ajudam a visualizar conceitos difíceis. Uma continuação visual e acessível.', 'Intermediário', array['física', 'cosmologia', 'teoria', 'ilustrado', 'divulgação científica']),
  ('95641b36-131e-5ccb-83a1-99d8683ef2d3', 'Brief Answers to the Big Questions', 'Stephen Hawking', 'Ciência', 'en', 'Publicado após a morte do autor, o livro reúne respostas curtas de Hawking a perguntas como "Como tudo começou?" e "Podemos prever o futuro?". Ele aborda também inteligência artificial e o futuro da humanidade. Uma síntese de suas ideias.', 'Intermediário', array['física', 'perguntas', 'futuro', 'inteligência artificial', 'divulgação científica']),
  ('bccc9fee-1cbc-512a-b26b-41a935ac1248', 'Astrophysics for People in a Hurry', 'Neil deGrasse Tyson', 'Ciência', 'en', 'Tyson resume em capítulos curtos temas como Big Bang, matéria escura e a vida no cosmos, para quem tem pouco tempo. A linguagem é leve e cheia de analogias. Um panorama rápido da astrofísica.', 'Intermediário', array['astrofísica', 'universo', 'divulgação científica', 'curto', 'cosmos']),
  ('af4eb5da-06d2-50a5-82a2-b22fd4208ea4', 'The Elegant Universe', 'Brian Greene', 'Ciência', 'en', 'Greene explica a teoria das cordas e a busca por unir a relatividade e a mecânica quântica numa só descrição do universo. Ele usa analogias para ideias abstratas. Um livro denso, mas acessível para curiosos.', 'Avançado', array['física', 'teoria das cordas', 'relatividade', 'quântica', 'divulgação científica']),
  ('e3a0005d-f410-5aa2-b6d2-70b4981b34e3', 'The Fabric of the Cosmos', 'Brian Greene', 'Ciência', 'en', 'Greene investiga o que são espaço e tempo, da relatividade de Einstein à física quântica e à cosmologia. Ele propõe visões surpreendentes sobre a realidade. Uma exploração aprofundada das ideias da física moderna.', 'Avançado', array['física', 'espaço', 'tempo', 'realidade', 'divulgação científica']),
  ('9ab32bbe-09f6-5d5a-a4de-52b91dfc4497', 'The Selfish Gene', 'Richard Dawkins', 'Ciência', 'en', 'Dawkins propõe ver a evolução do ponto de vista dos genes, que "usam" os organismos para se replicar, e apresenta a ideia de meme. O livro mudou a forma de falar de evolução e comportamento. Um clássico e muito debatido.', 'Avançado', array['evolução', 'genética', 'biologia', 'comportamento', 'clássico']),
  ('cd55ce79-b361-5a02-879d-2c7a2b1ee404', 'The Blind Watchmaker', 'Richard Dawkins', 'Ciência', 'en', 'Dawkins argumenta que a seleção natural, sem planejamento, explica a complexidade da vida, usando simulações de computador e exemplos animais. O livro discute a ideia de um "relojoeiro" criador. Uma defesa apaixonada da evolução.', 'Avançado', array['evolução', 'seleção natural', 'biologia', 'complexidade', 'divulgação científica']),
  ('db45edd4-650d-5f3d-a846-cc2a41d924b9', 'The God Delusion', 'Richard Dawkins', 'Ciência', 'en', 'Dawkins argumenta contra a existência de um deus pessoal e critica o papel das religiões na sociedade. O livro provocou debates intensos entre crentes e não crentes. Uma obra controversa que apresenta um ponto de vista ateu.', 'Avançado', array['religião', 'ateísmo', 'ciência', 'debate', 'polêmico']),
  ('9c9a9d13-d34c-5ca9-beb6-f18946c007f4', 'The Greatest Show on Earth', 'Richard Dawkins', 'Ciência', 'en', 'Dawkins reúne evidências a favor da evolução, de fósseis e da genética a observações de populações atuais. O tom é didático e direto. Um livro para entender como sabemos que a vida evolui.', 'Intermediário', array['evolução', 'evidências', 'biologia', 'fósseis', 'divulgação científica']),
  ('274c5093-8ebc-51dc-b8bd-daacb8f5f8da', 'Silent Spring', 'Rachel Carson', 'Ciência', 'en', 'Publicado em 1962, o livro alerta para os efeitos dos pesticidas, como o DDT, sobre aves, ecossistemas e pessoas. A obra gerou grande debate e impulsionou o movimento ambiental. Um marco da literatura ecológica.', 'Avançado', array['meio ambiente', 'pesticidas', 'natureza', 'clássico', 'ecologia']),
  ('cefdf532-eb12-57ab-a2fd-727f66a9fe6c', 'Guns, Germs, and Steel', 'Jared Diamond', 'História', 'en', 'Diamond argumenta que as diferenças de poder entre sociedades vêm sobretudo de fatores ambientais, como plantas, animais e geografia. O livro percorre milênios de história humana. Um best-seller que provocou muita discussão.', 'Intermediário', array['história', 'civilizações', 'geografia', 'sociedade', 'ciência']),
  ('444a1eb8-5608-52b8-9cd2-ca71b60c03f8', 'Collapse', 'Jared Diamond', 'História', 'en', 'Diamond examina por que algumas sociedades colapsam e outras sobrevivem, olhando para desmatamento, clima e decisões políticas. Ele analisa exemplos do passado e do presente. Um livro sobre ambiente e escolhas coletivas.', 'Intermediário', array['história', 'sociedade', 'meio ambiente', 'civilizações', 'sustentabilidade']),
  ('827f2905-e4e9-5a94-a6e8-9581aeaa8854', 'A Short History of Nearly Everything', 'Bill Bryson', 'Ciência', 'en', 'Bryson percorre, com humor, a história das descobertas sobre o universo, a Terra e a vida, contando também quem foram os cientistas. A leitura é leve e curiosa. Um panorama divertido da ciência.', 'Intermediário', array['ciência', 'história da ciência', 'humor', 'divulgação científica', 'universo']),
  ('f5059026-722e-5dcc-857e-158c8c8728b8', 'The Body', 'Bill Bryson', 'Ciência', 'en', 'Bryson faz um passeio pelo corpo humano, da pele ao cérebro, e conta curiosidades sobre como ele funciona e sobre a história da medicina. O tom é bem-humorado. Uma leitura informativa e descontraída.', 'Intermediário', array['corpo humano', 'saúde', 'medicina', 'curiosidades', 'divulgação científica']),
  ('197eb97f-62c2-5078-a399-358e0d080f8d', 'At Home', 'Bill Bryson', 'História', 'en', 'Bryson percorre os cômodos de uma casa antiga na Inglaterra e usa cada um para contar a história de hábitos, objetos e inovações do dia a dia. A narrativa é cheia de curiosidades. Uma história da vida privada contada com leveza.', 'Intermediário', array['história', 'vida cotidiana', 'casa', 'curiosidades', 'humor']),
  ('669d1a5b-9c65-5730-b106-783ab897853f', 'Stiff', 'Mary Roach', 'Ciência', 'en', 'Roach investiga o que acontece com cadáveres doados à ciência, de pesquisas médicas a testes de impacto. O tom é curioso e bem-humorado, apesar do tema delicado. Uma leitura inusitada sobre morte e ciência.', 'Intermediário', array['corpo humano', 'ciência', 'humor', 'curiosidades', 'morte']),
  ('8b98feee-40e8-54f8-b5ae-28a0ab2f79d8', 'Packing for Mars', 'Mary Roach', 'Ciência', 'en', 'Roach explora os desafios do corpo humano no espaço, como comer, dormir e ir ao banheiro, em tom leve. Ela conversa com cientistas e astronautas. Um livro divertido sobre a vida fora da Terra.', 'Intermediário', array['espaço', 'astronautas', 'ciência', 'humor', 'curiosidades']),
  ('df5d01b4-bdad-53a9-b8fc-a1606943fe79', 'Gulp', 'Mary Roach', 'Ciência', 'en', 'Roach viaja pelo sistema digestivo, da boca ao intestino, contando experimentos, curiosidades e histórias. O livro mistura ciência e humor. Uma exploração bem-humorada de como comemos.', 'Intermediário', array['corpo humano', 'digestão', 'ciência', 'humor', 'curiosidades']),
  ('2d59a715-948d-57e1-b200-1a1c2330da8b', 'The Man Who Mistook His Wife for a Hat', 'Oliver Sacks', 'Ciência', 'en', 'O neurologista Sacks conta histórias de pacientes com distúrbios neurológicos curiosos, como o homem que não reconhecia rostos. Cada caso é tratado com sensibilidade. Um clássico sobre cérebro e identidade.', 'Intermediário', array['neurologia', 'cérebro', 'casos clínicos', 'medicina', 'humanidade']),
  ('6771e8b3-62f4-5e59-b00c-9ca5fc38ff58', 'Musicophilia', 'Oliver Sacks', 'Ciência', 'en', 'Sacks explora como a música afeta o cérebro, da amusia a melodias que não saem da cabeça, com casos de pacientes. Ele mostra o poder terapêutico dos sons. Um livro sobre música e mente.', 'Intermediário', array['música', 'cérebro', 'neurologia', 'casos clínicos', 'humanidade']),
  ('3e17b00e-575d-57ed-9fc2-d4267a8372d7', 'Awakenings', 'Oliver Sacks', 'Ciência', 'en', 'Sacks relata o tratamento de pacientes com uma rara doença do sono prolongado, nos anos 1960, e o "despertar" provocado por uma nova droga. O livro mostra esperanças e limites do tratamento. Um relato humano e científico.', 'Avançado', array['neurologia', 'medicina', 'casos clínicos', 'história', 'humanidade']),
  ('174cb6f3-ac6a-596b-b04d-f1f99512cf2f', 'The Emperor of All Maladies', 'Siddhartha Mukherjee', 'Ciência', 'en', 'Mukherjee conta a história do câncer, da Antiguidade aos tratamentos modernos, como se fosse uma biografia da doença. Ele mistura ciência, casos de pacientes e relatos de médicos. Um livro premiado e comovente.', 'Avançado', array['câncer', 'medicina', 'história', 'ciência', 'biografia']),
  ('a4b4e0dd-c77e-534e-a694-26db4b7d565a', 'The Gene', 'Siddhartha Mukherjee', 'Ciência', 'en', 'Mukherjee narra a história da genética, de Mendel às tecnologias de edição genética, misturando ciência e memória familiar. Ele discute os dilemas éticos do conhecimento sobre os genes. Uma história íntima e abrangente.', 'Avançado', array['genética', 'história', 'medicina', 'família', 'ciência']),
  ('4f9ea527-0ca1-55d7-8551-eeacd40ad562', 'Surely You''re Joking, Mr. Feynman!', 'Richard P. Feynman', 'Biografia e Memórias', 'en', 'O físico Richard Feynman conta, com humor, episódios de sua vida, do trabalho no projeto da bomba atômica a travessuras e passatempos. O tom é de conversa. Um retrato divertido de um cientista curioso.', 'Intermediário', array['física', 'humor', 'curiosidade', 'memórias', 'ciência']),
  ('59e7da42-b0fb-57fb-a548-c5d3c19595a2', 'What Do You Care What Other People Think?', 'Richard P. Feynman', 'Biografia e Memórias', 'en', 'Em novas histórias, Feynman fala da relação com o pai, do amor pela esposa e de sua participação na comissão sobre o acidente do ônibus espacial Challenger. O livro mistura leveza e emoção. Uma continuação cheia de sentimento.', 'Intermediário', array['física', 'memórias', 'ciência', 'desafio', 'curiosidade']),
  ('cedfb199-4b92-5420-8f36-5df2e5dd4b02', 'Six Easy Pieces', 'Richard P. Feynman', 'Ciência', 'en', 'Reúne seis palestras de Feynman sobre fundamentos da física, de átomos à gravitação. A linguagem é simples e instigante. Uma introdução clássica à forma de pensar dos físicos.', 'Intermediário', array['física', 'aulas', 'ciência', 'introdução', 'divulgação científica']),
  ('cc58a706-e059-5c03-a601-146adcddd4d3', 'The Immortal Life of Henrietta Lacks', 'Rebecca Skloot', 'Ciência', 'en', 'Skloot conta a história de Henrietta Lacks, cujas células, retiradas sem seu conhecimento, deram origem à linhagem HeLa, usada em inúmeras pesquisas. O livro mistura ciência, racismo e ética médica. Uma reportagem comovente.', 'Intermediário', array['medicina', 'ética', 'história', 'células', 'biografia']),
  ('356c45d7-3921-580b-94ad-d8260f413e77', 'The Sixth Extinction', 'Elizabeth Kolbert', 'Ciência', 'en', 'Kolbert viaja por vários lugares para mostrar como a atividade humana está provocando uma nova extinção em massa. O livro mistura reportagem e ciência. Um alerta premiado sobre biodiversidade.', 'Intermediário', array['meio ambiente', 'extinção', 'biodiversidade', 'clima', 'jornalismo']),
  ('dee2895a-5f98-5e9a-946f-041c64abf064', 'Why We Sleep', 'Matthew Walker', 'Ciência', 'en', 'Walker, neurocientista, defende a importância do sono para a memória, a saúde e as emoções e dá orientações para dormir melhor. O livro é muito popular, e algumas de suas afirmações foram questionadas por outros pesquisadores. Uma leitura útil, mas que merece senso crítico.', 'Intermediário', array['sono', 'saúde', 'cérebro', 'hábitos', 'ciência']),
  ('0a61e647-ce54-5570-bd4f-25cd02e93c2b', 'The Body Keeps the Score', 'Bessel van der Kolk', 'Psicologia', 'en', 'O psiquiatra van der Kolk explica como o trauma afeta o cérebro e o corpo e apresenta abordagens de tratamento, como terapia e práticas corporais. O livro inclui histórias de pacientes. Uma obra influente sobre trauma.', 'Intermediário', array['trauma', 'psicologia', 'corpo', 'terapia', 'saúde mental']),
  ('17d39347-661b-554a-82b4-c68040045778', 'Behave', 'Robert M. Sapolsky', 'Ciência', 'en', 'Sapolsky investiga por que as pessoas se comportam como se comportam, passando pelo cérebro, pelos hormônios, pela infância, pela cultura e pela evolução. A linguagem é bem-humorada, mas o conteúdo é denso. Um panorama amplo sobre o comportamento humano.', 'Avançado', array['comportamento', 'neurociência', 'biologia', 'psicologia', 'sociedade']),
  ('b9d48aa4-44d7-505d-a2a1-8e02beb3ee74', 'Why Zebras Don''t Get Ulcers', 'Robert M. Sapolsky', 'Ciência', 'en', 'Sapolsky explica como o estresse afeta o corpo e por que, ao contrário dos animais, humanos o sentem de forma crônica. O livro traz humor e muitos exemplos. Uma introdução clássica à fisiologia do estresse.', 'Intermediário', array['estresse', 'saúde', 'biologia', 'fisiologia', 'divulgação científica']),
  ('09eb319f-d506-515a-983e-77f1f69278f2', 'On the Origin of Species', 'Charles Darwin', 'Ciência', 'en', 'Publicado em 1859, o livro apresenta a teoria da evolução por seleção natural, apoiada em observações de plantas e animais. Darwin responde a possíveis objeções e discute sua relevância. Uma obra que mudou a biologia.', 'Avançado', array['evolução', 'seleção natural', 'clássico', 'biologia', 'história da ciência']),
  ('3d952f28-d723-5527-a4e2-a5b357ec314f', 'The Voyage of the Beagle', 'Charles Darwin', 'Ciência', 'en', 'Darwin relata a viagem de cinco anos a bordo do navio Beagle, com observações sobre geologia, animais e povos. As experiências ajudaram a formar suas ideias sobre a evolução. Um diário de viagem e de descobertas.', 'Avançado', array['viagem', 'natureza', 'evolução', 'diário', 'clássico']),
  ('bbdfc9a0-9bb6-5aee-8792-9f2e7e68cc59', 'Braiding Sweetgrass', 'Robin Wall Kimmerer', 'Ciência', 'en', 'Kimmerer, botânica e integrante da nação Potawatomi, reúne ensaios que combinam ciência e saberes indígenas sobre plantas e a relação com a Terra. O texto é poético e reflexivo. Um livro sobre gratidão e cuidado com a natureza.', 'Intermediário', array['natureza', 'botânica', 'sabedoria indígena', 'ecologia', 'ensaios']),
  ('57a5b68c-e727-5dc7-849b-39d8d306db75', 'The Soul of an Octopus', 'Sy Montgomery', 'Ciência', 'en', 'Montgomery acompanha polvos num aquário e conta como conheceu a inteligência e a personalidade desses animais. O livro mistura ciência e afeto. Uma leitura encantadora sobre mentes diferentes da nossa.', 'Intermediário', array['animais', 'polvos', 'inteligência', 'natureza', 'amizade']),
  ('664b2c9d-a690-56e9-a2d2-8b7249e97f7a', 'H Is for Hawk', 'Helen Macdonald', 'Biografia e Memórias', 'en', 'Depois da morte do pai, Helen Macdonald decide treinar um gavião, o que a leva a enfrentar o luto. O livro mistura memórias, natureza e a vida de um escritor inglês que também treinou aves de rapina. Um relato poético sobre perda.', 'Avançado', array['luto', 'natureza', 'memórias', 'aves', 'escrita']),
  ('2eb2ed12-d4f3-5f83-8a51-9183956ce0a2', 'A Sand County Almanac', 'Aldo Leopold', 'Ciência', 'en', 'Publicado em 1949, o livro reúne ensaios sobre as estações numa fazenda em Wisconsin e propõe uma "ética da terra". Leopold defende que o ser humano é parte da comunidade natural. Um clássico da conservação.', 'Avançado', array['natureza', 'ética ambiental', 'ensaios', 'clássico', 'conservação']),
  ('b49b6023-b0a5-54db-8ac8-754586b2f391', 'Walden', 'Henry David Thoreau', 'Ensaios e Crônicas', 'en', 'Thoreau relata o período em que viveu numa cabana junto ao lago Walden, entre 1845 e 1847, e reflete sobre simplicidade e autonomia. A prosa mistura observação da natureza e crítica social. Um clássico sobre viver com menos.', 'Avançado', array['natureza', 'simplicidade', 'filosofia', 'clássico', 'ensaios']),
  ('6f21b968-f70f-5473-b4ff-56b3feea61bd', 'The Hot Zone', 'Richard Preston', 'Ciência', 'en', 'Preston conta, com ritmo de thriller, como o vírus Ebola chegou a um laboratório perto de Washington e como cientistas tentaram contê-lo. O livro mistura reportagem e narrativa dramática. Uma leitura tensa sobre doenças emergentes.', 'Intermediário', array['epidemias', 'ebola', 'suspense', 'saúde', 'jornalismo']),
  ('44357612-de99-5462-8db0-1e287415aa9c', 'Spillover', 'David Quammen', 'Ciência', 'en', 'Quammen investiga como doenças saltam de animais para humanos, do ebola à gripe e à aids, e entrevista cientistas pelo mundo. Ele explica por que novas epidemias são esperadas. Uma reportagem científica que continua muito atual.', 'Intermediário', array['epidemias', 'zoonoses', 'saúde', 'ciência', 'jornalismo']),
  ('dc56e80d-9d8d-5478-9e8e-be05a893acf2', 'The Song of the Cell', 'Siddhartha Mukherjee', 'Ciência', 'en', 'Mukherjee conta a história das células, da descoberta ao uso na medicina, e como compreendê-las abre novas terapias. O livro mistura ciência e relatos pessoais. Uma narrativa sobre a unidade básica da vida.', 'Avançado', array['células', 'biologia', 'medicina', 'história', 'ciência']),
  ('8dcacb50-bd32-5419-84a0-49d18b2d3c08', 'Entangled Life', 'Merlin Sheldrake', 'Ciência', 'en', 'Sheldrake apresenta o mundo dos fungos, de mofos a cogumelos e redes subterrâneas, e mostra como eles influenciam ecossistemas e vida humana. O livro mistura ciência e curiosidade pessoal. Um passeio por um reino pouco conhecido.', 'Intermediário', array['fungos', 'natureza', 'biologia', 'ecologia', 'divulgação científica']),
  ('e2e88f4c-4e22-5535-8051-2350eb460d28', 'The Brain That Changes Itself', 'Norman Doidge', 'Ciência', 'en', 'Doidge apresenta histórias de pessoas que recuperaram funções ou superaram limitações graças à neuroplasticidade, a capacidade do cérebro de se reorganizar. O livro explica as pesquisas por trás disso. Uma leitura esperançosa sobre o cérebro.', 'Intermediário', array['cérebro', 'neuroplasticidade', 'saúde', 'casos clínicos', 'neurociência']),
  ('02ee3f8f-d114-5328-b5d9-be2de6767297', 'The Language Instinct', 'Steven Pinker', 'Ciência', 'en', 'Pinker defende que a linguagem é um instinto humano, como teias de aranha são para aranhas, e explica como as crianças a adquirem. O livro tem humor e muitos exemplos. Uma introdução animada à linguística.', 'Avançado', array['linguagem', 'linguística', 'mente', 'evolução', 'divulgação científica']),
  ('de8c39b2-9ff3-5b9d-96f2-65e1098bce98', 'The Better Angels of Our Nature', 'Steven Pinker', 'História', 'en', 'Pinker reúne dados para defender que a violência diminuiu ao longo da história e propõe explicações para isso. A tese é muito debatida e criticada. Um livro extenso e provocativo sobre progresso social.', 'Avançado', array['violência', 'história', 'sociedade', 'estatísticas', 'progresso']),
  ('bf641449-21c2-52a3-a855-0eacc7484e0e', 'Becoming', 'Michelle Obama', 'Biografia e Memórias', 'en', 'Michelle Obama conta sua trajetória, da infância em Chicago à advocacia e à vida na Casa Branca como primeira-dama. Ela fala de família, identidade, maternidade e dos desafios do cargo. Uma memória franca e inspiradora.', 'Intermediário', array['memórias', 'mulheres', 'política', 'infância', 'inspiração']),
  ('620a993a-7dbe-5928-8477-d74bb3f2f0e3', 'Born a Crime', 'Trevor Noah', 'Biografia e Memórias', 'en', 'Trevor Noah conta, com humor, como foi crescer na África do Sul do apartheid, filho de uma mãe negra e um pai branco, numa época em que o relacionamento dos dois era crime. O livro destaca a força da mãe. Um relato divertido e comovente.', 'Intermediário', array['memórias', 'humor', 'áfrica do sul', 'apartheid', 'família']),
  ('c75773d5-79ba-50bc-aa99-1598f193e54b', 'I Am Malala', 'Malala Yousafzai and Christina Lamb', 'Biografia e Memórias', 'en', 'Malala conta como defendeu o direito das meninas à educação no Paquistão e sobreviveu a um ataque do Talibã. A história mostra sua família e a luta que a levou ao Nobel da Paz. Um relato de coragem e esperança.', 'Intermediário', array['educação', 'coragem', 'paquistão', 'memórias', 'direitos humanos']),
  ('dd0ec4dd-665b-509c-9559-f8deadee12c6', 'Long Walk to Freedom', 'Nelson Mandela', 'Biografia e Memórias', 'en', 'Mandela narra sua vida, da infância no campo à luta contra o apartheid, aos 27 anos de prisão e à presidência da África do Sul. O livro mostra a evolução de um líder. Uma autobiografia central do século XX.', 'Avançado', array['memórias', 'política', 'apartheid', 'liberdade', 'história']),
  ('b0881557-d147-5d09-862c-54895882a105', 'Educated', 'Tara Westover', 'Biografia e Memórias', 'en', 'Tara cresce numa família de sobrevivencialistas em Idaho e só entra numa sala de aula aos dezessete anos. Ela vai estudar na universidade, e o conhecimento a afasta da família. Uma memória sobre educação, lealdade e liberdade.', 'Intermediário', array['memórias', 'educação', 'família', 'superação', 'estados unidos']),
  ('5a6fc68d-6cbc-5186-a117-40212ae61a12', 'The Glass Castle', 'Jeannette Walls', 'Biografia e Memórias', 'en', 'Jeannette Walls conta a infância com pais excêntricos e imprevisíveis, que viviam se mudando e passando necessidade. Apesar disso, ela e os irmãos encontram formas de seguir em frente. Uma memória sobre amor, negligência e resiliência.', 'Intermediário', array['memórias', 'infância', 'pobreza', 'família', 'superação']),
  ('434de94c-942f-5226-af07-942e827e2d00', 'Hillbilly Elegy', 'J. D. Vance', 'Biografia e Memórias', 'en', 'Vance relata a vida em uma família de origem dos Apalaches que se mudou para Ohio e enfrentou pobreza, vício e instabilidade. O livro mistura lembranças e análise social. Uma memória muito discutida sobre classe e cultura.', 'Intermediário', array['memórias', 'família', 'classe trabalhadora', 'estados unidos', 'sociedade']),
  ('07d4e4c2-4914-59bf-92e0-bd8c46447bb2', 'Steve Jobs', 'Walter Isaacson', 'Biografia e Memórias', 'en', 'Isaacson escreve a biografia autorizada de Steve Jobs, com base em mais de quarenta entrevistas feitas com ele e com pessoas próximas. O livro mostra o gênio criativo e o temperamento difícil. Um retrato detalhado de um inovador.', 'Intermediário', array['biografia', 'tecnologia', 'apple', 'inovação', 'liderança']),
  ('e1bcc914-5205-59fc-a955-646ed49e9fbe', 'Einstein: His Life and Universe', 'Walter Isaacson', 'Biografia e Memórias', 'en', 'Isaacson narra a vida de Albert Einstein, do jovem funcionário de escritório de patentes ao cientista famoso, e explica suas ideias de forma acessível. O livro também discute suas posições políticas e pessoais. Uma biografia completa.', 'Intermediário', array['biografia', 'física', 'ciência', 'história', 'gênio']),
  ('fcef647d-f89d-5f1d-918b-fc538975ad6b', 'Leonardo da Vinci', 'Walter Isaacson', 'Biografia e Memórias', 'en', 'Isaacson usa os cadernos de Leonardo da Vinci para mostrar como a curiosidade sem limites uniu arte, ciência e invenção. O livro acompanha obras famosas e projetos inacabados. Um retrato de um dos maiores gênios da história.', 'Intermediário', array['biografia', 'arte', 'ciência', 'renascimento', 'curiosidade']),
  ('49357a27-0451-5a8d-b355-3cf1cabfee80', 'Benjamin Franklin: An American Life', 'Walter Isaacson', 'Biografia e Memórias', 'en', 'Isaacson narra a vida de Benjamin Franklin, que foi escritor, cientista, diplomata e um dos pais fundadores dos Estados Unidos. A biografia mostra suas conquistas, falhas e senso de humor. Um retrato vivo de um personagem multifacetado.', 'Avançado', array['biografia', 'história', 'estados unidos', 'inventor', 'política']),
  ('e2b83e8a-2a88-5ed6-82c1-fcfcde87bed9', 'Narrative of the Life of Frederick Douglass', 'Frederick Douglass', 'Biografia e Memórias', 'en', 'Frederick Douglass conta como nasceu escravizado em Maryland, sem saber a própria idade, e como aprendeu a ler escondido, mesmo proibido. Relata os castigos, a luta corpo a corpo contra o feitor Covey e a fuga para o Norte em 1838. Publicado em 1845, o livro virou uma das armas mais fortes do movimento abolicionista.', 'Avançado', array['escravidão', 'liberdade', 'memórias', 'clássico', 'história']),
  ('50aa9586-95e0-54c6-b600-9616ebb2f365', 'Up from Slavery', 'Booker T. Washington', 'Biografia e Memórias', 'en', 'Booker Washington narra sua trajetória desde a infância como escravizado até se tornar fundador do instituto Tuskegee e uma figura pública de grande influência. O livro é uma reflexão sobre trabalho, educação e progresso. Uma autobiografia histórica, muito discutida.', 'Avançado', array['memórias', 'educação', 'história', 'estados unidos', 'clássico']),
  ('2a13a94f-e970-5080-8dd3-a07862d20378', 'I Know Why the Caged Bird Sings', 'Maya Angelou', 'Biografia e Memórias', 'en', 'Maya Angelou relata a infância e a adolescência no sul dos Estados Unidos, marcadas por racismo, trauma e a força das palavras e da família. A narrativa é poética e sincera. O primeiro volume de suas autobiografias.', 'Intermediário', array['memórias', 'infância', 'racismo', 'resiliência', 'literatura']),
  ('dd8ddac8-6946-5610-a9a1-1b188a79025e', 'The Autobiography of Malcolm X', 'Malcolm X and Alex Haley', 'Biografia e Memórias', 'en', 'Escrita com o jornalista Alex Haley, a autobiografia acompanha Malcolm X da infância difícil à prisão, à fé e à liderança. O livro mostra transformações de pensamento ao longo da vida. Um documento central do século XX.', 'Intermediário', array['biografia', 'racismo', 'história', 'política', 'religião']),
  ('3ce57888-de7c-5d86-be4e-b4d7f474ab14', 'Dreams from My Father', 'Barack Obama', 'Biografia e Memórias', 'en', 'Barack Obama conta a busca por sua identidade, filho de um pai queniano e de uma mãe americana, e sua viagem ao Quênia para conhecer a família. O livro foi escrito antes de ele entrar na política nacional. Uma memória reflexiva e pessoal.', 'Intermediário', array['memórias', 'identidade', 'raça', 'família', 'política']),
  ('3b40bad2-cf6b-59f3-8650-bdb91c4d84ff', 'A Promised Land', 'Barack Obama', 'Biografia e Memórias', 'en', 'Obama narra a trajetória política e o primeiro mandato como presidente dos Estados Unidos, com bastidores de decisões importantes. O livro é o primeiro volume de suas memórias presidenciais. Um relato detalhado e pessoal.', 'Intermediário', array['memórias', 'política', 'presidência', 'estados unidos', 'história']),
  ('45705c62-f41e-5e5e-af5e-11ac9136eb90', 'Open', 'Andre Agassi', 'Biografia e Memórias', 'en', 'Agassi conta, com franqueza surpreendente, sua carreira no tênis e revela que, por muito tempo, odiou o esporte. O livro fala de pressão do pai, crises e reinvenção. Uma autobiografia esportiva sincera.', 'Intermediário', array['esporte', 'tênis', 'memórias', 'pressão', 'superação']),
  ('e32e6ee1-9f02-53ab-b93e-48d9dae23d3f', 'Into the Wild', 'Jon Krakauer', 'Biografia e Memórias', 'en', 'Krakauer reconstrói a história de Chris McCandless, jovem que abandonou tudo e foi viver sozinho no Alasca, onde morreu. O autor tenta entender suas motivações. Uma reportagem sobre liberdade e riscos.', 'Intermediário', array['aventura', 'natureza', 'jornalismo', 'jovem', 'alasca']),
  ('645399cf-21f9-5906-8e40-13a7274a2e4e', 'Into Thin Air', 'Jon Krakauer', 'Biografia e Memórias', 'en', 'Krakauer, que estava na expedição, relata o desastre de 1996 no Monte Everest, em que vários alpinistas morreram durante uma tempestade. O livro discute decisões, ambição e limites. Um relato tenso e emocionante.', 'Intermediário', array['montanhismo', 'everest', 'tragédia', 'aventura', 'jornalismo']),
  ('63a870d3-f942-5236-a22f-f25255225944', 'Unbroken', 'Laura Hillenbrand', 'Biografia e Memórias', 'en', 'Hillenbrand conta a vida de Louis Zamperini, corredor olímpico que sobreviveu a um acidente aéreo, semanas à deriva no mar e anos em campos de prisioneiros japoneses. A história mostra resistência e perdão. Uma biografia de superação.', 'Intermediário', array['segunda guerra', 'sobrevivência', 'esporte', 'coragem', 'história']),
  ('18dd54e9-577d-5bc8-828a-f97ff79cc66f', 'Seabiscuit', 'Laura Hillenbrand', 'História', 'en', 'Hillenbrand conta a história do improvável cavalo de corrida Seabiscuit e de seus donos, treinador e jóquei, na época da Grande Depressão. A trajetória deles virou símbolo de esperança. Uma narrativa envolvente de esporte e história.', 'Intermediário', array['corridas de cavalo', 'grande depressão', 'esperança', 'história', 'estados unidos']),
  ('bd45d9de-9988-5f53-be22-683dda8ef3af', 'The Boys in the Boat', 'Daniel James Brown', 'História', 'en', 'Brown conta como nove rapazes de origem humilde, da equipe de remo da Universidade de Washington, chegaram às Olimpíadas de Berlim, em 1936. A história mistura esporte, trabalho em equipe e contexto histórico. Uma narrativa de superação.', 'Intermediário', array['esporte', 'remo', 'olimpíadas', 'década de 1930', 'superação']),
  ('20f9e14d-7834-524b-a057-35ce66133f59', 'Alexander Hamilton', 'Ron Chernow', 'Biografia e Memórias', 'en', 'Chernow acompanha a vida de Alexander Hamilton, órfão imigrante que se tornou um dos pais fundadores e primeiro secretário do Tesouro dos Estados Unidos. A biografia mostra suas ideias e rivalidades. A obra inspirou o musical Hamilton.', 'Avançado', array['biografia', 'história', 'estados unidos', 'política', 'fundadores']),
  ('3be1c683-0754-5a0d-92af-d8c118fc0cc5', 'Washington: A Life', 'Ron Chernow', 'Biografia e Memórias', 'en', 'Chernow narra a vida de George Washington, do jovem oficial ao general da Revolução e primeiro presidente. A biografia mostra suas qualidades e contradições. Um retrato humano de um líder fundador.', 'Avançado', array['biografia', 'história', 'estados unidos', 'liderança', 'independência']),
  ('63374231-811b-5657-9130-73c74e143d71', 'Grant', 'Ron Chernow', 'Biografia e Memórias', 'en', 'Chernow retrata Ulysses Grant, general vitorioso na Guerra Civil e presidente, revendo uma imagem muitas vezes injusta. O livro fala de sucesso, fracasso e luta contra o vício. Uma biografia extensa e reveladora.', 'Avançado', array['biografia', 'guerra civil', 'presidência', 'história', 'estados unidos']),
  ('e40f549b-657c-549f-82aa-da4fcb2d1b87', 'John Adams', 'David McCullough', 'Biografia e Memórias', 'en', 'McCullough narra a vida de John Adams, advogado, diplomata e segundo presidente dos Estados Unidos, com destaque para o casamento com Abigail. O livro mostra os bastidores da independência. Uma biografia premiada e de leitura fluida.', 'Avançado', array['biografia', 'independência', 'história', 'política', 'estados unidos']),
  ('b82e980f-228f-51df-93d4-c72b9d146253', '1776', 'David McCullough', 'História', 'en', 'McCullough conta o ano de 1776, em que as colônias declararam independência, mas o exército de Washington enfrentou derrotas e dificuldades. O livro acompanha soldados e líderes na guerra. Uma narrativa vívida e humana.', 'Intermediário', array['independência', 'guerra', 'estados unidos', 'história', 'washington']),
  ('6b1a6377-86e8-54b8-a2b2-b410b132aa0e', 'The Wright Brothers', 'David McCullough', 'Biografia e Memórias', 'en', 'McCullough conta a história de Wilbur e Orville Wright, que construíram e pilotaram o primeiro avião motorizado. Ele destaca a determinação, o trabalho em equipe e a vida familiar. Uma biografia curta e envolvente.', 'Intermediário', array['aviação', 'invenção', 'biografia', 'história', 'estados unidos']),
  ('d079fb7b-4758-5086-a208-4b822bd2b202', 'The Devil in the White City', 'Erik Larson', 'História', 'en', 'Larson alterna a construção da Feira Mundial de Chicago, em 1893, com a história de um assassino que agia na cidade. O resultado é uma narrativa que mistura história e suspense. Um livro de não ficção de leitura envolvente.', 'Intermediário', array['chicago', 'assassino em série', 'feira mundial', 'história', 'suspense']),
  ('35101869-defb-554c-aa61-90f138792810', 'In the Garden of Beasts', 'Erik Larson', 'História', 'en', 'Larson acompanha o embaixador americano William Dodd e sua filha em Berlim, em 1933, quando o regime nazista se consolidava. A narrativa mostra como a ameaça foi sendo subestimada. Um retrato pessoal de um período decisivo.', 'Intermediário', array['nazismo', 'berlim', 'diplomacia', 'história', 'década de 1930']),
  ('55c1b19b-00be-5cc8-8830-cd020adbed16', 'Dead Wake', 'Erik Larson', 'História', 'en', 'Larson reconstrói o naufrágio do navio de passageiros Lusitania, afundado por um submarino alemão em 1915. A narrativa alterna passageiros, capitão e comandante do submarino. Um relato de tensão crescente.', 'Intermediário', array['primeira guerra', 'navio', 'história', 'tragédia', 'suspense']),
  ('05a2ad73-372f-5896-bcb1-24c8b87def50', 'The Splendid and the Vile', 'Erik Larson', 'História', 'en', 'Larson acompanha o primeiro ano de Churchill como primeiro-ministro, em 1940 e 1941, durante os bombardeios sobre Londres. O livro mostra também a vida de sua família e de assessores. Um retrato próximo e humano de um período dramático.', 'Intermediário', array['segunda guerra', 'churchill', 'londres', 'história', 'família']),
  ('65cd0dad-ca8e-5f66-82cc-4e0aae90b7b2', 'Team of Rivals', 'Doris Kearns Goodwin', 'História', 'en', 'Goodwin conta como Abraham Lincoln reuniu antigos adversários políticos em seu governo e os transformou em aliados durante a Guerra Civil. O livro mostra sua habilidade de liderança. Uma biografia coletiva premiada.', 'Avançado', array['lincoln', 'guerra civil', 'liderança', 'história', 'política']),
  ('988c3fe6-1774-586c-acb0-7f581c6715f8', 'The Warmth of Other Suns', 'Isabel Wilkerson', 'História', 'en', 'Wilkerson conta a Grande Migração de milhões de negros do Sul para o Norte e o Oeste dos Estados Unidos, seguindo três pessoas em suas jornadas. O livro mistura história e relatos íntimos. Uma obra premiada sobre esperança e desigualdade.', 'Intermediário', array['migração', 'racismo', 'história', 'estados unidos', 'famílias']),
  ('4357cff8-fd25-5888-9071-b5cb6d58974f', 'Caste', 'Isabel Wilkerson', 'História', 'en', 'Wilkerson argumenta que a desigualdade racial nos Estados Unidos funciona como um sistema de castas e o compara a outras hierarquias, como a da Índia. O livro mistura história, casos e análise. Uma leitura provocativa sobre estrutura social.', 'Intermediário', array['racismo', 'sociedade', 'história', 'estados unidos', 'desigualdade']),
  ('3b5d05df-df58-5041-966d-4909cc8a6dac', 'Just Mercy', 'Bryan Stevenson', 'Biografia e Memórias', 'en', 'O advogado Bryan Stevenson conta casos de pessoas condenadas injustamente, em especial o de um homem no corredor da morte no Alabama. O livro mostra falhas do sistema criminal. Um relato comovente sobre justiça e compaixão.', 'Intermediário', array['justiça', 'direitos humanos', 'racismo', 'advocacia', 'estados unidos']),
  ('83f5652f-d9cd-5b2d-932d-6ce118e156d2', 'The New Jim Crow', 'Michelle Alexander', 'História', 'en', 'Alexander argumenta que o encarceramento em massa nos Estados Unidos funciona como um novo sistema de controle racial. Ela reúne dados, leis e histórias. Um livro influente e debatido sobre justiça criminal.', 'Avançado', array['racismo', 'encarceramento', 'justiça', 'sociedade', 'estados unidos']),
  ('9ea6ba32-13e0-57d2-881c-95a6eb210615', 'Between the World and Me', 'Ta-Nehisi Coates', 'Ensaios e Crônicas', 'en', 'Em forma de carta ao filho adolescente, Coates reflete sobre o que significa viver num corpo negro nos Estados Unidos. O texto mistura memória, história e ensaio. Um livro curto, poético e direto.', 'Intermediário', array['racismo', 'estados unidos', 'carta', 'identidade', 'ensaio']),
  ('f14bc7be-4761-5875-abee-f2b720eca152', 'A People''s History of the United States', 'Howard Zinn', 'História', 'en', 'Zinn conta a história dos Estados Unidos do ponto de vista de trabalhadores, povos indígenas, escravizados e outros grupos que costumam ficar de fora. O livro é influente e também criticado por seu viés. Uma leitura que oferece outra perspectiva.', 'Intermediário', array['história', 'estados unidos', 'movimentos sociais', 'crítica', 'sociedade']),
  ('d9d059f3-5f85-57ba-a7ff-783c452e150a', 'The Rise and Fall of the Third Reich', 'William L. Shirer', 'História', 'en', 'Shirer, que viveu na Alemanha nazista como correspondente, narra a ascensão de Hitler e o colapso do regime. O livro usa documentos e testemunhos. Uma obra extensa e clássica sobre o período.', 'Avançado', array['nazismo', 'segunda guerra', 'história', 'alemanha', 'clássico']),
  ('8fb28edd-f499-50b9-bcc4-95345bfb2686', 'Band of Brothers', 'Stephen E. Ambrose', 'História', 'en', 'Ambrose acompanha a Companhia Easy, uma unidade de paraquedistas americanos, do treinamento aos combates na Europa na Segunda Guerra. A narrativa se apoia em entrevistas com os veteranos. Um relato de camaradagem e coragem.', 'Intermediário', array['segunda guerra', 'soldados', 'companheirismo', 'história', 'militar']),
  ('eba21d5c-b577-50d5-a84d-cb5cbe93e920', 'The Guns of August', 'Barbara W. Tuchman', 'História', 'en', 'Tuchman narra o primeiro mês da Primeira Guerra Mundial, em 1914, e as decisões que levaram a Europa ao conflito. O livro ganhou o Pulitzer. Um clássico de história narrativa.', 'Avançado', array['primeira guerra', 'história', 'diplomacia', 'europa', 'clássico']),
  ('6a24723d-3292-512c-95dd-bddcd1f9b41d', 'SPQR', 'Mary Beard', 'História', 'en', 'Mary Beard conta a história de Roma, de suas origens a 212 d.C., questionando mitos e dando voz a pessoas comuns. O texto é cheio de humor e crítica das fontes. Uma introdução acessível à Roma antiga.', 'Intermediário', array['roma antiga', 'história', 'império', 'sociedade', 'antiguidade']),
  ('85f36f8d-1bf6-515c-bdeb-195bfc549d68', 'The Silk Roads', 'Peter Frankopan', 'História', 'en', 'Frankopan propõe contar a história do mundo a partir do centro da Ásia, mostrando como as rotas comerciais ligaram impérios, religiões e ideias. A narrativa cobre milênios. Um panorama que muda o ponto de vista tradicional.', 'Intermediário', array['história mundial', 'ásia', 'comércio', 'impérios', 'religião']),
  ('131467bf-bb2e-5d59-8b9a-6046c31c3bdf', 'Salt: A World History', 'Mark Kurlansky', 'História', 'en', 'Kurlansky conta a história do mundo a partir do sal, de seu papel na conservação de alimentos a guerras e impostos. O livro mistura curiosidades e receitas. Uma forma saborosa de ver a história.', 'Intermediário', array['história', 'alimentação', 'comércio', 'cultura', 'curiosidades']),
  ('3e346e21-434d-5127-aa9b-0693e04b6bf0', 'Killers of the Flower Moon', 'David Grann', 'História', 'en', 'Grann reconstrói a série de assassinatos de membros da nação Osage, enriquecida pelo petróleo, em Oklahoma, nos anos 1920, e a investigação que foi um dos primeiros grandes casos do FBI. O livro revela conspiração e ganância. Um relato de crime e injustiça.', 'Intermediário', array['crime real', 'osage', 'década de 1920', 'fbi', 'história']),
  ('9e86aa5a-2a04-5b94-9bb3-196548c1aebe', 'The Lost City of Z', 'David Grann', 'História', 'en', 'Grann investiga o desaparecimento do explorador Percy Fawcett na Amazônia, em 1925, enquanto procurava uma cidade perdida. O autor refaz parte da expedição. Uma narrativa de aventura e mistério.', 'Intermediário', array['exploração', 'amazônia', 'mistério', 'aventura', 'história']),
  ('2d5c4484-0eba-5299-b828-2b5c9819de1a', 'Empire of Pain', 'Patrick Radden Keefe', 'História', 'en', 'Keefe conta a história da família Sackler e da empresa que lançou o OxyContin, e como a busca por lucro alimentou a crise dos opioides. O livro se apoia em extensa reportagem. Um retrato de poder e responsabilidade.', 'Intermediário', array['opioides', 'saúde', 'família', 'negócios', 'jornalismo']),
  ('eb33b178-a042-5d4e-b255-2df82b759ae4', 'Say Nothing', 'Patrick Radden Keefe', 'História', 'en', 'Keefe parte do desaparecimento de uma mulher em Belfast, em 1972, para contar o conflito da Irlanda do Norte e as vidas por ele marcadas. O livro mistura investigação e história. Um relato de violência, memória e silêncio.', 'Intermediário', array['irlanda do norte', 'conflito', 'mistério', 'história', 'jornalismo']),
  ('76f932fb-604d-537a-a241-0466f7e2aefa', 'Mere Christianity', 'C. S. Lewis', 'Espiritualidade', 'en', 'Baseado em palestras de rádio feitas durante a Segunda Guerra, o livro apresenta as ideias básicas da fé cristã com argumentos claros e exemplos do dia a dia. Lewis parte da noção de lei moral para chegar à fé. Um clássico acessível para crentes e céticos.', 'Intermediário', array['cristianismo', 'fé', 'apologética', 'clássico', 'ética'])
insert into public.livros (id, titulo, autor, genero, idioma, resumo, nivel_dificuldade, tags) values
  ('e2b5fa88-21a6-5ac2-a1c2-1a283da19aea', 'The Screwtape Letters', 'C. S. Lewis', 'Espiritualidade', 'en', 'O livro reúne cartas de um demônio experiente a seu sobrinho aprendiz sobre como tentar um jovem humano. A inversão de perspectiva revela armadilhas comuns da vida espiritual. Um clássico bem-humorado e perspicaz.', 'Intermediário', array['cristianismo', 'tentação', 'humor', 'clássico', 'ficção']),
  ('94c88478-c2e9-5b15-a5a2-aeb3ab0c48a5', 'The Problem of Pain', 'C. S. Lewis', 'Espiritualidade', 'en', 'Lewis enfrenta a pergunta de por que um Deus bom permite o sofrimento e examina respostas da tradição cristã. O texto é argumentativo e cuidadoso. Uma reflexão clássica sobre dor e fé.', 'Avançado', array['cristianismo', 'sofrimento', 'fé', 'filosofia', 'clássico']),
  ('1b326651-3fd5-59e7-bb23-0d7d43b0c1a3', 'A Grief Observed', 'C. S. Lewis', 'Espiritualidade', 'en', 'Anotações pessoais que Lewis escreveu depois da morte da esposa, em que ele expõe dúvidas, raiva e saudade. O livro acompanha o movimento do luto sem respostas fáceis. Um texto breve e muito sincero.', 'Intermediário', array['luto', 'fé', 'diário', 'dor', 'clássico']),
  ('bcad1c02-f776-5e50-9974-a5258c3167d6', 'The Great Divorce', 'C. S. Lewis', 'Espiritualidade', 'en', 'Numa fantasia em forma de sonho, um grupo viaja de ônibus do inferno aos arredores do céu e é convidado a ficar. Os diálogos mostram como o orgulho e os apegos impedem a mudança. Uma alegoria sobre liberdade e escolhas.', 'Intermediário', array['cristianismo', 'céu e inferno', 'alegoria', 'escolhas', 'clássico']),
  ('5aaff272-e313-5e78-a517-4a0c041a9088', 'The Four Loves', 'C. S. Lewis', 'Espiritualidade', 'en', 'Lewis analisa quatro tipos de amor, afeto, amizade, amor romântico e caridade, e mostra seus valores e riscos. O livro mistura filosofia e observação da vida. Uma reflexão profunda sobre o amor.', 'Avançado', array['amor', 'amizade', 'cristianismo', 'reflexão', 'clássico']),
  ('180bc270-fa97-5a6e-8f1c-cd9a28da7116', 'Surprised by Joy', 'C. S. Lewis', 'Biografia e Memórias', 'en', 'Lewis conta a "forma" de sua vida até a conversão ao cristianismo, passando por escola, guerra e amizades. O tema central é a "alegria", um desejo que parecia apontar para algo além. Uma autobiografia intelectual e espiritual.', 'Avançado', array['memórias', 'fé', 'conversão', 'infância', 'clássico']),
  ('61e6ea94-7dab-5833-84e8-302d5f7a9698', 'Miracles', 'C. S. Lewis', 'Espiritualidade', 'en', 'Lewis discute se os milagres são possíveis e como a razão e a fé se relacionam. Ele examina o naturalismo e propõe respostas com argumentos filosóficos. Um livro desafiador para quem gosta de debate.', 'Avançado', array['cristianismo', 'milagres', 'filosofia', 'fé', 'clássico']),
  ('1d6fbbc4-ebbf-576f-9245-d15ab83e3238', 'Orthodoxy', 'G. K. Chesterton', 'Espiritualidade', 'en', 'Chesterton conta, com humor e paradoxos, como chegou à fé cristã e por que a considera mais satisfatória do que alternativas modernas. O estilo é brilhante e provocador. Um clássico da apologética.', 'Avançado', array['cristianismo', 'fé', 'paradoxo', 'clássico', 'humor']),
  ('e50b5e72-477b-5cd2-9a75-e99dc6d36eec', 'The Everlasting Man', 'G. K. Chesterton', 'Espiritualidade', 'en', 'Chesterton escreve em 1925 uma resposta às histórias da humanidade que tratam o homem como mais um animal. Na primeira parte olha para a pré-história, a arte das cavernas e as religiões antigas; na segunda, para a figura de Jesus de Nazaré. O tom é cheio de humor e paradoxos, e o raciocínio vai de imagens simples a grandes conclusões.', 'Avançado', array['cristianismo', 'história', 'fé', 'clássico', 'apologética']),
  ('f0eccdfe-b543-581b-9c11-cfefd94894eb', 'The Purpose Driven Life', 'Rick Warren', 'Espiritualidade', 'en', 'Em quarenta capítulos curtos, Warren propõe uma jornada para descobrir o propósito de Deus para a vida, a começar pela frase "não é sobre você". Cada capítulo traz reflexão e perguntas. Um dos livros cristãos mais vendidos.', 'Iniciante', array['propósito', 'cristianismo', 'devocional', '40 dias', 'vida']),
  ('6e7f9864-b622-508a-a764-3251c35c1534', 'The Pursuit of God', 'A. W. Tozer', 'Espiritualidade', 'en', 'Tozer convida o leitor a desejar profundamente a presença de Deus e a viver a fé de modo interior e sincero. Os capítulos curtos tratam de humildade, simplicidade e adoração. Um clássico de devoção cristã.', 'Intermediário', array['cristianismo', 'oração', 'devoção', 'clássico', 'intimidade com deus']),
  ('dd194bd6-17cd-5a40-98c9-37917cc390f1', 'The Knowledge of the Holy', 'A. W. Tozer', 'Espiritualidade', 'en', 'Tozer examina atributos de Deus, como sabedoria, amor e justiça, e defende que o que pensamos dele molda nossa vida. O tom é de adoração, e não só de estudo. Um clássico sobre o caráter divino.', 'Intermediário', array['cristianismo', 'deus', 'adoração', 'teologia', 'clássico']),
  ('a1a30bc1-86a4-5f23-8006-54c4b1004915', 'Knowing God', 'J. I. Packer', 'Espiritualidade', 'en', 'Packer defende que conhecer a Deus é mais do que saber sobre ele e analisa seus atributos e o sentido de uma relação pessoal com Deus. Mistura estudo e aplicação prática. Um clássico de teologia popular.', 'Intermediário', array['cristianismo', 'teologia', 'deus', 'fé', 'clássico']),
  ('bf129ef8-4003-5374-8e4c-12326453fdf8', 'The Reason for God', 'Timothy Keller', 'Espiritualidade', 'en', 'Keller enfrenta objeções comuns à fé, como sofrimento, exclusivismo e injustiça, e apresenta razões para crer. O tom é respeitoso com quem duvida. Um livro de argumento claro e acessível.', 'Intermediário', array['cristianismo', 'dúvida', 'apologética', 'fé', 'razão']),
  ('c6880cdc-2102-5d7f-a94f-570e2aa5f6bb', 'The Prodigal God', 'Timothy Keller', 'Espiritualidade', 'en', 'Keller reinterpreta a parábola do filho pródigo e destaca também o irmão mais velho, mostrando duas formas de se afastar de Deus. O livro enfatiza a graça. Uma leitura curta e reveladora.', 'Intermediário', array['cristianismo', 'parábola', 'graça', 'jesus', 'reflexão']),
  ('2b889866-bd6a-5707-833c-6808ff620257', 'Prayer: Experiencing Awe and Intimacy with God', 'Timothy Keller', 'Espiritualidade', 'en', 'Keller explica por que orar é difícil e essencial e apresenta caminhos práticos, ligados a salmos e a grandes autores cristãos. O livro mistura teologia e orientações simples. Um guia reflexivo sobre oração.', 'Intermediário', array['oração', 'cristianismo', 'fé', 'devoção', 'prática']),
  ('31af4741-0e66-5ae6-bc42-75ea7c2172d4', 'The Return of the Prodigal Son', 'Henri J. M. Nouwen', 'Espiritualidade', 'en', 'Nouwen medita sobre o quadro de Rembrandt do filho pródigo e sobre os papéis do filho, do irmão mais velho e do pai. A reflexão o leva a pensar em sua própria vida. Um clássico sobre perdão e acolhimento.', 'Intermediário', array['parábola', 'graça', 'arte', 'cristianismo', 'reflexão']),
  ('a5696a93-8f2b-5d48-84c4-f323d7f139f9', 'The Wounded Healer', 'Henri J. M. Nouwen', 'Espiritualidade', 'en', 'Nouwen defende que quem cuida de outros serve melhor quando reconhece as próprias feridas. O livro reflete sobre solidão e serviço no mundo contemporâneo. Uma obra curta e profunda sobre vocação.', 'Avançado', array['ministério', 'sofrimento', 'cuidado', 'cristianismo', 'reflexão']),
  ('cff8faf9-da4e-5d70-b55b-60b1f95ca956', 'Life of the Beloved', 'Henri J. M. Nouwen', 'Espiritualidade', 'en', 'Escrito para um amigo não religioso, o livro ajuda o leitor a ver a si mesmo como "amado", e não como alguém que precisa provar valor. Nouwen explora a ideia de ser escolhido, abençoado e partilhado. Uma leitura calorosa e simples.', 'Intermediário', array['identidade', 'amor', 'fé', 'cristianismo', 'reflexão']),
  ('d3fe07a2-5757-5e1e-ae6f-9954870edb0e', 'New Seeds of Contemplation', 'Thomas Merton', 'Espiritualidade', 'en', 'Merton reflete sobre a vida interior, a oração e a descoberta do verdadeiro eu diante de Deus, em capítulos curtos. O estilo é poético e profundo. Um clássico da espiritualidade contemplativa.', 'Avançado', array['contemplação', 'oração', 'silêncio', 'cristianismo', 'clássico']),
  ('554fa5b3-4600-509b-8518-5e469ba3f593', 'The Seven Storey Mountain', 'Thomas Merton', 'Biografia e Memórias', 'en', 'Merton conta como, depois de uma juventude inquieta, converteu-se ao catolicismo e entrou num mosteiro trapista. A autobiografia virou best-seller nos anos 1940. Um relato de busca espiritual.', 'Avançado', array['memórias', 'conversão', 'mosteiro', 'fé', 'clássico']),
  ('7f9f3905-1e66-5e75-a9b2-d6822ec7c480', 'The Ragamuffin Gospel', 'Brennan Manning', 'Espiritualidade', 'en', 'Manning escreve sobre a graça de Deus como boa notícia para pessoas frágeis, cansadas e fracassadas. O livro desafia a religião baseada em desempenho. Uma leitura acolhedora e provocadora.', 'Intermediário', array['graça', 'cristianismo', 'fé', 'fragilidade', 'reflexão']),
  ('41c7589e-64f5-5023-8c54-0f063c7af42b', 'What''s So Amazing About Grace?', 'Philip Yancey', 'Espiritualidade', 'en', 'Yancey examina o que a graça significa na prática e por que é tão rara entre as pessoas, inclusive entre cristãos. Ele conta histórias de perdão e transformação. Um livro sensível sobre acolhimento e misericórdia.', 'Intermediário', array['graça', 'perdão', 'cristianismo', 'fé', 'reflexão']),
  ('805c6827-bc1c-523c-8b92-b6ee58c1c4d8', 'Disappointment with God', 'Philip Yancey', 'Espiritualidade', 'en', 'Yancey enfrenta três perguntas incômodas: Deus é injusto, silencioso ou escondido? Ele conversa com pessoas que passaram por sofrimento e revisita o livro de Jó. Uma reflexão honesta sobre dúvida.', 'Intermediário', array['dúvida', 'sofrimento', 'fé', 'cristianismo', 'reflexão']),
  ('fc2d91a3-fa21-520c-be38-176f63b0df16', 'Prayer: Does It Make Any Difference?', 'Philip Yancey', 'Espiritualidade', 'en', 'Yancey fala das dificuldades e das alegrias da oração, usando histórias e reflexões pessoais. Ele aborda dúvidas, silêncio e a ideia de que orar muda quem ora. Um livro sincero para quem tem dificuldade de rezar.', 'Intermediário', array['oração', 'fé', 'cristianismo', 'dúvida', 'prática']),
  ('efd38c09-22ad-527e-a671-9c961bc9d8ee', 'Celebration of Discipline', 'Richard J. Foster', 'Espiritualidade', 'en', 'Foster apresenta práticas como meditação, oração, jejum, simplicidade e serviço como caminhos para crescer espiritualmente. O livro mistura teoria e orientações práticas. Um clássico sobre vida espiritual.', 'Intermediário', array['disciplinas espirituais', 'oração', 'jejum', 'cristianismo', 'clássico']),
  ('9afe5ccf-fa32-5c71-aa70-b70db55177d4', 'The Divine Conspiracy', 'Dallas Willard', 'Espiritualidade', 'en', 'Willard interpreta o Sermão do Monte como um convite a viver sob o reino de Deus aqui e agora. Ele critica uma fé limitada à vida depois da morte. Um livro denso e transformador.', 'Avançado', array['reino de deus', 'jesus', 'cristianismo', 'teologia', 'discipulado']),
  ('2a059ae0-6859-54b0-929a-174792b74156', 'Anxious for Nothing', 'Max Lucado', 'Espiritualidade', 'en', 'Lucado comenta o trecho bíblico de Filipenses sobre não ficar ansioso e propõe passos práticos de oração e gratidão. A linguagem é simples e cheia de exemplos do cotidiano. Um guia gentil contra a ansiedade.', 'Iniciante', array['ansiedade', 'oração', 'fé', 'paz', 'filipenses']),
  ('725fbe8d-26aa-53da-a875-c24d0765d7b7', 'You''ll Get Through This', 'Max Lucado', 'Espiritualidade', 'en', 'Lucado usa a história bíblica de José para falar de esperança em tempos difíceis e da ideia de que Deus age mesmo no meio da dor. O texto é caloroso e acessível. Um livro de consolo e perseverança.', 'Iniciante', array['esperança', 'fé', 'sofrimento', 'josé', 'perseverança']),
  ('32dd374a-5907-550e-8cf8-3e7956421bcb', 'Just Like Jesus', 'Max Lucado', 'Espiritualidade', 'en', 'Lucado reflete sobre as qualidades de Jesus, como compaixão, perdão e humildade, e convida o leitor a desenvolvê-las. O livro tem tom pessoal e histórias do cotidiano. Uma leitura simples e inspiradora.', 'Iniciante', array['cristianismo', 'jesus', 'coração', 'graça', 'devocional']),
  ('b22a03b9-d49e-5740-bbda-c18049d323ee', 'The Case for Christ', 'Lee Strobel', 'Espiritualidade', 'en', 'O jornalista Lee Strobel, que era ateu, entrevista especialistas para investigar as evidências sobre Jesus e a ressurreição. O livro conta o que ele descobriu e como mudou de ideia. Uma obra popular de apologética.', 'Intermediário', array['apologética', 'cristianismo', 'evidências', 'jornalismo', 'fé']),
  ('19a2dc4f-66da-55b0-b2e6-e0dbc343c5f3', 'Jesus Calling', 'Sarah Young', 'Espiritualidade', 'en', 'Devocional com textos curtos para cada dia, escritos como se fossem palavras de Jesus ao leitor. O estilo é calmo e de consolo. Um livro popular para a leitura diária.', 'Iniciante', array['devocional', 'oração', 'paz', 'cristianismo', 'dia a dia']),
  ('25375fc6-3515-58b3-906f-8285db321d4e', 'Streams in the Desert', 'L. B. Cowman', 'Espiritualidade', 'en', 'Devocional clássico com leituras diárias que combinam trechos bíblicos, citações e histórias para animar quem passa por tempos difíceis. Cada texto é curto. Um livro de consolo em tempos áridos.', 'Intermediário', array['devocional', 'consolo', 'fé', 'perseverança', 'clássico']),
  ('dcfbadb6-59d7-500d-8cd2-b4961363bc83', 'My Utmost for His Highest', 'Oswald Chambers', 'Espiritualidade', 'en', 'Devocional clássico com reflexões diárias que desafiam o leitor a viver de maneira dedicada a Deus. Os textos são curtos e densos. Um dos devocionais mais lidos do século XX.', 'Intermediário', array['devocional', 'fé', 'discipulado', 'clássico', 'vida diária']),
  ('eb2cf7d4-d976-53a2-a3bf-71db0ed80c43', 'The Pilgrim''s Progress', 'John Bunyan', 'Ficção Clássica', 'en', 'Publicada em 1678, a alegoria conta a viagem de Cristão da Cidade da Destruição até a Cidade Celestial, enfrentando tentações e desafios. Cada lugar e personagem representa algo da vida espiritual. Um clássico da literatura inglesa.', 'Avançado', array['alegoria', 'clássico', 'cristianismo', 'jornada', 'século xvii']),
  ('40a31605-75aa-59ea-b05b-6de22a613ae9', 'The Shack', 'William P. Young', 'Drama', 'en', 'Depois da perda trágica da filha, Mack recebe um bilhete que o leva a uma cabana, onde tem um encontro inesperado com Deus. A história aborda dor, perdão e confiança. Um romance de fé e consolo muito popular.', 'Intermediário', array['fé', 'sofrimento', 'luto', 'perdão', 'ficção cristã']),
  ('be786e3b-6646-5c99-bf62-4b60937a3acb', 'The Hiding Place', 'Corrie ten Boom', 'Biografia e Memórias', 'en', 'Corrie ten Boom conta como sua família holandesa escondeu judeus durante a ocupação nazista e como ela foi presa. O livro mostra fé, coragem e perdão. Um relato comovente da Segunda Guerra.', 'Intermediário', array['segunda guerra', 'fé', 'perdão', 'holanda', 'memórias']),
  ('cb02dee6-bda5-5e71-9db6-5a3ad2658e44', 'Through Gates of Splendor', 'Elisabeth Elliot', 'Biografia e Memórias', 'en', 'Elisabeth Elliot narra a história de cinco missionários mortos em 1956 no Equador ao tentarem contato com um povo isolado. O livro mostra sua preparação, fé e o que ocorreu depois. Um relato sobre coragem e sacrifício.', 'Intermediário', array['missões', 'fé', 'equador', 'história', 'coragem']),
  ('3b74e989-130a-5274-8c81-1bc2d6875c16', 'Crazy Love', 'Francis Chan', 'Espiritualidade', 'en', 'Chan convida o leitor a responder ao amor de Deus com um compromisso radical, em vez de uma fé morna. Ele propõe revisar prioridades e viver de modo generoso. Um livro direto e provocador.', 'Intermediário', array['cristianismo', 'amor de deus', 'compromisso', 'vida', 'reflexão']),
  ('97e4c63f-15b9-5b3b-a597-4161959ee3c7', 'Don''t Waste Your Life', 'John Piper', 'Espiritualidade', 'en', 'Piper defende que a vida tem sentido quando é vivida para glorificar a Deus, mesmo em tarefas comuns. Ele desafia o leitor a evitar uma vida acomodada. Um livro curto e intenso sobre propósito.', 'Intermediário', array['vocação', 'cristianismo', 'propósito', 'missão', 'vida']),
  ('bb04dbb3-7b47-5af3-a826-619295630898', 'Gentle and Lowly', 'Dane Ortlund', 'Espiritualidade', 'en', 'Ortlund examina como a Bíblia descreve o coração de Jesus, que se apresenta como manso e humilde, e como ele trata pecadores e sofredores. O livro é pastoral e acolhedor. Uma leitura de consolo e esperança.', 'Intermediário', array['jesus', 'graça', 'cristianismo', 'coração', 'consolo']),
  ('792fdeab-bb67-56f4-bb77-76a5c3918802', 'Surprised by Hope', 'N. T. Wright', 'Espiritualidade', 'en', 'Wright discute o que a Bíblia diz sobre ressurreição, vida depois da morte e esperança, e defende que a fé cristã tem a ver com a restauração do mundo. O livro é denso e provocativo. Uma obra importante de teologia.', 'Avançado', array['esperança', 'ressurreição', 'cristianismo', 'teologia', 'escatologia']),
  ('7474f6fa-72c9-5d56-9db6-263029e807a5', 'Simply Christian', 'N. T. Wright', 'Espiritualidade', 'en', 'Wright apresenta uma visão geral da fé cristã a partir de ideias como justiça, beleza, relacionamentos e espiritualidade. Ele fala a quem está curioso ou reavaliando a fé. Uma introdução em linguagem acessível.', 'Intermediário', array['cristianismo', 'fé', 'introdução', 'teologia', 'reflexão']),
  ('7a80458e-3f9a-542e-9640-5022488b32a0', 'The Prophet', 'Kahlil Gibran', 'Poesia', 'en', 'Almustafa, o profeta, passou doze anos na cidade de Orphalese e espera um navio que o levará para casa. Antes de partir, o povo lhe pede conselhos sobre o amor, o casamento, os filhos, o trabalho, a alegria, a dor e a morte. As respostas vêm em vinte e seis textos curtos, em prosa poética, que se leem em poucos minutos cada um.', 'Intermediário', array['poesia', 'sabedoria', 'amor', 'vida', 'clássico']),
  ('157bd586-3bae-5904-ad80-e7cdd25e5be4', 'The Art of Happiness', 'Dalai Lama and Howard C. Cutler', 'Espiritualidade', 'en', 'O Dalai Lama conversa com o psiquiatra Howard Cutler sobre como alcançar uma vida feliz por meio de compaixão, treino da mente e boas relações. O livro mistura budismo e psicologia ocidental. Uma leitura calma e prática.', 'Intermediário', array['felicidade', 'compaixão', 'budismo', 'psicologia', 'diálogo']),
  ('8ce4aa14-78c7-5945-9e2c-7aeab48ca4ea', 'The Book of Joy', 'Dalai Lama and Desmond Tutu', 'Espiritualidade', 'en', 'Dois grandes líderes espirituais conversam, durante uma semana, sobre como encontrar alegria mesmo em meio ao sofrimento. Eles contam histórias e riem juntos. Um livro caloroso sobre alegria, perdão e gratidão.', 'Intermediário', array['alegria', 'compaixão', 'sofrimento', 'diálogo', 'sabedoria']),
  ('2df16d1e-65ae-5b8b-9100-918eefdeebf4', 'Be Here Now', 'Ram Dass', 'Espiritualidade', 'en', 'Publicado em 1971, o livro combina relato pessoal, ilustrações e ensinamentos sobre meditação e a vida no presente. Ram Dass conta sua busca depois de deixar a carreira acadêmica. Um clássico da contracultura.', 'Intermediário', array['presente', 'espiritualidade', 'meditação', 'contracultura', 'clássico']),
  ('d2af3d78-e90b-538f-86ea-ad44eb1dc072', 'Wherever You Go, There You Are', 'Jon Kabat-Zinn', 'Espiritualidade', 'en', 'Kabat-Zinn apresenta a atenção plena como prática simples de estar presente e em paz com a vida como ela é. Os capítulos são curtos e trazem exercícios. Um guia clássico de mindfulness.', 'Intermediário', array['mindfulness', 'meditação', 'atenção plena', 'bem-estar', 'prática']),
  ('f4b4bfe4-15d7-5f60-946a-93ed469741f2', 'Autobiography of a Yogi', 'Paramahansa Yogananda', 'Biografia e Memórias', 'en', 'Yogananda conta sua vida e seus encontros com mestres espirituais na Índia, apresentando ideias sobre meditação e yoga. O livro foi lançado em 1946 e levou essas práticas a muitos leitores ocidentais. Uma autobiografia espiritual.', 'Intermediário', array['espiritualidade', 'yoga', 'índia', 'memórias', 'meditação']),
  ('dac2b2e2-b978-5032-b477-2a5a8fbf4843', 'Hamlet', 'William Shakespeare', 'Teatro', 'en', 'O príncipe Hamlet, da Dinamarca, recebe a visita do fantasma do pai, que conta ter sido envenenado pelo irmão, Cláudio, agora rei e casado com a viúva. Para ter certeza, Hamlet finge loucura e encena uma peça diante da corte. A dúvida entre agir e esperar custa a vida de Ofélia, Polônio e, num duelo final, de quase todos.', 'Avançado', array['shakespeare', 'tragédia', 'vingança', 'clássico', 'dinamarca']),
  ('d4099b96-ed59-5f8b-b03b-e97637d24de7', 'Macbeth', 'William Shakespeare', 'Teatro', 'en', 'Três bruxas dizem ao general escocês Macbeth que ele será rei, e a esposa, lady Macbeth, o empurra para assassinar o rei Duncan. Depois do crime, Macbeth manda matar também o amigo Banquo e passa a ver o fantasma dele. A culpa enlouquece o casal, e a profecia da floresta de Birnam se cumpre de um jeito que ele não esperava.', 'Avançado', array['shakespeare', 'tragédia', 'ambição', 'clássico', 'escócia']),
  ('1de18b3c-a31d-58b8-8cf3-8dc026024011', 'Romeo and Juliet', 'William Shakespeare', 'Teatro', 'en', 'Em Verona, as famílias Montéquio e Capuleto vivem em guerra, mas Romeu e Julieta se conhecem num baile de máscaras e se apaixonam. Frei Lourenço os casa em segredo, e uma briga de rua termina com a morte de Mercúcio e Teobaldo e o exílio de Romeu. Um plano para fingir a morte de Julieta dá errado, e os dois acabam mortos, o que enfim reconcilia as famílias.', 'Avançado', array['shakespeare', 'tragédia', 'amor', 'clássico', 'verona']),
  ('51ed7df0-21fd-5f47-9af0-6bf3374d07fc', 'Othello', 'William Shakespeare', 'Teatro', 'en', 'O general mouro Otelo, a serviço de Veneza, se casa em segredo com Desdêmona e é enviado a Chipre. Iago, ressentido por ter sido preterido na promoção, planta a suspeita de que a esposa o trai com o tenente Cássio, usando um lenço como falsa prova. O ciúme leva Otelo a cometer um crime que ele só entende tarde demais.', 'Avançado', array['shakespeare', 'tragédia', 'ciúme', 'manipulação', 'clássico']),
  ('4767989f-79f7-5664-8e0a-d6cff84593d6', 'King Lear', 'William Shakespeare', 'Teatro', 'en', 'O velho rei Lear decide dividir o reino entre as três filhas conforme o amor que declaram. Goneril e Regan o adulam; Cordélia, que não sabe bajular, é deserdada. Traído pelas duas, Lear vaga numa tempestade ao lado do Bobo, enquanto, numa história paralela, o conde de Gloucester é enganado pelo filho bastardo Edmund.', 'Avançado', array['shakespeare', 'tragédia', 'família', 'loucura', 'clássico']),
  ('d52ac548-6102-5af4-9ce8-b5f44cb80cd5', 'A Midsummer Night''s Dream', 'William Shakespeare', 'Teatro', 'en', 'Em Atenas, Hermia ama Lysander, mas o pai quer casá-la com Demetrius, e Helena, apaixonada por Demetrius, os segue pela floresta. Lá, o rei das fadas, Oberon, manda o duende Puck pingar uma poção do amor nos olhos errados, e tudo se embaralha. Enquanto isso, o tecelão Bottom ganha cabeça de burro e conquista a rainha Titânia.', 'Avançado', array['shakespeare', 'comédia', 'magia', 'amor', 'fadas']),
  ('d3ca23c4-5563-5da7-92e2-9f3cb946c0ab', 'The Tempest', 'William Shakespeare', 'Teatro', 'en', 'Próspero, antigo duque de Milão, vive numa ilha há doze anos com a filha Miranda, o espírito Ariel e o escravo Caliban. Ao saber que o irmão traidor passa de navio por ali, provoca uma tempestade e traz todos para a ilha. Entre feitiços, o amor de Miranda por Ferdinand e uma conspiração desajeitada, ele escolhe perdoar e abrir mão de sua magia.', 'Avançado', array['shakespeare', 'magia', 'ilha', 'perdão', 'clássico']),
  ('bafb5c0a-0a3c-5d9f-98e8-44b3afdca8b8', 'Much Ado About Nothing', 'William Shakespeare', 'Teatro', 'en', 'Em Messina, os soldados voltam da guerra, e Beatriz e Benedito, que vivem trocando farpas, são enganados pelos amigos, que os fazem acreditar que cada um ama o outro em segredo. Em paralelo, o vilão Dom João arma uma intriga que quase destrói o casamento de Cláudio e Hero. Os guardas atrapalhados do guarda-mor Dogberry ajudam a revelar a verdade.', 'Avançado', array['shakespeare', 'comédia', 'romance', 'humor', 'intrigas']),
  ('bcff6682-7534-5bbe-9e1a-ef873b220030', 'Twelfth Night', 'William Shakespeare', 'Teatro', 'en', 'Depois de um naufrágio, Viola chega à Ilíria e, achando que o irmão gêmeo Sebastian morreu, se disfarça de rapaz com o nome de Cesário e serve ao duque Orsino. Ela se apaixona por ele, que ama a condessa Olívia, que por sua vez se apaixona por Cesário. A chegada de Sebastian e uma carta falsa que faz do mordomo Malvólio um tolo completam a confusão.', 'Avançado', array['shakespeare', 'comédia', 'disfarce', 'amor', 'confusão']),
  ('2fba02a7-bf3e-5eca-9be6-80f7e6c3e799', 'Julius Caesar', 'William Shakespeare', 'Teatro', 'en', 'Em Roma, Brutus e Cássio temem que Júlio César queira virar rei e organizam uma conspiração para matá-lo nos Idos de Março. Depois do assassinato, Marco Antônio faz um discurso no funeral que vira o povo contra os conspiradores. A guerra civil termina em Filipos, e Brutus, mesmo vencido, é tratado como um homem de honra.', 'Avançado', array['shakespeare', 'tragédia', 'política', 'traição', 'roma']),
  ('48288173-a071-546c-b1b7-6c9d45b0be66', 'The Merchant of Venice', 'William Shakespeare', 'Teatro', 'en', 'Bassanio quer pedir a mão da rica Pórcia e consegue o dinheiro por meio do amigo Antônio, que toma emprestado do agiota Shylock com um contrato horrível: se não pagar a tempo, dará uma libra da própria carne. Quando os navios de Antônio se perdem, a dívida vai a julgamento, e Pórcia, disfarçada de advogado, decide o caso. A peça trata de justiça, misericórdia e preconceito.', 'Avançado', array['shakespeare', 'comédia', 'justiça', 'dívida', 'veneza']),
  ('5d30b764-e8f9-5de8-bd91-45555efb9b3d', 'As You Like It', 'William Shakespeare', 'Teatro', 'en', 'Banida pelo tio, o duque Frederick, Rosalinda foge para a Floresta de Arden com a prima Celia e o bobo Touchstone, disfarçada de rapaz. Lá reencontra Orlando, que a ama, e o testa sem se revelar. Entre canções, poemas pendurados nas árvores e casamentos finais, a peça traz o célebre discurso de que o mundo todo é um palco.', 'Avançado', array['shakespeare', 'comédia', 'amor', 'floresta', 'disfarce']),
  ('9a75290a-8d00-5ee0-8870-e6e254f4f310', 'Richard III', 'William Shakespeare', 'Teatro', 'en', 'Ricardo, duque de Gloucester, deformado e cheio de ambição, abre a peça dizendo que o inverno do descontentamento chegou. Com charme e crueldade ele elimina o irmão Clarence, casa com Anne e manda prender os dois sobrinhos na Torre de Londres para tomar a coroa. Seu reinado dura pouco: na batalha de Bosworth, o conde de Richmond o derrota.', 'Avançado', array['shakespeare', 'tragédia', 'poder', 'história', 'vilão']),
  ('0c2b6827-54bc-594c-bef6-cda4645c8615', 'Henry V', 'William Shakespeare', 'Teatro', 'en', 'O jovem rei Henrique V, antes conhecido pelas farras, reivindica o trono da França e leva o exército inglês a atravessar o Canal. Depois do cerco de Harfleur, as tropas cansadas e doentes enfrentam um exército muito maior em Azincourt. O discurso da irmandade de quem luta ao lado do rei é um dos mais famosos do teatro.', 'Avançado', array['shakespeare', 'história', 'guerra', 'liderança', 'inglaterra']),
  ('01038c54-bda8-52ea-9596-1bfa318a3154', 'The Taming of the Shrew', 'William Shakespeare', 'Teatro', 'en', 'Em Pádua, o pai de Catarina e Bianca só deixará casar a mais nova depois que a geniosa mais velha encontrar marido. Petruchio, em busca de fortuna, aceita o desafio e tenta dominar Catarina com comportamentos exagerados. A peça é encenada para o bêbado Christopher Sly, e o final, em que Catarina fala sobre obediência, é muito discutido hoje.', 'Avançado', array['shakespeare', 'comédia', 'casamento', 'gênero', 'disputa']),
  ('07157d66-c4d8-50a1-8d2e-88405b3fccf9', 'The Importance of Being Earnest', 'Oscar Wilde', 'Teatro', 'en', 'Jack Worthing e Algernon Moncrieff inventam identidades falsas para escapar de obrigações, mas ambos dizem se chamar Ernest quando se apaixonam por Gwendolen e Cecily, que só aceitam casar com um homem com esse nome. Entre confusões, uma bolsa de mão esquecida e a lady Bracknell, a peça ridiculariza as regras da boa sociedade com diálogos rápidos.', 'Intermediário', array['comédia', 'sátira', 'sociedade', 'humor', 'vitoriano']),
  ('81a61276-a179-5e61-b0b3-98333767cc86', 'An Ideal Husband', 'Oscar Wilde', 'Teatro', 'en', 'Sir Robert Chiltern é um político respeitado, casado com uma mulher que o admira como a um homem perfeito. A senhora Cheveley aparece com uma carta que prova que, no começo da carreira, ele vendeu um segredo de Estado, e o chantageia. Para sair do aperto, Robert recorre ao amigo irônico Lord Goring, e o casal precisa aprender a perdoar.', 'Intermediário', array['comédia', 'política', 'chantagem', 'casamento', 'vitoriano']),
  ('59548cc9-a8ec-5ae5-a9f4-7b5f4c144a48', 'Pygmalion', 'George Bernard Shaw', 'Teatro', 'en', 'O professor de fonética Henry Higgins aposta com o coronel Pickering que consegue passar uma vendedora de flores, Eliza Doolittle, por duquesa, só mudando a maneira dela de falar. Eliza treina por meses e brilha num baile da alta sociedade. Depois, ela exige ser tratada como pessoa, e não como experiência, numa peça que inspirou o musical My Fair Lady.', 'Intermediário', array['comédia', 'classes sociais', 'linguagem', 'sociedade', 'clássico']),
  ('9cbd1c12-3a58-5a88-9d13-eb7cadb6e60b', 'Saint Joan', 'George Bernard Shaw', 'Teatro', 'en', 'Shaw acompanha Joana d''Arc desde as visões que a levam a convencer o príncipe herdeiro a lhe dar um exército até o julgamento por heresia em Ruão, onde é condenada. A peça mostra tanto os soldados que a seguem quanto os bispos que a temem. Um epílogo passa-se em 1920, depois da canonização, e pergunta se o mundo estaria pronto para receber uma santa viva.', 'Avançado', array['história', 'julgamento', 'fé', 'joana d''arc', 'drama']),
  ('57f953ba-211f-541f-b8e8-66d88ec870f7', 'Death of a Salesman', 'Arthur Miller', 'Teatro', 'en', 'Willy Loman, um caixeiro-viajante envelhecido, se agarra a ilusões de sucesso enquanto perde o emprego e a conexão com os filhos. Memórias e realidade se misturam na peça. Um retrato duro do sonho americano.', 'Intermediário', array['drama', 'sonho americano', 'família', 'clássico', 'tragédia moderna']),
  ('b2e39298-9a1f-5a7c-9125-1db13d85bbb0', 'The Crucible', 'Arthur Miller', 'Teatro', 'en', 'Na Salem de 1692, acusações de bruxaria se espalham por medo e interesse pessoal, e John Proctor precisa decidir entre salvar a vida e manter a honra. A peça é uma alegoria do macarthismo. Um drama intenso sobre histeria coletiva.', 'Intermediário', array['drama', 'caça às bruxas', 'salem', 'histeria', 'alegoria']),
  ('c153b6b2-6a44-5155-b5f2-608f60f1a6ac', 'A View from the Bridge', 'Arthur Miller', 'Teatro', 'en', 'Eddie Carbone, estivador do Brooklyn, abriga dois primos imigrantes ilegais e se perturba com o interesse de um deles pela sobrinha que criou. O ciúme e a obsessão levam a uma tragédia. Um drama curto e forte sobre honra e desejo.', 'Intermediário', array['drama', 'família', 'imigração', 'brooklyn', 'tragédia']),
  ('5478e87a-f2e2-5ed7-8498-4bb743081001', 'A Streetcar Named Desire', 'Tennessee Williams', 'Teatro', 'en', 'Blanche DuBois chega a Nova Orleans para morar com a irmã Stella e entra em conflito com o cunhado, o brutal Stanley. A fragilidade de Blanche e suas ilusões se desfazem aos poucos. Um clássico do teatro americano.', 'Intermediário', array['drama', 'fragilidade', 'sul dos eua', 'família', 'clássico']),
  ('ce404aee-c0fb-5807-9e04-4c9f79599dfa', 'The Glass Menagerie', 'Tennessee Williams', 'Teatro', 'en', 'Tom narra lembranças da família: a mãe, Amanda, que vive de ilusões do passado, e a irmã tímida, Laura, que coleciona bichinhos de vidro. A visita de um colega mexe com todos. Uma peça de memória, delicada e melancólica.', 'Intermediário', array['drama', 'família', 'memória', 'sonhos', 'clássico']),
  ('7d3ef98f-9719-50cf-a6e8-5feb4aec36ee', 'Cat on a Hot Tin Roof', 'Tennessee Williams', 'Teatro', 'en', 'Numa fazenda do Sul, a família se reúne para o aniversário de Big Daddy, e Brick e Maggie lidam com mentiras e frustrações. Segredos e tensões vêm à tona em uma noite. Um drama familiar intenso.', 'Intermediário', array['drama', 'família', 'mentiras', 'sul dos eua', 'casamento']),
  ('254529a5-41c2-5fce-8ed5-769942bbf44c', 'Our Town', 'Thornton Wilder', 'Teatro', 'en', 'Um narrador conduz o público pela vida em Grover''s Corners, uma cidadezinha americana, em cenário quase vazio. A peça mostra amor, casamento e morte, destacando o valor das pequenas coisas. Um clássico simples e emocionante.', 'Intermediário', array['drama', 'vida cotidiana', 'pequena cidade', 'morte', 'clássico']),
  ('de136bdd-f558-5c79-a98c-b99c60cbad51', 'A Raisin in the Sun', 'Lorraine Hansberry', 'Teatro', 'en', 'A família negra Younger, em Chicago, discute o que fazer com um seguro de vida que pode mudar a situação deles. Cada um tem um sonho, e uma decisão põe tudo à prova. Um clássico sobre dignidade e esperança.', 'Intermediário', array['drama', 'família', 'sonhos', 'racismo', 'chicago']),
  ('ee09caa5-1294-5f21-8b05-aecc5b67b49f', 'Long Day''s Journey into Night', 'Eugene O''Neill', 'Teatro', 'en', 'Num único dia, a família Tyrone se enfrenta em acusações, lembranças e vícios, dentro de casa. A peça é um retrato duro, em parte autobiográfico, das feridas familiares. Um dos grandes dramas americanos.', 'Avançado', array['drama', 'família', 'vício', 'memória', 'tragédia']),
  ('4ea07be5-d4fc-5388-a544-430a614bee66', 'Who''s Afraid of Virginia Woolf?', 'Edward Albee', 'Teatro', 'en', 'Um casal de professores, George e Martha, recebe um jovem casal depois de uma festa, e a noite se transforma em jogos cruéis. Entre bebida e provocações, ilusões se desfazem. Um drama ácido sobre casamento e mentiras.', 'Avançado', array['drama', 'casamento', 'conflito', 'noite', 'sátira']),
  ('d7788608-4820-548a-8cab-f5203f123ef8', 'An Inspector Calls', 'J. B. Priestley', 'Teatro', 'en', 'Durante um jantar da família Birling, um inspetor aparece investigando a morte de uma jovem e mostra que cada um teve alguma culpa. A peça questiona a responsabilidade social. Um drama de mistério muito lido nas escolas britânicas.', 'Intermediário', array['drama', 'mistério', 'classes sociais', 'responsabilidade', 'inglaterra']),
  ('958cea66-8dd5-53f1-9a53-988554f2b24d', 'Look Back in Anger', 'John Osborne', 'Teatro', 'en', 'Jimmy Porter, um jovem inteligente e furioso, desconta a frustração na esposa, Alison, num apartamento apertado. A peça marcou o teatro inglês dos anos 1950 ao mostrar a raiva da classe trabalhadora. Um drama de forte tensão.', 'Avançado', array['drama', 'raiva', 'casamento', 'inglaterra', 'classes sociais']),
  ('c04543cc-aee0-5993-90c4-5f54efd75e82', 'The Homecoming', 'Harold Pinter', 'Teatro', 'en', 'Um homem volta a Londres com a esposa para visitar a família do pai, e as relações de poder entre todos se transformam de modo estranho. Os diálogos são cheios de pausas e ameaças. Uma peça marcante do teatro do absurdo britânico.', 'Avançado', array['drama', 'família', 'poder', 'silêncio', 'absurdo']),
  ('dc4e8a00-f80e-5032-90d9-81625d790a35', 'Rosencrantz and Guildenstern Are Dead', 'Tom Stoppard', 'Teatro', 'en', 'A peça acompanha dois personagens secundários de Hamlet, que não entendem o que está acontecendo ao redor deles. Os diálogos brincam com acaso, destino e linguagem. Uma comédia filosófica e inventiva.', 'Avançado', array['comédia', 'absurdo', 'hamlet', 'metateatro', 'humor']),
  ('9b06b188-876a-5087-b8ca-c90dab51d281', 'Arcadia', 'Tom Stoppard', 'Teatro', 'en', 'Numa casa de campo inglesa, duas épocas, 1809 e a atualidade, se alternam enquanto personagens tentam entender um mistério do passado. A peça mistura matemática, poesia e amor. Uma obra inteligente e comovente.', 'Avançado', array['comédia', 'ciência', 'tempo', 'mistério', 'inglaterra']),
  ('d53133af-bd8b-53d9-8f6e-3afbdeef586f', 'Doctor Faustus', 'Christopher Marlowe', 'Teatro', 'en', 'O estudioso Faustus vende a alma ao diabo em troca de conhecimento e poder por vinte e quatro anos. Com o tempo se esgotando, ele tenta escapar do pacto. Uma tragédia clássica sobre ambição e castigo.', 'Avançado', array['tragédia', 'pacto', 'conhecimento', 'clássico', 'renascimento']),
  ('cf1bbf0c-46fb-531b-9855-a7f22fcfcd43', 'Leaves of Grass', 'Walt Whitman', 'Poesia', 'en', 'Whitman reúne poemas que celebram o corpo, a natureza e a democracia, destacando o famoso Song of Myself. O verso livre e a voz direta marcaram a poesia americana. Uma obra que o autor reescreveu por toda a vida.', 'Avançado', array['poesia', 'américa', 'natureza', 'democracia', 'clássico']),
  ('06d821e8-86c5-5f30-ae3d-6041c791abc9', 'The Complete Poems of Emily Dickinson', 'Emily Dickinson', 'Poesia', 'en', 'Reúne quase todos os poemas de Dickinson, curtos, intensos e cheios de travessões, sobre morte, natureza, amor e fé. A maior parte foi publicada só depois de sua morte. Uma poesia inconfundível e inovadora.', 'Avançado', array['poesia', 'natureza', 'morte', 'clássico', 'mulheres']),
  ('7e6fac83-6f77-5870-9a5f-1fcde0e40b3d', 'The Waste Land', 'T. S. Eliot', 'Poesia', 'en', 'Publicado em 1922, o poema longo junta vozes, referências e imagens fragmentadas para retratar a desilusão depois da Primeira Guerra. É difícil, mas muito influente. Um marco da poesia modernista.', 'Avançado', array['poesia', 'modernismo', 'pós-guerra', 'fragmentos', 'clássico']),
  ('748acdb2-6d0b-5f93-84ab-19e83278a988', 'Paradise Lost', 'John Milton', 'Poesia', 'en', 'O poema épico de Milton, publicado em 1667, conta a rebelião de Satanás contra Deus e a queda de Adão e Eva. O Satanás da obra é carismático e complexo. Um clássico monumental da poesia inglesa.', 'Avançado', array['poesia épica', 'clássico', 'queda', 'séculos xvii', 'religião']),
  ('e1bd4034-0336-5ca2-b57c-9259f9fbe54d', 'The Canterbury Tales', 'Geoffrey Chaucer', 'Poesia', 'en', 'Peregrinos a caminho de Canterbury passam o tempo contando histórias, de cavaleiros a comerciantes, com humor e crítica social. A obra, do fim do século XIV, é escrita em inglês medieval. Um retrato vivo da sociedade da época.', 'Avançado', array['poesia', 'idade média', 'histórias', 'peregrinos', 'clássico']),
  ('f8ac5f78-3a02-5328-9e2b-dc7e8d83b3b5', 'Songs of Innocence and of Experience', 'William Blake', 'Poesia', 'en', 'Blake contrapõe poemas sobre a inocência da infância a outros sobre as dores da experiência e das injustiças. As ilustrações do próprio autor fazem parte da obra. Uma coletânea curta e muito influente.', 'Avançado', array['poesia', 'romantismo', 'infância', 'crítica social', 'clássico']),
  ('00b85e87-c35c-50d8-94fe-2cb5d31b36d2', 'Lyrical Ballads', 'William Wordsworth and Samuel Taylor Coleridge', 'Poesia', 'en', 'Publicado em 1798, o livro reúne poemas de Wordsworth e Coleridge que usam linguagem comum e falam de natureza e emoção, marcando o início do Romantismo inglês. Inclui o célebre poema do Velho Marinheiro. Uma obra fundadora.', 'Avançado', array['poesia', 'romantismo', 'natureza', 'clássico', 'século xviii']),
  ('29cf1c27-dcb5-5179-9de2-c7346c9f5e88', 'The Rime of the Ancient Mariner', 'Samuel Taylor Coleridge', 'Poesia', 'en', 'Um velho marinheiro conta a um convidado de casamento como matou um albatroz e passou a sofrer uma maldição em alto-mar. O poema narrativo mistura aventura e culpa. Um clássico sombrio e musical.', 'Avançado', array['poesia', 'romantismo', 'mar', 'maldição', 'clássico']),
  ('a37f884b-669b-55b8-95e4-389c2054d0a3', 'The Raven and Other Poems', 'Edgar Allan Poe', 'Poesia', 'en', 'A coletânea traz o poema O Corvo, em que um homem de luto recebe a visita de um corvo que repete uma palavra. A sonoridade e o clima sombrio são marcas de Poe. Uma leitura clássica da poesia gótica.', 'Avançado', array['poesia', 'gótico', 'morte', 'melancolia', 'clássico']),
  ('68d88cab-3d46-5a2c-83c4-ea5b63836643', 'Howl and Other Poems', 'Allen Ginsberg', 'Poesia', 'en', 'Publicado em 1956, o livro traz o poema Uivo, que denuncia a destruição de mentes de uma geração e abalou a sociedade da época. A obra provocou um célebre processo por obscenidade. Um marco da geração beat.', 'Avançado', array['poesia', 'geração beat', 'contracultura', 'polêmico', 'clássico']),
  ('f5409c30-afba-531e-9d2e-0d074d0b19de', 'Ariel', 'Sylvia Plath', 'Poesia', 'en', 'Reunido após a morte da autora, o livro traz poemas intensos e perturbadores sobre dor, raiva, maternidade e identidade. A voz é direta e de grande força imagética. Um marco da poesia confessional.', 'Avançado', array['poesia', 'confessional', 'mulheres', 'dor', 'clássico']),
  ('27761649-1c24-59ee-a17f-562ea204ac1f', 'Milk and Honey', 'Rupi Kaur', 'Poesia', 'en', 'Rupi Kaur reúne poemas curtos e desenhos sobre dor, amor, perda e cura. A linguagem é simples e direta, com versos minúsculos. Uma leitura rápida, muito popular entre jovens.', 'Iniciante', array['poesia', 'mulheres', 'amor', 'trauma', 'cura']),
  ('f46b9bc1-c24b-55c3-8fd5-e364ef7a58dc', 'The Sun and Her Flowers', 'Rupi Kaur', 'Poesia', 'en', 'Em poemas curtos organizados em capítulos, Kaur trata de perda, migração, amor-próprio e renovação. A linguagem é simples e acompanhada de ilustrações. Um livro de poesia acessível e emotivo.', 'Iniciante', array['poesia', 'mulheres', 'crescimento', 'migração', 'cura']),
  ('02414bad-8072-57c6-b991-de0673b72cc6', 'Devotions: The Selected Poems of Mary Oliver', 'Mary Oliver', 'Poesia', 'en', 'Reúne poemas escolhidos de Mary Oliver, em que ela observa a natureza com atenção e gratidão. A linguagem é clara e cheia de luz. Uma poesia que convida a desacelerar e prestar atenção.', 'Intermediário', array['poesia', 'natureza', 'gratidão', 'atenção', 'espiritualidade']),
  ('5e3bc0c1-4da9-5dbd-b2aa-3467d9d6d302', 'And Still I Rise', 'Maya Angelou', 'Poesia', 'en', 'Publicada em 1978, a coletânea inclui o poema que dá título ao livro, um hino de dignidade e superação diante da opressão. Os versos mesclam firmeza, ritmo e esperança. Uma poesia de força e orgulho.', 'Intermediário', array['poesia', 'resiliência', 'mulheres', 'racismo', 'esperança']),
  ('82e3b3ea-6236-555f-b7e7-4c7a03729989', 'Dom Casmurro', 'Machado de Assis', 'Ficção Clássica', 'pt', 'Bentinho conta sua vida e o amor por Capitu, de quem desconfia ter sido traído pelo melhor amigo. A dúvida nunca é resolvida, e o leitor decide em quem confiar. Um dos maiores romances da língua portuguesa.', null, array['realismo', 'ciúme', 'traição', 'narrador duvidoso', 'clássico'])
insert into public.livros (id, titulo, autor, genero, idioma, resumo, nivel_dificuldade, tags) values
  ('34d818fd-9a05-5239-ab21-5544f8d0275d', 'Memórias Póstumas de Brás Cubas', 'Machado de Assis', 'Ficção Clássica', 'pt', 'Brás Cubas, já morto, narra a própria vida com humor e ironia, sem poupar a si nem a sociedade carioca do século XIX. O livro quebra as regras do romance de sua época. Um marco do Realismo brasileiro.', null, array['realismo', 'ironia', 'sátira', 'morte', 'clássico']),
  ('860371bc-d7a4-5a20-90f2-61bf872bab13', 'Quincas Borba', 'Machado de Assis', 'Ficção Clássica', 'pt', 'Rubião herda a fortuna do filósofo Quincas Borba e se muda para o Rio de Janeiro, onde é explorado por falsos amigos. A doutrina do Humanitismo satiriza a ideia de que só os fortes sobrevivem. Uma crítica ácida à sociedade da época.', null, array['realismo', 'herança', 'loucura', 'sátira', 'clássico']),
  ('c79f85a9-112f-5a17-8d1a-3260e222176b', 'O Alienista', 'Machado de Assis', 'Contos', 'pt', 'O médico Simão Bacamarte cria um hospício em Itaguaí e passa a internar quem considera desequilibrado, até quase toda a cidade. A história ridiculariza o poder da ciência sem limites. Uma novela curta, irônica e muito atual.', null, array['sátira', 'loucura', 'ciência', 'novela', 'clássico']),
  ('b6808b8e-ebf5-5734-b081-439ebbc7270e', 'Helena', 'Machado de Assis', 'Ficção Clássica', 'pt', 'Helena chega a uma família de classe alta por causa de uma disposição do testamento do conselheiro Vale, e todos tentam entender quem ela é. O segredo sobre sua origem ameaça sua felicidade. Um romance do início da carreira de Machado.', null, array['romantismo', 'família', 'segredo', 'amor', 'clássico']),
  ('5dfca66d-7eea-57fe-95f3-1da67806e880', 'Iracema', 'José de Alencar', 'Ficção Clássica', 'pt', 'A indígena Iracema se apaixona pelo colonizador português Martim e abandona seu povo para viver com ele. A narrativa poética funda o mito sobre a origem do Ceará. Um clássico do Romantismo indianista.', null, array['romantismo', 'indianismo', 'amor', 'ceará', 'clássico']),
  ('d5397232-4186-57e5-8e6c-ea77e340bdcc', 'O Guarani', 'José de Alencar', 'Ficção Clássica', 'pt', 'O índio Peri protege a jovem Ceci e sua família numa fazenda no Rio de Janeiro do século XVII, enfrentando inimigos e perigos. A história idealiza a relação entre os povos. Um romance de aventura e amor impossível.', null, array['romantismo', 'indianismo', 'aventura', 'amor', 'clássico']),
  ('487d6840-332c-5c3f-af22-b750eec014cf', 'Senhora', 'José de Alencar', 'Ficção Clássica', 'pt', 'A jovem Aurélia, agora rica, compra um marido: o mesmo Fernando que a abandonou por dinheiro. O casamento por contrato vira um jogo de orgulho e humilhação. Um romance sobre dinheiro e amor no Rio do século XIX.', null, array['romantismo', 'casamento', 'dinheiro', 'sociedade', 'clássico']),
  ('a0f4723f-467a-51e6-871b-813e8c00ec74', 'Lucíola', 'José de Alencar', 'Ficção Clássica', 'pt', 'O jovem Paulo se apaixona por Lúcia, uma cortesã famosa do Rio de Janeiro, e descobre o passado doloroso que a levou àquela vida. O amor dela é um caminho de redenção e culpa. Um romance de crítica social.', null, array['romantismo', 'amor', 'sociedade', 'redenção', 'clássico']),
  ('3e238437-9c13-5159-8f83-170fb92cdb43', 'Memórias de um Sargento de Milícias', 'Manuel Antônio de Almeida', 'Ficção Clássica', 'pt', 'O romance acompanha o malandro Leonardo, filho de uma pisadela e um beliscão, em suas confusões na cidade do tempo do rei Dom João VI. A narrativa é leve e cheia de tipos populares. Um clássico da sátira de costumes.', null, array['humor', 'malandragem', 'rio de janeiro', 'sátira', 'clássico']),
  ('521e1708-8630-5f27-a007-9ca375b23081', 'O Cortiço', 'Aluísio Azevedo', 'Ficção Clássica', 'pt', 'Num cortiço do Rio de Janeiro, o português João Romão enriquece à custa da exploração dos moradores, enquanto o ambiente molda os personagens. O romance mostra a vida popular com realismo cru. Um marco do Naturalismo brasileiro.', null, array['naturalismo', 'cortiço', 'pobreza', 'rio de janeiro', 'clássico']),
  ('c39975e1-1a1a-507f-a392-ae7988b5ee8b', 'O Mulato', 'Aluísio Azevedo', 'Ficção Clássica', 'pt', 'Raimundo volta ao Maranhão, rico e formado, e se apaixona por Ana Rosa, mas o preconceito sobre sua origem o impede de ser aceito. A história expõe o racismo na sociedade da época. Um romance inaugural do Naturalismo no Brasil.', null, array['naturalismo', 'racismo', 'maranhão', 'amor', 'clássico']),
  ('820a7b12-9119-5657-bd45-45a3726b193b', 'O Ateneu', 'Raul Pompeia', 'Ficção Clássica', 'pt', 'Sérgio conta os anos de internato no Ateneu, colégio elitista do Rio de Janeiro, e descobre rivalidades, hipocrisia e decepções. O estilo é cheio de ironia e imagens. Um clássico sobre a vida escolar no século XIX.', null, array['memórias', 'escola', 'internato', 'crítica social', 'clássico']),
  ('1649c6a9-9144-5ed4-9b90-b6939b896c21', 'Triste Fim de Policarpo Quaresma', 'Lima Barreto', 'Ficção Clássica', 'pt', 'O major Policarpo Quaresma dedica a vida a defender ideias nacionalistas, como adotar o tupi como língua oficial, e se frustra com a realidade do país. A história critica o patriotismo ingênuo e a política da época. Um clássico do Pré-Modernismo.', null, array['pré-modernismo', 'patriotismo', 'sátira', 'política', 'clássico']),
  ('d7842feb-5ce1-59b4-ac5a-afff80d9118b', 'Clara dos Anjos', 'Lima Barreto', 'Ficção Clássica', 'pt', 'Clara, jovem negra do subúrbio carioca, é seduzida e abandonada por um rapaz de família branca que não se responsabiliza pelo erro. O romance retrata o preconceito de cor e de classe. Uma obra de denúncia social.', null, array['pré-modernismo', 'racismo', 'subúrbio', 'mulheres', 'clássico']),
  ('eff030b6-7a44-5fba-9aa5-242272681cfb', 'Os Sertões', 'Euclides da Cunha', 'História', 'pt', 'Euclides da Cunha narra a Guerra de Canudos, no sertão da Bahia, descrevendo a terra, o povo e o conflito com o exército. A obra mistura ciência, literatura e denúncia. Um clássico fundamental para entender o Brasil.', null, array['canudos', 'sertão', 'guerra', 'jornalismo', 'clássico']),
  ('41d0b6cb-4218-5fb0-a999-e0eaefab945f', 'Vidas Secas', 'Graciliano Ramos', 'Ficção Clássica', 'pt', 'Fabiano, Sinhá Vitória, os filhos e a cadela Baleia vagam pelo sertão fugindo da seca. A linguagem é seca como a paisagem, e a miséria limita até a fala. Um dos grandes romances do Modernismo brasileiro.', null, array['modernismo', 'sertão', 'seca', 'pobreza', 'clássico']),
  ('415f65aa-d0aa-5599-8837-f2a398e8a46c', 'São Bernardo', 'Graciliano Ramos', 'Ficção Clássica', 'pt', 'O fazendeiro Paulo Honório conta como conquistou a fazenda São Bernardo e como seu ciúme destruiu o casamento com Madalena. A narrativa é direta e áspera. Um romance sobre poder, posse e solidão.', null, array['modernismo', 'ciúme', 'fazendeiro', 'casamento', 'clássico']),
  ('459ca739-a62f-56bb-8abc-6a855835490b', 'Angústia', 'Graciliano Ramos', 'Ficção Clássica', 'pt', 'Luís da Silva, funcionário público em Maceió, mergulha em ciúme e obsessão ao ver a vizinha ser conquistada por um rival rico. A narrativa se mistura com delírios e lembranças. Um romance psicológico de grande intensidade.', null, array['modernismo', 'obsessão', 'psicológico', 'alagoas', 'clássico']),
  ('fb382539-c3a3-5721-bd76-d26b63fbb359', 'Memórias do Cárcere', 'Graciliano Ramos', 'Biografia e Memórias', 'pt', 'Graciliano relata os meses em que esteve preso sem acusação formal durante o governo Vargas, em 1936 e 1937. O livro mostra a vida na prisão e os companheiros que conheceu. Um testemunho literário forte sobre autoritarismo.', null, array['memórias', 'ditadura', 'prisão', 'modernismo', 'clássico']),
  ('a851bfa5-0a01-57af-a370-2e96f438899c', 'Infância', 'Graciliano Ramos', 'Biografia e Memórias', 'pt', 'Em capítulos curtos, Graciliano lembra a própria infância no interior do Nordeste, marcada por medo, castigos e solidão. A prosa é precisa e sem sentimentalismo. Um clássico das memórias brasileiras.', null, array['memórias', 'infância', 'sertão', 'violência', 'clássico']),
  ('1c8c69cb-a6a6-523a-9cda-d53dc8950a9b', 'O Quinze', 'Rachel de Queiroz', 'Ficção Clássica', 'pt', 'Em 1915, a grande seca no Ceará força a família do vaqueiro Chico Bento a migrar, enquanto a professora Conceição vive suas dúvidas sobre o amor. O romance retrata a miséria do sertão. Uma obra marcante do regionalismo de 1930.', null, array['modernismo', 'seca', 'ceará', 'mulheres', 'clássico']),
  ('0ebc9a71-978e-5861-9828-6df650bd75c6', 'Capitães da Areia', 'Jorge Amado', 'Ficção Clássica', 'pt', 'Um grupo de meninos abandonados vive de pequenos roubos nas ruas de Salvador, liderados por Pedro Bala. O livro mostra a infância sem proteção e os sonhos desses jovens. Um dos romances mais lidos do autor.', null, array['salvador', 'meninos de rua', 'modernismo', 'pobreza', 'clássico']),
  ('4d827f5d-47d2-5e1a-9889-331692a033e0', 'Gabriela, Cravo e Canela', 'Jorge Amado', 'Ficção Clássica', 'pt', 'Em Ilhéus, nos anos 1920, o árabe Nacib contrata a retirante Gabriela como cozinheira e se apaixona por ela. A cidade se transforma com o cacau e com novas ideias. Um romance sensual e cheio de humor baiano.', null, array['bahia', 'romance', 'costumes', 'ilhéus', 'clássico']),
  ('7172c6e5-4f43-54e8-9041-aaea7af651c8', 'Dona Flor e Seus Dois Maridos', 'Jorge Amado', 'Ficção Clássica', 'pt', 'Viúva do boêmio Vadinho, dona Flor se casa com o farmacêutico Teodoro, mas o fantasma do primeiro marido volta para reclamá-la. A história mistura humor, desejo e costumes baianos. Um clássico do realismo fantástico popular.', null, array['bahia', 'humor', 'romance', 'fantasma', 'clássico']),
  ('1efe83d2-b4bd-58ab-8204-8200f0a6a0b6', 'Terras do Sem Fim', 'Jorge Amado', 'Ficção Clássica', 'pt', 'Fazendeiros disputam, com violência, as terras do cacau no sul da Bahia. O romance acompanha a ambição e a morte de quem faz fortuna na região. Uma saga sobre poder e cobiça.', null, array['cacau', 'bahia', 'disputa', 'coronéis', 'clássico']),
  ('6585205a-9f42-578b-98f4-5118a43af9c4', 'O Tempo e o Vento', 'Érico Veríssimo', 'Ficção Clássica', 'pt', 'A saga acompanha as famílias Terra e Cambará por dois séculos no Rio Grande do Sul, de missões jesuíticas a Getúlio Vargas. A história pessoal se mistura com a história do Brasil. Uma das grandes sagas da literatura brasileira.', null, array['rio grande do sul', 'saga', 'história', 'família', 'clássico']),
  ('eb957a81-aca2-58a4-81de-6decf152f3de', 'Olhai os Lírios do Campo', 'Érico Veríssimo', 'Ficção Clássica', 'pt', 'Eugênio, um médico que se afastou das origens humildes por ambição, reencontra a antiga namorada Olívia e repensa suas escolhas. O romance questiona dinheiro, amor e consciência. Um dos livros mais populares do autor.', null, array['romance', 'sociedade', 'ambição', 'amor', 'clássico']),
  ('9e130619-b321-5a22-8b16-d581e82347ea', 'Grande Sertão: Veredas', 'João Guimarães Rosa', 'Ficção Clássica', 'pt', 'O ex-jagunço Riobaldo conta sua vida a um interlocutor, falando de lutas, pacto com o diabo e do amor por Diadorim. A linguagem inventiva mistura fala sertaneja e invenção. Uma obra-prima da literatura brasileira.', null, array['sertão', 'jagunços', 'amor', 'linguagem', 'clássico']),
  ('afbef0b0-a0fb-5dd1-a334-38d51eb5760c', 'Sagarana', 'João Guimarães Rosa', 'Contos', 'pt', 'Reúne contos passados no sertão de Minas Gerais, com vaqueiros, jagunços e até animais que pensam. A linguagem mistura oralidade e invenção poética. O livro de estreia de Guimarães Rosa.', null, array['sertão', 'contos', 'minas gerais', 'animais', 'clássico']),
  ('367e64f1-15d0-50ae-a806-3b1e892d4780', 'Primeiras Estórias', 'João Guimarães Rosa', 'Contos', 'pt', 'Vinte e um contos curtos mostram personagens simples diante de acontecimentos estranhos e comoventes, como a canoa que muda a vida de uma família. A linguagem é poética e criativa. Uma coletânea de grande beleza.', null, array['contos', 'sertão', 'poético', 'fantasia', 'clássico']),
  ('3f8bd99b-d3a4-599b-9ba1-922fe634f9ca', 'A Hora da Estrela', 'Clarice Lispector', 'Ficção Clássica', 'pt', 'O narrador Rodrigo conta a vida de Macabéa, uma datilógrafa nordestina pobre e ingênua no Rio de Janeiro. A história questiona quem tem direito a ser visto. O último livro publicado por Clarice em vida.', null, array['modernismo', 'nordeste', 'pobreza', 'mulheres', 'clássico']),
  ('56a15dc2-a40d-5bec-934b-a5acc6a316bd', 'A Paixão Segundo G.H.', 'Clarice Lispector', 'Ficção Clássica', 'pt', 'Uma mulher da alta sociedade esmaga uma barata no quarto da empregada e, a partir daí, enfrenta uma crise profunda de identidade. O romance é uma jornada interior. Uma das obras mais radicais de Clarice.', null, array['introspecção', 'filosofia', 'existencialismo', 'mulheres', 'clássico']),
  ('7a2ffbf0-8970-5057-ab56-432de8743539', 'Laços de Família', 'Clarice Lispector', 'Contos', 'pt', 'Treze contos mostram mulheres e famílias em momentos de pequenas rupturas, como uma viagem de bonde ou um jantar. Os fatos são simples, mas revelam crises interiores. Um dos livros de contos mais admirados do país.', null, array['contos', 'família', 'mulheres', 'introspecção', 'clássico']),
  ('2b664221-6002-56e2-bf63-a536be8c139c', 'Perto do Coração Selvagem', 'Clarice Lispector', 'Ficção Clássica', 'pt', 'O romance acompanha Joana, desde a infância, em busca de liberdade e de compreensão de si mesma, num fluxo de pensamentos e lembranças. Foi o livro de estreia de Clarice, aos vinte e poucos anos. Uma obra inovadora na literatura brasileira.', null, array['modernismo', 'introspecção', 'mulheres', 'estreia', 'clássico']),
  ('ef564cec-49d3-551c-9517-c50240864a68', 'Água Viva', 'Clarice Lispector', 'Ficção Clássica', 'pt', 'Sem enredo tradicional, o texto reúne reflexões de uma narradora que tenta captar o instante presente e a própria criação. A escrita é fragmentada e poética. Um livro experimental e íntimo.', null, array['introspecção', 'fluxo de consciência', 'arte', 'tempo', 'clássico']),
  ('e5d7fef5-d466-5f3a-8873-afab16a718d0', 'Macunaíma', 'Mário de Andrade', 'Ficção Clássica', 'pt', 'O herói Macunaíma, nascido índio e que se torna branco, vive aventuras mágicas entre a floresta e a cidade em busca de um amuleto. A obra mistura lendas de diversas regiões do país. Um marco do Modernismo brasileiro.', null, array['modernismo', 'folclore', 'herói sem nenhum caráter', 'brasil', 'clássico']),
  ('292206b0-d3aa-597f-a953-74384e717fb3', 'Pauliceia Desvairada', 'Mário de Andrade', 'Poesia', 'pt', 'Publicado em 1922, o livro reúne poemas sobre a cidade de São Paulo, com versos livres e imagens ousadas. O prefácio funciona como manifesto modernista. Uma obra importante do movimento.', null, array['modernismo', 'poesia', 'são paulo', 'semana de 22', 'clássico']),
  ('2d34db58-75e6-5ac9-b324-bc81888e5f73', 'Antologia Poética', 'Carlos Drummond de Andrade', 'Poesia', 'pt', 'Reúne poemas escolhidos de Drummond, de Sentimento do Mundo a A Rosa do Povo, com humor, melancolia e olhar atento ao cotidiano. O poeta mineiro fala de cidade, amor, política e tempo. Um dos maiores nomes da poesia brasileira.', null, array['poesia', 'modernismo', 'cotidiano', 'clássico', 'drummond']),
  ('e2b09b1f-55af-5535-aeb9-812a2eb0c602', 'Alguma Poesia', 'Carlos Drummond de Andrade', 'Poesia', 'pt', 'Livro de estreia de Drummond, de 1930, traz poemas curtos e irônicos, entre eles No meio do caminho. O poeta mistura humor, timidez e observação. Uma obra marcante da primeira geração modernista.', null, array['poesia', 'modernismo', 'estreia', 'minas gerais', 'clássico']),
  ('f0ec15c4-0f5b-57d0-a024-ed227b47e838', 'Sentimento do Mundo', 'Carlos Drummond de Andrade', 'Poesia', 'pt', 'Publicado em 1940, o livro mostra um poeta atento ao sofrimento do mundo, em tempos de guerra e de crise. Os versos unem lirismo, ironia e consciência social. Um dos livros fundamentais de Drummond.', null, array['poesia', 'modernismo', 'guerra', 'solidariedade', 'clássico']),
  ('5fbea85a-2d7d-5112-ac5b-61bb4a7a968e', 'Poesias Completas', 'Manuel Bandeira', 'Poesia', 'pt', 'Reúne a obra do poeta pernambucano, de versos simples sobre o cotidiano, o amor e a morte, como Pasárgada e Os Sapos. A linguagem é direta e cheia de ternura e ironia. Uma leitura essencial da poesia modernista.', null, array['poesia', 'modernismo', 'cotidiano', 'clássico', 'recife']),
  ('02667d3f-5ad9-5f69-b60b-ad72cd4b75da', 'Romanceiro da Inconfidência', 'Cecília Meireles', 'Poesia', 'pt', 'Poemas contam em forma de romanceiro a Inconfidência Mineira, de ouro, sonhos de liberdade e prisão de Tiradentes. A autora mistura voz popular e lirismo. Uma obra-prima da poesia brasileira.', null, array['poesia', 'inconfidência mineira', 'história', 'clássico', 'minas gerais']),
  ('1a28b909-2dfc-5a20-a945-3029801d02ab', 'Morte e Vida Severina', 'João Cabral de Melo Neto', 'Poesia', 'pt', 'Severino, retirante do sertão, caminha até o Recife encontrando sinais de morte pelo caminho, até presenciar um nascimento. O poema dramático tem versos curtos e ritmo popular. Um clássico da poesia e do teatro brasileiro.', null, array['poesia', 'nordeste', 'teatro', 'migração', 'clássico']),
  ('bd299d48-c3f6-5a8e-b764-4e822b651aed', 'O Auto da Compadecida', 'Ariano Suassuna', 'Teatro', 'pt', 'João Grilo e Chicó, dois amigos astutos do sertão, enganam gente poderosa e acabam diante do tribunal divino, onde a Compadecida intercede. A peça mistura cordel, humor e fé. Um dos textos teatrais mais queridos do país.', null, array['teatro', 'humor', 'nordeste', 'religião', 'clássico']),
  ('c0853de8-4db6-59f1-be5b-395d29c2b6ba', 'O Alquimista', 'Paulo Coelho', 'Ficção Clássica', 'pt', 'O pastor Santiago deixa a Espanha e atravessa o deserto em busca de um tesouro revelado em sonho, encontrando mestres e aprendizados pelo caminho. A fábula fala de seguir a própria lenda pessoal. Um dos livros brasileiros mais vendidos no mundo.', null, array['fábula', 'jornada', 'sonhos', 'espiritualidade', 'best-seller']),
  ('8b4a2383-e5a6-5a68-b657-255661d4841f', 'Diário de um Mago', 'Paulo Coelho', 'Biografia e Memórias', 'pt', 'Paulo Coelho relata sua peregrinação pelo Caminho de Santiago e os exercícios espirituais que aprendeu pelo percurso. O livro mistura aventura e busca interior. Foi seu primeiro livro publicado.', null, array['peregrinação', 'caminho de santiago', 'espiritualidade', 'autoconhecimento', 'aventura']),
  ('31c40198-70e0-505e-a38a-3f109f40e388', 'Veronika Decide Morrer', 'Paulo Coelho', 'Romance', 'pt', 'Veronika tenta se matar, sobrevive e acorda num hospital psiquiátrico, onde descobre que lhe resta pouco tempo de vida. Ali ela aprende a valorizar o presente. Um romance sobre normalidade e desejo de viver.', null, array['loucura', 'vida', 'suicídio', 'esperança', 'hospital psiquiátrico']),
  ('ae0d3d86-43ab-52ad-aa79-e729e20a00ba', 'Onze Minutos', 'Paulo Coelho', 'Romance', 'pt', 'A brasileira Maria vai para a Suíça sonhando com uma vida melhor e acaba na prostituição, onde busca entender amor e prazer. O livro acompanha sua trajetória interior. Um romance sobre desejo e liberdade.', null, array['amor', 'sexualidade', 'suíça', 'mulheres', 'descoberta']),
  ('5d54174c-e093-5aa8-b75d-8e8a56017714', 'Dois Irmãos', 'Milton Hatoum', 'Romance', 'pt', 'Numa família libanesa em Manaus, os gêmeos Yaqub e Omar crescem rivais, e a convivência com a mãe e a empregada Domingas marca a narrativa. O narrador reconstrói uma história de ciúme e perda. Um dos romances mais premiados da literatura recente.', null, array['manaus', 'família', 'irmãos', 'imigração', 'memória']),
  ('29ce44cb-4d18-5304-8a7d-00006eda188a', 'Relato de um Certo Oriente', 'Milton Hatoum', 'Romance', 'pt', 'Uma mulher volta a Manaus depois de anos fora e reconstrói a história da família libanesa em que cresceu. Vozes e lembranças se cruzam para recompor o passado. Um romance de estreia elogiado pela crítica.', null, array['manaus', 'família', 'imigração', 'memória', 'amazônia']),
  ('c40d2fe0-a30d-5233-b7ed-0574318fbacf', 'Budapeste', 'Chico Buarque', 'Romance', 'pt', 'Um ghost-writer brasileiro perde-se em Budapeste por acaso e se encanta pela língua húngara e por uma mulher que lhe ensina. Ao voltar ao Rio, a identidade dele se mistura com a de outro autor. Um romance sobre linguagem e identidade.', null, array['identidade', 'escrita', 'húngaro', 'rio de janeiro', 'linguagem']),
  ('f6d97d4c-ac2c-5063-9a49-b053fc61b22a', 'Leite Derramado', 'Chico Buarque', 'Romance', 'pt', 'Um homem muito velho, internado num hospital, relembra a vida e a decadência da família numa narrativa cheia de lapsos. A memória se mistura com delírios que escondem a verdade. Um romance sobre classe e esquecimento no Brasil.', null, array['memória', 'família', 'decadência', 'velhice', 'rio de janeiro']),
  ('4529506b-87d0-5ed4-b85c-980233e411ca', 'Torto Arado', 'Itamar Vieira Junior', 'Romance', 'pt', 'Duas irmãs crescem numa fazenda na Chapada Diamantina, e um acidente na infância muda a vida das duas. A história acompanha a luta pela terra e a força do povo negro do campo. Um romance premiado e muito lido.', null, array['bahia', 'irmãs', 'terra', 'racismo', 'trabalho rural']),
  ('443fea58-20d4-5b26-92af-7da145209ced', 'Ponciá Vicêncio', 'Conceição Evaristo', 'Romance', 'pt', 'Ponciá deixa o campo para tentar a vida na cidade e leva consigo as lembranças dos ancestrais e do trabalho nos campos. A narrativa mostra a dor e a resistência de mulheres negras. Um romance sensível e poético.', null, array['mulheres', 'racismo', 'memória', 'pobreza', 'negritude']),
  ('021fdd98-a3b4-5ee6-88c3-5d3e49545cc5', 'Olhos d''Água', 'Conceição Evaristo', 'Contos', 'pt', 'Os contos mostram mulheres negras que enfrentam violência, pobreza e perdas, mas também amor e afeto. A autora cria o conceito de escrevivência. Um livro de leitura curta e muito forte.', null, array['contos', 'mulheres', 'racismo', 'periferia', 'memória']),
  ('340fa40d-a93b-5e01-8406-89c29723f8d9', 'Quarto de Despejo', 'Carolina Maria de Jesus', 'Biografia e Memórias', 'pt', 'Moradora da favela do Canindé, em São Paulo, Carolina anota no diário a fome, a luta para criar os filhos e o preconceito. O livro foi um sucesso mundial nos anos 1960. Um testemunho direto sobre pobreza no Brasil.', null, array['diário', 'favela', 'fome', 'são paulo', 'mulheres']),
  ('786a1ee5-70ba-55bc-80e0-4e29395858e5', 'Ensaio sobre a Cegueira', 'José Saramago', 'Ficção Clássica', 'pt', 'Uma epidemia de cegueira branca atinge uma cidade, e os doentes são isolados num manicômio onde reinam violência e abuso. Só uma mulher continua enxergando. Uma parábola sobre egoísmo e solidariedade.', null, array['epidemia', 'cegueira', 'sociedade', 'distopia', 'nobel']),
  ('516d3b55-0c83-5dfb-b6b0-ba46b1afc096', 'O Evangelho Segundo Jesus Cristo', 'José Saramago', 'Ficção Clássica', 'pt', 'Saramago reconta a vida de Jesus como homem comum, dividido entre o destino que Deus lhe reserva e a liberdade. O livro provocou polêmica em Portugal. Um romance sobre fé, culpa e livre-arbítrio.', null, array['religião', 'jesus', 'polêmica', 'nobel', 'reescrita']),
  ('606edb5e-4922-5207-bd55-d343d0de2f8f', 'Memorial do Convento', 'José Saramago', 'Ficção Clássica', 'pt', 'Na construção do convento de Mafra, no século XVIII, Baltasar e Blimunda constroem uma máquina de voar com o padre Bartolomeu. O romance mistura história, fantasia e amor. Uma das obras principais do Nobel português.', null, array['portugal', 'história', 'amor', 'inquisição', 'nobel']),
  ('973fec7c-8b7d-5466-b7e8-b47ea82a5ca6', 'O Ano da Morte de Ricardo Reis', 'José Saramago', 'Ficção Clássica', 'pt', 'O heterônimo de Fernando Pessoa, Ricardo Reis, volta a Lisboa em 1936, ano de morte do poeta, e passeia por uma cidade sob ditadura. Entre conversas com o fantasma de Pessoa, ele pensa sobre liberdade e destino. Um romance de lirismo e política.', null, array['fernando pessoa', 'lisboa', 'heterônimo', 'história', 'nobel']),
  ('c9f8c74d-3072-53f4-b5fb-945fb9df3133', 'Todos os Nomes', 'José Saramago', 'Ficção Clássica', 'pt', 'Um funcionário de arquivo, o senhor José, fica obcecado em descobrir a vida de uma mulher desconhecida cujo registro ele encontra por acaso. A busca o leva a quebrar regras e mudar de vida. Uma fábula sobre solidão.', null, array['burocracia', 'solidão', 'busca', 'arquivo', 'nobel']),
  ('34d6be7b-abbc-5f06-a96d-a9ab3be3f06b', 'Os Maias', 'Eça de Queirós', 'Ficção Clássica', 'pt', 'A história de três gerações de uma família rica de Lisboa culmina no romance proibido de Carlos da Maia com Maria Eduarda. O livro retrata a sociedade portuguesa do século XIX. Um dos grandes romances da língua portuguesa.', null, array['portugal', 'realismo', 'família', 'amor', 'clássico']),
  ('b6b477e1-472e-5517-8d11-f68c0a454c97', 'O Primo Basílio', 'Eça de Queirós', 'Ficção Clássica', 'pt', 'Luísa, casada e entediada, se envolve com o primo Basílio quando o marido viaja, e uma criada descobre o caso e passa a chantageá-la. O romance critica a hipocrisia da burguesia lisboeta. Um clássico do Realismo.', null, array['portugal', 'adultério', 'realismo', 'sociedade', 'clássico']),
  ('c02b1f18-6c3d-5f8a-a130-bfdd9c49c38a', 'O Crime do Padre Amaro', 'Eça de Queirós', 'Ficção Clássica', 'pt', 'O jovem padre Amaro assume uma paróquia em Leiria e se envolve com Amélia, filha da hospedeira. O romance critica a hipocrisia do clero e da sociedade provinciana. Um livro que causou escândalo na época.', null, array['portugal', 'igreja', 'realismo', 'hipocrisia', 'clássico']),
  ('3f58a4ac-a53b-5217-b80e-ed518cd08fc6', 'A Relíquia', 'Eça de Queirós', 'Ficção Clássica', 'pt', 'Teodorico Raposo viaja a Jerusalém para trazer uma relíquia à tia beata e acaba com uma troca embaraçosa de presentes. A narrativa mistura humor e sátira à religiosidade de fachada. Um romance divertido e irônico.', null, array['portugal', 'humor', 'religião', 'sátira', 'clássico']),
  ('638fddfe-181e-51cc-9bee-366848b00614', 'Mensagem', 'Fernando Pessoa', 'Poesia', 'pt', 'Único livro de poemas em português que Pessoa publicou em vida, reúne versos sobre figuras e mitos da história de Portugal. A obra mistura glória e saudade. Um clássico da poesia lusófona.', null, array['portugal', 'poesia', 'história', 'mito', 'clássico']),
  ('0b05c50b-3ec3-51f6-96c7-537dfd506239', 'O Livro do Desassossego', 'Fernando Pessoa', 'Filosofia', 'pt', 'Pessoa atribui ao semi-heterônimo Bernardo Soares uma série de fragmentos sobre tédio, sonho e solidão numa Lisboa cotidiana. O livro foi organizado depois da morte do autor. Um texto marcante da literatura de introspecção.', null, array['diário', 'fragmentos', 'solidão', 'lisboa', 'introspecção']),
  ('262baa21-3855-528b-8373-cfee34e516c0', 'Os Lusíadas', 'Luís de Camões', 'Poesia', 'pt', 'O poema épico narra a viagem de Vasco da Gama às Índias e exalta a história de Portugal, misturando fatos e mitologia. Foi publicado em 1572. Uma das maiores obras da língua portuguesa.', null, array['épico', 'portugal', 'navegações', 'renascimento', 'clássico']),
  ('30ca0928-639d-5c72-86e7-3daf6b99e944', 'Terra Sonâmbula', 'Mia Couto', 'Romance', 'pt', 'Em meio à guerra civil em Moçambique, o velho Tuahir e o menino Muidinga vivem num ônibus queimado e leem cadernos de um morto. As histórias dos cadernos se misturam à realidade. Um romance poético da literatura africana de língua portuguesa.', null, array['moçambique', 'guerra', 'realismo fantástico', 'infância', 'áfrica']),
  ('620a1e3f-4228-5f61-8ff4-19d3f3636681', 'O Último Voo do Flamingo', 'Mia Couto', 'Romance', 'pt', 'Um investigador da ONU chega a uma vila moçambicana para descobrir por que soldados estão explodindo e desaparecendo. A linguagem mistura humor e magia. Um romance cheio de invenção.', null, array['moçambique', 'mistério', 'realismo fantástico', 'áfrica', 'humor']),
  ('4e9df78c-5721-5f48-93e8-4fcb2d2d9061', 'Mayombe', 'Pepetela', 'Romance', 'pt', 'Guerrilheiros do MPLA lutam por independência na floresta de Mayombe, em Angola, e enfrentam dilemas pessoais e tensões entre grupos. A narrativa é feita de vozes diferentes. Um clássico da literatura angolana.', null, array['angola', 'guerra', 'independência', 'floresta', 'áfrica']),
  ('33c63d11-a595-5bb2-9336-de63fa36cec7', 'O Vendedor de Passados', 'José Eduardo Agualusa', 'Romance', 'pt', 'Félix Ventura vende passados novos a clientes ricos, inventando genealogias e histórias. Um estrangeiro estranho pede uma identidade e traz problemas. Um romance divertido sobre memória e invenção.', null, array['angola', 'memória', 'identidade', 'humor', 'realismo fantástico']),
  ('dec52096-9ee3-5226-baa6-98292195ce2d', 'O Pequeno Príncipe', 'Antoine de Saint-Exupéry', 'Infantil', 'pt', 'Um piloto perdido no deserto conhece um pequeno príncipe vindo de um asteroide, que conta suas viagens por outros planetas. A amizade com uma raposa ensina o valor dos laços. Um clássico para crianças e adultos.', null, array['fábula', 'amizade', 'infância', 'filosofia', 'clássico']),
  ('18039157-c4d5-54e6-8b7b-86ed21e8af9d', 'Reinações de Narizinho', 'Monteiro Lobato', 'Infantil', 'pt', 'Narizinho, que mora no Sítio do Picapau Amarelo, vive aventuras com a boneca Emília, o Visconde de Sabugosa e outros personagens. A imaginação mistura folclore e fantasia. O livro inicia a série clássica de Monteiro Lobato.', null, array['sítio do picapau amarelo', 'fantasia', 'boneca', 'clássico', 'aventura']),
  ('79ff7515-691a-5841-b852-a02a793ec753', 'O Saci', 'Monteiro Lobato', 'Infantil', 'pt', 'Pedrinho e os amigos saem à caça do Saci-Pererê na mata, enfrentando o medo e conhecendo seres do folclore brasileiro. O livro apresenta lendas de forma divertida. Uma aventura do Sítio do Picapau Amarelo.', null, array['sítio do picapau amarelo', 'folclore', 'saci', 'floresta', 'aventura']),
  ('b7887c54-8bd3-576c-aae5-fda157ebc5f3', 'Caçadas de Pedrinho', 'Monteiro Lobato', 'Infantil', 'pt', 'Pedrinho decide caçar a onça que ronda o sítio, e a turma se une para enfrentar o bicho. A narrativa mistura humor e fantasia. Um clássico muito lido do Sítio do Picapau Amarelo.', null, array['sítio do picapau amarelo', 'aventura', 'animais', 'humor', 'clássico']),
  ('03dea587-7ae1-520e-a56a-0d76b61e06d9', 'O Menino Maluquinho', 'Ziraldo', 'Infantil', 'pt', 'Um menino travesso, cheio de ideias e com uma panela na cabeça, alegra a casa e a rua com suas brincadeiras. O livro retrata a infância com carinho. Um dos maiores sucessos da literatura infantil brasileira.', null, array['infância', 'humor', 'família', 'clássico', 'ilustrado']),
  ('6e2fc357-22fb-580f-8c5a-b4a8de6bedfe', 'Flicts', 'Ziraldo', 'Infantil', 'pt', 'Flicts é uma cor que não tem lugar no arco-íris nem em outras partes e procura seu espaço no mundo. A história fala de diferença e aceitação. Um clássico ilustrado de Ziraldo.', null, array['cores', 'identidade', 'solidão', 'clássico', 'ilustrado']),
  ('09aa4e60-9152-5111-bf56-974a26e4d5ba', 'Marcelo, Marmelo, Martelo', 'Ruth Rocha', 'Infantil', 'pt', 'Marcelo é um menino curioso que questiona os nomes das coisas e inventa os seus próprios. O livro reúne histórias leves sobre linguagem e imaginação. Um clássico de Ruth Rocha.', null, array['palavras', 'curiosidade', 'humor', 'infância', 'clássico']),
  ('0b1a1047-aaa9-5d52-85d5-ec68ee009db1', 'O Reizinho Mandão', 'Ruth Rocha', 'Infantil', 'pt', 'Um rei mandão proíbe os súditos de dizer a palavra "não" e acaba perdendo o controle do reino. A fábula mostra, de forma divertida, o abuso do poder. Um clássico da literatura infantil brasileira.', null, array['poder', 'humor', 'reis', 'fábula', 'clássico']),
  ('fa83b258-751c-5ccb-a7f3-010921056a50', 'Bisa Bia, Bisa Bel', 'Ana Maria Machado', 'Infantil', 'pt', 'Uma menina encontra num baú uma foto da bisavó e passa a conversar com a imagem dela, imaginando como era a vida da época. O livro compara gerações com delicadeza. Um clássico de Ana Maria Machado.', null, array['família', 'infância', 'gerações', 'memória', 'fantasia']),
  ('66934f13-2e40-5ec6-adc4-4518e3fd11b0', 'Menina Bonita do Laço de Fita', 'Ana Maria Machado', 'Infantil', 'pt', 'Um coelho branco quer ter a filha tão pretinha quanto a menina bonita e descobre que a cor está na história da família. O livro aborda diversidade de forma doce. Um clássico ilustrado.', null, array['diversidade', 'coelho', 'identidade', 'infância', 'ilustrado']),
  ('6cc79120-eb89-5c7f-a6fe-ea35846e4795', 'A Bolsa Amarela', 'Lygia Bojunga', 'Infantil', 'pt', 'Raquel esconde na bolsa amarela seus três grandes desejos: ser adulta, ser menino e ser escritora. O livro mistura fantasia e conflitos familiares com sensibilidade. Um clássico da literatura infantojuvenil.', null, array['imaginação', 'infância', 'desejos', 'fantasia', 'clássico']),
  ('84b46303-024e-5aae-b7ab-edbda8e92599', 'O Sítio do Picapau Amarelo — A Chave do Tamanho', 'Monteiro Lobato', 'Infantil', 'pt', 'Emília tenta acabar com a guerra e acaba diminuindo o tamanho de todas as pessoas do mundo, que ficam minúsculas. A turma enfrenta novos perigos num mundo diferente. Uma das aventuras mais criativas de Lobato.', null, array['fantasia', 'guerra', 'sítio do picapau amarelo', 'humor', 'aventura']),
  ('354b2a72-3cc6-5376-897d-d14d50eaace0', 'Os Meninos da Rua Paulo', 'Ferenc Molnár', 'Juvenil', 'pt', 'Em Budapeste, um grupo de meninos defende o terreno onde brincam contra uma gangue rival. O livro mostra coragem, amizade e sacrifício. Um clássico juvenil húngaro muito lido no Brasil.', null, array['amizade', 'coragem', 'budapeste', 'guerra', 'clássico']),
  ('e6e741d4-0515-5406-b739-6c3f36b93f66', 'A Droga da Obediência', 'Pedro Bandeira', 'Juvenil', 'pt', 'Um grupo de jovens, os Karas, descobre um plano para controlar adolescentes com uma droga que torna as pessoas obedientes. Eles se unem para investigar. Um clássico juvenil de mistério.', null, array['mistério', 'suspense', 'escola', 'aventura', 'juvenil']),
  ('f92b10b1-b273-5ee6-970f-82f0a2b100f6', 'O Diário de Anne Frank', 'Anne Frank', 'Biografia e Memórias', 'pt', 'Anne Frank anota no diário o tempo que passou escondida com a família num anexo secreto em Amsterdã, durante a ocupação nazista. O texto mostra medo, esperança e crescimento de uma adolescente. Um dos documentos mais lidos sobre o Holocausto.', null, array['segunda guerra', 'diário', 'holocausto', 'adolescência', 'esperança']),
  ('4399e341-810b-57aa-9a7b-1521c8fc386d', 'Marley e Eu', 'John Grogan', 'Biografia e Memórias', 'pt', 'O autor conta como a família cresceu com um labrador exagerado e bagunceiro, o Marley, que traz alegria e confusão a todos. O livro mistura humor e emoção. Uma história sobre amizade com um animal.', null, array['cachorro', 'família', 'humor', 'memórias', 'emoção']),
  ('f4cb001d-3b53-5c67-8d09-6988f1dad351', 'Sherlock Holmes — O Cão dos Baskervilles', 'Arthur Conan Doyle', 'Mistério e Suspense', 'pt', 'Sherlock Holmes e Watson investigam uma lenda sobre um cão sobrenatural que assombra a família Baskerville. A investigação revela uma trama de herança e crime. Um dos casos mais famosos do detetive.', null, array['sherlock holmes', 'mistério', 'inglaterra', 'clássico', 'detetive']),
  ('e292106f-4e17-5677-b8c7-d955e2c25936', 'A Revolução dos Bichos', 'George Orwell', 'Ficção Clássica', 'pt', 'Animais de uma fazenda expulsam o dono humano e criam um governo próprio, mas os porcos tomam o poder e traem os ideais. A fábula critica regimes autoritários. Um clássico curto e muito lido.', null, array['fábula política', 'totalitarismo', 'animais', 'sátira', 'clássico']),
  ('b977da7e-d049-5c7b-a055-ec47b9289e87', 'As Cobras', 'Luis Fernando Verissimo', 'Quadrinhos e Graphic Novels', 'pt', 'As cobras criadas por Verissimo comentam o cotidiano, os costumes e a política em tiras irônicas e filosóficas. Os personagens estão sempre se engolindo. Um clássico da charge brasileira.', null, array['quadrinhos', 'humor', 'cobras', 'tiras', 'ironia']),
  ('04896067-431b-50de-913a-385260fb51ab', 'Quase Memória', 'Carlos Heitor Cony', 'Biografia e Memórias', 'pt', 'O autor recebe um pacote misterioso e, a partir dele, revisita a história do pai, jornalista e boêmio, e sua própria infância. A narrativa mistura memória e invenção. Uma obra elogiada pela crítica.', null, array['memórias', 'pai', 'rio de janeiro', 'crônica', 'família']),
  ('c118921e-18bc-59d3-8f8e-cd56670837c9', 'Cem Anos de Solidão', 'Gabriel García Márquez', 'Ficção Clássica', 'pt', 'A saga da família Buendía, em Macondo, passa por sete gerações cheias de amores, guerras, magia e solidão. A narrativa mistura realidade e fantasia. Um dos maiores romances do século XX.', null, array['realismo mágico', 'macondo', 'família', 'américa latina', 'nobel']),
  ('2f1da63c-15d0-57e4-b428-93bc30ef91bc', 'O Amor nos Tempos do Cólera', 'Gabriel García Márquez', 'Romance', 'pt', 'Florentino espera mais de cinquenta anos para voltar a ficar com Fermina, que escolheu outro homem. A história mostra como o amor atravessa o tempo. Um romance intenso e melancólico.', null, array['amor', 'espera', 'colômbia', 'velhice', 'nobel']),
  ('22a0f1d6-5d67-5c1e-90fe-b29983a729d8', 'Crônica de uma Morte Anunciada', 'Gabriel García Márquez', 'Ficção Clássica', 'pt', 'Toda a cidade sabe que Santiago Nasar vai ser morto, mas ninguém consegue ou quer impedir. O narrador reconstrói o caso anos depois. Uma novela curta sobre honra e omissão.', null, array['crime', 'honra', 'colômbia', 'jornalismo', 'nobel']),
  ('2252cd59-bd07-5caf-9d49-60fddfa42db0', 'O Aleph', 'Jorge Luis Borges', 'Contos', 'pt', 'Os contos de Borges tratam de labirintos, tempo e infinito, com ideias que desafiam a lógica. O conto que dá título ao livro descreve um ponto onde se vê todo o universo. Um clássico da literatura fantástica.', null, array['argentina', 'fantasia', 'infinito', 'filosofia', 'contos']),
  ('7c8793ef-17b0-5c38-94cf-01dcf4238179', '1808', 'Laurentino Gomes', 'História', 'pt', 'O jornalista conta como a fuga da corte portuguesa para o Rio de Janeiro, em 1808, mudou o Brasil. A narrativa é leve e cheia de detalhes curiosos. Um best-seller de divulgação histórica.', null, array['brasil', 'corte portuguesa', 'história', 'napoleão', 'narrativa']),
  ('d79ddb05-0337-5204-8c5c-c2d7206713ff', '1822', 'Laurentino Gomes', 'História', 'pt', 'Laurentino Gomes reconta a Independência do Brasil, mostrando que o processo foi mais complexo e arriscado do que ensina o mito. O livro destaca personagens e conflitos regionais. Uma leitura envolvente para quem gosta de história.', null, array['brasil', 'independência', 'dom pedro', 'história', 'narrativa']),
  ('6fb41818-4cee-5a5c-874b-01db81d79fd9', '1889', 'Laurentino Gomes', 'História', 'pt', 'O autor relata os acontecimentos que levaram ao fim da monarquia e à Proclamação da República no Brasil. A obra mostra uma sociedade em transformação, entre a abolição e a crise do Império. Fecha a trilogia do autor.', null, array['brasil', 'república', 'monarquia', 'história', 'narrativa']),
  ('796a6c92-c21d-5a12-b715-b0275e99761f', 'Escravidão — Volume 1', 'Laurentino Gomes', 'História', 'pt', 'O primeiro volume mostra a origem do tráfico de africanos e como a escravidão moldou o Brasil. O autor combina pesquisa histórica e narrativa jornalística. Uma leitura importante sobre a formação do país.', null, array['escravidão', 'brasil', 'áfrica', 'história', 'racismo'])
insert into public.livros (id, titulo, autor, genero, idioma, resumo, nivel_dificuldade, tags) values
  ('aa8a437b-fe9f-5d60-afc6-08ef465f220e', 'Casa-Grande & Senzala', 'Gilberto Freyre', 'História', 'pt', 'Freyre analisa a formação da sociedade brasileira a partir da vida nos engenhos e da convivência entre senhores, escravizados e indígenas. A obra foi muito influente e é bastante debatida. Um clássico da sociologia brasileira.', null, array['brasil', 'sociedade', 'formação', 'sociologia', 'clássico']),
  ('d0faf001-cd8b-536b-8769-e68e10100c92', 'Raízes do Brasil', 'Sérgio Buarque de Holanda', 'História', 'pt', 'Sérgio Buarque analisa a formação do Brasil e apresenta a ideia do homem cordial. O livro discute herança ibérica, vida rural e política. Um dos ensaios mais importantes do pensamento brasileiro.', null, array['brasil', 'sociologia', 'formação', 'cordialidade', 'clássico']),
  ('a7f4fa58-0814-5694-ae98-bc40bb2240a4', 'O Povo Brasileiro', 'Darcy Ribeiro', 'História', 'pt', 'Darcy Ribeiro reconta a formação do povo brasileiro a partir do encontro de indígenas, portugueses e africanos. O texto é apaixonado e cheio de ideias fortes. Um ensaio clássico sobre identidade nacional.', null, array['brasil', 'antropologia', 'identidade', 'formação', 'ensaio']),
  ('5a873293-a465-50cc-98b2-0412c47ce5ab', 'Pedagogia do Oprimido', 'Paulo Freire', 'Filosofia', 'pt', 'Paulo Freire defende uma educação que dialogue com o aluno e o ajude a perceber e a transformar sua realidade. O livro critica a educação que só deposita conteúdo. Uma obra mundialmente influente.', null, array['educação', 'libertação', 'pedagogia', 'política', 'clássico']),
  ('eea13089-82fa-5e68-b36b-264058c8ee91', 'Pedagogia da Autonomia', 'Paulo Freire', 'Filosofia', 'pt', 'Freire reúne reflexões sobre o que significa ensinar e propõe um professor que respeita o saber do aluno e pratica a ética. O livro é curto e direto. Uma leitura essencial para quem atua em educação.', null, array['educação', 'ensino', 'ética', 'autonomia', 'professor']),
  ('52f02617-a6d8-57dd-b6d3-9e4eea003470', 'Por que Fazemos o que Fazemos?', 'Mario Sergio Cortella', 'Filosofia', 'pt', 'O filósofo reflete sobre trabalho, propósito e escolhas, usando exemplos do cotidiano. O texto é acessível e cheio de provocações. Um livro de divulgação filosófica.', null, array['trabalho', 'sentido', 'ética', 'reflexão', 'vida']),
  ('141087ab-2c42-50c1-97b1-e177f9b045f5', 'Não Nascemos Prontos', 'Mario Sergio Cortella', 'Desenvolvimento Pessoal', 'pt', 'Cortella reúne crônicas sobre aprendizado contínuo, convivência e vida profissional. Para ele, a vida é feita de construção constante. Um livro leve e inspirador.', null, array['educação', 'crescimento', 'vida', 'ética', 'reflexão']),
  ('dcf2d8b7-f65b-58f9-a192-88996e23f513', 'Pílulas de Sabedoria', 'Leandro Karnal', 'Filosofia', 'pt', 'O historiador reúne textos curtos sobre felicidade, relações, educação e ética, com humor e referências históricas. O estilo é de conversa. Uma leitura acessível sobre grandes questões.', null, array['reflexão', 'vida', 'história', 'ética', 'ensaios']),
  ('5792f897-ce8a-5d17-a688-108db8b08a15', 'O Dilema do Porco-Espinho', 'Leandro Karnal', 'Filosofia', 'pt', 'Karnal usa a metáfora do porco-espinho de Schopenhauer para falar de como lidamos com a solidão e a necessidade do outro. O livro mistura filosofia e experiência pessoal. Uma leitura leve sobre convivência.', null, array['solidão', 'relacionamentos', 'convivência', 'reflexão', 'filosofia']),
  ('ce9ac6dc-8e97-5e5e-9476-28edaa223c95', 'Sapiens: Uma Breve História da Humanidade', 'Yuval Noah Harari', 'História', 'pt', 'Harari conta a história da humanidade, da Revolução Cognitiva à era moderna, destacando mitos coletivos e mudanças como a agricultura. O livro mistura história, biologia e filosofia. Um best-seller mundial.', null, array['humanidade', 'evolução', 'história', 'antropologia', 'best-seller']),
  ('8e5b6c1c-89f5-5afd-b35a-c83c559572ca', 'Homo Deus', 'Yuval Noah Harari', 'História', 'pt', 'Harari imagina o futuro da humanidade diante de avanços em biotecnologia e inteligência artificial. O livro discute felicidade, imortalidade e poder. Uma continuação de Sapiens focada no amanhã.', null, array['futuro', 'tecnologia', 'humanidade', 'inteligência artificial', 'ensaio']),
  ('2d475784-ec0c-5732-a115-e6b232b2516e', 'Os Segredos da Mente Milionária', 'T. Harv Eker', 'Negócios e Finanças', 'pt', 'O autor defende que crenças inconscientes sobre dinheiro moldam a vida financeira e propõe mudar a mentalidade. O livro reúne princípios simples. Um clássico de finanças pessoais.', null, array['dinheiro', 'mentalidade', 'riqueza', 'hábitos', 'finanças']),
  ('65c61708-975f-5f08-95f4-5f969ef3adb8', 'Pai Rico, Pai Pobre', 'Robert Kiyosaki', 'Negócios e Finanças', 'pt', 'Kiyosaki compara o que aprendeu com o pai biológico e com o pai de um amigo sobre dinheiro e trabalho. O livro defende educação financeira e criação de ativos. Um best-seller sobre mentalidade financeira.', null, array['finanças', 'investimento', 'educação financeira', 'renda', 'best-seller']),
  ('6bd4b72a-aa0b-597c-a3be-7530ef2b47fa', 'O Homem Mais Rico da Babilônia', 'George S. Clason', 'Negócios e Finanças', 'pt', 'Em parábolas passadas na antiga Babilônia, o livro ensina princípios simples como poupar parte da renda e investir com cuidado. A linguagem é de fábula. Um clássico de educação financeira.', null, array['finanças', 'economia', 'babilônia', 'parábolas', 'clássico']),
  ('1c194ce6-db72-5cfe-a82d-68e6b5045de4', 'Mindset: A Nova Psicologia do Sucesso', 'Carol S. Dweck', 'Psicologia', 'pt', 'Dweck apresenta a ideia de mentalidade fixa e mentalidade de crescimento e mostra como elas afetam o desempenho. O livro usa exemplos de escola, trabalho e esporte. Uma obra influente em psicologia da motivação.', null, array['mentalidade', 'aprendizado', 'sucesso', 'crescimento', 'psicologia']),
  ('671829a8-5dd0-5af9-972a-ebf03ce98fe1', 'O Poder do Hábito', 'Charles Duhigg', 'Psicologia', 'pt', 'Duhigg explica como se formam os hábitos e como podemos mudá-los, com exemplos de pessoas e empresas. O livro apresenta o ciclo de deixa, rotina e recompensa. Uma leitura prática e fácil.', null, array['hábitos', 'mudança', 'comportamento', 'produtividade', 'ciência']),
  ('10f88c1b-d3a2-52a5-b340-49b114add83f', 'Hábitos Atômicos', 'James Clear', 'Desenvolvimento Pessoal', 'pt', 'James Clear mostra como pequenas mudanças diárias levam a grandes resultados e propõe métodos práticos para criar bons hábitos. A linguagem é direta e cheia de exemplos. Um dos livros de hábitos mais populares.', null, array['hábitos', 'mudança', 'produtividade', 'rotina', 'best-seller']),
  ('ac97c90c-4241-52f7-8015-cfae28508b76', 'Rápido e Devagar: Duas Formas de Pensar', 'Daniel Kahneman', 'Psicologia', 'pt', 'Kahneman descreve dois modos de pensar, um rápido e intuitivo, outro lento e analítico, e mostra como erramos em decisões. O autor ganhou o prêmio Nobel de Economia. Um clássico da psicologia do julgamento.', null, array['decisão', 'vieses', 'psicologia', 'economia comportamental', 'ciência']),
  ('ee6a9275-ab74-5127-a189-4e611e9db170', 'Como Fazer Amigos e Influenciar Pessoas', 'Dale Carnegie', 'Desenvolvimento Pessoal', 'pt', 'Carnegie reúne princípios simples para se relacionar melhor, como se interessar pelas pessoas e ouvir com atenção. O livro vendeu milhões de cópias desde 1936. Um clássico do desenvolvimento pessoal.', null, array['relacionamentos', 'comunicação', 'influência', 'clássico', 'carreira']),
  ('e4a0d932-c932-5194-b49a-d100d81c59f0', 'A Sutil Arte de Ligar o F*da-se', 'Mark Manson', 'Desenvolvimento Pessoal', 'pt', 'Manson defende que a felicidade depende de escolher bem com o que se importar e aceitar que a vida tem dificuldades. O tom é direto e bem-humorado. Um best-seller que critica a autoajuda tradicional.', null, array['prioridades', 'vida', 'autoajuda', 'humor', 'best-seller']),
  ('4a7cbbcb-a13a-58bd-98d6-30bdc6cfb7f1', 'O Poder do Agora', 'Eckhart Tolle', 'Espiritualidade', 'pt', 'Tolle defende que viver o momento presente é o caminho para a paz interior e para sair dos pensamentos que geram sofrimento. O livro mistura espiritualidade e prática. Um dos livros de consciência mais vendidos.', null, array['presença', 'mente', 'paz', 'consciência', 'meditação']),
  ('f64945b3-d0fb-5323-95d2-2759da902def', 'Mulheres que Correm com os Lobos', 'Clarissa Pinkola Estés', 'Psicologia', 'pt', 'A psicanalista analisa contos e mitos para apresentar a mulher selvagem e propor reflexões sobre intuição e criatividade. O livro mistura psicologia e narrativas. Uma obra muito lida sobre identidade feminina.', null, array['mulheres', 'mitos', 'psicologia', 'contos', 'feminino']),
  ('1213d0ee-c36d-5c76-aeb3-04d3200eae7c', 'Quem Mexeu no Meu Queijo?', 'Spencer Johnson', 'Desenvolvimento Pessoal', 'pt', 'Dois ratinhos e dois homenzinhos vivem num labirinto em busca de queijo e reagem de formas diferentes quando ele acaba. A fábula fala de mudança e adaptação. Um livro curto, popular em empresas.', null, array['mudança', 'fábula', 'carreira', 'adaptação', 'best-seller']),
  ('d28836fa-cd25-5a7d-8618-6140fc680689', 'O Monge e o Executivo', 'James C. Hunter', 'Negócios e Finanças', 'pt', 'Um executivo participa de um retiro num mosteiro, onde um ex-empresário que virou monge ensina sobre liderança baseada em servir. A história é contada como romance. Um clássico de liderança para iniciantes.', null, array['liderança', 'serviço', 'fábula', 'gestão', 'carreira']),
  ('d7f97751-4521-506a-bf15-48e80a543c15', 'Os 7 Hábitos das Pessoas Altamente Eficazes', 'Stephen R. Covey', 'Desenvolvimento Pessoal', 'pt', 'Covey apresenta sete princípios, como ser proativo e começar com o fim em mente, para melhorar a vida pessoal e profissional. A obra virou referência em liderança. Um clássico do desenvolvimento pessoal.', null, array['hábitos', 'eficácia', 'liderança', 'carreira', 'clássico']),
  ('ef273f79-c88f-522b-8153-7606be931ae5', 'Maus', 'Art Spiegelman', 'Quadrinhos e Graphic Novels', 'en', 'O autor desenha a história do pai, sobrevivente de Auschwitz, usando ratos para os judeus e gatos para os nazistas. Entre os relatos, mostra a difícil relação entre pai e filho. A obra recebeu um Pulitzer especial.', 'Intermediário', array['holocausto', 'memórias', 'pai e filho', 'graphic novel', 'pulitzer']),
  ('f35708ec-1e91-5d56-b488-7f0e096bf71d', 'Persepolis', 'Marjane Satrapi', 'Quadrinhos e Graphic Novels', 'en', 'Marjane conta sua infância e adolescência no Irã durante a Revolução Islâmica e a guerra com o Iraque, depois na Europa. Os desenhos são simples e em preto e branco. Uma memória em quadrinhos de grande sucesso.', 'Intermediário', array['irã', 'infância', 'revolução', 'memórias', 'mulheres']),
  ('1ae280e4-6542-598d-ad9e-b007e108f8d7', 'Watchmen', 'Alan Moore and Dave Gibbons', 'Quadrinhos e Graphic Novels', 'en', 'Um grupo de heróis aposentados investiga o assassinato de um deles e descobre uma conspiração em plena Guerra Fria. A obra desmonta o mito do super-herói. Um marco dos quadrinhos adultos.', 'Avançado', array['super-heróis', 'distopia', 'guerra fria', 'mistério', 'clássico']),
  ('f18a6c59-7368-5830-b0d6-291191a5f204', 'V for Vendetta', 'Alan Moore and David Lloyd', 'Quadrinhos e Graphic Novels', 'en', 'Num futuro autoritário na Inglaterra, o misterioso V usa uma máscara e planeja derrubar o governo com ataques simbólicos. A história questiona liberdade e controle. Um clássico distópico em quadrinhos.', 'Avançado', array['distopia', 'anarquia', 'resistência', 'inglaterra', 'clássico']),
  ('a6854b49-f0f8-5cfe-bfa4-39c33e69a545', 'The Sandman: Preludes and Nocturnes', 'Neil Gaiman', 'Quadrinhos e Graphic Novels', 'en', 'Morpheus, o Senhor dos Sonhos, escapa de décadas de cativeiro e tenta reconstruir seu reino. A série mistura mitologia e horror. O primeiro volume de uma das grandes séries de fantasia em quadrinhos.', 'Avançado', array['fantasia', 'sonhos', 'mitologia', 'terror', 'clássico']),
  ('12e2e673-42d2-585e-82b1-f2c138af1b5d', 'Fun Home', 'Alison Bechdel', 'Quadrinhos e Graphic Novels', 'en', 'Alison relembra a relação com o pai, que lidava com segredos e morreu cedo, e a própria descoberta da identidade. A narrativa mistura literatura e vida. Uma memória em quadrinhos premiada.', 'Avançado', array['memórias', 'família', 'identidade', 'literatura', 'graphic novel']),
  ('ea207ef5-f309-5d3c-96ff-5da8dae939f7', 'Calvin and Hobbes: The Essential', 'Bill Watterson', 'Quadrinhos e Graphic Novels', 'en', 'Calvin, um menino de seis anos com muita imaginação, vive aventuras com seu tigre de pelúcia Hobbes, que ganha vida só para ele. As tiras falam de infância, filosofia e escola com humor. Um clássico dos quadrinhos.', 'Iniciante', array['humor', 'infância', 'imaginação', 'tiras', 'clássico']),
  ('0cc4ab69-524d-52c6-9020-6a3ccba1ce65', 'The Far Side Gallery', 'Gary Larson', 'Quadrinhos e Graphic Novels', 'en', 'Reúne cartuns de painel único com humor absurdo e animais que agem como pessoas. As piadas são curtas e rápidas de ler. Uma coletânea clássica de humor.', 'Iniciante', array['humor', 'cartuns', 'animais', 'absurdo', 'clássico']),
  ('0709ec04-f253-56c7-a37c-9351c885630e', 'Peanuts: The Complete Collection', 'Charles M. Schulz', 'Quadrinhos e Graphic Novels', 'en', 'Charlie Brown, Snoopy e a turma enfrentam derrotas, alegrias e dúvidas do dia a dia nas tiras que Schulz publicou por cinquenta anos. O humor é doce e melancólico. Um clássico dos quadrinhos.', 'Iniciante', array['humor', 'infância', 'amizade', 'tiras', 'clássico']),
  ('45e04ea9-b66a-5334-b2e2-e593d6ba0894', 'Garfield at Large', 'Jim Davis', 'Quadrinhos e Graphic Novels', 'en', 'O gato preguiçoso Garfield adora lasanha, odeia segundas-feiras e atormenta o dono Jon e o cachorro Odie. As tiras são curtas e de linguagem simples. Uma leitura leve para treinar o inglês.', 'Iniciante', array['humor', 'gatos', 'tiras', 'comida', 'clássico']),
  ('5a7ca53d-17ec-5e59-977b-c123268a0722', 'Smile', 'Raina Telgemeier', 'Quadrinhos e Graphic Novels', 'en', 'Raina cai e machuca os dentes e passa por anos de tratamentos dentários enquanto lida com amizades e a adolescência. O livro mistura humor e emoção. Uma graphic novel popular entre jovens leitores.', 'Iniciante', array['infância', 'amizade', 'aparelho dental', 'escola', 'memórias']),
  ('e528c157-bb69-50c9-bc4e-c9b8e8ef0fa7', 'Dog Man', 'Dav Pilkey', 'Quadrinhos e Graphic Novels', 'en', 'Um policial e seu cão sofrem um acidente e são unidos numa cirurgia, formando o Dog Man, herói que combate o gato Petey. O livro é cheio de piadas bobas. Uma série de quadrinhos infantis muito popular.', 'Iniciante', array['humor', 'super-herói', 'cachorro', 'infantil', 'quadrinhos']),
  ('5539f903-dd5d-5b96-9fb4-6dc11e81aa4f', 'Amulet: The Stonekeeper', 'Kazu Kibuishi', 'Quadrinhos e Graphic Novels', 'en', 'Depois de uma tragédia, Emily e o irmão se mudam e acabam descobrindo um amuleto mágico que os leva a um mundo de demônios e robôs. Ela precisa salvar a mãe. Uma aventura de fantasia em quadrinhos.', 'Iniciante', array['fantasia', 'aventura', 'família', 'amuleto', 'juvenil']),
  ('a52f5009-6409-5073-9a2e-8c6904a8db9a', 'Bone: Out from Boneville', 'Jeff Smith', 'Quadrinhos e Graphic Novels', 'en', 'Os primos Bone são expulsos de sua cidade e chegam a um vale misterioso cheio de criaturas e perigos. A história mistura humor e fantasia épica. O primeiro volume de uma série premiada.', 'Iniciante', array['fantasia', 'aventura', 'humor', 'primos', 'quadrinhos']),
  ('04cd26d5-53a7-5b8b-8ddf-3aa02dcfadc5', 'American Born Chinese', 'Gene Luen Yang', 'Quadrinhos e Graphic Novels', 'en', 'Três histórias paralelas, um menino filho de imigrantes, o Rei Macaco e um adolescente popular, se entrelaçam sobre identidade e pertencimento. O livro mistura humor e mitologia chinesa. Uma graphic novel premiada.', 'Intermediário', array['identidade', 'imigração', 'escola', 'mitologia', 'graphic novel']),
  ('9933e620-00d5-5158-8713-0642113a41dc', 'March: Book One', 'John Lewis, Andrew Aydin and Nate Powell', 'Quadrinhos e Graphic Novels', 'en', 'O congressista John Lewis relembra sua infância no Alabama e os primeiros passos do movimento pelos direitos civis. Os desenhos em preto e branco dão força à narrativa. O primeiro volume de uma trilogia premiada.', 'Intermediário', array['direitos civis', 'memórias', 'história', 'estados unidos', 'graphic novel']),
  ('5c544fd3-91ef-55ac-baa1-3efeb00005f9', 'Ghost World', 'Daniel Clowes', 'Quadrinhos e Graphic Novels', 'en', 'Duas amigas recém-formadas passam o verão vagando pela cidade, criticando todos ao redor e enfrentando o fim da adolescência. O tom é irônico e melancólico. Uma graphic novel cultuada.', 'Avançado', array['adolescência', 'amizade', 'ironia', 'vida urbana', 'graphic novel']),
  ('d6aa4d69-e305-5e55-835b-90e60004f1ed', 'Carmilla', 'Joseph Sheridan Le Fanu', 'Terror', 'en', 'Laura, que vive isolada num castelo, faz amizade com a misteriosa Carmilla, e a saúde dela começa a piorar. A novela, de 1872, é anterior a Drácula. Um clássico do vampirismo gótico.', 'Avançado', array['vampiros', 'gótico', 'clássico', 'mistério', 'novela']),
  ('b6d19681-42d8-55d9-aeb5-f88c33f3a160', 'The Haunting of Hill House', 'Shirley Jackson', 'Terror', 'en', 'Quatro pessoas passam o verão numa casa conhecida por ser assombrada, para um estudo sobre o sobrenatural. A frágil Eleanor se prende cada vez mais ao lugar. Um clássico do terror psicológico.', 'Avançado', array['casa assombrada', 'psicológico', 'suspense', 'clássico', 'mulheres']),
  ('de8dd919-3660-50cf-9e65-33996e0a15eb', 'The Shining', 'Stephen King', 'Terror', 'en', 'Jack Torrance aceita ser zelador de um hotel isolado no inverno, e a presença do lugar e os poderes do filho Danny mudam tudo. A família fica à mercê da loucura. Um dos romances de terror mais famosos.', 'Intermediário', array['hotel', 'isolamento', 'terror', 'família', 'best-seller']),
  ('c76799ec-fa2b-5a4c-b608-df9a8d1b51c0', 'It', 'Stephen King', 'Terror', 'en', 'Um grupo de amigos de Derry enfrenta, na infância e de novo adultos, uma criatura que assume a forma de um palhaço. A obra alterna passado e presente. Um dos grandes romances de terror de King.', 'Intermediário', array['palhaço', 'infância', 'amizade', 'cidade pequena', 'best-seller']),
  ('ea2c85aa-ae5d-538b-9123-016d65305ffa', 'Pet Sematary', 'Stephen King', 'Terror', 'en', 'Louis Creed, depois de perder o gato da filha, enterra o animal num cemitério antigo e vê a vida ser perturbada por um desfecho assustador. O livro trata de luto e das escolhas diante da morte. Um romance sombrio de King.', 'Intermediário', array['luto', 'morte', 'família', 'sobrenatural', 'best-seller']),
  ('3e457815-e41b-5765-8424-253b937db578', 'Carrie', 'Stephen King', 'Terror', 'en', 'Carrie, adolescente tímida e criada por uma mãe religiosa, descobre poderes de telecinese e sofre humilhações na escola. Uma noite de baile muda tudo. O romance de estreia de Stephen King.', 'Intermediário', array['adolescência', 'telecinese', 'bullying', 'vingança', 'estreia']),
  ('211b715a-2cda-5191-8c1e-2892060fd1a8', 'Salem''s Lot', 'Stephen King', 'Terror', 'en', 'Um escritor volta à sua cidade natal no Maine e descobre que um vampiro está transformando os moradores. A cidade vai sendo dominada aos poucos. Um romance de terror clássico.', 'Intermediário', array['vampiros', 'cidade pequena', 'terror', 'best-seller', 'maine']),
  ('a07ea71f-ae09-5999-9641-4fe7aa51ff9d', 'Misery', 'Stephen King', 'Terror', 'en', 'O escritor Paul Sheldon sofre um acidente e é resgatado por Annie Wilkes, sua fã número um, que o mantém preso e o obriga a reescrever um livro. A obsessão dela vira pesadelo. Um thriller psicológico de King.', 'Intermediário', array['suspense', 'escritor', 'obsessão', 'psicológico', 'best-seller']),
  ('372debc8-6179-5c45-90af-8069290a6b74', 'Interview with the Vampire', 'Anne Rice', 'Terror', 'en', 'Um vampiro, Louis, conta a um repórter sua vida desde que foi transformado por Lestat, em Nova Orleans. A história trata de culpa, solidão e imortalidade. Um romance que deu nova vida ao gênero.', 'Avançado', array['vampiros', 'new orleans', 'imortalidade', 'gótico', 'best-seller']),
  ('babaca25-2d9f-5c38-b016-da1ba326ec3f', 'Frankenstein, or The Modern Prometheus', 'Mary Shelley', 'Terror', 'en', 'O cientista Victor Frankenstein cria um ser vivo e o abandona, o que desencadeia vingança e tragédia. O romance, de 1818, discute responsabilidade científica. Um clássico gótico e de ficção científica.', 'Avançado', array['ciência', 'criação', 'monstro', 'gótico', 'clássico']),
  ('135c47f1-58b1-5a94-80af-7c2d7822061f', 'The Turn of the Screw', 'Henry James', 'Terror', 'en', 'Numa noite de Natal, alguém lê o diário de uma jovem governanta contratada para cuidar de duas crianças, Miles e Flora, numa casa de campo chamada Bly. Ela começa a ver dois vultos, os fantasmas do antigo criado Peter Quint e da governanta Miss Jessel, e acredita que querem as crianças. Até o fim, o leitor não sabe se os espíritos existem ou se ela está enlouquecendo.', 'Avançado', array['governanta', 'fantasmas', 'ambiguidade', 'novela', 'clássico']),
  ('74c2c486-56a9-5e8a-9dea-fea4f8114592', 'We Have Always Lived in the Castle', 'Shirley Jackson', 'Terror', 'en', 'Merricat vive numa casa grande e isolada com a irmã e o tio depois de uma tragédia familiar, até a chegada de um primo mudar tudo. A narrativa é sutil e perturbadora. Um clássico do suspense psicológico.', 'Avançado', array['mistério', 'família', 'isolamento', 'psicológico', 'clássico']),
  ('f749b467-420a-594e-9a18-b2d377fbff85', 'Bird Box', 'Josh Malerman', 'Terror', 'en', 'Uma mulher precisa levar os filhos de olhos vendados por um rio, num mundo em que ver certas criaturas leva à loucura. O livro alterna passado e presente. Um terror de suspense contínuo.', 'Intermediário', array['apocalipse', 'suspense', 'maternidade', 'criaturas', 'best-seller']),
  ('3c098764-2b4b-5d9c-b68b-9cf1ee88e135', 'The Alchemist', 'Paulo Coelho', 'Ficção Clássica', 'en', 'O pastor Santiago deixa a Espanha e atravessa o deserto em busca de um tesouro revelado em sonho, encontrando mestres e aprendizados pelo caminho. A fábula fala de seguir a própria lenda pessoal. Um dos livros brasileiros mais vendidos no mundo, aqui na versão em inglês.', 'Iniciante', array['fábula', 'jornada', 'sonhos', 'espiritualidade', 'best-seller']),
  ('1ab1dc68-fe1d-5e39-964d-1c6bb340d6fa', 'Mindfulness in Plain English', 'Bhante Henepola Gunaratana', 'Espiritualidade', 'en', 'O monge explica de forma simples como praticar meditação de atenção plena e lidar com distrações e dúvidas. O texto combina orientação prática e ensinamentos budistas. Um guia clássico para iniciantes.', 'Intermediário', array['meditação', 'atenção plena', 'budismo', 'prática', 'paz']),
  ('a90d687b-17ff-5591-8c2f-65e7354d3eb0', 'Sapiens: A Brief History of Humankind', 'Yuval Noah Harari', 'História', 'en', 'O historiador Yuval Noah Harari propõe que o Homo sapiens dominou o planeta por saber criar histórias em comum, como religiões, dinheiro e países, que fazem milhões de desconhecidos cooperarem. O livro passa pelas revoluções Cognitiva, Agrícola e Científica. A edição em inglês tem frases claras, adequadas ao nível intermediário.', 'Intermediário', array['humanidade', 'evolução', 'história', 'antropologia', 'best-seller']),
  ('fb81378f-fbc4-59ca-a2a2-30bd84749298', 'Orgulho e Preconceito', 'Jane Austen', 'Ficção Clássica', 'pt', 'Elizabeth Bennet, inteligente e de opinião firme, enfrenta o orgulho do rico Darcy e os próprios preconceitos. A história satiriza casamentos arranjados e diferenças de classe. Um dos romances mais amados da literatura inglesa.', null, array['romance', 'sociedade', 'inglaterra', 'clássico', 'humor']),
  ('0f9a2d44-49c1-5b14-afbb-dad7f7464545', 'Razão e Sensibilidade', 'Jane Austen', 'Ficção Clássica', 'pt', 'As irmãs Elinor e Marianne Dashwood, uma racional e outra impulsiva, lidam com perdas e decepções amorosas depois de perderem a herança. A obra contrasta duas formas de sentir. Um romance de costumes elegante e irônico.', null, array['romance', 'irmãs', 'inglaterra', 'clássico', 'sociedade']),
  ('5a6546a5-bde5-58fa-93a7-eba88953bcce', 'Persuasão', 'Jane Austen', 'Ficção Clássica', 'pt', 'Anne Elliot, convencida a recusar um pedido de casamento anos atrás, reencontra o capitão Wentworth, agora rico e bem-sucedido. A história fala de arrependimento e segundas chances. O último romance concluído por Austen.', null, array['romance', 'segunda chance', 'inglaterra', 'clássico', 'maturidade']),
  ('a836eb24-0076-55f1-95c4-65765f267c9e', 'O Morro dos Ventos Uivantes', 'Emily Brontë', 'Ficção Clássica', 'pt', 'Heathcliff, acolhido por uma família nos pântanos da Inglaterra, vive uma paixão obsessiva por Catherine e busca vingança depois de perdê-la. A narrativa atravessa duas gerações. Um romance sombrio e intenso.', null, array['romance', 'vingança', 'gótico', 'paixão', 'clássico']),
  ('60750376-3c03-5142-825e-4b86441091f5', 'Grandes Esperanças', 'Charles Dickens', 'Ficção Clássica', 'pt', 'O órfão Pip recebe uma herança misteriosa e se muda para Londres para virar cavalheiro, deixando de lado quem o amava. Aos poucos, descobre a origem do dinheiro. Um romance sobre ambição e gratidão.', null, array['romance', 'ascensão social', 'inglaterra', 'clássico', 'orfandade']),
  ('bf1ec71c-6902-53ce-ba0b-e77e1d384ac3', 'Um Conto de Natal', 'Charles Dickens', 'Ficção Clássica', 'pt', 'O avarento Scrooge recebe na véspera de Natal a visita de três espíritos que o levam a repensar a própria vida. A história fala de generosidade e redenção. Uma novela curta e muito querida.', null, array['natal', 'fantasmas', 'redenção', 'novela', 'clássico']),
  ('315024b5-80ab-5df4-9eca-73236afa8d94', 'Crime e Castigo', 'Fiódor Dostoiévski', 'Ficção Clássica', 'pt', 'O estudante Raskólnikov mata uma velha agiota e passa a ser consumido por culpa e medo de ser descoberto. O romance explora moral, pobreza e redenção. Uma obra-prima da literatura russa.', null, array['culpa', 'rússia', 'psicológico', 'clássico', 'filosofia']),
  ('fb9eb1e1-4b47-5188-93a8-2e41c9e00618', 'Os Irmãos Karamázov', 'Fiódor Dostoiévski', 'Ficção Clássica', 'pt', 'Três irmãos muito diferentes e seu pai violento se envolvem numa disputa que termina em assassinato. O livro discute fé, livre-arbítrio e culpa. O último e mais ambicioso romance de Dostoiévski.', null, array['rússia', 'família', 'fé', 'filosofia', 'clássico']),
  ('fa2351aa-b19b-5f87-a6d2-098b01ec329b', 'Guerra e Paz', 'Liev Tolstói', 'Ficção Clássica', 'pt', 'O romance acompanha famílias da aristocracia russa durante as guerras napoleônicas, entre bailes, batalhas e dilemas pessoais. A obra une história e vida íntima. Um monumento da literatura mundial.', null, array['rússia', 'napoleão', 'história', 'família', 'clássico']),
  ('3d0412e3-0c81-5b5a-951b-0dfc5493ca12', 'Anna Kariênina', 'Liev Tolstói', 'Ficção Clássica', 'pt', 'Anna, mulher da alta sociedade russa, abandona o casamento por um amor proibido e enfrenta o julgamento social. Em paralelo, o romance mostra a busca de Liévin por sentido. Um clássico sobre paixão e sociedade.', null, array['rússia', 'adultério', 'sociedade', 'clássico', 'romance']),
  ('cde27416-fd3b-596c-9e82-80d43a28eda8', 'Os Miseráveis', 'Victor Hugo', 'Ficção Clássica', 'pt', 'Jean Valjean, ex-presidiário, tenta recomeçar a vida enquanto o inspetor Javert o persegue na França do século XIX. O romance passa por pobreza, revolução e amor. Uma epopeia sobre justiça e redenção.', null, array['frança', 'justiça', 'redenção', 'história', 'clássico']),
  ('1ce1aeb1-de37-5d65-875b-6d3066e5cb1e', 'O Corcunda de Notre-Dame', 'Victor Hugo', 'Ficção Clássica', 'pt', 'Na Paris medieval, o sineiro deformado Quasímodo se apaixona por Esmeralda, uma cigana perseguida por um clérigo obcecado. A catedral é cenário e personagem. Um clássico romântico e trágico.', null, array['frança', 'paris', 'catedral', 'amor', 'clássico']),
  ('f804e8c0-8bee-515e-ba2c-ce7c6b6e4f17', 'O Conde de Monte Cristo', 'Alexandre Dumas', 'Aventura', 'pt', 'Edmond Dantès é preso injustamente, foge e volta rico para punir os que o traíram. A história une aventura, mistério e justiça. Um dos grandes romances de aventura.', null, array['frança', 'vingança', 'aventura', 'prisão', 'clássico']),
  ('d2f22420-3f18-5c6f-86c5-b8d1f7161e04', 'Os Três Mosqueteiros', 'Alexandre Dumas', 'Aventura', 'pt', 'O jovem D''Artagnan chega a Paris para ser mosqueteiro, faz amizade com Athos, Porthos e Aramis e se envolve em intrigas da corte. O lema deles é um por todos, todos por um. Um clássico da aventura.', null, array['frança', 'espadachins', 'aventura', 'amizade', 'clássico']),
  ('9d72f3bc-4ea7-55df-936e-fb930ac6f339', 'Madame Bovary', 'Gustave Flaubert', 'Ficção Clássica', 'pt', 'Emma Bovary, entediada com a vida de esposa de um médico do interior, busca emoção em casos amorosos e em gastos, e acaba endividada. O romance retrata a ilusão romântica. Um marco do Realismo.', null, array['frança', 'realismo', 'casamento', 'tédio', 'clássico']),
  ('2db36170-99fb-50a5-bf1f-45c5a6e601b7', 'O Vermelho e o Negro', 'Stendhal', 'Ficção Clássica', 'pt', 'Julien Sorel, filho de um carpinteiro, usa inteligência e charme para subir na sociedade francesa, entre a Igreja e a aristocracia. Seus amores e ambições o levam à ruína. Um clássico do romance francês.', null, array['frança', 'ambição', 'sociedade', 'clássico', 'romance']),
  ('8148a358-ead6-52c3-8c5e-047e3ff92ec8', 'O Estrangeiro', 'Albert Camus', 'Ficção Clássica', 'pt', 'Meursault, um homem indiferente, mata um árabe numa praia da Argélia e é julgado mais por sua falta de emoção do que pelo crime. O livro expressa a filosofia do absurdo. Um clássico curto e marcante.', null, array['existencialismo', 'absurdo', 'argélia', 'clássico', 'nobel']),
  ('65e03565-59d6-50de-9ef3-163f6f423a31', 'A Peste', 'Albert Camus', 'Ficção Clássica', 'pt', 'Uma epidemia de peste isola a cidade de Orã, e o médico Rieux e outros personagens lutam contra a doença e o desespero. O romance fala de solidariedade e do sentido diante do sofrimento. Uma obra relevante em tempos de crise.', null, array['epidemia', 'solidariedade', 'argélia', 'existencialismo', 'nobel']),
  ('b93cfd65-633b-503f-a29e-e4439ca7177b', 'A Metamorfose', 'Franz Kafka', 'Ficção Clássica', 'pt', 'Gregor Samsa acorda transformado em um inseto gigante e vê sua família passar do espanto à rejeição. A novela é um retrato de alienação e dever. Um clássico curto da literatura do século XX.', null, array['absurdo', 'família', 'alienação', 'novela', 'clássico']),
  ('af3cdc6f-9743-541e-b394-1f951f1ff90d', 'O Processo', 'Franz Kafka', 'Ficção Clássica', 'pt', 'Josef K é preso uma manhã sem saber o motivo e enfrenta um tribunal misterioso e inalcançável. O romance expressa angústia diante de sistemas incompreensíveis. Uma obra marcante do absurdo.', null, array['burocracia', 'culpa', 'absurdo', 'justiça', 'clássico']),
  ('6264df36-2978-5a29-b96d-7c3dcca61114', 'Admirável Mundo Novo', 'Aldous Huxley', 'Ficção Científica', 'pt', 'Num futuro em que as pessoas são geneticamente planejadas e mantidas felizes por drogas e prazer, Bernard e John questionam o sistema. O livro critica o conforto como forma de controle. Um clássico da distopia.', null, array['distopia', 'controle', 'tecnologia', 'sociedade', 'clássico']),
  ('cd4534c4-7bcd-5f7d-a737-c052b7930ba0', 'O Senhor dos Anéis: A Sociedade do Anel', 'J. R. R. Tolkien', 'Fantasia', 'pt', 'O hobbit Frodo recebe um anel perigoso e parte numa jornada com uma sociedade de amigos para destruí-lo no fogo onde foi forjado. O mundo da Terra-média é cheio de povos e línguas. O primeiro volume da trilogia.', null, array['terra média', 'aventura', 'anel', 'épico', 'clássico']),
  ('cb9e1903-a887-5b4d-b606-fc2eb1a44ac2', 'Harry Potter e a Pedra Filosofal', 'J. K. Rowling', 'Fantasia', 'pt', 'Harry descobre aos onze anos que é bruxo e vai estudar em Hogwarts, onde faz amigos e enfrenta o vilão que matou seus pais. O livro iniciou a série mais popular do mundo. Uma aventura de fantasia e amizade.', null, array['magia', 'hogwarts', 'juvenil', 'amizade', 'best-seller']),
  ('2f54c807-37be-509f-a3e3-92928c28af67', 'Percy Jackson e o Ladrão de Raios', 'Rick Riordan', 'Fantasia', 'pt', 'Percy descobre que é filho de um deus grego e é acusado de roubar o raio de Zeus, então parte numa viagem pelos Estados Unidos para provar a inocência. A história mistura humor e mitologia. Um sucesso juvenil.', null, array['mitologia grega', 'aventura', 'juvenil', 'semideuses', 'humor']),
  ('77039577-625e-5eba-bf9f-fe714eb25257', 'Jogos Vorazes', 'Suzanne Collins', 'Ficção Científica', 'pt', 'Katniss se oferece no lugar da irmã para participar dos Jogos Vorazes, um torneio televisionado em que jovens lutam até a morte. A história critica o poder e o espetáculo. O primeiro livro de uma trilogia de grande sucesso.', null, array['distopia', 'sobrevivência', 'juvenil', 'rebelião', 'best-seller']),
  ('4e38e732-b1b5-5f25-a8e7-ccd6aa5b2c2d', 'A Culpa é das Estrelas', 'John Green', 'Juvenil', 'pt', 'Hazel e Gus, adolescentes que se conhecem num grupo de apoio para pacientes de câncer, vivem uma história de amor cheia de humor e dor. Juntos, refletem sobre sentido e despedida. Um romance juvenil emocionante.', null, array['amor', 'doença', 'adolescência', 'emoção', 'best-seller']),
  ('a5f885aa-07a7-5877-97c2-7a0252c6a25b', 'O Código Da Vinci', 'Dan Brown', 'Mistério e Suspense', 'pt', 'O simbologista Robert Langdon investiga um assassinato no Louvre e segue pistas escondidas em obras de arte. A trama envolve segredos da Igreja. Um thriller de ritmo acelerado.', null, array['thriller', 'paris', 'códigos', 'religião', 'best-seller']),
  ('171c9d3c-e1ca-536f-8391-449763016662', 'O Perfume', 'Patrick Süskind', 'Ficção Clássica', 'pt', 'Jean-Baptiste Grenouille tem um olfato extraordinário e nenhum cheiro próprio, e comete crimes para criar o perfume perfeito. O romance tem clima sombrio e sensorial. Um sucesso mundial.', null, array['frança', 'obsessão', 'olfato', 'crime', 'século xviii']),
  ('b02c62be-8617-5591-8ea2-4a530f67ad65', 'O Nome da Rosa', 'Umberto Eco', 'Mistério e Suspense', 'pt', 'Em 1327, o frade Guilherme de Baskerville investiga mortes num mosteiro italiano onde há uma biblioteca labiríntica. O romance mistura mistério, filosofia e história medieval. Um clássico moderno.', null, array['idade média', 'mosteiro', 'mistério', 'religião', 'clássico']),
  ('e0236680-3e27-5cfc-833f-e84774a76ef6', 'O Velho e o Mar', 'Ernest Hemingway', 'Ficção Clássica', 'pt', 'Santiago, velho pescador cubano, passa oitenta e quatro dias sem pescar nada e fisga um marlim enorme no octogésimo quinto. A luta dura dias em alto-mar. Uma novela curta sobre coragem e dignidade.', null, array['pesca', 'perseverança', 'cuba', 'novela', 'nobel']),
  ('54802e8e-8f8b-5312-8c81-cbb14883e6eb', 'O Apanhador no Campo de Centeio', 'J. D. Salinger', 'Ficção Clássica', 'pt', 'Holden Caulfield, expulso da escola, vaga por Nova York contando seus dias com sarcasmo e angústia. A voz do narrador marcou gerações. Um clássico sobre a passagem para a vida adulta.', null, array['adolescência', 'alienação', 'nova york', 'clássico', 'narrador']),
  ('75e84d38-ac31-571d-857d-5e27cf078dff', 'O Sol é para Todos', 'Harper Lee', 'Ficção Clássica', 'pt', 'Scout Finch narra a infância numa cidade do Alabama, onde seu pai, o advogado Atticus, defende um homem negro injustamente acusado. O livro trata de justiça e preconceito. Um clássico premiado com o Pulitzer.', null, array['racismo', 'justiça', 'infância', 'sul dos eua', 'clássico']),
  ('c7043315-d415-52eb-a87e-099323667e43', 'O Grande Gatsby', 'F. Scott Fitzgerald', 'Ficção Clássica', 'pt', 'Nick Carraway conta como conheceu o misterioso milionário Gatsby, que dá festas extravagantes na esperança de reconquistar o antigo amor, Daisy. A história critica o sonho americano. Um clássico curto e elegante.', null, array['anos 1920', 'sonho americano', 'amor', 'riqueza', 'clássico']),
  ('5a45e933-c7a3-5222-be9a-c54d15c6d03d', 'As Vinhas da Ira', 'John Steinbeck', 'Ficção Clássica', 'pt', 'A família Joad deixa Oklahoma durante a Grande Depressão e viaja para a Califórnia em busca de trabalho e dignidade. O romance denuncia a exploração dos camponeses. Um clássico premiado.', null, array['grande depressão', 'migração', 'pobreza', 'estados unidos', 'clássico']),
  ('ba6cdf9b-40db-5ed4-9073-9ebcb23d5999', 'A Menina que Roubava Livros', 'Markus Zusak', 'Juvenil', 'pt', 'Na Alemanha nazista, a menina Liesel rouba livros e os lê para os vizinhos, enquanto sua família esconde um judeu no porão. A narradora é a própria Morte. Um romance emocionante sobre palavras e coragem.', null, array['segunda guerra', 'alemanha', 'livros', 'morte', 'amizade']),
  ('5f77eef4-947d-551e-aefb-8f1b050cbf6c', 'Extraordinário', 'R. J. Palacio', 'Juvenil', 'pt', 'August Pullman, menino com uma diferença facial, vai à escola pela primeira vez no quinto ano e enfrenta curiosidade e preconceito. A história é contada por vários pontos de vista. Um livro sobre bondade e aceitação.', null, array['escola', 'amizade', 'diferença', 'empatia', 'família']),
  ('e9b5a743-066f-5897-823e-8d0664482a4d', 'O Menino do Pijama Listrado', 'John Boyne', 'Juvenil', 'pt', 'Bruno, filho de um oficial nazista, faz amizade com um menino do outro lado da cerca de um campo de concentração. A inocência dos dois mostra a crueldade do mundo adulto. Um romance juvenil comovente.', null, array['segunda guerra', 'holocausto', 'amizade', 'infância', 'ficção']),
  ('15865d96-5798-5593-b996-d742b898ec68', 'As Crônicas de Nárnia: O Leão, a Feiticeira e o Guarda-Roupa', 'C. S. Lewis', 'Fantasia', 'pt', 'Quatro irmãos entram por um guarda-roupa e chegam a Nárnia, um reino sob o inverno eterno da Feiticeira Branca. Com a ajuda do leão Aslam, eles lutam para libertá-lo. O primeiro livro publicado das Crônicas de Nárnia.', null, array['nárnia', 'aventura', 'fantasia', 'irmãos', 'clássico']),
  ('be44889e-916e-52e6-8780-61f40c8b7c4a', 'Alice no País das Maravilhas', 'Lewis Carroll', 'Infantil', 'pt', 'Alice cai na toca de um coelho e chega a um mundo de personagens absurdos, como o Chapeleiro e a Rainha de Copas. A lógica do sonho domina a história. Um clássico cheio de humor e jogos de linguagem.', null, array['fantasia', 'nonsense', 'clássico', 'coelho', 'aventura']),
  ('8ea68878-f908-55a6-92cc-17f52f48f98d', 'A Menina que Brincava com Fogo', 'Stieg Larsson', 'Mistério e Suspense', 'pt', 'Lisbeth Salander é acusada de assassinatos e o jornalista Mikael Blomkvist tenta provar sua inocência, descobrindo um passado sombrio. O thriller sueco cresce em tensão. O segundo livro da trilogia Millennium.', null, array['thriller', 'suécia', 'hacker', 'crime', 'best-seller']),
  ('a0cdc0b4-0084-54ca-981d-fc5514ac8699', 'Assassinato no Expresso do Oriente', 'Agatha Christie', 'Mistério e Suspense', 'pt', 'Preso pela neve num trem de luxo, o detetive Hercule Poirot investiga o assassinato de um passageiro entre pessoas que parecem ter segredos. A solução é uma das mais famosas do gênero. Um clássico de Agatha Christie.', null, array['poirot', 'mistério', 'trem', 'detetive', 'clássico']),
  ('1a26e3c3-f92b-5e08-8f1e-e91e1e5387b2', 'O Assassinato de Roger Ackroyd', 'Agatha Christie', 'Mistério e Suspense', 'pt', 'Num vilarejo inglês, um homem rico é encontrado morto, e o detetive aposentado Hercule Poirot aceita investigar. A solução surpreendeu os leitores da época. Um dos romances mais inventivos de Agatha Christie.', null, array['poirot', 'mistério', 'vilarejo', 'detetive', 'clássico'])
insert into public.livros (id, titulo, autor, genero, idioma, resumo, nivel_dificuldade, tags) values
  ('faf564e6-9982-59b3-a489-550c261cf323', 'Sherlock Holmes: Um Estudo em Vermelho', 'Arthur Conan Doyle', 'Mistério e Suspense', 'pt', 'Watson conhece Sherlock Holmes e os dois investigam um crime misterioso com a palavra "Rache" escrita na parede. A trama volta aos Estados Unidos para explicar a motivação. A primeira aventura do detetive.', null, array['sherlock holmes', 'mistério', 'londres', 'detetive', 'clássico']),
  ('4443f8df-df72-54bd-b8df-f51c3213162d', 'Ensaio sobre a Lucidez', 'José Saramago', 'Ficção Clássica', 'pt', 'Numa capital, a maioria dos eleitores vota em branco, e o governo reage com medo e repressão. O romance reflete sobre democracia e poder. Uma continuação espiritual de Ensaio sobre a Cegueira.', null, array['política', 'eleições', 'sociedade', 'nobel', 'sátira']),
  ('8202f2a8-79ec-53c6-b838-e387d0cfbbc9', 'A Jangada de Pedra', 'José Saramago', 'Ficção Clássica', 'pt', 'A Península Ibérica se separa da Europa e navega pelo Atlântico, e um grupo de pessoas se encontra por causa de fatos estranhos. A história mistura fantasia e crítica política. Um romance original de Saramago.', null, array['península ibérica', 'fantasia', 'viagem', 'nobel', 'política']),
  ('69a27bd0-cc7d-547c-9423-d8ee0ca3518c', 'O Cavaleiro Inexistente', 'Italo Calvino', 'Fantasia', 'pt', 'Um cavaleiro de armadura brilhante não tem corpo, existe apenas por vontade, e acompanha o exército de Carlos Magno. A fábula brinca com o heroísmo e a identidade. Uma narrativa curta e original.', null, array['cavalaria', 'fábula', 'idade média', 'ironia', 'existência']),
  ('bd4e1ae8-383f-5f6d-8fef-1d67246e1fab', 'As Cidades Invisíveis', 'Italo Calvino', 'Ficção Clássica', 'pt', 'Marco Polo descreve ao imperador Kublai Khan cidades imaginárias, cada uma com uma característica fantástica. Os relatos falam de memória, desejo e linguagem. Um livro poético e experimental.', null, array['cidades', 'imaginação', 'viagem', 'marco polo', 'literatura']),
  ('69c9cb9b-fbf8-53b1-b06b-f11229f48e4a', 'A Insustentável Leveza do Ser', 'Milan Kundera', 'Romance', 'pt', 'Em Praga, depois da invasão soviética, o médico Tomas e as mulheres de sua vida enfrentam dilemas sobre amor, liberdade e leveza. O romance mistura filosofia e narrativa. Um clássico do século XX.', null, array['amor', 'política', 'praga', 'filosofia', 'liberdade']),
  ('2735b047-f9b3-5016-90e3-4c1a231b0b21', 'A Elegância do Ouriço', 'Muriel Barbery', 'Romance', 'pt', 'Numa casa de apartamentos de luxo em Paris, uma zeladora culta e uma menina inteligente escondem suas qualidades até a chegada de um novo morador. O livro fala de beleza e invisibilidade social. Um romance delicado.', null, array['paris', 'amizade', 'filosofia', 'classes sociais', 'sensibilidade']),
  ('dfa01e72-7d28-5aca-af52-41481e2c2c52', 'Mulherzinhas', 'Louisa May Alcott', 'Ficção Clássica', 'pt', 'As quatro irmãs March, Meg, Jo, Beth e Amy, crescem durante a Guerra Civil americana enquanto sonham com futuros diferentes. Jo quer ser escritora. Um clássico sobre família e amadurecimento.', null, array['irmãs', 'família', 'estados unidos', 'clássico', 'juvenil']),
  ('0257dfd3-7243-596a-a399-d5b1ecae5b18', 'Anne de Green Gables', 'Lucy Maud Montgomery', 'Juvenil', 'pt', 'A órfã Anne chega por engano a uma fazenda no Canadá e conquista os irmãos Cuthbert com sua imaginação e boca grande. A vida na ilha é cheia de aventuras. Um clássico juvenil sobre pertencimento.', null, array['orfandade', 'imaginação', 'canadá', 'família', 'clássico']),
  ('be67d7d1-8ab7-550a-b6a1-6cf597be81eb', 'Heidi', 'Johanna Spyri', 'Infantil', 'pt', 'A pequena Heidi vai morar com o avô nos Alpes suíços e depois é levada para a cidade, sentindo falta da natureza. A amizade com Clara muda tudo. Um clássico infantil sobre amor e saudade.', null, array['alpes', 'infância', 'natureza', 'amizade', 'clássico']),
  ('d1d8d9df-597b-5bf4-a2dc-73463e287f79', 'Pollyanna', 'Eleanor H. Porter', 'Infantil', 'pt', 'Pollyanna vai morar com a tia severa e conquista a cidade com o jogo do contente, que consiste em achar algo bom em tudo. A história fala de otimismo e bondade. Um clássico infantojuvenil.', null, array['otimismo', 'órfã', 'alegria', 'clássico', 'juvenil']),
  ('57b7eca0-b933-5198-978f-a81b0339d720', 'O Jardim Secreto', 'Frances Hodgson Burnett', 'Infantil', 'pt', 'A órfã Mary Lennox descobre um jardim trancado numa mansão inglesa e, com ajuda de um menino local, o traz de volta à vida. O jardim também cura a si e ao primo doente. Um clássico sobre natureza e transformação.', null, array['natureza', 'amizade', 'mistério', 'cura', 'clássico']),
  ('98ed580d-362d-5569-a4f1-abd52a058546', 'O Vento nos Salgueiros', 'Kenneth Grahame', 'Infantil', 'pt', 'Toupeira, Rato, Texugo e o exagerado Sapo vivem aventuras às margens de um rio inglês. A amizade e a vida simples são os temas. Um clássico encantador da literatura infantil inglesa.', null, array['animais', 'amizade', 'aventura', 'inglaterra', 'clássico']),
  ('23d7eeaf-fb6d-548a-a053-b712f1be0c71', 'Mogli, o Menino Lobo', 'Rudyard Kipling', 'Infantil', 'pt', 'Mogli, criado por lobos na selva indiana, aprende a lei da floresta com Baloo e Bagheera e enfrenta o tigre Shere Khan. A história une aventura e aprendizado. Uma coletânea clássica de contos.', null, array['selva', 'animais', 'aventura', 'clássico', 'índia']),
  ('9763aa9f-0b50-5bb8-a5a4-aeef341941af', 'O Mágico de Oz', 'L. Frank Baum', 'Infantil', 'pt', 'Um ciclone leva Dorothy e o cachorro Totó para a terra de Oz, onde ela segue a estrada de tijolos amarelos para pedir ajuda ao Mágico. No caminho, conhece o Espantalho, o Homem de Lata e o Leão. Um clássico da fantasia.', null, array['fantasia', 'aventura', 'amizade', 'clássico', 'oz']),
  ('43dea514-7ecc-5a72-8f4c-f44a822c8e2d', 'Pinóquio', 'Carlo Collodi', 'Infantil', 'pt', 'O boneco de madeira Pinóquio ganha vida, foge de casa e se mete em confusões, e seu nariz cresce quando mente. Ele aprende o valor da obediência e da verdade. Um clássico infantil italiano.', null, array['marionete', 'mentira', 'aventura', 'clássico', 'itália']),
  ('7db77e4c-5e58-57b4-b445-678b07769a17', 'Ilíada', 'Homero', 'Poesia', 'pt', 'O poema épico narra episódios da Guerra de Troia, centrado na ira do guerreiro Aquiles e na morte de Heitor. Deuses e mortais se misturam nos combates. Um dos textos fundadores da literatura ocidental.', null, array['épico', 'grécia', 'guerra de troia', 'mitologia', 'clássico']),
  ('1891e7a9-5dc1-5e0b-ac63-39c2bac3af8b', 'Odisseia', 'Homero', 'Poesia', 'pt', 'Depois da guerra de Troia, Ulisses tenta voltar a Ítaca e enfrenta monstros, tempestades e deuses por dez anos. Em casa, a esposa Penélope resiste aos pretendentes. Um clássico da aventura e do retorno.', null, array['épico', 'grécia', 'aventura', 'mitologia', 'clássico']),
  ('baee5552-bca4-527f-ba6c-d8ac579e65d4', 'A Divina Comédia', 'Dante Alighieri', 'Poesia', 'pt', 'Dante é guiado por Virgílio pelo Inferno e pelo Purgatório e por Beatriz até o Paraíso, num poema sobre pecado, justiça e redenção. A obra reúne teologia e política da Idade Média. Um monumento da literatura mundial.', null, array['épico', 'inferno', 'paraíso', 'idade média', 'clássico']),
  ('d92741ad-a584-5572-9363-c07e8360fa2a', 'Dom Quixote', 'Miguel de Cervantes', 'Ficção Clássica', 'pt', 'Um fidalgo enlouquecido pelos livros de cavalaria se torna Dom Quixote e sai pelo mundo com o escudeiro Sancho Pança. Entre moinhos de vento e ilusões, a obra brinca com realidade e ficção. Um dos maiores romances de todos os tempos.', null, array['espanha', 'cavalaria', 'sátira', 'aventura', 'clássico']),
  ('c0f26ecc-13c6-5f1c-9feb-bf012c4bda34', 'A Arte da Guerra', 'Sun Tzu', 'Filosofia', 'pt', 'Um tratado chinês antigo sobre estratégia militar que também é lido como guia de liderança e negócios. O texto defende planejamento, conhecimento do adversário e economia de esforços. Uma leitura curta e muito citada.', null, array['estratégia', 'china', 'guerra', 'liderança', 'clássico']),
  ('861d639b-da7f-5b37-84ec-d48ea0f5dfc9', 'O Príncipe', 'Nicolau Maquiavel', 'Filosofia', 'pt', 'Maquiavel aconselha governantes sobre como conquistar e manter o poder, separando política e moral. O livro foi polêmico e influenciou o pensamento político. Um clássico curto da teoria do poder.', null, array['política', 'poder', 'renascimento', 'estratégia', 'clássico']),
  ('a2846393-481f-5ca5-8e88-686dcb61ae91', 'Meditações', 'Marco Aurélio', 'Filosofia', 'pt', 'Anotações pessoais do imperador romano, em que ele reflete sobre dever, morte e controle das emoções. O estoicismo guia o texto. Uma leitura clássica de sabedoria prática.', null, array['estoicismo', 'roma', 'reflexão', 'ética', 'clássico']),
  ('e0bd537b-ce2a-5208-88ae-b81a730f78e0', 'A República', 'Platão', 'Filosofia', 'pt', 'Em diálogo, Sócrates discute o que é justiça e como seria uma cidade ideal, incluindo a alegoria da caverna. O livro trata de educação, governo e filosofia. Um dos pilares da filosofia ocidental.', null, array['justiça', 'política', 'grécia', 'caverna', 'clássico']),
  ('de10cd79-1799-5ee3-974f-d1aea27d69ca', 'Ética a Nicômaco', 'Aristóteles', 'Filosofia', 'pt', 'Aristóteles investiga o que é a boa vida e defende que a felicidade vem de agir com virtude e razão. Ele analisa coragem, justiça e amizade. Um clássico da filosofia moral.', null, array['ética', 'virtude', 'felicidade', 'grécia', 'clássico']),
  ('e512fce2-ea03-5c36-9c99-c7978e6b2d53', 'Assim Falou Zaratustra', 'Friedrich Nietzsche', 'Filosofia', 'pt', 'O profeta Zaratustra desce da montanha para ensinar o além-homem e a morte de Deus em discursos poéticos. A obra desafia valores tradicionais. Um livro influente e provocativo.', null, array['filosofia', 'além-homem', 'moral', 'poético', 'clássico']),
  ('070a7d4f-b5e1-530f-82ef-6673d942aa98', 'O Mundo de Sofia', 'Jostein Gaarder', 'Filosofia', 'pt', 'A adolescente Sofia recebe cartas misteriosas que contam a história da filosofia, do mito até o século XX, enquanto uma trama de mistério se desenrola. O livro combina romance e aula. Uma introdução leve à filosofia.', null, array['filosofia', 'romance', 'juvenil', 'história da filosofia', 'mistério']),
  ('256c8987-4e06-5dab-b0f1-2fec00e496d3', 'Uma Breve História do Tempo', 'Stephen Hawking', 'Ciência', 'pt', 'Hawking explica para leigos temas como o Big Bang, os buracos negros e a natureza do tempo, com poucas equações. A linguagem é clara e cheia de analogias. Um clássico da divulgação científica.', null, array['cosmos', 'física', 'buracos negros', 'tempo', 'divulgação']),
  ('eff6eac6-62d2-5d8f-af42-d9375af27431', 'O Gene Egoísta', 'Richard Dawkins', 'Ciência', 'pt', 'Dawkins explica a evolução do ponto de vista dos genes e cria o conceito de meme. A obra discute cooperação, egoísmo e seleção natural. Um clássico influente da biologia.', null, array['evolução', 'genes', 'biologia', 'seleção natural', 'divulgação']),
  ('f6dd648d-6a77-5f91-b7f6-14e1274e6f86', 'A Origem das Espécies', 'Charles Darwin', 'Ciência', 'pt', 'Em 1859, Darwin apresenta a teoria da evolução por seleção natural, baseada em observações de plantas e animais. O livro mudou a biologia. Um clássico da ciência.', null, array['evolução', 'seleção natural', 'biologia', 'clássico', 'século xix']),
  ('7a740370-1aaf-543c-be70-fa1d4a1a4418', 'Sidarta', 'Hermann Hesse', 'Ficção Clássica', 'pt', 'Sidarta, jovem indiano, deixa a família em busca da iluminação e passa por ascetismo, prazer e riqueza antes de encontrar a paz. O romance reflete sobre autoconhecimento. Um clássico espiritual curto.', null, array['espiritualidade', 'índia', 'busca', 'budismo', 'clássico']),
  ('ea9cdd42-00c3-553d-b3e8-ddc448a54406', 'O Lobo da Estepe', 'Hermann Hesse', 'Ficção Clássica', 'pt', 'Harry Haller, intelectual solitário, sente-se dividido entre o homem e o lobo que carrega dentro de si, até conhecer uma jovem que o apresenta a outra vida. O romance trata de crise e identidade. Um clássico do século XX.', null, array['identidade', 'solidão', 'alemanha', 'existencial', 'clássico']),
  ('9ef63b55-5cee-5c88-a57c-a3473b485502', 'O Retrato de Dorian Gray', 'Oscar Wilde', 'Ficção Clássica', 'pt', 'Dorian Gray deseja manter sempre a juventude, e seu retrato passa a envelhecer e a mostrar os efeitos de seus atos. O livro reflete sobre vaidade e moral. Um clássico de Oscar Wilde.', null, array['beleza', 'juventude', 'vício', 'retrato', 'clássico']),
  ('2a07b100-1eba-5ec5-868d-f4d6dc017093', 'O Médico e o Monstro', 'Robert Louis Stevenson', 'Terror', 'pt', 'Em Londres, o advogado Utterson investiga a ligação entre o respeitável Dr Jekyll e o brutal Mr Hyde. A resposta mostra a luta entre bem e mal dentro de uma pessoa. Uma novela curta e clássica.', null, array['dualidade', 'gótico', 'londres', 'ciência', 'clássico']),
  ('7c673aeb-faaf-597f-bf15-66a75c03de47', 'A Ilha do Tesouro', 'Robert Louis Stevenson', 'Aventura', 'pt', 'O jovem Jim Hawkins encontra um mapa do tesouro e parte numa viagem de navio, onde o cozinheiro Long John Silver esconde planos traiçoeiros. A história criou muitas imagens de piratas. Um clássico de aventura.', null, array['piratas', 'tesouro', 'aventura', 'juvenil', 'clássico']),
  ('06c98918-1671-54f3-85b1-c3156ad76cdf', 'Vinte Mil Léguas Submarinas', 'Júlio Verne', 'Ficção Científica', 'pt', 'O professor Aronnax e seus companheiros são capturados pelo capitão Nemo e viajam pelos oceanos a bordo do submarino Nautilus. A obra mistura aventura e ciência. Um clássico da ficção científica.', null, array['submarino', 'oceano', 'aventura', 'capitão nemo', 'clássico']),
  ('b45077bd-345c-5934-9c82-8ec3c047062a', 'A Volta ao Mundo em Oitenta Dias', 'Júlio Verne', 'Aventura', 'pt', 'O inglês Phileas Fogg aposta que consegue dar a volta ao mundo em oitenta dias e parte com seu criado Passepartout, enfrentando atrasos e perigos. A viagem é cheia de reviravoltas. Um clássico da aventura.', null, array['viagem', 'aposta', 'aventura', 'clássico', 'século xix']),
  ('c5fa37e7-02f3-5602-b976-fbff5f040a9c', 'A Máquina do Tempo', 'H. G. Wells', 'Ficção Científica', 'pt', 'Um inventor viaja ao futuro distante e encontra uma humanidade dividida em duas espécies. A novela critica desigualdades sociais. Um clássico fundador da ficção científica.', null, array['tempo', 'futuro', 'distopia', 'clássico', 'novela']),
  ('92551df9-2ca4-5183-8296-7c20d0aaeb94', 'A Guerra dos Mundos', 'H. G. Wells', 'Ficção Científica', 'pt', 'Marcianos invadem a Inglaterra com máquinas de guerra imensas, e a humanidade se vê indefesa. O narrador relata a destruição e a fuga. Um clássico da invasão alienígena.', null, array['marcianos', 'invasão', 'inglaterra', 'clássico', 'suspense']),
  ('476f2851-656a-5a00-99dd-734ded5b5558', 'Eu, Robô', 'Isaac Asimov', 'Ficção Científica', 'pt', 'Contos conectados mostram os conflitos entre humanos e robôs governados pelas Três Leis da Robótica. As histórias têm mistério e reflexão. Um clássico da ficção científica.', null, array['robôs', 'leis da robótica', 'contos', 'clássico', 'futuro']),
  ('9b1ee25b-b112-5234-bea8-79e1a41d4e22', 'Fundação', 'Isaac Asimov', 'Ficção Científica', 'pt', 'Um matemático prevê a queda do Império Galáctico e cria a Fundação para reduzir o tempo de barbárie. A saga acompanha séculos de crises. Um clássico da ficção científica.', null, array['império galáctico', 'ciência', 'futuro', 'saga', 'clássico']),
  ('07879a2a-cc4d-561f-9ef9-75ae719dd595', 'Duna', 'Frank Herbert', 'Ficção Científica', 'pt', 'O jovem Paul Atreides e sua família assumem o controle do planeta deserto Arrakis, fonte da valiosa especiaria. Traição e profecia mudam seu destino. Um épico de ficção científica.', null, array['deserto', 'política', 'ecologia', 'épico', 'clássico']),
  ('33a10575-2549-56df-a1a5-a5c5bcf522ee', 'O Guia do Mochileiro das Galáxias', 'Douglas Adams', 'Ficção Científica', 'pt', 'Arthur Dent escapa da destruição da Terra com o amigo Ford Prefect e viaja pelo espaço com um guia eletrônico. O humor britânico domina a história. Uma comédia de ficção científica adorada.', null, array['humor', 'espaço', 'absurdo', 'aventura', 'clássico']),
  ('cf292001-cd14-5e4f-8701-e327a1fc4dc9', 'A Guerra dos Tronos', 'George R. R. Martin', 'Fantasia', 'pt', 'Famílias nobres de Westeros disputam o Trono de Ferro enquanto uma ameaça antiga volta do norte. Os capítulos mudam de ponto de vista. O primeiro livro da saga As Crônicas de Gelo e Fogo.', null, array['intriga', 'reinos', 'dragões', 'épico', 'best-seller']),
  ('42535dfd-4b29-5406-ae51-66526b291acd', 'O Nome do Vento', 'Patrick Rothfuss', 'Fantasia', 'pt', 'Kvothe, famoso mago e músico, conta a um cronista como foi sua juventude, da perda da família à escola de magia. O relato mistura lenda e verdade. O primeiro volume da série A Crônica do Matador do Rei.', null, array['magia', 'música', 'narrador', 'épico', 'best-seller']),
  ('f66e7170-a2ad-5884-8339-0843faa12c16', 'A Moreninha', 'Joaquim Manuel de Macedo', 'Romance', 'pt', 'O estudante Augusto aposta com os amigos que nunca se apaixonará e passa um fim de semana na ilha de uma família, onde conhece a moça que desafia a aposta. O romance é leve e sentimental. Um clássico do Romantismo brasileiro.', null, array['romantismo', 'amor', 'juventude', 'rio de janeiro', 'clássico']),
  ('7c3fe10c-6824-5ea6-8608-7704b5dbb9de', 'A Escrava Isaura', 'Bernardo Guimarães', 'Ficção Clássica', 'pt', 'Isaura, escravizada de pele clara e muito educada, resiste às investidas do senhor e tenta viver ao lado do homem que ama. O romance denuncia a escravidão por meio de uma história de amor. Um clássico muito adaptado para a TV.', null, array['romantismo', 'escravidão', 'amor', 'abolição', 'clássico']),
  ('e30a58c7-f238-508b-b118-bbcf21f17567', 'Inocência', 'Visconde de Taunay', 'Ficção Clássica', 'pt', 'No interior de Mato Grosso, um naturalista conhece a jovem Inocência, prometida a outro homem, e os dois se apaixonam. A pureza e a lei do pai levam a um desfecho trágico. Um clássico do Romantismo sertanejo.', null, array['romantismo', 'sertão', 'amor', 'tragédia', 'clássico']),
  ('2380a278-d737-58ca-b74d-3a173a32078d', 'Esaú e Jacó', 'Machado de Assis', 'Ficção Clássica', 'pt', 'Os gêmeos Pedro e Paulo brigam desde o ventre e disputam, em tudo, a atenção da mesma moça. A narrativa acompanha a passagem do Império para a República. Um romance elegante e irônico de Machado de Assis.', null, array['realismo', 'irmãos', 'política', 'império', 'república']),
  ('a573b7f0-8aed-5b5d-95bf-5e47ecd36f5e', 'Memorial de Aires', 'Machado de Assis', 'Ficção Clássica', 'pt', 'O diplomata aposentado Aires registra no diário a vida de um casal de velhos e dos jovens ao redor. O livro é delicado e melancólico. O último romance de Machado de Assis.', null, array['realismo', 'diário', 'velhice', 'casamento', 'clássico']),
  ('e44e117a-e314-5293-b7e1-9b33fa5deb53', 'Viva o Povo Brasileiro', 'João Ubaldo Ribeiro', 'Ficção Clássica', 'pt', 'O romance acompanha por séculos várias gerações de brasileiros no Recôncavo Baiano, entre senhores e escravizados, em busca de liberdade e identidade. A narrativa mistura humor, mito e história. Uma saga monumental.', null, array['história', 'bahia', 'saga', 'identidade', 'brasil']),
  ('0a079e72-3fd7-5c00-9e33-6dad853a1b8c', 'Sargento Getúlio', 'João Ubaldo Ribeiro', 'Ficção Clássica', 'pt', 'Um sargento teimoso leva um preso por centenas de quilômetros pelo sertão, decidido a cumprir a ordem mesmo diante de mudanças políticas. O romance é narrado pelo próprio personagem. Uma obra intensa e regional.', null, array['sertão', 'violência', 'dever', 'monólogo', 'clássico']),
  ('4ac43761-de52-5ea0-a0f4-40bb969eeae2', 'Menino de Engenho', 'José Lins do Rego', 'Ficção Clássica', 'pt', 'Carlinhos, órfão, vai viver no engenho do avô e conta a infância cercada de parentes, escravizados e moradores. O livro retrata a decadência do ciclo da cana. Um clássico do regionalismo nordestino.', null, array['nordeste', 'infância', 'engenho', 'memória', 'clássico']),
  ('9fc621d7-dce3-596c-8dcd-cdd97c07ed6b', 'Fogo Morto', 'José Lins do Rego', 'Ficção Clássica', 'pt', 'Três personagens, um mestre seleiro, o dono do engenho e um capitão, mostram o fim do mundo dos engenhos de cana na Paraíba. O romance tem tom sombrio e humano. Considerado uma obra-prima do regionalismo.', null, array['nordeste', 'engenho', 'decadência', 'clássico', 'regionalismo']),
  ('89e86ea5-60a1-56f5-bfbf-d377665855d0', 'Lavoura Arcaica', 'Raduan Nassar', 'Ficção Clássica', 'pt', 'André foge de casa e depois volta à família de origem libanesa, onde enfrenta o pai autoritário e seus desejos proibidos. A linguagem é poética e intensa. Um romance curto e impactante.', null, array['família', 'tradição', 'rebeldia', 'poético', 'libanês']),
  ('5a976bde-6c75-54a1-87da-1e689da8d5ff', 'Um Copo de Cólera', 'Raduan Nassar', 'Ficção Clássica', 'pt', 'Depois de uma noite de amor, um homem e uma mulher entram em uma discussão feroz que revela poder e vaidade. A novela é curta e muito intensa. Um texto marcante da literatura brasileira.', null, array['casal', 'discussão', 'poder', 'novela', 'intenso']),
  ('947347e8-5e60-5325-8e3a-e5bd37188882', 'O Encontro Marcado', 'Fernando Sabino', 'Ficção Clássica', 'pt', 'Eduardo Marciano cresce em Belo Horizonte, passa a juventude entre amigos e sonhos literários e enfrenta o amadurecimento. O romance acompanha as escolhas e perdas. Um clássico de formação da literatura brasileira.', null, array['juventude', 'amizade', 'minas gerais', 'amadurecimento', 'clássico']),
  ('f26560d3-36d2-5b48-9c47-f46638a0b016', 'O Homem Nu', 'Fernando Sabino', 'Ensaios e Crônicas', 'pt', 'Reúne crônicas curtas e divertidas sobre situações do cotidiano, com destaque para a que dá título ao livro, em que um homem fica trancado fora do apartamento. O humor é fino e acessível. Uma boa porta de entrada para as crônicas brasileiras.', null, array['crônicas', 'humor', 'cotidiano', 'brasil', 'clássico']),
  ('0e414187-133d-544a-963e-f025a7e796f1', 'Vestido de Noiva', 'Nelson Rodrigues', 'Teatro', 'pt', 'Depois de um atropelamento, Alaíde revive lembranças e fantasias entre três planos: realidade, memória e alucinação. A peça de 1943 renovou o teatro brasileiro. Um marco do teatro moderno.', null, array['teatro', 'memória', 'modernismo', 'tragédia', 'clássico']),
  ('9edf4ec3-71a5-579d-ac41-eaed1dd0d1ee', 'O Beijo no Asfalto', 'Nelson Rodrigues', 'Teatro', 'pt', 'Um homem beija um desconhecido que está morrendo no asfalto, e um jornal cria um escândalo em torno do ato. A peça revela hipocrisia e sensacionalismo. Uma tragédia carioca de Nelson Rodrigues.', null, array['teatro', 'rio de janeiro', 'imprensa', 'tragédia', 'preconceito']),
  ('5df49907-cab4-54c6-9296-2edeab56dc0e', 'Bonitinha, mas Ordinária', 'Nelson Rodrigues', 'Teatro', 'pt', 'Um jovem pobre é pressionado a casar com a filha de um milionário que sofreu um abuso, e o dinheiro entra em conflito com a honra. A peça fala de moral e interesse. Um clássico ácido de Nelson Rodrigues.', null, array['teatro', 'dinheiro', 'moral', 'rio de janeiro', 'sátira']),
  ('7e248cf4-60ea-5938-bde7-7837170dd923', 'Navalha na Carne', 'Plínio Marcos', 'Teatro', 'pt', 'Num quarto de pensão, uma prostituta, seu cafetão e o empregado se confrontam em uma noite de humilhação e tensão. A peça retrata a vida à margem com crueza. Um marco do teatro brasileiro.', null, array['teatro', 'marginalidade', 'violência', 'são paulo', 'drama']),
  ('6dcae9e6-677d-50d5-998f-6bd4fc2ebb16', 'Eles Eram Muitos Cavalos', 'Luiz Ruffato', 'Romance', 'pt', 'Num único dia em São Paulo, o romance reúne cenas, vozes e fragmentos de vidas muito diferentes. O resultado é um retrato da metrópole. Uma obra premiada da literatura contemporânea.', null, array['são paulo', 'fragmentos', 'cidade', 'vozes', 'contemporâneo']),
  ('7903d091-d7cb-590d-910d-d41c16017052', 'Cidade de Deus', 'Paulo Lins', 'Romance', 'pt', 'O romance acompanha, por décadas, a história do conjunto habitacional Cidade de Deus, no Rio de Janeiro, e a vida de jovens do crime e da pobreza. A narrativa mistura vozes e gírias. Uma obra marcante da literatura brasileira.', null, array['favela', 'violência', 'rio de janeiro', 'crime', 'contemporâneo']),
  ('769915e5-264a-59e1-a726-91cc85e515a0', 'Estorvo', 'Chico Buarque', 'Romance', 'pt', 'Um homem tenta fugir de um perseguidor desconhecido e circula pela cidade e pelo passado, em uma narrativa confusa e angustiante. O romance de estreia de Chico Buarque mostra a paranoia urbana. Um texto curto e enigmático.', null, array['rio de janeiro', 'paranoia', 'fuga', 'urbano', 'contemporâneo']),
  ('9596fbf5-bb12-551f-b58c-78ccf0e495c9', 'Feliz Ano Novo', 'Rubem Fonseca', 'Contos', 'pt', 'Os contos mostram assaltos, desigualdade e vidas à margem no Rio de Janeiro, narrados em linguagem direta. O livro foi censurado durante a ditadura. Uma coletânea importante do conto brasileiro.', null, array['contos', 'violência', 'rio de janeiro', 'crime', 'contemporâneo']),
  ('941173ad-0289-5ce5-9ce0-e3151665f4fe', 'A Grande Arte', 'Rubem Fonseca', 'Mistério e Suspense', 'pt', 'O advogado Mandrake investiga um caso de assassinatos envolvendo uma prostituta e acaba enfrentando um perigoso assassino. A narrativa é crua e cheia de ação. Um dos romances policiais mais conhecidos do autor.', null, array['policial', 'rio de janeiro', 'crime', 'advogado', 'thriller']),
  ('8edd4a3f-bfa3-5fca-bc1c-25e155a2cfdf', 'As Meninas', 'Lygia Fagundes Telles', 'Romance', 'pt', 'Três jovens universitárias moram numa pensão de freiras em São Paulo, durante a ditadura, e enfrentam dilemas sobre amor, política e liberdade. O romance dá voz a cada uma delas. Um clássico da escritora.', null, array['ditadura', 'mulheres', 'amizade', 'são paulo', 'década de 1970']),
  ('740dbfd1-6730-5798-8395-3c6dad23a3d9', 'Antes do Baile Verde', 'Lygia Fagundes Telles', 'Contos', 'pt', 'Contos de Lygia Fagundes Telles exploram amor, solidão, medo e a passagem do tempo. A autora usa detalhes para criar tensão e emoção. Uma coletânea clássica do conto brasileiro.', null, array['contos', 'mulheres', 'memória', 'suspense', 'clássico']),
  ('8c903dd7-da16-51d2-b4ec-fcca3af3203d', 'Morangos Mofados', 'Caio Fernando Abreu', 'Contos', 'pt', 'Reúne contos sobre jovens e adultos em crise na cidade, em tempos de ditadura e mudança. A prosa é sensível e urbana. Um dos livros mais queridos de Caio Fernando Abreu.', null, array['contos', 'juventude', 'solidão', 'anos 1980', 'urbano']),
  ('cd91cb87-e186-5728-ba27-9ae1b1452054', 'O Centauro no Jardim', 'Moacyr Scliar', 'Romance', 'pt', 'Guedali, nascido centauro numa família de imigrantes judeus no Sul do Brasil, tenta encontrar seu lugar no mundo. O romance une humor, fantasia e reflexão sobre identidade. Uma obra premiada de Moacyr Scliar.', null, array['imigração', 'identidade', 'realismo fantástico', 'rio grande do sul', 'humor']),
  ('3d98824c-723c-5e6b-95d0-88d5a49d6cea', 'A Máquina de Fazer Espanhóis', 'Valter Hugo Mãe', 'Romance', 'pt', 'Silva, viúvo de oitenta e quatro anos, é levado para um lar de idosos em Portugal e reflete sobre a vida, a perda e a amizade. A linguagem é poética e sem maiúsculas. Um romance comovente.', null, array['velhice', 'portugal', 'perda', 'memória', 'sensibilidade']),
  ('f6c655d3-46cf-54c3-a0e8-574d5ca3d027', 'Broquéis', 'Cruz e Sousa', 'Poesia', 'pt', 'Publicado em 1893, o livro reúne poemas de Cruz e Sousa com imagens musicais, tom místico e sofrimento do poeta negro. É um marco do Simbolismo brasileiro. Uma poesia densa e sonora.', null, array['simbolismo', 'poesia', 'brasil', 'século xix', 'clássico']),
  ('9b1e6e54-d907-5950-93c3-604052b23d42', 'Eu e Outras Poesias', 'Augusto dos Anjos', 'Poesia', 'pt', 'Os poemas misturam termos científicos, morte e pessimismo em versos fortes e inconfundíveis. O livro, de 1912, tem uma voz diferente na poesia da época. Um clássico singular da poesia brasileira.', null, array['poesia', 'pré-modernismo', 'morte', 'ciência', 'sombrio']),
  ('79aa8ab3-b4f7-5a9c-8f97-2d60beed846f', 'Espumas Flutuantes', 'Castro Alves', 'Poesia', 'pt', 'Primeiro livro de Castro Alves, reúne poemas de amor e de temas sociais, como O Navio Negreiro, contra a escravidão. O ritmo é forte e cheio de imagens. Um clássico do Romantismo brasileiro.', null, array['romantismo', 'amor', 'liberdade', 'poesia', 'século xix']),
  ('1b3ae7a2-0146-5479-9307-c5a125a18599', 'Canção do Exílio e Outros Poemas', 'Gonçalves Dias', 'Poesia', 'pt', 'Reúne poemas do Romantismo brasileiro, entre eles a Canção do Exílio, em que o poeta, longe, sente saudade da pátria. A linguagem é simples e musical. Uma leitura essencial da poesia nacional.', null, array['romantismo', 'pátria', 'saudade', 'indianismo', 'clássico']),
  ('a138c20a-4932-5f89-a310-eb478db889e4', 'Poemas, Sonetos e Baladas', 'Vinicius de Moraes', 'Poesia', 'pt', 'Reúne poemas de amor, sonetos e baladas de Vinicius de Moraes, poeta e compositor da bossa nova. A linguagem é musical e apaixonada. Uma coletânea muito querida.', null, array['poesia', 'amor', 'bossa nova', 'sonetos', 'clássico']),
  ('44d609eb-0ac3-5a1d-b8fc-ccdc35a70c9f', 'Bagagem', 'Adélia Prado', 'Poesia', 'pt', 'Em seu livro de estreia, Adélia Prado fala do cotidiano, do corpo e da fé com linguagem simples e surpreendente. A poeta mineira uniu o sagrado ao dia a dia. Uma estreia elogiada por Drummond.', null, array['poesia', 'cotidiano', 'fé', 'mulheres', 'minas gerais']),
  ('f2e48ebe-a261-588c-a7bc-f2ff3c71e0bb', 'Poema Sujo', 'Ferreira Gullar', 'Poesia', 'pt', 'Escrito no exílio, em Buenos Aires, o longo poema reconstrói a memória do poeta, de sua infância em São Luís à vida no Rio. A linguagem é intensa e cheia de imagens. Um marco da poesia brasileira.', null, array['poesia', 'exílio', 'memória', 'ditadura', 'clássico']),
  ('11b565c1-9e22-5a46-a317-4afbebdb8a63', 'Toda Poesia', 'Paulo Leminski', 'Poesia', 'pt', 'Reúne poemas curtos de Leminski, cheios de humor, jogos de palavras e influência do haicai. O poeta curitibano uniu cultura pop e erudição. Uma coletânea querida.', null, array['poesia', 'haicai', 'curitiba', 'humor', 'contemporâneo']),
  ('558a04e4-b74d-5532-9774-07762b86e879', 'O Vampiro de Curitiba', 'Dalton Trevisan', 'Contos', 'pt', 'Contos curtos mostram personagens solitários e obsessivos da cidade de Curitiba, em linguagem seca e direta. O autor é considerado um mestre do conto. Uma leitura intensa e rápida.', null, array['contos', 'curitiba', 'cotidiano', 'obsessão', 'minimalismo']),
  ('ec9d5ff0-a18b-5036-a4df-d99aa4b7267c', 'Memórias Sentimentais de João Miramar', 'Oswald de Andrade', 'Ficção Clássica', 'pt', 'Em capítulos curtos e experimentais, João Miramar conta sua vida de elite paulistana, de infância a viagens à Europa. A linguagem rompe com a tradição. Um marco do Modernismo brasileiro.', null, array['modernismo', 'experimental', 'são paulo', 'fragmentos', 'clássico']),
  ('e9a3c115-c9e3-5622-8369-29b7103527d5', 'Contos Novos', 'Mário de Andrade', 'Contos', 'pt', 'Reúne contos de Mário de Andrade sobre infância, vida em São Paulo e relações humanas. O estilo é simples e sensível. Um dos grandes livros de contos do Modernismo.', null, array['contos', 'modernismo', 'são paulo', 'infância', 'clássico']),
  ('e4ac3788-f02b-50ce-a89f-8405ba9eb44b', 'Dona Guidinha do Poço', 'Manuel de Oliveira Paiva', 'Ficção Clássica', 'pt', 'Num sertão do Ceará, uma fazendeira poderosa se envolve com um jovem e é levada a um crime que destrói sua vida. O romance retrata costumes e violência do interior. Um clássico do regionalismo.', null, array['realismo', 'ceará', 'sertão', 'crime', 'clássico']),
  ('f66419db-3f44-5d45-bea5-c18ef3349045', 'Mad Maria', 'Márcio Souza', 'Ficção Clássica', 'pt', 'O romance reconstrói a construção da ferrovia Madeira-Mamoré, na Amazônia, marcada por doenças, ganância e mortes. Entre engenheiros e operários, mostra o preço do progresso. Uma obra de ficção histórica.', null, array['amazônia', 'ferrovia', 'história', 'ambição', 'tragédia']),
  ('1d865108-e5a8-5921-b634-0c896522959a', 'O Cobrador', 'Rubem Fonseca', 'Contos', 'pt', 'Contos cruéis e diretos mostram personagens que usam a violência contra o que consideram injustiça social. O livro incomodou na época de sua publicação. Uma coletânea marcante do conto urbano.', null, array['contos', 'violência', 'desigualdade', 'rio de janeiro', 'crime']),
  ('37050a14-ecbc-5909-8a49-f32f8e4350ba', 'A Cartomante e Outros Contos', 'Machado de Assis', 'Contos', 'pt', 'Reúne contos curtos de Machado de Assis, com humor e ironia, como A Cartomante, em que a crença no destino leva a uma tragédia. As histórias revelam hipocrisias do cotidiano. Uma boa porta de entrada para o autor.', null, array['contos', 'realismo', 'destino', 'ciúme', 'clássico']),
  ('873c24b8-d768-56ce-b000-5945d460b19d', 'The Posthumous Memoirs of Brás Cubas', 'Machado de Assis', 'Ficção Clássica', 'en', 'Brás Cubas, já morto, narra a própria vida com humor e ironia, sem poupar a si nem a sociedade carioca do século XIX. O livro quebra as regras do romance de sua época. Um marco da literatura brasileira em tradução.', 'Avançado', array['realismo', 'ironia', 'sátira', 'brasil', 'clássico']),
  ('2c34835d-5056-5100-81ff-6ae85f2aa392', 'The Hour of the Star', 'Clarice Lispector', 'Ficção Clássica', 'en', 'O narrador conta a vida de Macabéa, uma datilógrafa nordestina pobre e ingênua no Rio de Janeiro. A história questiona quem tem direito a ser visto. O último livro que Clarice publicou em vida, em tradução.', 'Intermediário', array['brasil', 'pobreza', 'mulheres', 'modernismo', 'novela']),
  ('c4aec86d-6323-5b9d-898c-33875d39e871', 'The Devil to Pay in the Backlands', 'João Guimarães Rosa', 'Ficção Clássica', 'en', 'O ex-jagunço Riobaldo conta sua vida a um interlocutor, falando de lutas, pacto com o diabo e do amor por Diadorim. A linguagem inventiva mistura fala sertaneja e invenção. Uma obra-prima brasileira em tradução.', 'Avançado', array['sertão', 'jagunços', 'amor', 'linguagem', 'clássico']),
  ('377e41e6-31ac-5db5-81b7-a690aa2091d6', 'One Hundred Years of Solitude', 'Gabriel García Márquez', 'Ficção Clássica', 'en', 'A saga da família Buendía, em Macondo, passa por sete gerações cheias de amores, guerras, magia e solidão. A narrativa mistura realidade e fantasia. Um dos maiores romances do século XX, em tradução.', 'Avançado', array['realismo mágico', 'macondo', 'família', 'américa latina', 'nobel']),
  ('cd5d887b-f6fc-53a7-82a8-b326e8e625ab', 'Love in the Time of Cholera', 'Gabriel García Márquez', 'Romance', 'en', 'Florentino espera mais de cinquenta anos para voltar a ficar com Fermina, que escolheu outro homem. A história mostra como o amor atravessa o tempo. Um romance intenso e melancólico, em tradução.', 'Avançado', array['amor', 'espera', 'colômbia', 'velhice', 'nobel']),
  ('74db6579-d821-5635-9900-b65d3f4a2c34', 'Blindness', 'José Saramago', 'Ficção Clássica', 'en', 'Uma epidemia de cegueira branca atinge uma cidade, e os doentes são isolados num manicômio onde reinam violência e abuso. Só uma mulher continua enxergando. Uma parábola sobre egoísmo e solidariedade, em tradução.', 'Avançado', array['epidemia', 'cegueira', 'sociedade', 'distopia', 'nobel']),
  ('fcd99498-fcd9-54df-8368-574d65479964', 'The Little Prince', 'Antoine de Saint-Exupéry', 'Infantil', 'en', 'Um piloto perdido no deserto conhece um pequeno príncipe vindo de um asteroide, que conta suas viagens por outros planetas. A amizade com uma raposa ensina o valor dos laços. Um clássico para crianças e adultos, em tradução.', 'Iniciante', array['fábula', 'amizade', 'infância', 'filosofia', 'clássico']),
  ('085b73e9-a0ee-5b06-991c-895265b94ee9', 'The Diary of a Young Girl', 'Anne Frank', 'Biografia e Memórias', 'en', 'Entre 1942 e 1944, a adolescente Anne Frank escreve cartas à amiga imaginária Kitty sobre a vida num esconderijo atrás de uma estante em Amsterdã, com a família e outras quatro pessoas. Fala de medo, brigas, do primeiro amor por Peter e do sonho de virar escritora. Em inglês, o texto é simples e direto, bom para o nível intermediário.', 'Intermediário', array['segunda guerra', 'diário', 'holocausto', 'adolescência', 'esperança']),
  ('2e0d320a-af19-5fa8-82ae-a6078daa1710', 'Don Quixote', 'Miguel de Cervantes', 'Ficção Clássica', 'en', 'Alonso Quijano, um fidalgo da Mancha, enlouquece de tanto ler livros de cavalaria e se declara o cavaleiro Dom Quixote, com o fiel escudeiro Sancho Pança ao lado. Os dois confundem moinhos com gigantes e estalagens com castelos, e o humor se mistura com a tristeza dos fracassos. Em inglês, é um clássico longo, de leitura avançada.', 'Avançado', array['espanha', 'cavalaria', 'sátira', 'aventura', 'clássico']),
  ('1ec4c5c9-7769-5097-8c24-430b261469bc', 'The Odyssey', 'Homer', 'Poesia', 'en', 'Dez anos depois de Troia, Ulisses ainda tenta chegar a Ítaca e enfrenta o ciclope Polifemo, as sereias, Circe e Calipso. Em casa, a esposa Penélope adia o casamento com os pretendentes que consomem os bens da família, e o filho Telêmaco parte em busca do pai. A edição em inglês é uma leitura avançada, cheia de epítetos repetidos.', 'Avançado', array['épico', 'grécia', 'aventura', 'mitologia', 'clássico']),
  ('c6511ab3-0eae-581f-a226-5710fc6fed79', 'The Iliad', 'Homer', 'Poesia', 'en', 'Nos últimos dias do cerco de Troia, Aquiles se recusa a lutar depois de uma ofensa de Agamêmnon, e os gregos sofrem derrotas. Ele só volta ao combate quando o amigo Pátroclo é morto por Heitor, e o duelo entre os dois é o ponto alto do poema. Em inglês, é uma leitura de linguagem elevada e frases longas.', 'Avançado', array['épico', 'grécia', 'guerra de troia', 'mitologia', 'clássico']),
  ('c65adf5c-02be-591e-a309-5b8a52a75304', 'The Art of War', 'Sun Tzu', 'Filosofia', 'en', 'Atribuído ao general chinês Sun Tzu, o tratado tem treze capítulos curtos sobre planejamento, terreno, espionagem e o uso do engano. A ideia central é vencer sem lutar sempre que possível, conhecendo a si mesmo e ao adversário. Em inglês, as frases são curtas e diretas, boas para treinar a leitura.', 'Intermediário', array['estratégia', 'china', 'guerra', 'liderança', 'clássico']),
  ('decc8632-3294-5793-bd1d-26490548fda0', 'Meditations', 'Marcus Aurelius', 'Filosofia', 'en', 'O imperador romano Marco Aurélio escreveu estas notas para si mesmo durante campanhas militares, sem pensar em publicá-las. Elas repetem ideias estoicas: aceitar o que não depende de nós, agir com justiça e lembrar que a vida é breve. Em inglês, é um texto de frases curtas e aforismos, de nível avançado.', 'Avançado', array['estoicismo', 'roma', 'reflexão', 'ética', 'clássico'])
